    /**
     * The town uses the native gameplay receiver state without joining an
     * ordinary GameHub battle.  Keep every handler that assumes a room-owned
     * arena, combat roster or durable economy fail-closed until its town
     * producer is independently recovered.
     */
    private static boolean rentalTownGameplayOpcodeAllowed(int opcode) {
        return switch (opcode) {
            case Protocol.C_LOGOUT,
                    Protocol.C_QUIT,
                    Protocol.C_RESTART,
                    Protocol.C_SAY,
                    Protocol.C_TELL,
                    Protocol.C_WHO,
                    Protocol.C_CHAT,
                    Protocol.C_MONITOR_CONTROL,
                    Protocol.C_GOTO_PORTAL,
                    Protocol.C_CHANGE_DIRECTION,
                    Protocol.C_MOVE,
                    Protocol.C_BLINK,
                     Protocol.C_ONOFF,
                     Protocol.C_USE_ITEM,
                     Protocol.C_GET,
                     Protocol.C_DROP,
                     Protocol.C_DIALOG,
                     Protocol.C_HACTION,
                     Protocol.C_BUY_SELL,
                     Protocol.C_HYPERTEXT_INPUT_RESULT,
                     Protocol.C_SAVE,
                    Protocol.C_ACTION,
                    Protocol.C_ALIVE,
                    Protocol.C_ENTER_PORTAL,
                    Protocol.C_LITO_EXIT_ROOM,
                    Protocol.C_LITO_QUIT_FIGHT -> true;
            default -> false;
        };
    }

    private void rejectMalformedPacket(int opcode, IllegalArgumentException malformed) throws IOException {
        System.out.printf("[LiTo] rejected malformed C opcode=0x%02X phase=%s reason=%s%n",
                opcode, phase, malformed.getMessage());
        switch (opcode) {
            case Protocol.C_VERSION -> sendEncrypted(
                    Protocol.versionRejected(), "S_VERSION_CHECK malformed-request");
            case Protocol.C_LOGIN -> sendLoginFailure(Protocol.LoginCheckResult.ACCESS_FAILED, "malformed-login");
            case Protocol.C_LITO_SELECT_CHAR -> sendEncrypted(
                    Protocol.litoCharacterSelectResult(
                            Protocol.LitoCharacterSelectResult.SILENT_REJECTED),
                    "S_LITO_SELCHAR_RESULT malformed-request");
            case Protocol.C_LITO_ENTER_CHANNEL -> sendEncrypted(
                    Protocol.litoMalformedEnterChannelFailure(),
                    "S_LITO_ENTER_CHANNEL_RESULT malformed-request");
            case Protocol.C_LITO_CREATE_ROOM, Protocol.C_LITO_JOIN -> {
                rejectRoomRequest("malformed-request");
            }
            case Protocol.C_LITO_ASK_MATCH_MAKING -> sendEncrypted(
                    Protocol.litoAskMatchMakingResult(
                            Protocol.LitoMatchMakingResult.NO_TRANSITION),
                    "S_LITO_ASK_MATCH_MAKING_RESULT no-transition malformed-request");
            case Protocol.C_LITO_KICK_USER -> sendEncrypted(
                    Protocol.litoKickStatus(Protocol.LitoKickStatusResult.REJECTED),
                    "S_LITO_KICK_STATUS malformed-request");
            case Protocol.C_CREATE_CUSTOM_CHARACTER -> sendEncrypted(
                    Protocol.createCharacterFailure(
                            Protocol.CreateCharacterFailure.WRONG_AMOUNT, 0),
                    "S_CREATE_CHARACTER_CHECK malformed-request");
            case Protocol.C_ENTER_WORLD -> sendEncrypted(
                    Protocol.enterWorldCheck(Protocol.EnterWorldCheckResult.NO_TRANSITION, 0),
                    "S_ENTER_WORLD_CHECK malformed-request no-change");
            case Protocol.C_DELETE_CHARACTER -> sendEncrypted(
                    Protocol.deleteCharacterCheck(
                            Protocol.DeleteCharacterCheckResult.NO_TRANSITION, 0),
                    "S_DELETE_CHARACTER_CHECK malformed-request no-change");
            default -> {
                // Many legacy notifications have no paired S error opcode.
                // Keep the encrypted session synchronized and let the next
                // valid packet proceed instead of tearing down the socket.
            }
        }
    }

    private void openHypertext(byte[] payload) throws IOException {
        long objectId = Protocol.dialogObjectId(payload);
        if (phase == Phase.WORLD) {
            openClassicWorldHypertext(objectId);
            return;
        }
        if (phase != Phase.BATTLE) {
            System.out.println("[LiTo] C_DIALOG rejected invalid-phase=" + phase
                    + " object=" + objectId);
            return;
        }
        if (observer || playerHp <= 0 || rejectWhileParalyzed("C_DIALOG")) {
            return;
        }
        pendingHouseAuctionBid = null;

        if (rentalTownRoomState) {
            openRentalTownHypertext(objectId);
            return;
        }

        if (objectId == repairNpcObjectId()) {
            ArenaMapCatalog.Point npc = repairNpcPoint();
            if (npc == null || repairNpcDistance(npc) > 3) {
                System.out.println("[LiTo] C_DIALOG rejected repair-npc-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            pendingRepairNpc = new PendingRepairNpc(objectId, Phase.BATTLE,
                    activeInteractionContext(),
                    System.nanoTime() + REPAIR_CONTEXT_TIMEOUT_NANOS);
            sendEncrypted(Protocol.hypertext(objectId, REPAIR_NPC_HTML, "", List.of()),
                    "S_HYPERTEXT html=" + REPAIR_NPC_HTML + " repair-npc=" + objectId);
            return;
        }

        if (objectId == spellShopNpcObjectId()) {
            ArenaMapCatalog.Point npc = spellShopNpcPoint();
            if (npc == null || spellShopNpcDistance(npc) > 5) {
                System.out.println("[LiTo] C_DIALOG rejected spell-shop-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            String html = spellShopInitialHtml();
            sendEncrypted(Protocol.hypertext(objectId, html, "", List.of()),
                    "S_HYPERTEXT html=" + html + " spell-shop=" + objectId);
            return;
        }

        if (objectId == spellMaterialNpcObjectId()) {
            ArenaMapCatalog.Point npc = spellMaterialNpcPoint();
            if (npc == null || spellMaterialNpcDistance(npc) > 5) {
                System.out.println("[LiTo] C_DIALOG rejected spell-material-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            sendEncrypted(Protocol.hypertext(objectId, SPELL_MATERIAL_NPC_HTML, "", List.of()),
                    "S_HYPERTEXT html=" + SPELL_MATERIAL_NPC_HTML
                            + " spell-material-npc=" + objectId);
            return;
        }

        if (objectId == classicMerchantNpcObjectId()) {
            ArenaMapCatalog.Point npc = classicMerchantNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5) {
                System.out.println("[LiTo] C_DIALOG rejected classic-merchant-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            clearPendingClassicList();
            sendEncrypted(Protocol.hypertext(objectId, CLASSIC_MERCHANT_NPC_HTML, "", List.of()),
                    "S_HYPERTEXT html=" + CLASSIC_MERCHANT_NPC_HTML
                            + " classic-merchant=" + objectId);
            return;
        }

        if (objectId == warehouseNpcObjectId()) {
            ArenaMapCatalog.Point npc = warehouseNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5) {
                System.out.println("[LiTo] C_DIALOG rejected warehouse-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            armWarehouseDeposits(objectId);
            sendEncrypted(Protocol.hypertext(objectId, WAREHOUSE_NPC_HTML, "", List.of()),
                    "S_HYPERTEXT html=" + WAREHOUSE_NPC_HTML + " warehouse=" + objectId);
            return;
        }

        if (objectId == houseAuctionBoardObjectId()) {
            ArenaMapCatalog.Point board = houseAuctionBoardPoint();
            if (board == null || classicNpcDistance(board) > 5) {
                pendingHouseAuctionBid = null;
                System.out.println("[LiTo] C_DIALOG rejected house-auction-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            pendingHouseAuctionBid = null;
            sendHouseAuctionList("dialog");
            return;
        }

        if (objectId == mercenaryCommanderNpcObjectId()) {
            ArenaMapCatalog.Point npc = mercenaryCommanderNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5) {
                System.out.println("[LiTo] C_DIALOG rejected mercenary-commander-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            sendEncrypted(Protocol.hypertext(objectId,
                            CastleMercenaryCatalog.COMMANDER_HTML, "", List.of(playerName())),
                    "S_HYPERTEXT html=" + CastleMercenaryCatalog.COMMANDER_HTML
                            + " mercenary-commander=" + objectId);
            return;
        }

        if (objectId == castleStewardNpcObjectId()) {
            ArenaMapCatalog.Point npc = castleStewardNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5) {
                pendingCastleAdmin = null;
                pendingMercenaryAdmin = null;
                pendingCastleSecurity = null;
                System.out.println("[LiTo] C_DIALOG rejected castle-steward-distance object="
                        + objectId + " player=" + playerName());
                return;
            }
            pendingCastleAdmin = null;
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            CastleSummary castle = selectedLegacyCastle();
            CastleStewardProfile profile = castleStewardProfile(
                    castle == null ? 5 : castle.castleId());
            boolean owner = ownsLegacyCastle(castle);
            String html = profile.htmlPrefix() + (owner ? "1" : castle == null ? "7" : "6");
            List<String> arguments = !owner && castle != null
                    ? List.of(playerName()) : List.of();
            sendEncrypted(Protocol.hypertext(objectId, html, "", arguments),
                    "S_HYPERTEXT html=" + html + " castle-steward=" + objectId
                            + " authority=" + (owner ? "owner" : castle == null ? "none" : "member"));
            return;
        }

        BattleCompanion owned = ownedCompanion(objectId);
        if (owned == null) {
            boolean belongsToPeer = peerOwnsCompanion(objectId);
            System.out.println("[LiTo] C_DIALOG rejected object=" + objectId
                    + " result=" + (belongsToPeer ? "companion-not-owned" : "target-not-dialog-capable"));
            return;
        }
        BattleCompanion.Snapshot companion = owned.snapshot();
        if (!companion.active()) {
            System.out.println("[LiTo] C_DIALOG rejected object=" + objectId
                    + " result=companion-dismissed");
            return;
        }
        sendEncrypted(Protocol.hypertext(companion.objectId(), "anicom", "",
                        companion.anicomArguments()),
                "S_HYPERTEXT html=anicom object=" + companion.objectId()
                        + " posture=" + companion.posture());
    }

