    private void openClassicCastleSteward(ClassicWorldNpcCatalog.StaticNpc staticNpc) throws IOException {
        this.pendingCastleAdmin = null;
        this.pendingMercenaryAdmin = null;
        this.pendingCastleSecurity = null;
        if (this.classicNpcDistance(new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this))) > 5) {
            System.out.println("[LiTo] C_DIALOG classic-world castle steward rejected distance player=" + this.playerName());
            return;
        }
        CastleSummary castleSummary = this.selectedLegacyCastle();
        int n = this.classicCastleSceneId();
        boolean bl = castleSummary != null && castleSummary.castleId() == n;
        boolean bl2 = bl && this.ownsLegacyCastle(castleSummary);
        CastleStewardProfile castleStewardProfile = ClientSession.castleStewardProfile(n);
        String string = castleStewardProfile.htmlPrefix() + (bl2 ? "1" : (bl ? "6" : "7"));
        List<String> list = bl && !bl2 ? List.of(this.playerName()) : List.of();
        this.sendEncrypted(Protocol.hypertext(staticNpc.objectId(), string, "", list), "S_HYPERTEXT classic-world castle-steward=" + n + " html=" + string + " authority=" + (bl2 ? "owner" : (bl ? "member" : "none")));
    }

