    private void handleClassicWorldDesireKarmaManager(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        int amount = ClassicWorldDesireCaveActionCatalog.soulCrystalCount(
                request.action());
        int cost = ClassicWorldDesireCaveActionCatalog.soulCrystalKarmaCost(
                request.action());
        if (amount == 0 || karma.value() < 10_000_000) return;
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        InventoryCatalog.Definition reward = InventoryCatalog.find(40678);
        if (reward == null || !next.add(reward, amount)) {
            sendEncrypted(Protocol.messageCode(263),
                    "S_MESSAGE_CODE Desire-karma-manager-capacity=263");
            return;
        }
        int nextKarma = clampDesireCaveKarma((long) karma.value() - cost);
        saveClassicWorldDesireCaveMutation(previous, next, quests, nextKarma);
        sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                "S_MESSAGE_CODE Desire-karma-manager-reward=143 item=40678 amount="
                        + amount);
        sendEncrypted(Protocol.messageCode(1080),
                "S_MESSAGE_CODE Desire-karma-manager=1080 cost=" + cost);
        closeClassicWorldDesireCaveHtml(npc, request.action());
    }

    private void saveClassicWorldDesireCaveMutation(RuntimeInventory runtimeInventory, RuntimeInventory runtimeInventory2, Map<Integer, Integer> map, int n) throws IOException {
        this.state.saveDesireCaveState(this.stateCharacter(), this.shopPoints, runtimeInventory2.catalogCounts(), runtimeInventory2.catalogItemStates(), map, n);
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        if (runtimeInventory != runtimeInventory2 || !runtimeInventory.catalogCounts().equals(runtimeInventory2.catalogCounts()) || !runtimeInventory.catalogItemStates().equals(runtimeInventory2.catalogItemStates())) {
            this.sendInventoryDelta(runtimeInventory, this.inventory);
        }
    }

    private static int clampDesireCaveKarma(long value) {
        return (int) Math.max(-15_500_000L, Math.min(15_500_000L, value));
    }

    private static void removeUpToCatalog(
            RuntimeInventory target, long itemId, int maximum) {
        int available = target.catalogCounts().getOrDefault(itemId, 0);
        int amount = Math.min(available, maximum);
        if (amount > 0 && !target.removeCatalog(itemId, amount)) {
            throw new IllegalStateException("validated Desire Cave removal failed");
        }
    }

    private static void removeAllCatalog(RuntimeInventory target, long itemId) {
        int available = target.catalogCounts().getOrDefault(itemId, 0);
        if (available > 0 && !target.removeCatalog(itemId, available)) {
            throw new IllegalStateException("validated Desire Cave removal failed");
        }
    }

