    private void broadcastDwarfCastleDoors(
            List<ClassicWorldDwarfCastleDoorState.Snapshot> changed,
            String reason) throws IOException {
        for (ClassicWorldDwarfCastleDoorState.Snapshot door : changed) {
            int action = door.open()
                    ? BattleDoor.ACTION_OPEN : BattleDoor.ACTION_CLOSED;
            int passable = door.open()
                    ? BattleDoor.PASSABLE : BattleDoor.NOT_PASSABLE;
            byte[] actionPacket = Protocol.objectAction(
                    door.definition().objectId(), action);
            for (ClientSession member : classicWorldMembers(
                    ClassicWorldDwarfCastleCatalog.MAP_ID)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        door.definition().x(), door.definition().y())) {
                    continue;
                }
                member.sendEncrypted(actionPacket,
                        "S_ACTION Dwarf-castle-door=" + door.definition().doorId()
                                + " action=" + action + " reason=" + reason);
                member.sendDwarfCastleDoorAttributes(
                        door.definition(), passable, reason);
            }
        }
    }

    private void sendDwarfCastleDoorAttributes(
            ClassicWorldDwarfCastleCatalog.Door door,
            int passable, String reason) throws IOException {
        for (int edge = door.edgeLow(); edge <= door.edgeHigh(); edge++) {
            int x = door.direction() == 0 ? edge : door.entranceX();
            int y = door.direction() == 0 ? door.entranceY() : edge;
            sendEncrypted(Protocol.doorAttribute(
                            x, y, door.direction(), passable),
                    "S_CHANGE_ATTR Dwarf-castle-door=" + door.doorId()
                            + " x=" + x + " y=" + y
                            + " direction=" + door.direction()
                            + " passable=" + passable + " reason=" + reason);
        }
    }

