    /** Exact retained {@code NpcMakingExecutor} semantics for imported catalogs. */
    private void performClassicWorldCraft(
            ClassicWorldCraftCatalog.Recipe recipe, int amount) throws IOException {
        if (recipe == null || amount <= 0 || phase != Phase.WORLD
                || observer || playerHp <= 0 || classicWorldMapId != recipe.mapId()) {
            return;
        }
        if (battleLevel() < recipe.minimumLevel()) {
            sendEncrypted(Protocol.messageCode(916),
                    "S_MESSAGE_CODE classic-world-craft-level=916 recipe=" + recipe.id());
            return;
        }
        if (recipe.successRate() != 1_000 || recipe.failItemId() != 0) {
            throw new IOException("unsupported retained classic-world crafting probability contract");
        }

        boolean shortage = false;
        for (ClassicWorldCraftCatalog.MakingItem material : recipe.materials()) {
            if (material.enchant() != -1) {
                throw new IOException("unsupported enchanted classic-world crafting material");
            }
            long required;
            try {
                required = Math.multiplyExact((long) material.count(), amount);
            } catch (ArithmeticException overflow) {
                return;
            }
            long available = inventory.items().stream()
                    .filter(item -> item.definition().catalogId() == material.itemId())
                    .mapToLong(RuntimeInventory.Item::quantity).sum();
            if (available >= required) continue;
            shortage = true;
            InventoryCatalog.Definition definition =
                    ClassicWorldCraftCatalog.inventoryDefinition(material.itemId());
            String name = definition == null
                    ? Integer.toString(material.itemId()) : definition.name();
            long missing = required - available;
            sendEncrypted(Protocol.messageCode(337, name + " (" + missing + ")"),
                    "S_MESSAGE_CODE classic-world-craft-shortage=337 recipe="
                            + recipe.id() + " item=" + material.itemId()
                            + " shortage=" + missing);
        }
        if (shortage) return;

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        try {
            for (ClassicWorldCraftCatalog.MakingItem material : recipe.materials()) {
                long required = Math.multiplyExact((long) material.count(), amount);
                if (!next.removeCatalog(material.itemId(), required)) {
                    throw new IllegalStateException("validated crafting material vanished");
                }
            }
            for (ClassicWorldCraftCatalog.MakingItem result : recipe.results()) {
                if (result.enchant() < 0) {
                    throw new IOException("invalid classic-world crafting result enchant");
                }
                long quantity = Math.multiplyExact((long) result.count(), amount);
                InventoryCatalog.Definition definition =
                        ClassicWorldCraftCatalog.inventoryDefinition(result.itemId());
                if (definition == null) {
                    throw new IOException("classic-world crafting item definition vanished");
                }
                boolean added = result.enchant() == 0
                        ? next.add(definition, quantity)
                        : addEnchantedCraftingResult(
                                next, definition, quantity, result.enchant());
                if (!added) {
                    sendEncrypted(Protocol.messageCode(263),
                            "S_MESSAGE_CODE classic-world-craft-capacity=263 recipe="
                                    + recipe.id());
                    return;
                }
            }
        } catch (ArithmeticException overflow) {
            sendEncrypted(Protocol.messageCode(263),
                    "S_MESSAGE_CODE classic-world-craft-capacity=263 recipe="
                            + recipe.id() + " reason=quantity-overflow");
            return;
        }
        if (BattleInventoryWeight.weight240(
                weightProfile(next, System.nanoTime())) >= 240) {
            sendEncrypted(Protocol.messageCode(270),
                    "S_MESSAGE_CODE classic-world-craft-weight=270 recipe="
                            + recipe.id());
            return;
        }

        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);
        for (ClassicWorldCraftCatalog.MakingItem result : recipe.results()) {
            long quantity = (long) result.count() * amount;
            InventoryCatalog.Definition definition =
                    ClassicWorldCraftCatalog.inventoryDefinition(result.itemId());
            if (definition.stackable()) {
                String obtained = quantity == 1 ? definition.name()
                        : definition.name() + " (" + quantity + ")";
                sendEncrypted(Protocol.messageCode(403, obtained),
                        "S_MESSAGE_CODE classic-world-craft-success=403 recipe="
                                + recipe.id() + " item=" + result.itemId()
                                + " quantity=" + quantity);
            } else {
                for (long index = 0; index < quantity; index++) {
                    sendEncrypted(Protocol.messageCode(403, definition.name()),
                            "S_MESSAGE_CODE classic-world-craft-success=403 recipe="
                                    + recipe.id() + " item=" + result.itemId()
                                    + " quantity=1");
                }
            }
        }
        System.out.println("[LiTo] classic-world craft accepted player=" + playerName()
                + " map=" + classicWorldMapId + " npc=" + recipe.npcId()
                + " recipe=" + recipe.id() + " action=" + recipe.action()
                + " amount=" + amount);
    }

    private static boolean addEnchantedCraftingResult(
            RuntimeInventory target, InventoryCatalog.Definition definition,
            long quantity, int enchantLevel) {
        if (target == null || definition == null || quantity <= 0
                || quantity > Integer.MAX_VALUE || enchantLevel <= 0
                || (!definition.weapon() && !definition.armor())) {
            return false;
        }
        for (long index = 0; index < quantity; index++) {
            RuntimeInventory.PersistentItem state = new RuntimeInventory.PersistentItem(
                    0, 1, enchantLevel, 0, definition.identified(),
                    definition.blessing(), false, false, null);
            if (target.addDistinctState(definition, state) == 0) return false;
        }
        return true;
    }

    /** Retained pet status 6: delete collar/pet and replace it with a one-shot wild monster. */
    private boolean liberateClassicWorldPet(
            BattleCompanion owned, BattleCompanion.Snapshot companion)
            throws IOException {
        SourcePetTemplate source;
        try {
            source = selectedSourceAccounts().petTemplate(companion.npcId());
        } catch (Exception sourceFailure) {
            throw new IOException("cannot load selected-source liberated pet row for NPC "
                    + companion.npcId(), sourceFailure);
        }
        List<RuntimeInventory.Item> releasedItems = owned.carriedItems();
        ClassicWorldMonsterPopulation.Snapshot reservation = hub.reserveReleasedPet(
                classicWorldMapId, classicWorldInstanceId,
                companion, source, releasedItems);
        if (reservation == null) {
            System.out.println("[LiTo] persistent pet liberation rejected owner="
                    + playerName() + " pet=" + companion.objectId()
                    + " result=wild-replacement-unavailable");
            return false;
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        RuntimeInventory.Item collar = next.item(companion.collarObjectId());
        if (collar == null || collar.definition().catalogId()
                != companion.collarCatalogId()
                || !next.remove(companion.collarObjectId(), 1)) {
            hub.cancelReleasedPet(
                    classicWorldMapId, classicWorldInstanceId,
                    reservation.objectId());
            throw new IOException("persistent pet collar disappeared before liberation");
        }
        try {
            state.saveEconomyStateDeletingPet(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates(), companion.collarObjectId());
        } catch (IOException | RuntimeException failure) {
            hub.cancelReleasedPet(
                    classicWorldMapId, classicWorldInstanceId,
                    reservation.objectId());
            throw failure;
        }
        ClassicWorldMonsterPopulation.Snapshot released =
                hub.commitReleasedPet(
                        classicWorldMapId, classicWorldInstanceId,
                        reservation.objectId());
        if (released == null) {
            throw new IllegalStateException(
                    "durable pet liberation could not commit wild replacement");
        }

        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);
        owned.deactivate();
        owned.clearCarriedItems();
        hub.transferClassicWorldMonsterTargets(
                companion.objectId(), playerObjectId());
        synchronized (tamedCompanions) {
            tamedCompanions.removeIf(candidate ->
                    candidate.snapshot().objectId() == companion.objectId());
        }
        byte[] remove = Protocol.removeObject(companion.objectId());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    companion.x(), companion.y())) continue;
            member.sendEncrypted(remove,
                    "S_REMOVE_OBJECT liberated-pet=" + companion.objectId()
                            + " owner=" + playerName());
            member.sendClassicWorldMonster(released, "pet-liberation");
        }
        System.out.println("[LiTo] persistent pet liberated owner=" + playerName()
                + " pet=" + companion.objectId() + " collar="
                + companion.collarObjectId() + " wild=" + released.objectId()
                + " npc=" + released.npcId() + " hp=" + released.currentHp()
                + "/" + released.maximumHp() + " carried-items="
                + releasedItems.size() + " collar-deleted=true pet-row-deleted=true");
        return true;
    }

    private long controlledCompanionContext() {
        return phase == Phase.WORLD && ClassicWorldMapCatalog.supports(classicWorldMapId)
                ? -((long) classicWorldMapId + 1L) : currentRoomId;
    }

    private void handleShapeChangeAction(Protocol.HypertextActionRequest request,
                                         PendingShapeChange pending) throws IOException {
        // Retained L1ActionPc consumes the one-shot shape-change capability
        // before it dispatches the chosen string, including unknown/favorite
        // actions.  A replay therefore cannot reuse a prior spell cast.
        boolean contextValid;
        synchronized (this) {
            // Another caster may have replaced the menu capability after the
            // request thread captured it.  Consume only the exact token being
            // answered so a stale callback cannot erase the newer menu.
            if (pendingShapeChange != pending) {
                System.out.println("[LiTo] C_HACTION shape-change rejected stale token object="
                        + request.worldObjectId() + " phase=" + phase);
                return;
            }
            pendingShapeChange = null;
            boolean battleContext = pending.originPhase() == Phase.BATTLE
                    && phase == Phase.BATTLE && currentRoomId == pending.roomId();
            boolean worldContext = pending.originPhase() == Phase.WORLD
                    && phase == Phase.WORLD
                    && classicWorldMapId == pending.mapId()
                    && classicWorldInstanceId == pending.instanceId();
            contextValid = (battleContext || worldContext)
                    && pending.targetObjectId() == playerObjectId()
                    && request.worldObjectId() == playerObjectId()
                    && request.parameter().isEmpty()
                    && !observer && playerHp > 0;
        }
        if (!contextValid) {
            System.out.println("[LiTo] C_HACTION shape-change rejected stale context object="
                    + request.worldObjectId() + " phase=" + phase
                    + " room=" + currentRoomId + " map=" + classicWorldMapId
                    + " instance=" + classicWorldInstanceId
                    + " action=" + request.action());
            return;
        }

        if (request.action().equalsIgnoreCase("none")) {
            BattlePolymorphCatalog.Form previous;
            synchronized (this) {
                boolean contextStillValid = pending.originPhase() == Phase.BATTLE
                        ? phase == Phase.BATTLE && currentRoomId == pending.roomId()
                        : pending.originPhase() == Phase.WORLD
                            && phase == Phase.WORLD
                            && classicWorldMapId == pending.mapId()
                            && classicWorldInstanceId == pending.instanceId();
                if (!contextStillValid || observer || playerHp <= 0) return;
                previous = polymorphStatus.clear();
            }
            sendEncrypted(Protocol.closeHypertext(playerObjectId()),
                    "S_CLOSE_LIST shape-change-none object=" + playerObjectId());
            if (previous != null) broadcastPolymorphAppearance("shape-change-none");
            System.out.println("[LiTo] C_HACTION shape-change cleared player=" + playerName());
            return;
        }

        BattlePolymorphCatalog.Form form = BattlePolymorphCatalog.find(request.action());
        if (form == null || !form.standardMenu()) {
            // mon_fav1..3 are client favorite placeholders.  The retained
            // selected server has no server-side favorite mapping and likewise
            // consumes the capability without inventing a form.
            System.out.println("[LiTo] C_HACTION shape-change ignored unknown selection="
                    + request.action());
            return;
        }
        if (characterLevel() < form.minimumLevel()) {
            sendEncrypted(Protocol.messageCode(181),
                    "S_MESSAGE_CODE shape-change-level=181 selection=" + form.selection());
            System.out.println("[LiTo] C_HACTION shape-change rejected level="
                    + characterLevel() + " required=" + form.minimumLevel()
                    + " selection=" + form.selection());
            return;
        }

        PolymorphEquipmentChange equipmentChange;
        synchronized (this) {
            boolean contextStillValid = pending.originPhase() == Phase.BATTLE
                    ? phase == Phase.BATTLE && currentRoomId == pending.roomId()
                    : pending.originPhase() == Phase.WORLD
                        && phase == Phase.WORLD
                        && classicWorldMapId == pending.mapId()
                        && classicWorldInstanceId == pending.instanceId();
            if (!contextStillValid || observer || playerHp <= 0) return;
            polymorphStatus.activate(System.nanoTime(), form, pending.durationSeconds());
            equipmentChange = preparePolymorphEquipment(form);
        }
        sendEncrypted(Protocol.closeHypertext(playerObjectId()),
                "S_CLOSE_LIST shape-change-selected object=" + playerObjectId());
        publishPolymorphEquipmentChange(equipmentChange, "shape-change-selected");
        broadcastPolymorphAppearance("shape-change-selected");
        System.out.println("[LiTo] C_HACTION shape-change player=" + playerName()
                + " selection=" + form.selection() + " gfx=" + form.gfx()
                + " walk-action=" + battleWalkAction()
                + " duration=" + pending.durationSeconds()
                + " skill-usable=" + form.skillUsable()
                + " phase=" + pending.originPhase()
                + " map=" + (pending.originPhase() == Phase.WORLD
                    ? pending.mapId() : 0)
                + " instance=" + (pending.originPhase() == Phase.WORLD
                    ? pending.instanceId() : -1));
    }

    private void requestPlayerTrade(byte[] payload) throws IOException {
        Protocol.ExchangeRequest request = Protocol.exchangeRequest(payload);
        ClientSession target = hub.beginPlayerTrade(currentRoomId, this,
                request.targetObjectId());
        if (target == null) {
            System.out.println("[LiTo] C_ASK_XCHG rejected requester=" + playerName()
                    + " target=" + request.targetObjectId() + " result=invalid-state-or-distance");
            return;
        }
        // The native client owns one S_ASK callback at a time. A trade prompt
        // supersedes a stale pet-name prompt instead of leaving two server
        // tokens able to consume the same C_ANSWER opcode.
        target.clearPendingAskCallbacks();
        target.sendEncrypted(Protocol.exchangeAsk(playerName()),
                "S_ASK question=252 trade-requester=" + playerName());
        System.out.println("[LiTo] C_ASK_XCHG pending requester=" + playerName()
                + " target=" + target.playerName());
    }

    private void addPlayerTradeItem(byte[] payload) throws IOException {
        Protocol.ExchangeItemRequest request = Protocol.exchangeItemRequest(payload);
        GameHub.TradeOfferOutcome outcome = hub.addPlayerTradeItem(this,
                request.inventoryObjectId(), request.quantity());
        if (outcome == null) {
            System.out.println("[LiTo] C_ADD_XCHG rejected player=" + playerName()
                    + " object=" + request.inventoryObjectId()
                    + " quantity=" + request.quantity());
            return;
        }
        outcome.owner().sendInventoryDelta(outcome.beforeDisplay(), outcome.afterDisplay());
        String displayName = exchangeDisplayName(outcome.item(), outcome.quantity());
        outcome.owner().sendEncrypted(Protocol.exchangeAddItem(0,
                        outcome.item().definition().icon(), displayName,
                        outcome.item().blessing()),
                "S_ADD_XCHG side=self object=" + outcome.item().objectId()
                        + " quantity=" + outcome.quantity());
        outcome.partner().sendEncrypted(Protocol.exchangeAddItem(1,
                        outcome.item().definition().icon(), displayName,
                        outcome.item().blessing()),
                "S_ADD_XCHG side=partner owner=" + outcome.owner().playerName()
                        + " quantity=" + outcome.quantity());
    }

    private void confirmPlayerTrade(byte[] payload) throws IOException {
        Protocol.requireExchangeOpcodeOnly(payload, Protocol.C_ACCEPT_XCHG);
        GameHub.TradeTerminalOutcome outcome = hub.confirmPlayerTrade(this);
        if (outcome.status() == GameHub.TradeConfirmStatus.INVALID) {
            System.out.println("[LiTo] C_ACCEPT_XCHG rejected player=" + playerName()
                    + " result=no-open-trade-or-replay");
            return;
        }
        if (outcome.status() == GameHub.TradeConfirmStatus.WAITING) {
            System.out.println("[LiTo] C_ACCEPT_XCHG waiting player=" + playerName());
            return;
        }
        finishPlayerTrade(outcome,
                outcome.status() == GameHub.TradeConfirmStatus.COMPLETED
                        ? Protocol.ExchangeTerminalResult.COMPLETED
                        : Protocol.ExchangeTerminalResult.CANCELLED_OR_FAILED,
                outcome.status() == GameHub.TradeConfirmStatus.COMPLETED
                        ? "committed" : "validation-failed", null);
    }

    private void cancelPlayerTrade(byte[] payload) throws IOException {
        Protocol.requireExchangeOpcodeOnly(payload, Protocol.C_CANCEL_XCHG);
        GameHub.TradeTerminalOutcome outcome = hub.cancelPlayerTrade(this);
        if (outcome.status() == GameHub.TradeConfirmStatus.INVALID) {
            System.out.println("[LiTo] C_CANCEL_XCHG ignored player=" + playerName()
                    + " result=no-active-trade");
            return;
        }
        finishPlayerTrade(outcome, Protocol.ExchangeTerminalResult.CANCELLED_OR_FAILED,
                "client-cancel", null);
    }

    private void finishPlayerTrade(GameHub.TradeTerminalOutcome outcome,
                                   Protocol.ExchangeTerminalResult result,
                                   String reason, ClientSession skip) throws IOException {
        IOException firstError = null;
        for (GameHub.TradeInventoryChange change : outcome.inventoryChanges()) {
            if (change.session() == skip) continue;
            try {
                change.session().sendInventoryDelta(change.before(), change.after());
            } catch (IOException error) {
                if (firstError == null) firstError = error;
            }
        }
        if (outcome.exchangeWindowOpen()) {
            byte[] terminal = Protocol.exchangeResult(result);
            for (ClientSession participant : outcome.participants()) {
                if (participant == skip) continue;
                try {
                    participant.sendEncrypted(terminal,
                            "S_XCHG_RESULT result=" + result.wireValue()
                                    + " reason=" + reason);
                } catch (IOException error) {
                    if (firstError == null) firstError = error;
                }
            }
        }
        System.out.println("[LiTo] player trade terminal result=" + result
                + " reason=" + reason + " participants="
                + outcome.participants().stream().map(ClientSession::playerName).toList());
        if (firstError != null) throw firstError;
    }

    private void cancelActivePlayerTrade(String reason, boolean notifySelf) throws IOException {
        GameHub.TradeTerminalOutcome outcome = hub.cancelPlayerTrade(this);
        if (outcome.status() == GameHub.TradeConfirmStatus.INVALID) return;
        finishPlayerTrade(outcome, Protocol.ExchangeTerminalResult.CANCELLED_OR_FAILED,
                reason, notifySelf ? null : this);
    }

    private static String exchangeDisplayName(RuntimeInventory.Item item, long quantity) {
        String name = item.nativeViewName();
        return item.definition().stackable() ? name + " (" + quantity + ")" : name;
    }

