    private void version(byte[] byArray) throws IOException {
        if (this.phase != Phase.KEY_SENT) {
            return;
        }
        Protocol.VersionRequest versionRequest = Protocol.versionRequest(byArray);
        System.out.printf("[LiTo] C_VERSION magic=0x%04X product=0x%X build=0x%04X fromCD=%d%n", versionRequest.magic(), versionRequest.product(), versionRequest.build(), versionRequest.fromCd());
        if (!Protocol.supportedVersion(versionRequest)) {
            this.sendEncrypted(Protocol.versionRejected(), "S_VERSION_CHECK rejected");
            return;
        }
        if (this.config.versionResponseDelayMs() > 0) {
            try {
                Thread.sleep(this.config.versionResponseDelayMs());
            }
            catch (InterruptedException interruptedException) {
                Thread.currentThread().interrupt();
                throw new IOException("version response delay interrupted", interruptedException);
            }
        }
        this.sendEncrypted(Protocol.versionAccepted(), "S_VERSION_CHECK accepted");
        NativePlayerCommit.scene(this, (Object)Phase.VERSION_OK, "phase");
    }

    private void login(byte[] payload) throws Exception {
        if (phase != Phase.VERSION_OK) return;
        Protocol.LoginRequest request;
        try {
            request = Protocol.loginRequest(payload);
        } catch (IllegalArgumentException malformed) {
            System.out.println("[LiTo] rejected malformed C_LOGIN: " + malformed.getMessage());
            sendLoginFailure(Protocol.LoginCheckResult.ACCESS_FAILED, "malformed-login");
            return;
        }
        String suppliedAccount = request.account();
        String suppliedPassword = request.password();
        long suppliedClientAddress = request.clientAddress();
        System.out.printf("[LiTo] C_LOGIN accountChars=%d passwordChars=%d clientAddress=%s connectorBytes=%d layout=%s%n",
                suppliedAccount.length(), suppliedPassword.length(),
                littleEndianIpv4(suppliedClientAddress),
                request.connector().getBytes(Protocol.LEGACY_TEXT).length,
                request.layout());
        // The protected LiTo 3.81C client sends one opaque, oversized
        // launcher-handoff credential record immediately after reconnecting
        // to the game endpoint, then follows it with the ordinary account /
        // password C_LOGIN.  It is not an authentication attempt and must not
        // receive S_LOGIN_CHECK failure: that delayed failure tears down the
        // native channel screen after the valid login has already succeeded.
        // Ignore at most one tightly bounded preamble and keep VERSION_OK so
        // only the following ordinary C_LOGIN can authenticate the session.
        if (!nativeGameLoginPreambleIgnored
                && isNativeGameLoginPreamble(endpoint, suppliedAccount, suppliedPassword)) {
            nativeGameLoginPreambleIgnored = true;
            System.out.printf("[LiTo] ignored native game-login handoff preamble accountChars=%d passwordChars=%d%n",
                    suppliedAccount.length(), suppliedPassword.length());
            return;
        }
        if (suppliedAccount.isBlank() || suppliedPassword.isBlank()
                || suppliedAccount.length() > 64 || suppliedPassword.length() > 128) {
            sendLoginFailure(Protocol.LoginCheckResult.ACCESS_FAILED, "invalid-credential-shape");
            return;
        }
        AuthResult auth;
        try {
            auth = accounts.authenticate(suppliedAccount, suppliedPassword);
        } catch (Exception databaseError) {
            System.out.println("[LiTo] authentication backend failed: "
                    + databaseError.getClass().getSimpleName() + ": " + databaseError.getMessage());
            sendLoginFailure(Protocol.LoginCheckResult.SYSTEM_ERROR, "authentication-backend-error");
            return;
        }
        if (!auth.accepted()) {
            sendLoginFailure(auth.banned() ? Protocol.LoginCheckResult.ACCOUNT_BANNED
                    : Protocol.LoginCheckResult.ACCESS_FAILED,
                    auth.banned() ? "account-banned" : "invalid-account-or-password");
            return;
        }
        if (state.isAccountBanned(SourceLogin.account(this, auth.account()))) {
            sendLoginFailure(Protocol.LoginCheckResult.ACCOUNT_BANNED, "sidecar-account-banned");
            return;
        }

        account = auth.account();

        SourceAdministration.clear(this);
        authenticatedClassicSources = auth.authorizedClassicSources();
        String stagedClassicSource = null;
        GameHub.ChannelPortHandoff stagedChannelPortHandoff = null;
        if (endpoint == Endpoint.LOGIN) {
            // A fresh authenticated LOGIN invalidates an abandoned selector
            // handoff from an older attempt. C_C8/C35 will stage the new one.
            hub.clearClassicSourceHandoff(SourceLogin.account(this, account));
        } else {
            stagedClassicSource = hub.pendingClassicSourceHandoff(SourceLogin.account(this, account));
            if (stagedClassicSource != null) {
                String canonical = canonicalClassicSource(stagedClassicSource);
                if (canonical != null && isClassicSourceAuthorized(canonical)) {
                    NativePlayerCommit.scene(this, canonical, "selectedClassicServerName");
                    SourceAdministration.clear(this);
                } else {
                    System.out.println("[LiTo] discarded invalid staged classic source account="
                            + mask(account));
                    stagedClassicSource = null;
                }
            }
            GameHub handoffHub = hub;
            String handoffAccount = account;
            int handoffChannel = boundChannelId;
            stagedChannelPortHandoff = handoffHub.pendingChannelPortHandoff(
                    SourceLogin.account(this, handoffAccount), handoffChannel);
            if (stagedChannelPortHandoff != null) {
                String canonical = canonicalClassicSource(
                        stagedChannelPortHandoff.source());
                if (canonical == null || !isClassicSourceAuthorized(canonical)) {
                    System.out.println("[LiTo] discarded invalid channel-port source account="
                            + mask(account) + " bound-channel=" + boundChannelId);
                    stagedChannelPortHandoff = null;
                } else {
                    NativePlayerCommit.scene(this, canonical, "selectedClassicServerName");
                    SourceAdministration.clear(this);
                }
            }
        }
        try {
            SourceCharacterDirectory directory =
                    loadCharacterDirectory(selectedClassicServerName);
            List<CastleWarSchedule> castleWarSchedules = accounts
                    .repositoryForClassicSource(selectedClassicServerName)
                    .castleWarSchedules();
            hub.registerClassicCastleWarSchedules(
                    selectedClassicServerName, castleWarSchedules);
            applyCharacterDirectory(directory);
            if (stagedChannelPortHandoff != null) {
                String handoffCharacter = stagedChannelPortHandoff.character();
                if (characters.stream().noneMatch(character ->
                        character.name().equalsIgnoreCase(handoffCharacter))) {
                    System.out.println("[LiTo] discarded channel-port handoff missing character account="
                            + mask(account) + " bound-channel=" + boundChannelId);
                    stagedChannelPortHandoff = null;
                }
            }
        } catch (Exception databaseError) {
            account = null;
            SourceAdministration.clear(this);
            authenticatedClassicSources = Set.of();
            System.out.println("[LiTo] character lookup failed: "
                    + databaseError.getClass().getSimpleName() + ": " + databaseError.getMessage());
            sendLoginFailure(Protocol.LoginCheckResult.SYSTEM_ERROR, "character-backend-error");
            return;
        }
        if (!hub.acceptAuthenticatedAccount(this, endpoint, account)) {
            account = null;
            SourceAdministration.clear(this);
            authenticatedClassicSources = Set.of();
            characters = List.of();
            previewCharacter = "";
            sendLoginFailure(Protocol.LoginCheckResult.ACCOUNT_IN_USE, "account-in-use");
            return;
        }
        if (endpoint == Endpoint.GAME && stagedClassicSource != null) {
            GameHub handoffHub = hub;
            String handoffAccount = account;
            String handoffSource = selectedClassicServerName;
            boolean consumed = handoffHub.consumeClassicSourceHandoff(
                    SourceLogin.account(this, handoffAccount), handoffSource);
            System.out.println("[LiTo] GAME claimed classic-source handoff source="
                    + selectedClassicServerName + " consumed=" + consumed
                    + " account=" + mask(account));
        }
        if (endpoint == Endpoint.GAME && stagedChannelPortHandoff != null) {
            channelPortHandoffTarget = stagedChannelPortHandoff.channelId();
            channelPortHandoffCharacter = stagedChannelPortHandoff.character();
            System.out.println("[LiTo] GAME claimed pending channel-port endpoint="
                    + config.gameBind() + ":"
                    + (boundChannelId < 0 ? config.port()
                    : config.channelPort(boundChannelId))
                    + " channel=" + channelPortHandoffTarget
                    + " account=" + mask(account));
        }
        NativePlayerCommit.scene(this, Phase.AUTHENTICATED, "phase");
        if (endpoint == Endpoint.GAME) {
            beginGameBootstrap();
            notifyWantedAccountLogin();
        } else {
            sendLoginBootstrap();
        }
        System.out.println("[LiTo] authenticated account=" + mask(account) + " characters=" + characters.size()
                + " origin=" + config.originSourceId() + ":" + config.originSourceName());
    }

    static boolean isNativeGameLoginPreamble(
            Endpoint endpoint, String suppliedAccount, String suppliedPassword) {
        return endpoint == Endpoint.GAME
                && suppliedAccount.length() > 64
                && suppliedAccount.length() <= 192
                && !suppliedPassword.isBlank()
                && suppliedPassword.length() <= 512;
    }

    private void beginGameBootstrap() throws IOException {
        nextLoginNoticeIndex = 0;
        pendingNoticeAck = PendingNoticeAck.NONE;
        litoNewsAcknowledgementPending = false;
        // S_FB is emitted by the LOGIN endpoint before S_F4 redirects the
        // same authenticated account to GAME.  The native client keeps that
        // directory across the socket handoff, but a per-ClientSession flag
        // does not.  Re-arm only the configured public group-1 capability on
        // the authenticated GAME session; C_CF still requires the one-shot
        // C_D9 transition, exact configured id, empty password and a selected
        // character before it can enter the isolated mode-6 room state.
        rentalTownDirectoryAdvertised = config.rentalTownDirectoryEnabled();
        rentalTownJoinPending = false;
        rentalItemSetSelection = -1;
        sendNextLoginNoticeOrBootstrap();
    }

    private void sendNextLoginNoticeOrBootstrap() throws IOException {
        List<Integer> noticeIds = config.loginNoticeMessageIds();
        if (nextLoginNoticeIndex >= noticeIds.size()) {
            pendingNoticeAck = PendingNoticeAck.NONE;
            sendGameBootstrap();
            return;
        }
        int messageId = noticeIds.get(nextLoginNoticeIndex++);
        pendingNoticeAck = messageId == 438
                ? PendingNoticeAck.LOGIN_RESULT : PendingNoticeAck.READ_NOTICE;
        sendEncrypted(Protocol.notice(messageId),
                "S_NOTICE message=" + messageId + " awaits=" + pendingNoticeAck);
    }

    private void acknowledgeReadNotice(byte[] payload) throws IOException {
        Protocol.readNotice(payload);
        if (endpoint != Endpoint.GAME || phase != Phase.AUTHENTICATED
                || pendingNoticeAck != PendingNoticeAck.READ_NOTICE) {
            System.out.println("[LiTo] C_READ_NOTICE ignored without matching pending notice phase="
                    + phase + " pending=" + pendingNoticeAck);
            return;
        }
        pendingNoticeAck = PendingNoticeAck.NONE;
        sendNextLoginNoticeOrBootstrap();
    }

    private void acknowledgeLoginResult(byte[] payload) throws IOException {
        Protocol.loginResult(payload);
        if (endpoint != Endpoint.GAME || phase != Phase.AUTHENTICATED
                || pendingNoticeAck != PendingNoticeAck.LOGIN_RESULT) {
            System.out.println("[LiTo] C_LOGIN_RESULT ignored without native message-438 capability phase="
                    + phase + " pending=" + pendingNoticeAck);
            return;
        }
        pendingNoticeAck = PendingNoticeAck.NONE;
        sendNextLoginNoticeOrBootstrap();
    }

    private void createAccount(byte[] payload) throws Exception {
        Protocol.NewAccountRequest request = Protocol.newAccountRequest(payload);
        if (phase != Phase.VERSION_OK) {
            System.out.println("[LiTo] C_NEW_ACCOUNT ignored invalid-phase=" + phase);
            return;
        }
        AccountMutationResult mutation;
        try {
            mutation = selectedSourceAccounts().createAccount(request.account(), request.password());
        } catch (Exception backendError) {
            mutation = AccountMutationResult.READ_ONLY;
            System.out.println("[LiTo] account creation backend failed: "
                    + backendError.getClass().getSimpleName() + ": " + backendError.getMessage());
        }
        Protocol.NewAccountCheckResult result = switch (mutation) {
            case SUCCESS -> Protocol.NewAccountCheckResult.RETURN_TO_LOGIN;
            case EXISTS -> Protocol.NewAccountCheckResult.ACCOUNT_ALREADY_EXISTS;
            default -> Protocol.NewAccountCheckResult.SYSTEM_ERROR_NO_TRANSITION;
        };
        sendEncrypted(Protocol.newAccountCheck(result, 0),
                "S_NEW_ACCOUNT_CHECK result=" + result.wireValue() + " mutation=" + mutation);
        System.out.println("[LiTo] C_NEW_ACCOUNT account=" + mask(request.account())
                + " type=" + request.type() + " profile-fields="
                + request.profileFields().size() + " mutation=" + mutation);
    }

    private void changePassword(byte[] payload) throws Exception {
        Protocol.PasswordChangeRequest request = Protocol.passwordChangeRequest(payload);
        if (phase != Phase.VERSION_OK) {
            System.out.println("[LiTo] C_CHANGE_PASSWORD ignored invalid-phase=" + phase);
            return;
        }
        AccountMutationResult mutation;
        try {
            mutation = selectedSourceAccounts().changePassword(
                    request.account(), request.oldPassword(), request.newPassword());
        } catch (Exception backendError) {
            mutation = AccountMutationResult.READ_ONLY;
            System.out.println("[LiTo] password-change backend failed: "
                    + backendError.getClass().getSimpleName() + ": " + backendError.getMessage());
        }
        Protocol.ChangePasswordCheckResult result = switch (mutation) {
            case SUCCESS -> Protocol.ChangePasswordCheckResult.RETURN_TO_LOGIN;
            case NOT_FOUND, WRONG_PASSWORD -> Protocol.ChangePasswordCheckResult.WRONG_PASSWORD;
            default -> Protocol.ChangePasswordCheckResult.PASSWORD_CHANGE_UNAVAILABLE;
        };
        sendEncrypted(Protocol.changePasswordCheck(result, 0),
                "S_CHANGE_PASSWORD_CHECK result=" + result.wireValue() + " mutation=" + mutation);
        System.out.println("[LiTo] C_CHANGE_PASSWORD account=" + mask(request.account())
                + " mutation=" + mutation);
    }

    private void registerQuiz(byte[] payload) throws Exception {
        Protocol.QuizRegistrationRequest request = Protocol.quizRegistrationRequest(payload);
        if (phase != Phase.VERSION_OK) {
            System.out.println("[LiTo] C_REGISTER_QUIZ ignored invalid-phase=" + phase);
            return;
        }
        AccountMutationResult mutation;
        try {
            mutation = selectedSourceAccounts().registerQuiz(request.account(), request.oldPassword(),
                    request.newPassword(), request.quizFields());
        } catch (Exception backendError) {
            mutation = AccountMutationResult.READ_ONLY;
            System.out.println("[LiTo] quiz-registration backend failed: "
                    + backendError.getClass().getSimpleName() + ": " + backendError.getMessage());
        }
        Protocol.ChangePasswordCheckResult result = switch (mutation) {
            case SUCCESS -> Protocol.ChangePasswordCheckResult.RETURN_TO_LOGIN;
            case NOT_FOUND, WRONG_PASSWORD -> Protocol.ChangePasswordCheckResult.WRONG_PASSWORD;
            default -> Protocol.ChangePasswordCheckResult.PASSWORD_CHANGE_UNAVAILABLE;
        };
        // The exact image has no dedicated S_REGISTER_QUIZ receiver.  C58
        // changes the password as part of registering two question/answer
        // pairs, while native S08 is the recovered account password result UI.
        sendEncrypted(Protocol.changePasswordCheck(result, 0),
                "S_CHANGE_PASSWORD_CHECK quiz-result=" + result.wireValue()
                        + " mutation=" + mutation);
        // Questions, answers and passwords are credentials.  Preserve only
        // the masked account and field count in process diagnostics.
        System.out.println("[LiTo] C_REGISTER_QUIZ account=" + mask(request.account())
                + " quiz-fields=" + request.quizFields().size() + " mutation=" + mutation);
    }

    private void changeAccountInfo(byte[] payload) throws Exception {
        Protocol.AccountInfoChangeRequest request = Protocol.accountInfoChangeRequest(payload);
        if (phase != Phase.VERSION_OK) {
            System.out.println("[LiTo] C_CHANGE_ACCOUNTINFO ignored invalid-phase=" + phase);
            return;
        }
        AccountMutationResult mutation;
        try {
            mutation = selectedSourceAccounts().changeAccountInfo(
                    request.account(), request.type(), request.profileFields());
        } catch (Exception backendError) {
            mutation = AccountMutationResult.READ_ONLY;
            System.out.println("[LiTo] account-info backend failed: "
                    + backendError.getClass().getSimpleName() + ": " + backendError.getMessage());
        }
        Protocol.ChangeAccountInfoCheckResult result = mutation == AccountMutationResult.SUCCESS
                ? Protocol.ChangeAccountInfoCheckResult.RETURN_TO_LOGIN
                : Protocol.ChangeAccountInfoCheckResult.SYSTEM_ERROR_NO_TRANSITION;
        sendEncrypted(Protocol.changeAccountInfoCheck(result, 0),
                "S_CHANGE_ACCOUNTINFO_CHECK result=" + result.wireValue()
                        + " mutation=" + mutation);
        // The seven native profile fields may contain personal information.
        // Preserve only field count in diagnostics; never log field contents.
        System.out.println("[LiTo] C_CHANGE_ACCOUNTINFO account=" + mask(request.account())
                + " type=" + request.type() + " profile-fields="
                + request.profileFields().size() + " mutation=" + mutation);
    }

    private void sendGameBootstrap() throws IOException {
        // S_E6 is a native server-triggered readiness barrier, not the reply
        // to C_E2. sub_48F500 answers it immediately when no modal UI is
        // active, or defers the same opcode-only acknowledgement until local
        // cleanup is complete. Do not expose the character selector until the
        // matching one-shot acknowledgement arrives.
        litoNewsAcknowledgementPending = true;
        sendEncrypted(Protocol.litoNewsTrigger(),
                "S_LITO_NEWS bootstrap readiness trigger awaits C_E2");
    }

    private void completeGameBootstrap() throws IOException {
        NativePlayerCommit.scene(this, (Object)Phase.LOBBY, "phase");
        if (!this.config.loginCommonNews().isEmpty()) {
            this.sendEncrypted(Protocol.commonNews(this.config.loginCommonNews()), "S_NEWS native login announcement bytes=" + this.config.loginCommonNews().getBytes(Protocol.LEGACY_TEXT).length);
        }
        if (this.config.characterListEnabled()) {
            this.sendCharacterDirectory();
        }
        if (this.autoSelectPendingChannelPortHandoff()) {
            return;
        }
        this.autoSelectPendingRentalBattleHandoff();
    }

    private boolean autoSelectPendingChannelPortHandoff() throws IOException {
        if (endpoint != Endpoint.GAME || phase != Phase.LOBBY
                || channelPortHandoffTarget < 0
                || channelPortHandoffCharacter.isBlank()
                || litoCharacterSelectionConsumed) return false;
        CharacterSummary handoffCharacter = characters.stream()
                .filter(character -> character.name().equalsIgnoreCase(
                        channelPortHandoffCharacter))
                .findFirst().orElse(null);
        if (handoffCharacter == null) return false;
        System.out.println("[LiTo] continuing channel-port handoff character="
                + handoffCharacter.name() + " channel=" + channelPortHandoffTarget
                + " endpoint=" + config.gameBind() + ":"
                + config.channelPort(channelPortHandoffTarget));
        // The reconnecting native client retained its selected character and
        // is already displaying the four-channel selector.  Restore server
        // ownership and data silently: emitting S_C8 here is a second UI
        // transition and makes the following direct C_CA freeze on loading.
        characterSelect(new Protocol.Writer()
                .c(Protocol.C_LITO_SELECT_CHAR)
                .s(handoffCharacter.name())
                .bytes(), false);
        return litoCharacterSelectionConsumed;
    }

    private boolean autoSelectPendingRentalBattleHandoff() throws IOException {
        if (this.endpoint != Endpoint.GAME || this.phase != Phase.LOBBY || this.accountName().isBlank() || this.litoCharacterSelectionConsumed) {
            return false;
        }
        CharacterSummary characterSummary2 = this.characters.stream().filter(characterSummary -> {
            GameHub gameHub = this.hub;
            String string2 = this.accountName();
            String string = this.stateCharacter(characterSummary.name());
            return gameHub.hasRentalBattleHandoff(SourceLogin.account(this, string2), string);
            }).findFirst().orElse(null);
        if (characterSummary2 == null) {
            return false;
        }
        System.out.println("[LiTo] continuing rental battle handoff character=" + characterSummary2.name() + " endpoint=GAME");
        this.characterSelect(new Protocol.Writer().c(201).s(characterSummary2.name()).bytes());
        return this.litoCharacterSelectionConsumed && this.rentalBattleLoadoutActive;
    }



    private void sendLoginBootstrap() throws IOException {
        sleepForBootstrap(config.loginBootstrapInitialDelayMs(), "initial");
        List<String> sequence = config.loginBootstrapSequence();
        for (int index = 0; index < sequence.size(); index++) {
            String token = sequence.get(index);
            switch (token) {
                case "login_check" -> sendLoginCheck(Protocol.LoginCheckResult.ACCEPTED, "accepted");
                case "login_ok" -> sendEncrypted(Protocol.litoLoginOk(), "S_LITO_LOGIN_OK");
                case "time_limit" -> sendEncrypted(
                        new Protocol.Writer().c(Protocol.S_LITO_TIMELIMIT).d(86_400).bytes(), "S_LITO_TIMELIMIT");
                case "classic_server_list" -> sendClassicServerList();
                case "lito_server_list" -> sendLitoServerList();
                default -> throw new IOException("unsupported login bootstrap token: " + token);
            }
            if (index + 1 < sequence.size()) {
                sleepForBootstrap(config.loginBootstrapStepDelayMs(), "between " + token + " and " + sequence.get(index + 1));
            }
        }
    }

    private void sleepForBootstrap(int delayMs, String stage) throws IOException {
        if (delayMs <= 0) return;
        System.out.println("[LiTo] bootstrap delay=" + delayMs + "ms stage=" + stage);
        try {
            Thread.sleep(delayMs);
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            throw new IOException("login bootstrap delay interrupted", ex);
        }
    }

    private void sendLoginCheck(Protocol.LoginCheckResult result, String note) throws IOException {
        sendEncrypted(Protocol.loginCheck(result, 3_600, config.serverName(), 0, 0),
                "S_LOGIN_CHECK " + note);
    }

    private void sendLoginFailure(Protocol.LoginCheckResult loginCheckResult, String string) throws IOException {
        this.sendEncrypted(Protocol.loginCheck(loginCheckResult, 0L, this.config.serverName(), 0, 0), "S_LOGIN_CHECK failure result=" + loginCheckResult.wireValue() + " " + string);
        NativePlayerCommit.scene(this, (Object)Phase.VERSION_OK, "phase");
    }

    private void sendClassicServerList() throws IOException {
        List<String> names = config.classicServerNames();
        long address = ipv4LittleEndian(config.advertisedHost());
        List<Protocol.ClassicServerEndpoint> endpoints = names.stream()
                .map(name -> new Protocol.ClassicServerEndpoint(
                        name, address, config.advertisedPort()))
                .toList();
        sendEncrypted(Protocol.classicServerList(endpoints),
                "S_SERVER_LIST count=" + names.size() + " first=" + names.get(0));
        sendNativeCharacterEventProbe();
    }

    /**
     * Dedicated loopback fixture for the original {@code /ltcharsvr} callback.
     * S_SERVER_LIST must be delivered first because {@code sub_48FAA0} owns the
     * selected-source record array consumed by {@code sub_4A74F0}.  Normal
     * configurations keep the switch false, so opcode 0x04 has no production
     * route and can never terminate an active gameplay client.
     */
    private void sendNativeCharacterEventProbe() throws IOException {
        if (!config.nativeCharacterEventProbeEnabled()) return;
        boolean isolated = "memory".equals(config.databaseMode())
                && config.databaseReadOnly() && !config.statePersistenceEnabled()
                && config.port() == 32100
                && socket.getInetAddress().isLoopbackAddress();
        if (!isolated || endpoint != Endpoint.LOGIN || phase != Phase.AUTHENTICATED) {
            System.out.println("[LiTo] native character-event probe rejected isolated="
                    + isolated + " endpoint=" + endpoint + " phase=" + phase);
            return;
        }
        sendEncrypted(Protocol.specialCharacterServerEvent(),
                "S_CHARACTER_INFO fixture-only /ltcharsvr callback after S_SERVER_LIST");
    }

    private void sendLitoServerList() throws IOException {
        // sub_4AC7D0 has two same-shaped but semantically distinct groups.
        // Group 1 is a room/battle directory whose click path consumes a room
        // id. Group 2 is the selectable VS-server list whose click path owns
        // endpoint reuse/reconnect. This endpoint is a server row, never room
        // zero; advertising it in group 1 leaves the native selector asking
        // the player to choose a VS server.
        List<Protocol.LitoRoomDirectoryEntry> directRooms =
                config.rentalTownDirectoryEnabled()
                        ? List.of(new Protocol.LitoRoomDirectoryEntry(
                                config.rentalTownDirectoryName(),
                                ipv4LittleEndian(config.rentalTownDirectoryHost()),
                                config.rentalTownDirectoryPort(),
                                config.rentalTownDirectoryRoomId(), 0))
                        : List.of();
        rentalTownDirectoryAdvertised = !directRooms.isEmpty();
        rentalTownJoinPending = false;
        byte[] packet = Protocol.litoServerDirectory(directRooms, List.of(
                new Protocol.LitoVsServerDirectoryEntry(
                        config.serverName(),
                        ipv4LittleEndian(config.advertisedHost()),
                        config.advertisedPort(),
                        0,
                        100)));
        sendEncrypted(packet, "S_LITO_SERVER_LIST rooms=" + directRooms.size()
                + " VS-servers=1 users=0 capacity=100"
                + (directRooms.isEmpty() ? "" : " rental-map=" + config.rentalTownMapId()));
        sendEncrypted(Protocol.vsServerStatus(
                        Protocol.LitoVsServerAvailability.AVAILABLE),
                "S_LITO_VS_SERVER_STATUS count=1 status=available");
    }

    private void selectClassicServer(byte[] byArray) throws IOException {
        Protocol.requireClassicServerSelect(byArray);
        if (this.endpoint != Endpoint.LOGIN || this.phase != Phase.AUTHENTICATED) {
            System.out.println("[LiTo] C_SERVER_SELECT ignored endpoint=" + String.valueOf((Object)this.endpoint) + " invalid-phase=" + String.valueOf((Object)this.phase));
            return;
        }
        if (this.config.nativeCharacterEventProbeEnabled()) {
            System.out.println("[LiTo] C_SERVER_SELECT deferred for native character-event probe; awaiting C_C8 callback");
            return;
        }
        if (this.config.nativeSourceSelectionProbeEnabled() && !this.nativeSourceSelectionRefreshSent) {
            this.nativeSourceSelectionRefreshSent = true;
            this.sendClassicServerList();
            System.out.println("[LiTo] C_SERVER_SELECT refreshed source list for physical retained-source selection; awaiting C_C8");
            return;
        }
        NativePlayerCommit.scene(this, (String) this.config.classicServerNames().get(0), "selectedClassicServerName");
        SourceAdministration.clear(this);
        GameHub gameHub = this.hub;
        String string2 = this.accountName();
        String string = this.selectedClassicServerName;
        gameHub.stageClassicSourceHandoff(SourceLogin.account(this, string2), string);
        this.enterLobby("C_SERVER_SELECT implicit-first=" + this.selectedClassicServerName);
    }

    private void enterLobby(String string) throws IOException {
        if (this.endpoint != Endpoint.LOGIN || this.phase != Phase.AUTHENTICATED) {
            return;
        }
        this.sleepForBootstrap(this.config.serverSelectResponseDelayMs(), "before VS-server redirect");
        this.sendEncrypted(Protocol.litoVsServerIp(0, ClientSession.ipv4LittleEndian(this.config.advertisedHost()), this.config.advertisedPort()), "S_LITO_VS_SERVER_IP " + string);
        NativePlayerCommit.scene(this, (Object)Phase.LOBBY, "phase");
    }

    private void sendCharacterDirectory() throws IOException {
        loadSqlTournamentProfiles();
        sendEncrypted(Protocol.litoCharacterDirectoryCount(characters.size()),
                "S_NUM_CHARACTER count=" + characters.size());
        // Bind every row before materializing ranks so the first row cannot
        // observe a partially populated partition.
        for (CharacterSummary character : characters) {
            String identity = stateCharacter(character.name());
            // Tournament directory/ranking state is an original-client byte
            // domain. Keep the lossless level on CharacterSummary and the
            // Schema 2 runtime packets, while binding only the saturated
            // directory projection here.
            int directoryLevel = NativeCharacterStats
                    .directoryProjection(character).level();
            state.bindRankingIdentity(identity, selectedClassicServerName,
                    GameHub.characterRankingSelector(character.level()),
                    directoryLevel, character.type());
        }
        // Materialize the official daily boundary before the rows below read
        // per-character ranks, then publish the complete versioned profile.
        state.ranking(Protocol.LitoRankingScope.OVERALL, null, 0);
        // A read-only source may expose existing Tournament profiles, but the
        // character directory must never attempt to create missing sidecar
        // rows.  Doing so used to abort immediately after S_NUM_CHARACTER,
        // leaving the original client on an empty loading page before any
        // S_CB character row could be delivered.
        if (!config.databaseReadOnly()) {
            persistSqlTournamentRoster();
        }
        for (CharacterSummary character : characters) {
            NativeCharacterStats.DirectoryProjection nativeStats =
                    NativeCharacterStats.directoryProjection(character);
            String directoryName = characters.size() == 1
                    ? litoDisplayName(character.name()) : character.name();
            ExtendedCharacterStatsBridge.publish(
                    "DIRECTORY", selectedClassicServerName, character, nativeStats);
            if (nativeStats.adjusted(character)) {
                System.out.println("[LiTo] saturated source character stats for native directory"
                        + " player=" + character.name() + " "
                        + nativeStats.auditSummary(character));
            }
            GameStateStore.TournamentStatistics statistics =
                    state.tournamentStatistics(stateCharacter(character.name()));
            int effectiveLawful = state.reconcileLawful(
                    stateCharacter(character.name()), nativeLawful(character.lawful()))
                    .effective();
            Protocol.LitoCharacterBattleStatistics nativeStatistics =
                    new Protocol.LitoCharacterBattleStatistics(
                            statistics.disconnects(), statistics.winRateDenominator(),
                            statistics.wins(), statistics.losses(),
                            GameHub.characterRankingSelector(character.level()));
            sendEncrypted(Protocol.litoCharacterDirectoryRow(
                            new Protocol.LitoCharacterDirectoryRow(
                                     directoryName, character.clanName(),
                                     character.type(), character.sex(),
                                     effectiveLawful,
                                     nativeStats.maxHp(), nativeStats.maxMp(),
                                     nativeStats.armorClass(), nativeStats.level(),
                                     nativeStats.strength(), nativeStats.dexterity(),
                                     nativeStats.constitution(), nativeStats.wisdom(),
                                     nativeStats.charisma(), nativeStats.intelligence(), 0,
                                     state.characterRankings(stateCharacter(character.name())), nativeStatistics)),
                    "S_LITO_CHARACTER_INFO directory-row name=" + directoryName
                            + " source-character=" + character.name()
                            + " classic-source=" + selectedClassicServerName
                            + " battles=" + statistics.winRateDenominator()
                            + " wins=" + statistics.wins()
                            + " losses=" + statistics.losses()
                            + " disconnects=" + statistics.disconnects());
        }
    }

    private static int nativeLawful(long lawful) {
        return (int) Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, lawful));
    }

    private void requestLitoCharacterInfo(byte[] payload) throws IOException {
        // sub_4AC4C0 is the native S_F5 receiver. Its source-refresh branch
        // emits C_C8 with format "cs" and passes the name at the currently
        // selected S_SERVER_LIST record (72-byte native record stride).
        // The record's native name field is 0x40 bytes including NUL. Parse
        // that exact envelope before allowing the advertised-name binding.
        String requested = Protocol.litoCharacterSourceRequest(payload).sourceName();
        // Initial GAME bootstrap is gated by the one-shot S_E6 -> C_E2
        // capability.  C_C8 is native on LOGIN/AUTHENTICATED (the cached
        // source branch in sub_48FAA0) and GAME/LOBBY (the S_F5 restart
        // branch in sub_4AC4C0), but it must not expose S_CB on GAME while
        // the readiness acknowledgement is still pending.
        if (endpoint == Endpoint.GAME && (phase != Phase.LOBBY
                || litoNewsAcknowledgementPending)) {
            System.out.println("[LiTo] C_LITO_LIN_CHARACTER_INFO ignored before"
                    + " GAME character-bootstrap readiness phase=" + phase
                    + " pending=" + litoNewsAcknowledgementPending);
            return;
        }
        if (endpoint == Endpoint.LOGIN && phase != Phase.AUTHENTICATED
                && phase != Phase.LOBBY) {
            System.out.println("[LiTo] C_LITO_LIN_CHARACTER_INFO ignored on LOGIN"
                    + " invalid-phase=" + phase);
            return;
        }
        String matched = canonicalClassicSource(requested);
        if (matched == null) {
            System.out.println("[LiTo] C_LITO_LIN_CHARACTER_INFO rejected unknown classic source"
                    + " encoded-bytes=" + requested.getBytes(Protocol.LEGACY_TEXT).length);
            return;
        }
        if (!isClassicSourceAuthorized(matched)) {
            System.out.println("[LiTo] C_LITO_LIN_CHARACTER_INFO rejected unauthorized classic source"
                    + " encoded-bytes=" + requested.getBytes(Protocol.LEGACY_TEXT).length);
            return;
        }
        if (endpoint == Endpoint.LOGIN) {
            if (phase != Phase.AUTHENTICATED) {
                System.out.println("[LiTo] C_LITO_LIN_CHARACTER_INFO LOGIN handoff replay ignored phase="
                        + phase);
                return;
            }
            NativePlayerCommit.scene(this, matched, "selectedClassicServerName");
            SourceAdministration.clear(this);
            GameHub handoffHub = hub;
            String handoffAccount = accountName();
            String handoffSource = selectedClassicServerName;
            handoffHub.stageClassicSourceHandoff(SourceLogin.account(this, handoffAccount), handoffSource);
            enterLobby("C_C8 selected-source=" + selectedClassicServerName);
            return;
        }
        SourceCharacterDirectory directory;
        List<CastleWarSchedule> castleWarSchedules;
        try {
            directory = loadCharacterDirectory(matched);
            castleWarSchedules = accounts.repositoryForClassicSource(matched)
                    .castleWarSchedules();
        } catch (Exception databaseError) {
            System.out.println("[LiTo] C_LITO_LIN_CHARACTER_INFO source lookup failed source="
                    + matched + " error=" + databaseError.getClass().getSimpleName()
                    + ": " + databaseError.getMessage());
            return;
        }
        NativePlayerCommit.scene(this, matched, "selectedClassicServerName");
        SourceAdministration.clear(this);
        hub.registerClassicCastleWarSchedules(
                selectedClassicServerName, castleWarSchedules);
        applyCharacterDirectory(directory);
        System.out.println("[LiTo] selected classic character source=" + selectedClassicServerName
                + " account=" + mask(account)
                + " authorized=" + isClassicSourceAuthorized(selectedClassicServerName)
                + " characters=" + characters.size());
        if (pendingTransition == PendingTransition.RESTART_AWAIT_SOURCE_REFRESH) {
            // S_RESTART -> C_D9 -> S_F0 -> C_CB/C_D0 -> S_F5 -> C_C8 is the
            // only tracked native path that may arm another C_C9 for the
            // already selected cached character.
            litoCharacterSelectionConsumed = false;
        }
        sendCharacterDirectory();
        if (pendingTransition == PendingTransition.RESTART_AWAIT_SOURCE_REFRESH) {
            pendingTransition = PendingTransition.NONE;
            System.out.println("[LiTo] native restart/source-refresh complete player=" + playerName());
        }
    }

    private SourceCharacterDirectory loadCharacterDirectory(String classicServerName)
            throws Exception {
        if (!isClassicSourceAuthorized(classicServerName)) {
            return new SourceCharacterDirectory(List.of(), 0);
        }
        List<CharacterSummary> originalCharacters = accounts
                .repositoryForClassicSource(classicServerName).characters(accountName());
        List<CharacterSummary> combined = new ArrayList<>(originalCharacters);
        String sourceAccount = GameStateStore.sourceCharacter(
                classicServerName, accountName());
        for (CharacterSummary created : state.createdCharacters(sourceAccount)) {
            boolean duplicate = combined.stream().anyMatch(existing ->
                    existing.name().equalsIgnoreCase(created.name()));
            if (!duplicate && combined.size() < 8) combined.add(created);
        }
        return new SourceCharacterDirectory(combined, originalCharacters.size());
    }

    private void applyCharacterDirectory(SourceCharacterDirectory directory) {
        characters = directory.characters();
        originalCharacterCount = directory.originalCharacterCount();
        previewCharacter = "";
        litoCharacterSelectionConsumed = false;
        // A different C_C8 source directory invalidates the previous source
        // snapshot. C_C9 must qualify the newly selected row before battle.
        sourceEquippedFireResistance = null;
        sourceBaseMagicResistance = null;
        sourceEquipmentMagicStats = null;
        sourceEquipmentVitalStats = null;
        sourceCounterMagicBypassSkills = Set.of();
        sourceSkillReuseDelays = Map.of();
        sourceInitialArmorClassModifier = 0;
        sourceEquipmentObjects = Map.of();
        consumedSourceEquipmentObjects = Set.of();
        sourceProjectileObjects = Map.of();
        sourceMagicDolls = Map.of();
        activeMagicDoll = null;
        sourcePhysicalGrowthStats = null;
        sourceInventoryWeightStats = null;
        retainedSourceInventoryWeight = -1;
    }

    private boolean isClassicSourceAuthorized(String classicServerName) {
        if (authenticatedClassicSources.isEmpty()) return true;
        return authenticatedClassicSources.stream()
                .anyMatch(source -> source.equalsIgnoreCase(classicServerName));
    }

    private String canonicalClassicSource(String requested) {
        if (requested == null) return null;
        return config.classicServerNames().stream()
                .filter(name -> name.equalsIgnoreCase(requested))
                .findFirst()
                .orElse(null);
    }

    private AccountRepository selectedSourceAccounts() {
        AccountRepository accountRepository = this.accounts.repositoryForClassicSource(this.selectedClassicServerName);
        LiToItemTemplates.preload(accountRepository);
        return accountRepository;
    }

