    private void persistSqlTournamentRoster() throws IOException {
        // Existing SQL rows cover every account already admitted to the ranking
        // population. Current account rows are also included so a fresh schema
        // bootstraps them without requiring a fabricated migration identity.
        Map<Long, String> candidates = new LinkedHashMap<>();
        sqlTournamentProfiles.values().forEach(profile -> candidates.put(
                profile.characterObjectId(), profile.characterName()));
        for (CharacterSummary character : characters) {
            candidates.put(character.objectId(), character.name());
        }
        for (Map.Entry<Long, String> candidate : candidates.entrySet()) {
            long objectId = candidate.getKey();
            String characterName = candidate.getValue();
            GameStateStore.TournamentProfileState replacement =
                    state.tournamentProfileState(stateCharacter(characterName));
            RepositoryTournamentProfile expected = sqlTournamentProfiles.get(objectId);
            if (expected != null && expected.snapshotVersion() > 0
                    && expected.state().equals(replacement)) continue;
            RepositoryTournamentMutation mutation;
            try {
                mutation = selectedSourceAccounts().persistTournamentProfile(
                        objectId, characterName,
                        expected != null && expected.snapshotVersion() > 0
                                ? expected : null,
                        replacement);
            } catch (Exception failure) {
                throw new IOException("cannot persist selected-source Tournament profile", failure);
            }
            if (mutation.status() == RepositoryTournamentMutationStatus.SUCCESS) {
                sqlTournamentProfiles.put(objectId, mutation.profile());
            } else if (mutation.status() != RepositoryTournamentMutationStatus.READ_ONLY
                    && mutation.status() != RepositoryTournamentMutationStatus.UNAVAILABLE) {
                throw new IOException("Tournament profile CAS refused: " + mutation.status());
            }
        }
    }

    private void persistSqlTournamentResult(GameStateStore.TournamentProfileState tournamentProfileState, GameStateStore.TournamentProfileState tournamentProfileState2) throws IOException {
        RepositoryTournamentMutation repositoryTournamentMutation;
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        if (characterSummary == null) {
            throw new IOException("selected Tournament character is missing");
        }
        RepositoryTournamentProfile repositoryTournamentProfile = this.sqlTournamentProfiles.get(characterSummary.objectId());
        if (repositoryTournamentProfile != null && repositoryTournamentProfile.snapshotVersion() > 0L && !LiveBattleStats.baselineEquals(repositoryTournamentProfile.state(), tournamentProfileState, this)) {
            throw new IOException("Tournament SQL cache differs from result baseline");
        }
        try {
            repositoryTournamentMutation = SharedDatabase.commitResult(this.selectedSourceAccounts(), characterSummary.objectId(), characterSummary.name(), repositoryTournamentProfile != null && repositoryTournamentProfile.snapshotVersion() > 0L ? repositoryTournamentProfile : null, tournamentProfileState2);
        }
        catch (Exception exception) {
            throw new IOException("cannot commit Tournament result", exception);
        }
        if (repositoryTournamentMutation.status() != RepositoryTournamentMutationStatus.SUCCESS) {
            throw new IOException("Tournament result persistence refused: " + String.valueOf((Object)repositoryTournamentMutation.status()));
        }
        this.sqlTournamentProfiles.put(characterSummary.objectId(), repositoryTournamentMutation.profile());
    }

