    static boolean isLateAuthenticatedLoginCharacterSelection(
            Endpoint endpoint, boolean selectionConsumed,
            String accountName, String requested,
            List<String> ownedCharacterNames, String classicServerName) {
        if (endpoint != Endpoint.LOGIN || selectionConsumed
                || accountName == null || accountName.isBlank()
                || requested == null || ownedCharacterNames == null
                || ownedCharacterNames.isEmpty()) {
            return false;
        }
        String selectedName = requested.isEmpty()
                ? ownedCharacterNames.stream()
                        .filter(name -> name.equalsIgnoreCase(accountName))
                        .findFirst().orElse("")
                : requested;
        if (selectedName.isEmpty()) return false;
        for (String ownedName : ownedCharacterNames) {
            if (ownedName.equalsIgnoreCase(selectedName)) return true;
        }
        return ownedCharacterNames.size() == 1
                && classicServerName != null
                && (ownedCharacterNames.get(0) + "(" + classicServerName + ")")
                        .equalsIgnoreCase(selectedName);
    }

