    private synchronized void sendInventoryBootstrap() throws IOException {
        if (inventoryBootstrapSent) return;
        if (clientInventoryObjectIds != null) {
            for (long objectId : List.copyOf(clientInventoryObjectIds)) {
                sendEncrypted(Protocol.removeInventory(objectId),
                        "S_REMOVE_INVENTORY before-rebuild object=" + objectId);
            }
        }
        List<Protocol.InventoryWireItem> items = new ArrayList<>(
                inventory.items().stream().map(RuntimeInventory.Item::wireItem).toList());
        Protocol.InventoryWireItem defensive = sourceDefensiveEquipmentWireItem();
        if (defensive != null) items.add(defensive);
        if (config.nativeTransferStoneProbeEnabled()) {
            items.add(Protocol.litoTransferStone(TRANSFER_STONE_PROBE_OBJECT_ID));
        }
        int batchSize = Math.min(0xFF, items.size());
        List<Protocol.InventoryWireItem> batch = items.subList(0, batchSize);
        sendEncrypted(Protocol.inventoryBatch(batch),
                "S_ADD_INVENTORY_BATCH items=" + batch.size()
                        + " source-defensive=" + (defensive != null)
                        + " transfer-stone-probe="
                        + config.nativeTransferStoneProbeEnabled());
        for (int index = batchSize; index < items.size(); index++) {
            Protocol.InventoryWireItem item = items.get(index);
            sendEncrypted(Protocol.addInventory(item),
                    "S_ADD_INVENTORY object=" + item.objectId()
                            + " use-type=" + item.useType());
        }
        inventoryBootstrapSent = true;
    }

    private Protocol.InventoryWireItem sourceDefensiveEquipmentWireItem() {
        if (sourceEquipmentMagicStats == null) return null;
        SourceDefensiveEquipment equipment =
                sourceEquipmentMagicStats.physical().defensiveEquipment();
        CharacterSummary character = selectedCharacterSummary();
        if (!equipment.present() || character == null) return null;
        long suffix = character.objectId() & 0x00FF_FFFFL;
        if (suffix == 0) suffix = 1;
        long objectId = SOURCE_DEFENSIVE_ITEM_OBJECT_BASE | suffix;
        return new Protocol.InventoryWireItem(
                objectId, equipment.useType(), 0, equipment.icon(),
                equipment.blessing(), 1, 1, equipment.nameId(), new byte[0]);
    }

    /** SQL rows bind to their exact character_items.id; sidecar fixtures retain
     * the deterministic legacy fallback for memory-only tests. */
    private void bindLetterObjects() {
        letterObjectBindings.clear();
        List<RuntimeInventory.Item> closed = inventory.items().stream()
                .filter(item -> item.definition().catalogId() == InventoryCatalog.LETTER_CLOSED)
                .toList();
        List<RuntimeInventory.Item> opened = inventory.items().stream()
                .filter(item -> item.definition().catalogId() == InventoryCatalog.LETTER_OPEN)
                .toList();
        if (sqlLetterSnapshot.authoritative()) {
            for (RepositoryLetter letter : sqlLetterSnapshot.letters()) {
                RuntimeInventory.Item item = inventory.item(letter.itemObjectId());
                long requiredCatalog = letter.opened()
                        ? InventoryCatalog.LETTER_OPEN : InventoryCatalog.LETTER_CLOSED;
                if (item == null || item.definition().catalogId() != requiredCatalog) {
                    throw new IllegalStateException(
                            "SQL physical-letter/backing runtime item mismatch object="
                                    + letter.itemObjectId());
                }
                letterObjectBindings.put(letter.itemObjectId(), letter.itemObjectId());
            }
            System.out.println("[LiTo] bound SQL physical letters player=" + playerName()
                    + " bindings=" + letterObjectBindings.size()
                    + " items=" + (closed.size() + opened.size()));
            return;
        }
        int closedIndex = 0;
        int openIndex = 0;
        for (GameStateStore.Letter letter : state.letters(stateCharacter()).stream()
                .sorted(java.util.Comparator.comparingLong(GameStateStore.Letter::id)).toList()) {
            List<RuntimeInventory.Item> candidates = letter.opened() ? opened : closed;
            int index = letter.opened() ? openIndex++ : closedIndex++;
            if (index < candidates.size()) {
                letterObjectBindings.put(candidates.get(index).objectId(), letter.id());
            }
        }
        System.out.println("[LiTo] bound physical letters player=" + playerName()
                + " bindings=" + letterObjectBindings.size()
                + " items=" + (closed.size() + opened.size()));
    }

    private void enterChannel(byte[] payload) throws IOException {
        Protocol.LitoChannelSelection selection = Protocol.litoEnterChannelRequest(payload);
        if (channelPortHandoffTarget >= 0
                && selection.target() == Protocol.LitoChannelTarget.CHANNEL) {
            selection = Protocol.LitoChannelSelection.activeChannel(
                    channelPortHandoffTarget);
        }
        int channelId = selection.wireValue();
        // C_CA 100 is emitted by the fifth (Return) control after its preceding
        // C_CB has left the active Tournament channel.  The client has already
        // switched to its loading root at this point; S_F5 is the exact native
        // source-refresh continuation and makes sub_4AC4C0 emit C_C8 for the
        // selected database.  Treating 100 as a silent notification leaves the
        // UI permanently stuck on the channel selector/loading transition.
        if (selection.target() == Protocol.LitoChannelTarget.CHANNEL_SELECTION) {
            if (phase == Phase.LOBBY) {
                if (pendingTransition == PendingTransition.NONE) {
                    pendingTransition = PendingTransition.RESTART_AWAIT_SOURCE_REFRESH;
                    litoCharacterSelectionConsumed = false;
                    sendEncrypted(Protocol.allowPostTransition(),
                            "S_LITO_VS_SERVER_ALLOW_JOIN channel-return source-refresh");
                    System.out.println("[LiTo] C_LITO_ENTER_CHANNEL return-to-character-list"
                            + " value=100 source=" + selectedClassicServerName);
                } else {
                    System.out.println("[LiTo] duplicate C_LITO_ENTER_CHANNEL return ignored"
                            + " pending=" + pendingTransition);
                }
            } else {
                System.out.println("[LiTo] C_LITO_ENTER_CHANNEL selector notification ignored phase="
                        + phase);
            }
            return;
        }
        // The raw 0x492FA0 callback owns both native selectors. In the ordinary
        // four-button UI C_CA 0..3 means a tournament channel. With the
        // /ltpremiumsvr capability and an already selected character,
        // dword_630C50 exposes LTItemSet<class>-<index> buttons and sends the
        // same byte. Resolve that union before any GameHub channel mutation.
        if (selection.target() == Protocol.LitoChannelTarget.CHANNEL
                && rentalItemSelectionContext()) {
            selectRentalItemSet(selection);
            return;
        }
        if (selection.target() == Protocol.LitoChannelTarget.CHANNEL
                && phase == Phase.LOBBY
                && config.dedicatedChannelPortsEnabled()
                && boundChannelId >= 0
                && channelId != boundChannelId) {
            redirectToChannelPort(channelId);
            return;
        }
        // The protected client sends C_CA twice when entering a channel.  The
        // first request performs the transition; the second is an immediate
        // idempotent refresh from the newly constructed lobby UI.  Rejecting
        // that refresh with S_C9 result=1 produces the native
        // "channel is not currently in service" warning even though the
        // first request already succeeded.
        if (selection.target() == Protocol.LitoChannelTarget.CHANNEL
                && phase == Phase.CHANNEL && channelId == currentChannelId) {
            GameHub.ChannelSnapshot channel = hub.enterChannel(channelId, this);
            if (channel != null) {
                sendChannelInfo(channel, "duplicate enter refresh");
                return;
            }
        }
        if (selection.target() == Protocol.LitoChannelTarget.ARGO
                && phase == Phase.CHANNEL && currentChannelId == ARGO_CHANNEL_ID) {
            sendChannelInfo(hub.argoChannelSnapshot(), "duplicate /argo refresh");
            return;
        }
        if (phase != Phase.LOBBY) {
            sendEncrypted(Protocol.litoEnterChannelFailure(
                            Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE, selection),
                    "S_LITO_ENTER_CHANNEL_RESULT rejected invalid-phase=" + phase);
            return;
        }
        sleepForBootstrap(config.enterChannelResponseDelayMs(), "before enter-channel response");
        if (!config.enterChannelResponseEnabled()) {
            System.out.println("[LiTo] C_LITO_ENTER_CHANNEL held for protocol diagnostics");
            return;
        }
        if (selection.target() == Protocol.LitoChannelTarget.ARGO) {
            // sub_452C20 can only issue /argo from the normal channel lobby:
            // it first sends C_CB, then C_CA 99, and preserves the selected
            // 0..3 channel locally for the inverse toggle.  Accepting 99
            // without that predecessor would invent a client-unreachable
            // state and make a malformed request look authoritative.
            if (lastTournamentChannelId < 0) {
                sendEncrypted(Protocol.litoEnterChannelFailure(
                                Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE,
                                selection),
                        "S_LITO_ENTER_CHANNEL_RESULT rejected argo-without-source-channel");
                return;
            }
            GameHub.ChannelSnapshot argo = hub.argoChannelSnapshot();
            sendEncrypted(Protocol.litoEnterChannelSuccess(selection),
                    "S_LITO_ENTER_CHANNEL_RESULT accepted /argo channel=99");
            sendChannelInfo(argo, "entered /argo");
            currentChannelId = ARGO_CHANNEL_ID;
            hubChannelId = -1;
            pendingLitoRoomInvitation = null;
            acceptedLitoRoomInvitation = null;
            NativePlayerCommit.scene(this, Phase.CHANNEL, "phase");
            System.out.println("[LiTo] entered /argo active-battle browser from channel="
                    + lastTournamentChannelId + " users=" + argo.users()
                    + "/" + argo.capacity());
            return;
        }
        CharacterSummary selected = selectedCharacterSummary();
        if (selected == null) {
            sendEncrypted(Protocol.litoEnterChannelFailure(
                            Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE, selection),
                    "S_LITO_ENTER_CHANNEL_RESULT rejected no-selected-character");
            return;
        }
        // The target client paints only four playable level bands (15+). Its
        // fifth ranking selector is the below-minimum state; unlike ordinary
        // cross-tier selection, that state has no playable Tournament channel
        // and is the directly supported producer-side meaning of result 10.
        if (GameHub.recommendedChannel(selected.level()) == null) {
            sendEncrypted(Protocol.litoEnterChannelFailure(
                            Protocol.LitoEnterChannelFailure.CHARACTER_LEVEL_RESTRICTED,
                            selection),
                    "S_LITO_ENTER_CHANNEL_RESULT character-level-restricted channel="
                            + channelId + " level=" + selected.level());
            return;
        }
        activatePendingRentalBattleHandoff("enter-channel-" + channelId);
        GameHub.ChannelSnapshot channel = hub.enterChannel(channelId, this);
        if (channel == null) {
            sendEncrypted(Protocol.litoEnterChannelFailure(
                            Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE, selection),
                    "S_LITO_ENTER_CHANNEL_RESULT rejected channel=" + channelId);
            return;
        }
        sendEncrypted(Protocol.litoEnterChannelSuccess(
                        Protocol.LitoChannelSelection.activeChannel(channel.id())),
                "S_LITO_ENTER_CHANNEL_RESULT accepted channel=" + channel.id());
        // LiTo constructs the channel UI in the S_C9 handler, then expects S_CA
        // to populate its channel id and the current/maximum player counters.
        // Leaving these fields untouched produces the half-painted lobby seen
        // on modern systems.  The original parser format is exactly "chh".
        sendChannelInfo(channel, "entered");
        currentChannelId = channel.id();
        hubChannelId = channel.id();
        lastTournamentChannelId = channel.id();
        hub.cancelMatchMaking(this);
        pendingMatchMakingRequest = null;
        pendingLitoRoomInvitation = null;
        acceptedLitoRoomInvitation = null;
        observer = false;
        NativePlayerCommit.scene(this, Phase.CHANNEL, "phase");
        if (channelPortHandoffTarget >= 0) {
            GameHub handoffHub = hub;
            String handoffAccount = accountName();
            String handoffCharacter = channelPortHandoffCharacter;
            String handoffSource = selectedClassicServerName;
            boolean consumed = handoffHub.consumeChannelPortHandoff(
                    SourceLogin.account(this, handoffAccount), handoffCharacter,
                    handoffSource, channelId);
            if (!consumed) {
                throw new IOException("channel-port handoff expired before channel entry");
            }
            channelPortHandoffTarget = -1;
            channelPortHandoffCharacter = "";
        }
        // S_C8 selects the character but does not populate the native lobby
        // status globals.  Publish the full authoritative family after the
        // channel UI exists, including the projected food/weight positions.
        sendLobbyStatusIfQualified();
        if (config.nativeTournamentEconomyEnabled() && nativeTournamentEconomyInitialized)
            sendPointStats();
        notifyBuddyPresence(Protocol.LitoBuddyPresence.ONLINE);
        System.out.println("[LiTo] entered game lobby channel=" + channel.id()
                + " name=" + channel.name() + " users=" + channel.users()
                + "/" + channel.capacity());
        if (config.cloneAppearanceProbeEnabled()) {
            hub.scheduleCloneAppearanceProbeAutoBattle(this, channel.id());
        }
    }

    private void redirectToChannelPort(int n) throws IOException {
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        if (characterSummary == null || this.accountName().isBlank()) {
            this.sendEncrypted(Protocol.litoEnterChannelFailure(Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE, Protocol.LitoChannelSelection.activeChannel(n)), "S_LITO_ENTER_CHANNEL_RESULT redirect rejected missing identity");
            return;
        }
        GameHub gameHub = this.hub;
        String string3 = this.accountName();
        String string2 = characterSummary.name();
        String string = this.selectedClassicServerName;
        int n2 = n;
        boolean bl = gameHub.stageChannelPortHandoff(SourceLogin.account(this, string3), string2, string, n2);
        if (!bl) {
            this.sendEncrypted(Protocol.litoEnterChannelFailure(Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE, Protocol.LitoChannelSelection.activeChannel(n)), "S_LITO_ENTER_CHANNEL_RESULT redirect handoff rejected");
            return;
        }
        GameHub gameHub2 = this.hub;
        String string5 = this.accountName();
        String string4 = this.selectedClassicServerName;
        gameHub2.stageClassicSourceHandoff(SourceLogin.account(this, string5), string4);
        this.channelPortTransferPending = true;
        this.sendEncrypted(Protocol.vsServerStatus(Protocol.LitoVsServerAvailability.AVAILABLE), "S_LITO_VS_SERVER_STATUS channel-port redirect available");
        this.sendEncrypted(Protocol.litoVsServerIp(0, ClientSession.ipv4LittleEndian(this.config.gameBind()), this.config.channelPort(n)), "S_LITO_VS_SERVER_IP channel-port=" + n + " destination=" + this.config.gameBind() + ":" + this.config.channelPort(n));
        System.out.println("[LiTo] channel-port redirect staged account=" + ClientSession.mask(this.account) + " character=" + characterSummary.name() + " source=" + this.selectedClassicServerName + " channel=" + n + " destination=" + this.config.gameBind() + ":" + this.config.channelPort(n));
    }

    /*
     * Enabled force condition propagation
     * Lifted jumps to return sites
     */
    private boolean rentalItemSelectionContext() {
        if (!this.config.rentalTownDirectoryEnabled()) return false;
        if (!this.rentalTownDirectoryAdvertised) return false;
        if (this.phase != Phase.LOBBY) return false;
        if (this.selectedCharacter.isEmpty()) return false;
        GameHub gameHub = this.hub;
        String string2 = this.accountName();
        String string = this.stateCharacter();
        if (gameHub.hasRentalBattleHandoff(SourceLogin.account(this, string2), string)) return false;
        return true;
    }

    private void selectRentalItemSet(Protocol.LitoChannelSelection channelSelection)
            throws IOException {
        int selection = channelSelection.wireValue();
        CharacterSummary character = selectedCharacterSummary();
        int choices = character == null ? 0 : switch (character.type()) {
            case 0, 1, 4 -> 3;
            case 2, 3 -> 2;
            default -> 0;
        };
        if (selection < 0 || selection >= choices) {
            sendEncrypted(Protocol.litoEnterChannelFailure(
                            Protocol.LitoEnterChannelFailure.CHANNEL_NOT_IN_SERVICE,
                            channelSelection),
                    "S_LITO_ENTER_CHANNEL_RESULT rental-item-set rejected class="
                            + (character == null ? -1 : character.type())
                            + " selection=" + selection + " choices=" + choices);
            return;
        }
        rentalItemSetSelection = selection;
        sendEncrypted(Protocol.litoEnterChannelSuccess(channelSelection),
                "S_LITO_ENTER_CHANNEL_RESULT rental-item-set accepted class="
                        + character.type() + " selection=" + selection
                        + " inventory-grant=deferred-to-town-scene-bootstrap");
        System.out.println("[LiTo] selected rental item set player=" + playerName()
                + " class=" + character.type() + " selection=" + selection
                + " phase=" + phase + " GameHub-channel=unchanged");
    }

    private void sendChannelInfo(GameHub.ChannelSnapshot channel, String trigger) throws IOException {
        sendEncrypted(Protocol.litoChannelInfo(
                        Protocol.LitoChannelSelection.activeChannel(channel.id()),
                        channel.users(), channel.capacity()),
                "S_LITO_CHANNEL_INFO channel=" + channel.id() + " name=" + channel.name()
                        + " users=" + channel.users() + " capacity=" + channel.capacity()
                        + " trigger=" + trigger);
    }

    private void leaveChannel() throws IOException {
        if (this.pendingTransition == PendingTransition.RESTART_AWAIT_RETURN) {
            this.completeRestartReturn(false);
            return;
        }
        if (this.phase != Phase.CHANNEL) {
            System.out.println("[LiTo] C_LITO_LEAVE_CHANNEL ignored invalid-phase=" + String.valueOf((Object)this.phase));
            return;
        }
        this.notifyBuddyPresence(Protocol.LitoBuddyPresence.OFFLINE);
        if (this.currentChannelId >= 0 && this.currentChannelId < GameHub.CHANNEL_COUNT) {
            this.lastTournamentChannelId = this.currentChannelId;
        }
        if (this.hubChannelId >= 0) {
            this.hub.leaveChannel(this.hubChannelId, this);
        }
        this.hub.cancelMatchMaking(this);
        this.pendingMatchMakingRequest = null;
        this.pendingLitoRoomInvitation = null;
        this.acceptedLitoRoomInvitation = null;
        this.resetNativeTournamentEconomy("channel-exit");
        this.currentChannelId = -1;
        this.hubChannelId = -1;
        NativePlayerCommit.scene(this, (Object)Phase.LOBBY, "phase");
        System.out.println("[LiTo] left game lobby player=" + this.playerName());
    }

    private void sendRoomList() throws IOException {
        LiveBattleStats.lobby(this);
        if (this.phase == Phase.LOBBY && this.config.rentalTownDirectoryEnabled() && this.rentalTownDirectoryAdvertised && !this.selectedCharacter.isEmpty() && this.rentalItemSetSelection >= 0) {
            this.sendLitoServerList();
            System.out.println("[LiTo] sent rental-town directory after item-set C_CE");
            return;
        }
        if (this.phase != Phase.CHANNEL && this.phase != Phase.ROOM) {
            return;
        }
        List<GameHub.RoomSnapshot> list = this.visibleRoomSnapshots();
        for (GameHub.RoomSnapshot roomSnapshot : list) {
            this.sendRoomListRow(roomSnapshot, "room-list");
        }
        System.out.println("[LiTo] sent room list entries=" + list.size());
    }

    private void sendRoomListRow(GameHub.RoomSnapshot room, String trigger) throws IOException {
        NativeRoomDirectoryRow.send(this, room, trigger);
    }

    private List<GameHub.RoomSnapshot> visibleRoomSnapshots() {
        return currentChannelId == ARGO_CHANNEL_ID
                ? hub.argoRoomSnapshots() : hub.roomSnapshots(currentChannelId);
    }

    private void findUser(byte[] payload) throws IOException {
        if (phase != Phase.CHANNEL) return;
        String query = Protocol.litoFindUserRequest(payload).query().trim();

        int matches = 0;
        for (GameHub.RoomSnapshot room : visibleRoomSnapshots()) {
            boolean matched = query.isEmpty() || hub.roomMembers(room.id()).stream()
                    .anyMatch(member -> member.sourceCharacterIdentity()
                            .equalsIgnoreCase(sourceCharacterIdentity(query)));
            if (!matched) {
                matched = hub.roomVirtualPlayers(room.id()).stream()
                        .anyMatch(member -> member.name().equalsIgnoreCase(query));
            }
            if (!matched && NativeRoomRules.bot(hub.roomRules(room.id()).mode(), hub, room.id())
                    && hub.roomCombatantCount(room.id()) < 2) {
                matched = "ArenaBot".equalsIgnoreCase(query);
            }
            if (matched) {
                sendRoomListRow(room, "find-user");
                matches++;
            }
        }
        System.out.println("[LiTo] C_LITO_FIND_USER query=" + query
                + " reserved=0,0 matches=" + matches);
    }

    private void sendRoomUser(byte[] payload) throws IOException {
        if (phase != Phase.CHANNEL) return;
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        long roomId = in.d();
        if (in.remaining() != 0) throw new IllegalArgumentException("invalid C_LITO_ROOM_USER payload");
        boolean visible = currentChannelId == ARGO_CHANNEL_ID
                ? hub.argoRoomSnapshot(roomId) != null
                : hub.roomExists(currentChannelId, roomId);
        if (!visible) {
            System.out.println("[LiTo] C_LITO_ROOM_USER unknown room=" + roomId);
            return;
        }
        List<ClientSession> members = hub.roomMembers(roomId);
        for (ClientSession member : members) {
            sendRoomParticipant(roomId, member,
                    Protocol.LitoForce.fromWire(hub.forceOf(roomId, member)),
                    member.observer ? "observer" : "player");
        }
        for (GameHub.RoomVirtualPlayer member : hub.roomVirtualPlayers(roomId)) {
            sendRoomVirtualPlayer(roomId, member, "gm-virtual-player");
        }
        if (NativeRoomRules.bot(hub.roomRules(roomId).mode(), hub, roomId)
                && hub.roomCombatantCount(roomId) < 2) {
            sendRoomParticipant(roomId, "ArenaBot", Protocol.LitoForce.FORCE_1,
                    0, 0, "", 0, "bot");
        }
        System.out.println("[LiTo] sent room users room=1 sessions=" + members.size());
    }

    private void joinRoom(byte[] payload, String trigger) throws IOException {
        joinRoom(payload, trigger, false);
    }

    private boolean consumeAcceptedLitoRoomInvitation(long roomId, String password) {
        PendingLitoRoomInvitation invitation = acceptedLitoRoomInvitation;
        acceptedLitoRoomInvitation = null;
        if (invitation == null) return false;
        boolean matches = phase == Phase.CHANNEL
                && System.nanoTime() - invitation.expiresAtNanos() < 0
                && invitation.channelId() == currentChannelId
                && invitation.roomId() == roomId
                && invitation.password().equals(password)
                && hub.roomExists(currentChannelId, roomId);
        if (!matches) {
            System.out.println("[LiTo] discarded accepted room invitation player="
                    + playerName() + " inviter=" + invitation.inviterName()
                    + " room=" + invitation.roomId() + " requested-room=" + roomId
                    + " reason=mismatch-expired-or-closed");
        }
        return matches;
    }

    private void joinRoom(byte[] payload, String trigger, boolean matchmaking) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        long roomId = in.d();
        String password = in.s();
        if (in.remaining() != 0) throw new IllegalArgumentException("invalid C_LITO_JOIN payload");
        // Native invitation acceptance always sends D6 before CF.  Any CF also
        // dismisses an unanswered S_D7 dialog; only the separately accepted,
        // one-shot capability may label this join as invitation-originated.
        pendingLitoRoomInvitation = null;
        if (consumeAcceptedLitoRoomInvitation(roomId, password)) {
            trigger = "invite-accept";
        }
        if (rentalTownJoinPending) {
            joinRentalTown(roomId, password, trigger, matchmaking);
            NativeRoomRules.joined(this);
            return;
        }
        if (phase != Phase.CHANNEL) {
            System.out.println("[LiTo] C_LITO_JOIN rejected invalid-phase=" + phase);
            rejectRoomRequest("invalid-phase", matchmaking);
            NativeRoomRules.joined(this);
            return;
        }
        boolean argoJoin = currentChannelId == ARGO_CHANNEL_ID;
        boolean previousObserver = observer;
        GameHub.RoomSnapshot argoRoom = argoJoin ? hub.argoRoomSnapshot(roomId) : null;
        int roomChannelId = argoRoom == null ? currentChannelId : argoRoom.channelId();
        if ((argoJoin && (argoRoom == null || !password.isEmpty()))
                || (!argoJoin && !hub.roomExists(roomChannelId, roomId))) {
            System.out.println("[LiTo] C_LITO_JOIN rejected unknown-room=" + roomId);
            rejectRoomRequest("unknown-room", matchmaking,
                    Protocol.LitoJoinFailure.ROOM_CLOSED);
            NativeRoomRules.joined(this);
            return;
        }
        GameHub.RoomSettings settings = hub.roomSettings(roomId);
        if (!argoJoin && !GameHub.canJoinRoom(roomChannelId, characterLevel(), settings)) {
            System.out.println("[LiTo] C_LITO_JOIN rejected upper-tier player=" + playerName()
                    + " level=" + characterLevel() + " channel=" + roomChannelId
                    + " room=" + roomId + " attributes=0x"
                    + Integer.toHexString(settings.attributes()));
            rejectRoomRequest("upper-tier", matchmaking,
                    Protocol.LitoJoinFailure.UPPER_TIER_RESTRICTED);
            NativeRoomRules.joined(this);
            return;
        }
        if (argoJoin) {
            observer = true;
            hub.observerChanged(this);
        }
        if (observer && !settings.allowsObservers()) {
            System.out.println("[LiTo] C_LITO_JOIN rejected observer-disabled player="
                    + playerName() + " room=" + roomId);
            observer = previousObserver;
            rejectRoomRequest("observer-disabled", matchmaking,
                    Protocol.LitoJoinFailure.OBSERVER_DISABLED);
            NativeRoomRules.joined(this);
            return;
        }
        // The /argo room-row callback has no password-dialog branch: it sends
        // C_CF with the native empty string for a running room.  Admission is
        // therefore controlled by the room's allow-observers flag, not by
        // exposing the combatants' private-room password to a spectator.
        if (!argoJoin && !hub.passwordMatches(roomChannelId, roomId, password)) {
            System.out.println("[LiTo] C_LITO_JOIN rejected invalid-password room=" + roomId);
            rejectRoomRequest("invalid-password", matchmaking,
                    Protocol.LitoJoinFailure.BAD_PASSWORD);
            NativeRoomRules.joined(this);
            return;
        }
        if (!hub.hasCapacity(roomChannelId, roomId, observer)) {
            System.out.println("[LiTo] C_LITO_JOIN rejected room-full=" + roomId);
            observer = previousObserver;
            rejectRoomRequest("room-full", matchmaking,
                    Protocol.LitoJoinFailure.ROOM_FULL);
            NativeRoomRules.joined(this);
            return;
        }

        if (argoJoin) {
            GameHub.ChannelSnapshot joinedChannel = hub.enterChannel(roomChannelId, this);
            if (joinedChannel == null) {
                observer = previousObserver;
                rejectRoomRequest("argo-channel-full", matchmaking);
                NativeRoomRules.joined(this);
                return;
            }
            hubChannelId = roomChannelId;
        }

        GameHub.RoomJoinOutcome roomJoin = hub.tryJoinRoom(roomId, this);
        if (!roomJoin.joined()) {
            System.out.println("[LiTo] C_LITO_JOIN rejected room-no-longer-joinable=" + roomId);
            if (argoJoin) {
                hub.leaveChannel(hubChannelId, this);
                hubChannelId = -1;
                observer = previousObserver;
            }
            Protocol.LitoJoinFailure nativeFailure = switch (roomJoin.failure()) {
                case BATTLE_STARTED -> Protocol.LitoJoinFailure.BATTLE_STARTED;
                case BATTLE_ENDED -> Protocol.LitoJoinFailure.BATTLE_ENDED;
                case FULL -> Protocol.LitoJoinFailure.ROOM_FULL;
                case KICKED -> Protocol.LitoJoinFailure.KICKED;
                case TEAM_ROOM_ONLY -> Protocol.LitoJoinFailure.TEAM_ROOM_ONLY;
                case CLASS_RESTRICTED -> Protocol.LitoJoinFailure.CLASS_RESTRICTED;
                case SERVER_RESTRICTED -> Protocol.LitoJoinFailure.SERVER_RESTRICTED;
                case NONE -> Protocol.LitoJoinFailure.SILENT_CLEANUP;
            };
            rejectRoomRequest("room-no-longer-joinable-" + roomJoin.failure(),
                    matchmaking, nativeFailure);
            NativeRoomRules.joined(this);
            return;
        }

        // This is the complete 3.81C S_CE room contract selected by
        // protocol 0x0734FD33: c,d,s,c,s,h,h,c,h,c,c,c,c,c,s,c,c,c,c,c.
        // Keeping the option fields explicit is important: S_D2 consumes the
        // globals populated by this parser when it creates the battle scene.
        String player = litoDisplayName();
        String owner = hub.roomOwnerDisplayName(roomId);
        if (owner.isBlank()) owner = player;
        BattleRules.RuleSet rules = hub.roomRules(roomId);
        Protocol.Writer joined = new Protocol.Writer()
                .c(Protocol.S_LITO_JOIN_RESULT)
                .c(0).d(roomId).s(settings.name())
                .c(settings.attributes()).s(settings.password())
                .h(Math.max(2, hub.roomCombatantCount(roomId))).h(settings.capacity())
                .c(settings.option0()).h(rules.mapId())
                // Five server-owned summary bytes are updated independently
                // by S_D5 subtypes 4 and 6..9. They are not C_CC/C_DD options.
                .c(0).c(0).c(0).c(0).c(0)
                .s(owner)
                .c(settings.option1()).c(settings.option2())
                .c(settings.option3()).c(settings.option4())
                .c(settings.selections().size());
        for (int selection : settings.selections()) joined.c(selection);
        if (matchmaking) {
            sendEncrypted(Protocol.litoAskMatchMakingResult(
                            Protocol.LitoMatchMakingResult.ACCEPTED),
                    "S_LITO_ASK_MATCH_MAKING_RESULT accepted room=" + roomId);
        }
        if (argoJoin && !previousObserver) {
            // S_E5 is the sole native writer of byte_64AFA1=1.  Synchronize
            // the role before S_CE/world construction so the client suppresses
            // combatant controls while byte_648F08 keeps the /argo lobby mode.
            sendEncrypted(Protocol.litoObserverResult(Protocol.LitoObserverState.ENABLED),
                    "S_LITO_SET_OBSERVER_RESULT enabled=true trigger=/argo");
        }
        sendEncrypted(joined.bytes(), "S_LITO_JOIN_RESULT accepted room=" + roomId + " trigger=" + trigger);
        hub.cancelMatchMaking(this);
        pendingMatchMakingRequest = null;
        NativePlayerCommit.scene(this, Phase.ROOM, "phase");
        ready = false;
        NativePlayerCommit.scene(this, roomId, "currentRoomId");
        if (!observer && roomJoin.combatantsBefore() == 1
                && NativeRoomRules.bot(hub.roomRules(roomId).mode(), hub, roomId)) {
            byte[] botLeft = new Protocol.Writer().c(Protocol.S_LITO_EXIT_ROOM)
                    .d(roomId).s("ArenaBot").bytes();
            for (ClientSession member : hub.roomMembers(roomId)) {
                if (member == this) continue;
                member.sendEncrypted(botLeft, "S_LITO_EXIT_ROOM ArenaBot replaced by player");
            }
        }
        List<ClientSession> members = roomJoin.members();
        for (ClientSession member : members) {
            sendRoomParticipant(roomId, member,
                    Protocol.LitoForce.fromWire(hub.forceOf(roomId, member)), "player");
            if (member != this) {
                member.sendRoomParticipant(roomId, this,
                        Protocol.LitoForce.fromWire(hub.forceOf(roomId, this)),
                        "player-joined");
            }
        }
        for (GameHub.RoomVirtualPlayer member : hub.roomVirtualPlayers(roomId)) {
            sendRoomVirtualPlayer(roomId, member, "gm-virtual-player");
        }
        if (NativeRoomRules.bot(hub.roomRules(roomId).mode(), hub, roomId)
                && hub.roomCombatantCount(roomId) < 2) {
            sendRoomParticipant(roomId, "ArenaBot", Protocol.LitoForce.FORCE_1,
                    0, 0, "", 0, "bot");
        }
        if (observer && hub.battleStarted(roomId)) {
            // A late observer did not see the room's original countdown.  The
            // native client expects those UI states before S_D2, so replay
            // them only to that observer without delaying the running match.
            for (int value = 3; value >= 1; value--) serverCountdown(value);
            startBattle();
        }
        System.out.println("[LiTo] joined room=" + roomId + " player=" + player + " observer=" + observer);
        LobbyRoomDirectory.refresh(this, "room-joined");
        NativeRoomRules.joined(this);
    }

    private void joinRentalTown(long l, String string, String string2, boolean bl) throws IOException {
        boolean bl2 = this.config.rentalTownDirectoryEnabled() && this.rentalTownDirectoryAdvertised && this.phase == Phase.LOBBY && l == this.config.rentalTownDirectoryRoomId() && string.isEmpty() && !this.selectedCharacter.isEmpty() && this.rentalItemSetSelection >= 0;
        this.rentalTownJoinPending = false;
        if (!bl2 || bl) {
            System.out.println("[LiTo] C_LITO_JOIN rental-town rejected room=" + l + " phase=" + String.valueOf((Object)this.phase) + " empty-password=" + string.isEmpty() + " selected-character=" + !this.selectedCharacter.isEmpty() + " item-set=" + this.rentalItemSetSelection);
            this.rejectRoomRequest("rental-town-chain", bl);
            return;
        }
        int n = Math.addExact(1, this.rentalTownOccupancy(l, this.config.rentalTownMapId()));
        String string3 = this.rentalTownOwnerName(l, this.config.rentalTownMapId());
        this.sendEncrypted(Protocol.litoRentalTownJoinResult(l, this.config.rentalTownDirectoryName(), this.config.rentalTownMapId(), string3, n), "S_LITO_JOIN_RESULT rental-town accepted room=" + l + " mode=6 map=" + this.config.rentalTownMapId() + " owner=" + string3 + " users=" + n + " trigger=" + string2);
        NativePlayerCommit.scene(this, (Object)Phase.ROOM, "phase");
        NativePlayerCommit.scene(this, l, "currentRoomId");
        this.ready = false;
        this.rentalTownRoomState = true;
        this.rentalTownMapId = this.config.rentalTownMapId();
        this.sendRoomParticipant(l, this, Protocol.LitoForce.FORCE_0, "rental-town-player");
        this.synchronizeRentalTownParticipantRows();
        this.startRentalTownScene();
        System.out.println("[LiTo] joined rental-town room=" + l + " player=" + this.playerName() + " map=" + this.config.rentalTownMapId() + " transfer-stone=granted scene-start=resource-derived-policy");
    }

    private void startRentalTownScene() throws IOException {
        NativeLitoTownScenePlan.Scene scene =
                NativeLitoTownScenePlan.require(rentalTownMapId);
        RentalLoadoutPlan plan = RentalLoadoutPlan.require(
                selectedCharacterSummary().type(), rentalItemSetSelection);
        rentalTownLoadout = plan.stage(
                scene.loadoutPolicy(), ClientSession::nextRentalItemObjectId);
        NativeDeItemApplication.replace(this, rentalTownLoadout.inventory(), 1);
        positionX = scene.spawnX();
        positionY = scene.spawnY();
        playerHeading = scene.heading();
        pendingPortal = null;
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
        pendingRentalHotelInput = null;
        rentalHotelLease = null;
        pendingRentalTownMapTransition = null;
        rentalTownTransferPending = false;
        rentalTownEmblemsGranted.clear();
        rentalTownEmblemsHeld.clear();
        rentalTownCitizen = false;
        rentalTownLightGemCount = RENTAL_LIGHT_GEM_PROVISIONAL_COUNT;
        pendingRentalMerchantList = null;

        // S_CE leaves the native client in room phase 2. Its dispatcher only
        // admits S_WORLD and S_D2 after the local S_D1 ready row advances that
        // room to phase 3. Ordinary Tournament rooms receive this row through
        // the ready/countdown flow; the server-gated rental town has no user
        // countdown, so publish the same transition immediately before WORLD.
        // The authoritative server-side ready flag remains false because this
        // synthetic direct room must never participate in GameHub matching.
        sendEncrypted(Protocol.readyState(
                        litoDisplayName(), Protocol.LitoParticipantState.READY),
                "S_LITO_READY_GAME rental-town scene-transition player="
                        + playerName());

        Protocol.BattleBootstrap bootstrap = Protocol.battleBootstrap(scene.mapId(), 1);
        sendEncrypted(bootstrap.world(),
                "S_WORLD rental-town map=" + scene.mapId()
                        + " resource-sha="
                        + NativeLitoTownCatalog.forMap(scene.mapId()).resourceSha256());
        sendEncrypted(bootstrap.start(),
                "S_LITO_START_GAME rental-town mode=6");
        NativeLitoTownCatalog.Town town = NativeLitoTownCatalog.forMap(scene.mapId());
        if (town == null) {
            throw new IOException("rental-town native geometry is missing");
        }
        sendEncrypted(Protocol.observerBox(
                        town.minX(), town.minY(), town.maxX() + 1, town.maxY() + 1),
                "S_LITO_OBSERVER_BOX rental-town min=" + town.minX() + ","
                        + town.minY() + " max-exclusive=" + (town.maxX() + 1)
                        + "," + (town.maxY() + 1));
        NativePlayerCommit.scene(this, Phase.BATTLE, "phase");
        notifyBuddyActivity(Protocol.LitoBuddyActivity.FIGHTING);
        int gameSeconds = ClassicLineageClock.now();
        sendEncrypted(Protocol.worldTime(gameSeconds),
                "S_TIME rental-town game-seconds=" + gameSeconds);

        List<Protocol.InventoryWireItem> items = new ArrayList<>(
                rentalTownInventory.items().stream()
                        .map(RuntimeInventory.Item::wireItem).toList());
        items.add(Protocol.litoRentalLightGem(
                RENTAL_LIGHT_GEM_OBJECT_ID, rentalTownLightGemCount));
        items.add(Protocol.litoRentalTownMap(RENTAL_TOWN_MAP_OBJECT_ID));
        items.add(Protocol.litoTransferStone(TRANSFER_STONE_PROBE_OBJECT_ID));
        sendEncrypted(Protocol.inventoryBatch(items),
                "S_ADD_INVENTORY_BATCH rental-town items=" + items.size()
                        + " set=" + rentalTownLoadout.source().label()
                        + " policy=" + scene.loadoutPolicy()
                        + " light-gems=" + RENTAL_LIGHT_GEM_PROVISIONAL_COUNT
                        + " town-map=granted transfer-stone=granted");
        rentalTownTransferStoneGranted = true;
        // LTshop-c names this balance as Boundless Arena coins.  Expose the
        // current authoritative account balance on first town entry without
        // inventing a second persistent currency item or conflating it with
        // the separately reset per-match Tournament allowance.
        sendPointStats();

        resetAndSendRentalTownStatus();
        sendRentalTownActor("scene-bootstrap");
        sendRentalTownNpcs("scene-bootstrap");
        sendRentalHotelGroundKeys("scene-bootstrap");
        sendEncrypted(Protocol.minimapPlayer(
                        playerObjectId(), positionX, positionY, true),
                "S_LITO_MINIMAP rental-town player=" + playerName()
                        + " x=" + positionX + " y=" + positionY);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT rental-town player=" + playerHp + "/" + playerMaxHp);
        synchronizeRentalTownActors("scene-bootstrap");
        System.out.println("[LiTo] rental-town scene bootstrapped map=" + scene.mapId()
                + " x=" + scene.spawnX() + " y=" + scene.spawnY()
                + " historical-spawn-exact=" + scene.historicalSpawnExact()
                + " spawn-authority=" + scene.spawnAuthority()
                + " loadout-policy=" + scene.loadoutPolicy()
                + " inventory-objects=" + rentalTownInventory.size());
    }

    private void sendRentalTownNpcs(String reason) throws IOException {
        List<NativeLitoRentalTownNpcCatalog.Npc> npcs =
                NativeLitoRentalTownNpcCatalog.forMap(rentalTownMapId);
        for (NativeLitoRentalTownNpcCatalog.Npc npc : npcs) {
            sendEncrypted(Protocol.litoRentalTownNpc(npc),
                    "S_PUT_OBJECT rental-town-npc resource=" + npc.resourceIndex()
                            + " object=" + npc.objectId() + " x=" + npc.x()
                            + " y=" + npc.y() + " reason=" + reason
                            + " placement="
                            + NativeLitoRentalTownNpcCatalog.PLACEMENT_AUTHORITY);
        }
    }

    private void openRentalTownHypertext(long objectId) throws IOException {
        NativeLitoRentalTownNpcCatalog.Npc npc =
                NativeLitoRentalTownNpcCatalog.find(rentalTownMapId, objectId);
        if (npc == null || rentalTownNpcDistance(npc) >
                NativeLitoRentalTownNpcCatalog.INTERACTION_RANGE) {
            System.out.println("[LiTo] C_DIALOG rental-town rejected object=" + objectId
                    + " map=" + rentalTownMapId + " player=" + playerName());
            return;
        }
        boolean completed = npc.role() == NativeLitoRentalTownNpcCatalog.Role.GUIDE
                ? rentalTownCitizen
                : rentalTownEmblemsGranted.contains(npc.emblemResourceIndex());
        String html = completed ? npc.endHtml() : npc.startHtml();
        sendEncrypted(Protocol.hypertext(npc.objectId(), html, "", List.of()),
                "S_HYPERTEXT rental-town-npc resource=" + npc.resourceIndex()
                        + " html=" + html + " completed=" + completed);
    }

    private void handleRentalTownHypertextAction(
            Protocol.HypertextActionRequest request) throws IOException {
        NativeLitoRentalTownNpcCatalog.Npc npc =
                NativeLitoRentalTownNpcCatalog.find(
                        rentalTownMapId, request.worldObjectId());
        if (npc == null || !request.parameter().isEmpty()
                || rentalTownNpcDistance(npc) >
                    NativeLitoRentalTownNpcCatalog.INTERACTION_RANGE) {
            System.out.println("[LiTo] C_HACTION rental-town rejected object="
                    + request.worldObjectId() + " action=" + request.action()
                    + " parameter=" + request.parameter() + " map=" + rentalTownMapId);
            return;
        }
        if (NativeLitoRentalTownNpcCatalog.isRentalMerchant(npc)) {
            if (NativeLitoRentalTownNpcCatalog.RETURN_ACTION.equals(request.action())) {
                openRentalTownReturnList(npc);
                return;
            }
            if (NativeLitoRentalTownNpcCatalog.RENT_ACTION.equals(request.action())) {
                openRentalTownRentList(npc);
                return;
            }
        }
        if (NativeLitoRentalTownNpcCatalog.isHotelService(npc)
                && NativeLitoRentalTownNpcCatalog.isHotelAction(request.action())) {
            handleRentalTownHotelAction(npc, request.action());
            return;
        }
        if (NativeLitoRentalTownNpcCatalog.isTeleportService(npc)
                && NativeLitoRentalTownNpcCatalog.isTeleportActionForNpc(
                        npc, request.action())) {
            handleRentalTownTeleportAction(npc, request.action());
            return;
        }
        if (npc.action() == null || !npc.action().equals(request.action())) {
            System.out.println("[LiTo] C_HACTION rental-town rejected object="
                    + request.worldObjectId() + " action=" + request.action()
                    + " result=unrecognized-resource-action");
            return;
        }
        if (npc.role() == NativeLitoRentalTownNpcCatalog.Role.GUIDE) {
            completeRentalTownCitizenship(npc);
            return;
        }
        grantRentalTownEmblem(npc);
    }

    private void handleRentalTownTeleportAction(NativeLitoRentalTownNpcCatalog.Npc npc, String string) throws IOException {
        NativeLitoRentalTeleportEndpointCatalog.Endpoint endpoint = NativeLitoRentalTeleportEndpointCatalog.find(this.config.rentalTeleportEndpoints(), npc.startHtml(), string);
        if (endpoint == null) {
            System.out.println("[LiTo] C_HACTION rental-town teleporter deferred resource=" + npc.resourceIndex() + " html=" + npc.startHtml() + " action=" + string + " result=server-owned-endpoint-not-configured");
            return;
        }
        GameHub gameHub = this.hub;
        String string3 = this.accountName();
        String string2 = this.stateCharacter();
        RuntimeInventory runtimeInventory = this.rentalTownInventory;
        boolean bl = gameHub.stageRentalBattleHandoff(SourceLogin.account(this, string3), string2, runtimeInventory);
        if (!bl) {
            System.out.println("[LiTo] C_HACTION rental-town teleporter rejected resource=" + npc.resourceIndex() + " html=" + npc.startHtml() + " action=" + string + " result=missing-authenticated-character-or-rental-loadout");
            return;
        }
        this.pendingRentalTeleportEndpoint = endpoint;
        this.rentalTownTransferPending = true;
        Protocol.LitoVsServerAvailability[] litoVsServerAvailabilityArray = NativeLitoRentalTeleportEndpointCatalog.statusTable(this.config.rentalTeleportEndpoints(), npc.startHtml());
        this.sendEncrypted(Protocol.vsServerStatus(litoVsServerAvailabilityArray), "S_LITO_VS_SERVER_STATUS rental-teleport html=" + npc.startHtml() + " count=" + litoVsServerAvailabilityArray.length);
        this.sendEncrypted(Protocol.litoVsServerIp(endpoint.serverIndex(), endpoint.ipv4(), endpoint.port()), "S_LITO_VS_SERVER_IP rental-teleport html=" + npc.startHtml() + " action=" + string + " index=" + endpoint.serverIndex() + " destination=" + endpoint.name() + "@" + endpoint.host() + ":" + endpoint.port());
        System.out.println("[LiTo] rental-town endpoint selected player=" + this.playerName() + " html=" + npc.startHtml() + " action=" + string + " index=" + endpoint.serverIndex() + " destination=" + endpoint.name() + " equipment-handoff-staged=" + bl);
    }

    private void openRentalTownRentList(
            NativeLitoRentalTownNpcCatalog.Npc npc) throws IOException {
        List<NativeLitoRentalMerchantCatalog.Item> offered =
                NativeLitoRentalMerchantCatalog.offeredBy(npc.resourceIndex());
        if (offered.isEmpty()) {
            pendingRentalMerchantList = null;
            System.out.println("[LiTo] C_HACTION rental-town merchant has no retained rows"
                    + " resource=" + npc.resourceIndex());
            return;
        }
        Map<Long, NativeLitoRentalMerchantCatalog.Item> byOrder =
                new LinkedHashMap<>();
        List<Protocol.ClassicBuyListRow> rows = new ArrayList<>();
        for (int index = 0; index < offered.size(); index++) {
            NativeLitoRentalMerchantCatalog.Item item = offered.get(index);
            long orderId = index;
            byOrder.put(orderId, item);
            rows.add(new Protocol.ClassicBuyListRow(
                    orderId, item.definition().icon(), item.lightGemPrice(),
                    item.definition().name(), item.buyListDetail()));
        }
        pendingRentalMerchantList = new PendingRentalMerchantList(
                npc.objectId(), npc.resourceIndex(), rentalTownMapId, 0,
                byOrder, System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.litoRentalBuyList(npc.objectId(), rows),
                "S_BUY_LIST rental-town resource=" + npc.resourceIndex()
                        + " rows=" + rows.size() + " currency=light-gem"
                        + " retained-source=true historical-official-exact="
                        + NativeLitoRentalMerchantCatalog.HISTORICAL_OFFICIAL_EXACT);
    }

    private void openRentalTownReturnList(
            NativeLitoRentalTownNpcCatalog.Npc npc) throws IOException {
        Map<Long, NativeLitoRentalMerchantCatalog.Item> accepted =
                new LinkedHashMap<>();
        for (NativeLitoRentalMerchantCatalog.Item item
                : NativeLitoRentalMerchantCatalog.offeredBy(npc.resourceIndex())) {
            accepted.put((long) item.sourceItemId(), item);
        }
        Map<Long, NativeLitoRentalMerchantCatalog.Item> byObject =
                new LinkedHashMap<>();
        List<Protocol.ClassicSellListRow> rows = new ArrayList<>();
        for (RuntimeInventory.Item inventoryItem : rentalTownInventory.items()) {
            NativeLitoRentalMerchantCatalog.Item item = accepted.get(
                    inventoryItem.definition().catalogId());
            if (item == null || inventoryItem.equipped()) continue;
            byObject.put(inventoryItem.objectId(), item);
            rows.add(new Protocol.ClassicSellListRow(
                    inventoryItem.objectId(), item.lightGemPrice()));
        }
        if (rows.isEmpty()) {
            pendingRentalMerchantList = null;
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(),
                            NativeLitoRentalTownNpcCatalog.NO_RENT_HTML,
                            "", List.of(npc.name())),
                    "S_HYPERTEXT rental-town-return-empty resource="
                            + npc.resourceIndex() + " html="
                            + NativeLitoRentalTownNpcCatalog.NO_RENT_HTML);
            return;
        }
        pendingRentalMerchantList = new PendingRentalMerchantList(
                npc.objectId(), npc.resourceIndex(), rentalTownMapId, 1,
                byObject, System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.classicSellList(npc.objectId(), rows),
                "S_SELL_LIST rental-town resource=" + npc.resourceIndex()
                        + " rows=" + rows.size() + " refund=light-gem");
    }

    private PendingRentalMerchantList validRentalMerchantList(
            Protocol.ClassicShopTransaction transaction) {
        PendingRentalMerchantList context = pendingRentalMerchantList;
        NativeLitoRentalTownNpcCatalog.Npc npc = context == null ? null
                : NativeLitoRentalTownNpcCatalog.find(
                        rentalTownMapId, context.npcObjectId());
        boolean valid = context != null && transaction != null
                && rentalTownRoomState && phase == Phase.BATTLE
                && !observer && playerHp > 0
                && context.mapId() == rentalTownMapId
                && context.npcObjectId() == transaction.npcObjectId()
                && context.mode() == transaction.mode()
                && npc != null && npc.resourceIndex() == context.merchantResourceIndex()
                && NativeLitoRentalTownNpcCatalog.isRentalMerchant(npc)
                && rentalTownNpcDistance(npc)
                    <= NativeLitoRentalTownNpcCatalog.INTERACTION_RANGE
                && System.nanoTime() <= context.expiresAtNanos();
        if (!valid) pendingRentalMerchantList = null;
        return valid ? context : null;
    }

    private void rentalTownBuySell(byte[] payload) throws IOException {
        Protocol.ClassicShopTransaction transaction =
                Protocol.classicShopTransaction(payload);
        if (rejectWhileParalyzed("C_BUY_SELL rental-town")) {
            pendingRentalMerchantList = null;
            return;
        }
        PendingRentalMerchantList context = validRentalMerchantList(transaction);
        if (context == null) {
            System.out.println("[LiTo] C_BUY_SELL rental-town rejected stale-context npc="
                    + transaction.npcObjectId() + " mode=" + transaction.mode());
            return;
        }
        if (transaction.lines().isEmpty()) {
            pendingRentalMerchantList = null;
            System.out.println("[LiTo] C_BUY_SELL rental-town cancel npc="
                    + transaction.npcObjectId() + " mode=" + transaction.mode());
            return;
        }

        Map<Long, Long> requested = new LinkedHashMap<>();
        try {
            for (Protocol.ShopLine line : transaction.lines()) {
                requested.merge(line.itemId(), line.quantity(), Math::addExact);
            }
        } catch (ArithmeticException overflow) {
            pendingRentalMerchantList = null;
            System.out.println("[LiTo] C_BUY_SELL rental-town rejected quantity-overflow");
            return;
        }

        RuntimeInventory previous = rentalTownInventory;
        RuntimeInventory next = previous.copy();
        long lightGemDelta = 0;
        long nextLightGemCount = rentalTownLightGemCount;
        String rejection = null;
        try {
            if (context.mode() == 0) {
                long expiresAt = Math.addExact(System.currentTimeMillis(),
                        Math.multiplyExact((long) NativeLitoRentalMerchantCatalog.RENTAL_SECONDS,
                                1_000L));
                long totalInstances = 0;
                long totalItemUnitWeight = 0;
                for (Map.Entry<Long, Long> entry : requested.entrySet()) {
                    NativeLitoRentalMerchantCatalog.Item item =
                            context.offeredByWireId().get(entry.getKey());
                    if (item == null) {
                        rejection = "unoffered-buy-row";
                        break;
                    }
                    totalInstances = Math.addExact(totalInstances, entry.getValue());
                    lightGemDelta = Math.addExact(lightGemDelta,
                            Math.multiplyExact(item.lightGemPrice(), entry.getValue()));
                    totalItemUnitWeight = Math.addExact(totalItemUnitWeight,
                            Math.multiplyExact((long) item.definition().unitWeight(),
                                    entry.getValue()));
                }
                if (rejection == null && (totalInstances > RuntimeInventory.MAX_SLOTS
                        || totalInstances > RuntimeInventory.MAX_SLOTS - next.size())) {
                    rejection = "inventory-capacity";
                }
                if (rejection == null && lightGemDelta > rentalTownLightGemCount) {
                    rejection = "insufficient-light-gem";
                }
                if (rejection == null && !BattleInventoryWeight.permitsShopOrder(
                        rentalTownWeightProfile(previous, System.nanoTime()),
                        totalItemUnitWeight)) {
                    rejection = "inventory-weight";
                }
                if (rejection == null) {
                    nextLightGemCount = Math.subtractExact(
                            rentalTownLightGemCount, lightGemDelta);
                }
                for (Map.Entry<Long, Long> entry : requested.entrySet()) {
                    if (rejection != null) break;
                    NativeLitoRentalMerchantCatalog.Item item =
                            context.offeredByWireId().get(entry.getKey());
                    for (long count = 0; count < entry.getValue(); count++) {
                        RuntimeInventory.PersistentItem state =
                                new RuntimeInventory.PersistentItem(
                                        0, 1, 0, 0, true,
                                        RuntimeInventory.BLESSING_NORMAL,
                                        false, false, false, null,
                                        item.definition().initialChargeCount(),
                                        expiresAt, false);
                        if (next.addDistinctState(item.definition(), state,
                                ClientSession::nextRentalItemObjectId) == 0) {
                            rejection = "inventory-capacity";
                            break;
                        }
                    }
                    if (rejection != null) break;
                }
            } else {
                for (Map.Entry<Long, Long> entry : requested.entrySet()) {
                    NativeLitoRentalMerchantCatalog.Item item =
                            context.offeredByWireId().get(entry.getKey());
                    RuntimeInventory.Item owned = next.item(entry.getKey());
                    if (item == null || owned == null || owned.equipped()
                            || owned.definition().catalogId() != item.sourceItemId()
                            || entry.getValue() != 1
                            || !next.remove(owned.objectId(), 1)) {
                        rejection = "invalid-return-row";
                        break;
                    }
                    lightGemDelta = Math.addExact(lightGemDelta,
                            item.lightGemPrice());
                }
                if (rejection == null) {
                    nextLightGemCount = Math.addExact(
                            rentalTownLightGemCount, lightGemDelta);
                }
            }
        } catch (ArithmeticException overflow) {
            rejection = "transaction-overflow";
        }

        pendingRentalMerchantList = null;
        if (rejection != null) {
            if (rejection.equals("insufficient-light-gem")) {
                sendEncrypted(Protocol.systemMessage(9, "光之寶石不足。"),
                        "S_SYSTEM_MESSAGE rental-town insufficient-light-gem");
            } else if (rejection.equals("inventory-capacity")) {
                sendInventoryCapacityOver("rental-town-merchant");
            } else if (rejection.equals("inventory-weight")) {
                sendInventoryWeightOver("rental-town-merchant");
            }
            System.out.println("[LiTo] C_BUY_SELL rental-town rejected npc="
                    + transaction.npcObjectId() + " mode=" + transaction.mode()
                    + " reason=" + rejection);
            return;
        }

        NativeDeItemApplication.replace(this, next, 1);
        rentalTownLightGemCount = nextLightGemCount;
        sendInventoryDelta(previous, rentalTownInventory, false);
        sendEncrypted(Protocol.changeInventoryCount(
                        RENTAL_LIGHT_GEM_OBJECT_ID, rentalTownLightGemCount),
                "S_CHANGE_INVENTORY_COUNT rental-town light-gems="
                        + rentalTownLightGemCount + " delta="
                        + (context.mode() == 0 ? -lightGemDelta : lightGemDelta));
        System.out.println("[LiTo] C_BUY_SELL rental-town accepted npc="
                + transaction.npcObjectId() + " resource="
                + context.merchantResourceIndex() + " mode=" + transaction.mode()
                + " rows=" + transaction.lines().size() + " light-gems="
                + rentalTownLightGemCount + " inventory=" + rentalTownInventory.size());
    }

    private void handleRentalTownHotelAction(
            NativeLitoRentalTownNpcCatalog.Npc npc, String action) throws IOException {
        long nowNanos = System.nanoTime();
        expireRentalHotelLeaseIfDue(nowNanos, "hotel-action");
        if (NativeLitoRentalTownNpcCatalog.HOTEL_ROOM_ACTION.equals(action)) {
            RentalHotelLease lease = activeRentalHotelLease(nowNanos);
            if (lease != null) {
                sendEncrypted(Protocol.hypertext(
                                npc.objectId(), NativeLitoRentalHotelCatalog.RENTED_HTML,
                                "", List.of(npc.name())),
                        "S_HYPERTEXT rental-town-hotel already-rented map="
                                + lease.room().mapId());
                return;
            }
            int mode = 0;
            String callback = "";
            pendingRentalHotelInput = new PendingRentalHotelInput(
                    npc.objectId(), rentalTownMapId,
                    NativeLitoRentalHotelCatalog.MAXIMUM_KEYS, mode, callback,
                    nowNanos + HOTEL_RENTAL_CONTEXT_TIMEOUT_NANOS);
            sendEncrypted(Protocol.hypertextInput(
                            npc.objectId(), 0, 1,
                            NativeLitoRentalHotelCatalog.MINIMUM_KEYS,
                            NativeLitoRentalHotelCatalog.MAXIMUM_KEYS,
                            mode, NativeLitoRentalHotelCatalog.INPUT_HTML,
                            "", callback, List.of(npc.name())),
                    "S_HYPERTEXT_INPUT rental-town-hotel free=true minimum="
                            + NativeLitoRentalHotelCatalog.MINIMUM_KEYS
                            + " maximum=" + NativeLitoRentalHotelCatalog.MAXIMUM_KEYS
                            + " historical-key-threshold-exact="
                            + NativeLitoRentalHotelCatalog.HISTORICAL_KEY_COUNT_THRESHOLDS_EXACT);
            return;
        }
        if (NativeLitoRentalTownNpcCatalog.HOTEL_RETURN_ACTION.equals(action)) {
            pendingRentalHotelInput = null;
            RentalHotelLease lease = activeRentalHotelLease(nowNanos);
            RentalTownHotelRegistry.Lease shared = lease == null ? null
                    : hub.rentalHotelLease(lease.token(), nowNanos);
            if (shared != null && shared.owner(playerObjectId())) {
                sendEncrypted(Protocol.hypertext(
                                npc.objectId(), NativeLitoRentalHotelCatalog.RETURNED_HTML,
                                "", List.of(npc.name())),
                        "S_HYPERTEXT rental-town-hotel returned map="
                                 + lease.room().mapId() + " logical-keys="
                                 + lease.keyCount());
                invalidateSharedRentalHotelLease(lease.token(), "manual-return");
            }
            return;
        }
        if (NativeLitoRentalTownNpcCatalog.HOTEL_ENTER_ACTION.equals(action)) {
            RentalHotelLease lease = activeRentalHotelLease(nowNanos);
            if (lease == null || nowNanos > lease.expiresAtNanos()
                    || !hub.rentalHotelInventoryOwnsCredential(
                            lease.token(), rentalTownInventory.items(), nowNanos)) return;
            NativeLitoRentalHotelCatalog.Room room = lease.room();
            beginRentalTownMapTransition(new Protocol.PortalDestination(
                            room.mapId(), room.entryX(), room.entryY(), true),
                    room.entryHeading(), "rental-hotel-enter", lease.token(), false);
        }
    }

    private void performRentalTownHotelRental(
            NativeLitoRentalTownNpcCatalog.Npc npc, int keyCount) throws IOException {
        NativeLitoRentalHotelCatalog.Room room =
                NativeLitoRentalHotelCatalog.forKeyCount(keyCount);
        if (room == null) return;
        long token = RENTAL_HOTEL_LEASE_SEQUENCE.getAndIncrement();
        long durationNanos = TimeUnit.SECONDS.toNanos(room.durationSeconds());
        long expiresAtNanos = System.nanoTime() + durationNanos;
        RuntimeInventory previous = rentalTownInventory;
        RuntimeInventory next = rentalTownInventory.copy();
        InventoryCatalog.Definition keyDefinition = InventoryCatalog.require(
                NativeLitoRentalHotelCatalog.KEY_ITEM_ID);
        if (!next.add(keyDefinition, keyCount)) {
            sendInventoryCapacityOver("rental-town-hotel-keys");
            return;
        }
        Set<Long> previousObjects = previous.items().stream()
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toSet());
        List<Long> keyObjectIds = next.items().stream()
                .filter(item -> !previousObjects.contains(item.objectId())
                        && item.definition().catalogId()
                            == NativeLitoRentalHotelCatalog.KEY_ITEM_ID)
                .map(RuntimeInventory.Item::objectId).toList();
        if (keyObjectIds.size() != keyCount) {
            throw new IOException("rental-hotel key allocation count changed");
        }
        RentalTownHotelRegistry.Lease registered = hub.registerRentalHotelLease(
                token, playerObjectId(), keyCount, room, expiresAtNanos,
                keyObjectIds);
        if (registered == null) return;
        RentalHotelLease lease = localRentalHotelLease(registered);
        synchronized (rentalHotelLifecycleLock) {
            if (rentalHotelLease != null) return;
            rentalHotelLease = lease;
        }
        NativeDeItemApplication.replace(this, next, 1);
        sendInventoryDelta(previous, rentalTownInventory, false);
        hub.scheduleRentalHotelExpiry(this, token, durationNanos);
        sendEncrypted(Protocol.hypertext(
                        npc.objectId(), NativeLitoRentalHotelCatalog.RENTED_HTML,
                        "", List.of(npc.name())),
                "S_HYPERTEXT rental-town-hotel rented free=true map="
                        + room.mapId() + " kind=" + room.kind()
                        + " logical-keys=" + keyCount
                        + " duration-seconds=" + room.durationSeconds()
                        + " key-item-resource-available="
                        + NativeLitoRentalHotelCatalog.HISTORICAL_KEY_ITEM_RESOURCE_AVAILABLE
                        + " key-transfer-available="
                        + NativeLitoRentalHotelCatalog.HISTORICAL_KEY_TRANSFER_AVAILABLE);
    }

    private void expireRentalHotelLeaseIfDue(long nowNanos, String reason)
            throws IOException {
        synchronized (rentalHotelLifecycleLock) {
            RentalHotelLease lease = rentalHotelLease;
            if (lease != null && nowNanos >= lease.expiresAtNanos()
                    && !NativeLitoRentalHotelCatalog.supportsMap(rentalTownMapId)) {
                RentalTownHotelRegistry.Lease shared =
                        hub.rentalHotelLease(lease.token(), Long.MIN_VALUE);
                if (shared != null && shared.owner(playerObjectId())) {
                    invalidateSharedRentalHotelLease(lease.token(), reason);
                } else {
                    rentalHotelLease = null;
                    pendingRentalHotelInput = null;
                }
            }
        }
    }

    void serverRentalHotelExpiry(long leaseToken) throws IOException {
        RentalHotelLease lease;
        long remaining;
        synchronized (rentalHotelLifecycleLock) {
            lease = rentalHotelLease;
            if (lease == null || lease.token() != leaseToken) return;
            remaining = lease.expiresAtNanos() - System.nanoTime();
            if (remaining > 0) {
                hub.scheduleRentalHotelExpiry(this, leaseToken, remaining);
                return;
            }
            RentalTownHotelRegistry.Lease shared =
                    hub.rentalHotelLease(leaseToken, Long.MIN_VALUE);
            if (shared == null || !shared.owner(playerObjectId())) return;
        }
        invalidateSharedRentalHotelLease(leaseToken, "rental-hotel-expiry");
    }

    private RentalHotelLease activeRentalHotelLease(long nowNanos) {
        RentalHotelLease local = rentalHotelLease;
        if (local != null && hub.rentalHotelLease(local.token(), nowNanos) != null) {
            return local;
        }
        RentalTownHotelRegistry.Lease shared =
                hub.rentalHotelLeaseForInventory(
                        rentalTownInventory.items(), nowNanos);
        if (shared == null) {
            rentalHotelLease = null;
            return null;
        }
        RentalHotelLease admitted = localRentalHotelLease(shared);
        rentalHotelLease = admitted;
        return admitted;
    }

    private static RentalHotelLease localRentalHotelLease(
            RentalTownHotelRegistry.Lease lease) {
        return new RentalHotelLease(
                lease.token(), lease.keyCount(), lease.room(),
                lease.expiresAtNanos());
    }

    private void invalidateSharedRentalHotelLease(long leaseToken, String reason)
            throws IOException {
        RentalTownHotelRegistry.Invalidation invalidation =
                hub.invalidateRentalHotelLease(leaseToken);
        if (invalidation == null) return;
        IOException first = null;
        List<ClientSession> affected = new ArrayList<>(
                hub.connectedSessionsSnapshot());
        if (!affected.contains(this)) affected.add(this);
        for (ClientSession member : affected) {
            try {
                member.serverRentalHotelLeaseInvalidated(invalidation, reason);
            } catch (IOException error) {
                if (first == null) first = error;
                System.out.println("[LiTo] rental-hotel invalidation send failed token="
                        + leaseToken + " player=" + member.playerName()
                        + " reason=" + error.getMessage());
            }
        }
        System.out.println("[LiTo] rental-hotel lease invalidated token="
                + leaseToken + " reason=" + reason + " keys="
                + invalidation.keyObjectIds().size());
        if (first != null) throw first;
    }

    private void serverRentalHotelLeaseInvalidated(
            RentalTownHotelRegistry.Invalidation invalidation, String reason)
            throws IOException {
        Set<Long> carried = rentalTownInventory.items().stream()
                .map(RuntimeInventory.Item::objectId)
                .filter(invalidation.keyObjectIds()::contains)
                .collect(java.util.stream.Collectors.toSet());
        if (!carried.isEmpty()) {
            RuntimeInventory previous = rentalTownInventory;
            NativeDeItemApplication.replace(this, rentalTownInventory.withoutObjects(carried), 1);
            if (rentalTownRoomState && phase == Phase.BATTLE) {
                sendInventoryDelta(previous, rentalTownInventory, false);
            }
        }
        if (rentalTownRoomState && phase == Phase.BATTLE) {
            for (RentalTownHotelRegistry.GroundItem ground
                    : invalidation.removedGroundItems()) {
                if (rentalHotelGroundScopeMatches(ground)
                        && BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY, ground.x(), ground.y())) {
                    sendEncrypted(Protocol.removeObject(ground.objectId()),
                            "S_REMOVE_OBJECT rental-hotel-key invalidated="
                                    + ground.objectId() + " reason=" + reason);
                }
            }
        }
        RentalHotelLease local = rentalHotelLease;
        if (local == null || local.token() != invalidation.lease().token()) return;
        pendingRentalHotelInput = null;
        boolean ownerDeparture = invalidation.lease().owner(playerObjectId())
                && switch (reason) {
                    case "room-exit", "battle-destination-selected",
                            "restart-return", "disconnect" -> true;
                    default -> false;
                };
        if (!ownerDeparture && rentalTownRoomState && phase == Phase.BATTLE
                && NativeLitoRentalHotelCatalog.supportsMap(rentalTownMapId)) {
            beginRentalTownMapTransition(new Protocol.PortalDestination(
                            NativeLitoRentalHotelCatalog.RETURN_MAP_ID,
                            NativeLitoRentalHotelCatalog.RETURN_X,
                            NativeLitoRentalHotelCatalog.RETURN_Y, true),
                    NativeLitoRentalHotelCatalog.RETURN_HEADING,
                    reason, local.token(), true);
        } else {
            rentalHotelLease = null;
            PendingRentalTownMapTransition transition =
                    pendingRentalTownMapTransition;
            if (transition != null
                    && transition.leaseToken() == invalidation.lease().token()) {
                pendingRentalTownMapTransition = null;
                pendingPortal = null;
                pendingPortalReady = false;
            }
        }
    }

    private void prepareRentalHotelDeparture(String reason) throws IOException {
        RentalHotelLease local = rentalHotelLease;
        if (local == null) return;
        RentalTownHotelRegistry.Lease shared =
                hub.rentalHotelLease(local.token(), Long.MIN_VALUE);
        if (shared != null && shared.owner(playerObjectId())) {
            invalidateSharedRentalHotelLease(local.token(), reason);
            return;
        }
        Set<Long> discarded = rentalTownInventory.items().stream()
                .filter(item -> item.definition().catalogId()
                        == NativeLitoRentalHotelCatalog.KEY_ITEM_ID)
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toSet());
        hub.discardRentalHotelKeys(discarded);
        rentalHotelLease = null;
    }

    private long rentalHotelGroundInstanceToken() {
        if (!NativeLitoRentalHotelCatalog.supportsMap(rentalTownMapId)) return 0;
        RentalHotelLease local = rentalHotelLease;
        return local == null ? -1 : local.token();
    }

    private boolean rentalHotelGroundScopeMatches(
            RentalTownHotelRegistry.GroundItem item) {
        return item != null && rentalTownRoomState
                && currentRoomId == item.roomId()
                && rentalTownMapId == item.mapId()
                && rentalHotelGroundInstanceToken() == item.instanceToken();
    }

    private void beginRentalTownMapTransition(
            Protocol.PortalDestination destination, int heading,
            String reason, long leaseToken, boolean clearLeaseOnCompletion)
            throws IOException {
        if (!rentalTownRoomState || phase != Phase.BATTLE
                || currentRoomId == 0 || pendingPortal != null
                || destination == null || !destination.accepted()
                || !rentalMapStandingPassable(
                        destination.mapId(), destination.x(), destination.y())) {
            return;
        }
        RentalHotelLease lease = rentalHotelLease;
        if (lease == null || lease.token() != leaseToken) return;
        boolean entering = rentalTownMapId == NativeLitoRentalHotelCatalog.RETURN_MAP_ID
                && destination.mapId() == lease.room().mapId();
        boolean returning = rentalTownMapId == lease.room().mapId()
                && destination.mapId() == NativeLitoRentalHotelCatalog.RETURN_MAP_ID;
        if (!entering && !returning) return;

        for (ClientSession peer : rentalTownPeers()) {
            peer.sendEncrypted(Protocol.removeObject(playerObjectId()),
                    "S_REMOVE_OBJECT rental-town map-transition=" + playerName());
            sendEncrypted(Protocol.removeObject(peer.playerObjectId()),
                    "S_REMOVE_OBJECT rental-town map-transition-peer=" + peer.playerName());
        }
        pendingRentalTownMapTransition = new PendingRentalTownMapTransition(
                rentalTownMapId, destination, Math.floorMod(heading, 8),
                reason, leaseToken, clearLeaseOnCompletion);
        pendingPortal = destination;
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL " + reason + " map=" + destination.mapId()
                        + " x=" + destination.x() + " y=" + destination.y()
                        + " historical-map-type-exact="
                        + NativeLitoRentalHotelCatalog.HISTORICAL_MAP_TYPE_ASSIGNMENT_EXACT);
    }

    private void grantRentalTownEmblem(
            NativeLitoRentalTownNpcCatalog.Npc npc) throws IOException {
        int resourceIndex = npc.emblemResourceIndex();
        if (rentalTownEmblemsGranted.add(resourceIndex)) {
            rentalTownEmblemsHeld.add(resourceIndex);
            Protocol.InventoryWireItem emblem = Protocol.litoRentalTownEmblem(
                    NativeLitoRentalTownNpcCatalog.emblemObjectId(resourceIndex),
                    resourceIndex, npc.emblemName());
            sendEncrypted(Protocol.addInventory(emblem),
                    "S_ADD_INVENTORY rental-town-emblem resource=" + resourceIndex
                            + " object=" + emblem.objectId()
                            + " identity="
                            + NativeLitoRentalTownNpcCatalog.IDENTITY_AUTHORITY);
        }
        sendEncrypted(Protocol.hypertext(npc.objectId(), npc.endHtml(), "", List.of()),
                "S_HYPERTEXT rental-town-emblem-complete resource=" + resourceIndex
                        + " html=" + npc.endHtml());
    }

    private void completeRentalTownCitizenship(
            NativeLitoRentalTownNpcCatalog.Npc guide) throws IOException {
        if (rentalTownCitizen) {
            sendEncrypted(Protocol.hypertext(
                            guide.objectId(), guide.endHtml(), "", List.of()),
                    "S_HYPERTEXT rental-town-citizen-already-complete");
            return;
        }
        Set<Integer> required = Set.of(
                NativeLitoRentalTownNpcCatalog.AUTHORITY_EMBLEM_INDEX,
                NativeLitoRentalTownNpcCatalog.CRAFTSMAN_EMBLEM_INDEX,
                NativeLitoRentalTownNpcCatalog.DELIGHT_EMBLEM_INDEX,
                NativeLitoRentalTownNpcCatalog.PEACE_EMBLEM_INDEX);
        if (!rentalTownEmblemsHeld.containsAll(required)) {
            sendEncrypted(Protocol.hypertext(
                            guide.objectId(), "Phan_Citizen", "", List.of()),
                    "S_HYPERTEXT rental-town-citizen-missing-emblems held="
                            + rentalTownEmblemsHeld.size());
            return;
        }
        for (int resourceIndex : List.of(
                NativeLitoRentalTownNpcCatalog.AUTHORITY_EMBLEM_INDEX,
                NativeLitoRentalTownNpcCatalog.CRAFTSMAN_EMBLEM_INDEX,
                NativeLitoRentalTownNpcCatalog.DELIGHT_EMBLEM_INDEX,
                NativeLitoRentalTownNpcCatalog.PEACE_EMBLEM_INDEX)) {
            sendEncrypted(Protocol.removeInventory(
                            NativeLitoRentalTownNpcCatalog.emblemObjectId(resourceIndex)),
                    "S_REMOVE_INVENTORY rental-town-emblem-consumed resource="
                            + resourceIndex);
        }
        rentalTownEmblemsHeld.clear();
        rentalTownCitizen = true;
        rentalTownLightGemCount = Math.addExact(rentalTownLightGemCount, 1L);
        sendEncrypted(Protocol.changeInventoryCount(
                        RENTAL_LIGHT_GEM_OBJECT_ID, rentalTownLightGemCount),
                "S_CHANGE_COUNT rental-town-citizenship light-gems="
                        + rentalTownLightGemCount
                        + " reward-authority=Phan_Citizen-singular-resource-text");
        sendEncrypted(Protocol.hypertext(
                        guide.objectId(), guide.endHtml(), "", List.of()),
                "S_HYPERTEXT rental-town-citizen-complete html=" + guide.endHtml());
    }

    private int rentalTownNpcDistance(
            NativeLitoRentalTownNpcCatalog.Npc npc) {
        return Math.max(Math.abs(positionX - npc.x()), Math.abs(positionY - npc.y()));
    }

    private static long nextRentalItemObjectId() {
        long objectId = RENTAL_ITEM_SEQUENCE.incrementAndGet();
        if (objectId > 0x6EFF_FFFFL) {
            throw new IllegalStateException("rental item object-id range exhausted");
        }
        return objectId;
    }

    private int rentalTownWalkAction() {
        return BattleAnimationCatalog.get().resolveEquippedWalkAction(
                battleGfx(), rentalTownInventory.equippedWalkAction());
    }

    private int rentalTownLightRange() {
        return rentalTownInventory.activeLightRange();
    }

    private void sendRentalTownActor(String reason) throws IOException {
        sendRentalTownActorOf(this, reason + "-local");
        System.out.println("[LiTo] rental-town local actor rebuilt reason=" + reason
                + " map=" + rentalTownMapId + " x=" + positionX + " y=" + positionY
                + " walk-action=" + rentalTownWalkAction());
    }

    private void synchronizeRentalTownParticipantRows() throws IOException {
        for (ClientSession peer : rentalTownPeers()) {
            sendRoomParticipant(currentRoomId, peer, Protocol.LitoForce.FORCE_0,
                    "rental-town-existing-player");
            peer.sendRoomParticipant(currentRoomId, this, Protocol.LitoForce.FORCE_0,
                    "rental-town-player-joined");
        }
    }

    private void synchronizeRentalTownActors(String reason) throws IOException {
        for (ClientSession peer : rentalTownPeers()) {
            if (rentalTownInNativeScreen(peer, positionX, positionY)) {
                sendRentalTownActorOf(peer, reason + "-existing-peer");
                peer.sendRentalTownActorOf(this, reason + "-peer-joined");
            }
            sendEncrypted(Protocol.minimapPlayer(
                            peer.playerObjectId(), peer.positionX, peer.positionY, true),
                    "S_LITO_MINIMAP rental-town existing-peer=" + peer.playerName()
                            + " reason=" + reason);
            peer.sendEncrypted(Protocol.minimapPlayer(
                            playerObjectId(), positionX, positionY, true),
                    "S_LITO_MINIMAP rental-town peer-joined=" + playerName()
                            + " reason=" + reason);
        }
    }

    private void sendRentalTownActorOf(ClientSession actor, String reason)
            throws IOException {
        sendBattleObjectAtHeading(
                actor.playerObjectId(), actor.playerName(),
                actor.sourceCharacterIdentity(), actor.positionX, actor.positionY,
                actor.battleGfx(), actor.rentalTownWalkAction(), actor.playerHeading,
                actor.rentalTownLightRange(), actor.battleMoveSpeed(), 4,
                actor.battleLevel(), nativeLawful(actor.characterLawful()),
                actor.classicTitle, actor == this ? 0xFF : actor.battleHpRatio());
        System.out.println("[LiTo] rental-town actor visible recipient=" + playerName()
                + " actor=" + actor.playerName() + " map=" + rentalTownMapId
                + " x=" + actor.positionX + " y=" + actor.positionY
                + " heading=" + actor.playerHeading + " reason=" + reason);
    }

    private boolean rentalTownInNativeScreen(
            ClientSession actor, int viewerX, int viewerY) {
        return actor != null
                && actor.rentalTownRoomState
                && actor.phase == Phase.BATTLE
                && actor.currentRoomId == currentRoomId
                && actor.rentalTownMapId == rentalTownMapId
                && sameRentalTownVisibilityInstance(actor)
                && BattleSpellCatalog.isInNativeScreen(
                        viewerX, viewerY, actor.positionX, actor.positionY);
    }

