                hub.nativeRoomParticipantReadyState(roomId, participant);
        sendRoomParticipant(roomId, participant.litoDisplayName(), force, characterType, sex,
                statistics, participant.nativeTournamentAffiliationName(), channelRank,
                readyState, awards, note);
