    void serverPrepareBattle() {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$serverPrepareBattle(scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    void serverEndBattle(BattleRules.Resolution resolution) throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$serverEndBattle(resolution, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

