    private void demandMercenaries(long commanderObjectId) throws IOException {
        GameStateStore.MercenaryAssignment assignment =
                state.mercenaryAssignment(stateCharacter());
        if (assignment.mercenaries().total() == 0) {
            sendEncrypted(Protocol.hypertext(commanderObjectId,
                            CastleMercenaryCatalog.EMPTY_HTML, "", List.of()),
                    "S_HYPERTEXT html=" + CastleMercenaryCatalog.EMPTY_HTML
                            + " mercenary-demand=empty player=" + playerName());
            return;
        }
        boolean templatesAvailable = CastleMercenaryCatalog.hasSummonTemplates(
                assignment.castleId(), assignment.mercenaries());
        if (!templatesAvailable) {
            // The only preserved castle_soldier row carries 0 for all four
            // NPC template ids. Keep the durable assignment intact and use
            // the native not-ready page instead of creating guessed actors.
            sendEncrypted(Protocol.hypertext(commanderObjectId,
                            CastleMercenaryCatalog.NOT_READY_HTML, "", List.of()),
                    "S_HYPERTEXT html=" + CastleMercenaryCatalog.NOT_READY_HTML
                            + " mercenary-demand=template-unavailable castle="
                            + assignment.castleId() + " count="
                            + assignment.mercenaries().total());
            return;
        }
        // Keep this branch safe if a future catalog supplies IDs before the
        // corresponding summon actor lifecycle is implemented and tested.
        sendEncrypted(Protocol.hypertext(commanderObjectId,
                        CastleMercenaryCatalog.NOT_READY_HTML, "", List.of()),
                "S_HYPERTEXT html=" + CastleMercenaryCatalog.NOT_READY_HTML
                        + " mercenary-demand=summon-not-implemented castle="
                        + assignment.castleId() + " count="
                        + assignment.mercenaries().total());
    }

