    /** Rebuilds the native client crown-slot table from effective ownership. */
    private void sendCastleOwnerMappings(List<ClientSession> battleMembers, String reason)
            throws IOException {
        Set<Integer> emittedSlots = new LinkedHashSet<>();
        for (ClientSession member : battleMembers) {
            CastleSummary castle = member.selectedLegacyCastle();
            if (!member.ownsLegacyCastle(castle)) continue;
            int crownSlot = castleOwnerCrownSlot(castle.castleId());
            if (crownSlot < 0 || !emittedSlots.add(crownSlot)) {
                System.out.println("[LiTo] S_CASTLE_OWNER skipped invalid/duplicate castle="
                        + castle.castleId() + " player=" + member.playerName());
                continue;
            }
            sendEncrypted(Protocol.castleOwner(crownSlot, member.playerObjectId()),
                    "S_CASTLE_OWNER slot=" + crownSlot + " castle=" + castle.castleId()
                            + " owner=" + member.playerName() + " object="
                            + member.playerObjectId() + " reason=" + reason);
        }
    }

    private static int castleOwnerCrownSlot(int castleId) {
        // Same-family 3.81 servers use client slot 8 for Orc Castle (id 2).
        if (castleId == 2) return 8;
        return castleId >= 1 && castleId <= 8 ? castleId : -1;
    }

    private ArenaMapCatalog.Point serviceNpcPoint(int slot) {
        // Gereng/Horun/Pandora/warehouse/castle service actors exist to keep
        // their independently verified classic 3.81 packet workflows
        // testable.  They are not part of the retained LiTo Tournament battle
        // bootstrap.  A native profile therefore suppresses both publication
        // and forged interaction by making the authoritative point absent.
        if (!config.battleCompatibilityServiceActorsEnabled()
                || currentRoomId == 0) return null;
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        if (rules == null) return null;
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(
                hub.battleMapId(currentRoomId, this));
        return ArenaMapCatalog.serviceSpawn(arena, slot);
    }

    private int classicNpcDistance(ArenaMapCatalog.Point npc) {
        return Math.max(Math.abs(positionX - npc.x()), Math.abs(positionY - npc.y()));
    }

    private CastleSummary selectedLegacyCastle() {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || character.clanName() == null
                || character.clanName().isBlank()) return null;
        try {
            for (int castleId = 1; castleId <= 8; castleId++) {
                CastleSummary castle = effectiveClassicCastleById(castleId);
                if (castle != null && castle.clanName().equalsIgnoreCase(
                        character.clanName())) return castle;
            }
            return null;
        } catch (Exception error) {
            System.out.println("[LiTo] effective castle lookup failed clan="
                    + character.clanName() + ": " + error.getMessage());
            return null;
        }
    }

    /**
     * Loads castle administration from the selected dynamic database when
     * LiTo SQL extensions are active. The sidecar is then only an exact
     * mirror; an unavailable LiTo repository fails closed instead of reviving
     * an older file snapshot.
     */
    private GameStateStore.CastleState administrativeCastleState(
            CastleSummary castle) throws IOException {
        if (castle == null) {
            throw new IllegalArgumentException("castle is required");
        }
        try {
            RepositoryCastleSnapshot sql = selectedSourceAccounts()
                    .castleState(castle.castleId());
            if (sql.authoritative()) {
                return state.reconcileSqlCastle(selectedClassicServerName, sql);
            }
            if ("lito_mysql".equals(config.databaseMode())) {
                throw new IOException("selected LiTo castle snapshot is unavailable");
            }
            return state.castle(selectedClassicServerName, castle);
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot load selected-source castle state "
                    + castle.castleId(), failure);
        }
    }

    /**
     * Owner-authorized whole-snapshot CAS. SQL is authoritative in
     * {@code lito_mysql}; memory/legacy fixtures retain the compatible
     * sidecar transaction.
     */
    private boolean persistAdministrativeCastleState(
            GameStateStore.CastleState expected, int taxRate, long publicMoney,
            boolean securityEnabled, GameStateStore.MercenaryRoster mercenaries)
            throws IOException {
        CharacterSummary owner = selectedCharacterSummary();
        if (owner == null || expected == null) return false;
        try {
            AccountRepository repository = selectedSourceAccounts();
            RepositoryCastleSnapshot sqlExpected = repository.castleState(
                    expected.castleId());
            if (sqlExpected.authoritative()) {
                GameStateStore.CastleState current = state.reconcileSqlCastle(
                        selectedClassicServerName, sqlExpected);
                if (!current.equals(expected)) return false;
                RepositoryCastleSnapshot replacement = new RepositoryCastleSnapshot(
                        true, sqlExpected.castleId(), taxRate, publicMoney,
                        sqlExpected.warTimeMillis(), securityEnabled, mercenaries,
                        sqlExpected.snapshotVersion());
                RepositoryCastleMutation mutation = repository.persistCastleState(
                        owner.objectId(), sqlExpected, replacement);
                if (mutation.snapshot().authoritative()) {
                    state.reconcileSqlCastle(
                            selectedClassicServerName, mutation.snapshot());
                }
                if (mutation.status() != RepositoryCastleMutationStatus.SUCCESS) {
                    System.out.println("[LiTo] SQL castle mutation refused status="
                            + mutation.status() + " castle=" + expected.castleId()
                            + " player=" + playerName());
                }
                return mutation.status() == RepositoryCastleMutationStatus.SUCCESS;
            }
            if ("lito_mysql".equals(config.databaseMode())) {
                throw new IOException("selected LiTo castle snapshot is unavailable");
            }
            return state.saveCastleState(selectedClassicServerName, expected,
                    taxRate, publicMoney, securityEnabled, mercenaries);
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot persist selected-source castle state "
                    + expected.castleId(), failure);
        }
    }

    private boolean persistCastleTreasuryTransfer(
            GameStateStore.CastleState expected, RuntimeInventory afterInventory,
            long publicMoney) throws IOException {
        CharacterSummary owner = selectedCharacterSummary();
        if (owner == null || expected == null || afterInventory == null) return false;
        try {
            AccountRepository repository = selectedSourceAccounts();
            RepositoryCastleSnapshot sqlExpected = repository.castleState(
                    expected.castleId());
            if (sqlExpected.authoritative()) {
                GameStateStore.CastleState current = state.reconcileSqlCastle(
                        selectedClassicServerName, sqlExpected);
                if (!current.equals(expected)) return false;
                RepositoryCastleSnapshot replacement = new RepositoryCastleSnapshot(
                        true, sqlExpected.castleId(), sqlExpected.taxRate(), publicMoney,
                        sqlExpected.warTimeMillis(), sqlExpected.securityEnabled(),
                        sqlExpected.mercenaries(), sqlExpected.snapshotVersion());
                Map<Long, Long> localToSource = state.sourceInventoryBindings(
                        stateCharacter()).stream().collect(
                                java.util.stream.Collectors.toMap(
                                        GameStateStore.SourceInventoryBinding::localObjectId,
                                        GameStateStore.SourceInventoryBinding::sourceObjectId,
                                        (left, right) -> left, LinkedHashMap::new));
                RepositoryCastleTreasuryMutation mutation =
                        repository.persistCastleTreasuryTransfer(
                                owner.objectId(), sqlExpected, replacement,
                                inventory, afterInventory, localToSource);
                if (mutation.snapshot().authoritative()) {
                    state.reconcileSqlCastle(
                            selectedClassicServerName, mutation.snapshot());
                }
                if (mutation.status() != RepositoryCastleTreasuryStatus.SUCCESS) {
                    System.out.println("[LiTo] SQL castle treasury transfer refused status="
                            + mutation.status() + " castle=" + expected.castleId()
                            + " player=" + playerName());
                    return false;
                }
                // SQL is authoritative. This write is only the local restart/debug
                // mirror; a failure cannot roll back or duplicate the SQL transfer.
                state.saveEconomyState(stateCharacter(), shopPoints,
                        afterInventory.catalogCounts(),
                        afterInventory.catalogItemStates());
                return true;
            }
            if ("lito_mysql".equals(config.databaseMode())) {
                throw new IOException("selected LiTo castle snapshot is unavailable");
            }
            return state.saveInventoryAndCastle(
                    selectedClassicServerName, stateCharacter(),
                    afterInventory.catalogCounts(), expected,
                    expected.taxRate(), publicMoney);
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot persist castle treasury transfer "
                    + expected.castleId(), failure);
        }
    }

    private CastleSummary effectiveClassicCastleById(int castleId) throws Exception {
        AccountRepository source = selectedSourceAccounts();
        CastleSummary legacy = source.castleById(castleId);
        if ("lito_mysql".equals(config.databaseMode())) return legacy;
        GameStateStore.CastleOwnershipState override = state.castleOwnership(
                selectedClassicServerName, castleId);
        if (override == null) return legacy;
        String castleName;
        long warTimeMillis;
        int taxRate;
        long publicMoney;
        if (legacy != null) {
            castleName = legacy.castleName();
            warTimeMillis = legacy.warTimeMillis();
            taxRate = legacy.taxRate();
            publicMoney = legacy.publicMoney();
        } else {
            CastleWarSchedule schedule = source.castleWarSchedules().stream()
                    .filter(candidate -> candidate.castleId() == castleId)
                    .findFirst().orElseThrow(() -> new IllegalStateException(
                            "missing selected castle schedule " + castleId));
            castleName = schedule.castleName();
            warTimeMillis = schedule.warTimeMillis();
            taxRate = 10;
            publicMoney = 0;
        }
        return new CastleSummary(castleId, override.clanName(),
                override.leaderName(), castleName, warTimeMillis,
                taxRate, publicMoney, override.leaderObjectId());
    }

    private CastleSummary effectiveClassicCastleForClan(String clanName) {
        if (clanName == null || clanName.isBlank()) return null;
        try {
            for (int castleId = 1; castleId <= 8; castleId++) {
                CastleSummary castle = effectiveClassicCastleById(castleId);
                if (castle != null && castle.clanName().equalsIgnoreCase(clanName)) {
                    return castle;
                }
            }
        } catch (Exception error) {
            System.out.println("[LiTo] effective castle target lookup failed clan="
                    + clanName + ": " + error.getMessage());
        }
        return null;
    }

    private boolean defendsClassicCastle(int castleId) {
        CastleSummary castle = selectedLegacyCastle();
        CharacterSummary character = selectedCharacterSummary();
        return castle != null && character != null
                && castle.castleId() == castleId
                && character.clanName() != null
                && castle.clanName().equalsIgnoreCase(character.clanName());
    }

    private boolean ownsLegacyCastle(CastleSummary castle) {
        CharacterSummary character = selectedCharacterSummary();
        return castle != null && character != null && character.type() == 0
                && castle.leaderName().equalsIgnoreCase(playerName())
                && castle.clanName().equalsIgnoreCase(character.clanName());
    }

    private CastleSummary castleOwnerAuthority(String action) {
        CastleSummary castle = selectedLegacyCastle();
        ArenaMapCatalog.Point npc = castleStewardNpcPoint();
        boolean allowed = castleStewardSceneSupports(castle)
                && !observer && playerHp > 0 && !movementLockPending
                && !timedStatus.actionLocked(System.nanoTime())
                && npc != null && classicNpcDistance(npc) <= 5
                && ownsLegacyCastle(castle);
        if (!allowed) {
            System.out.println("[LiTo] castle owner action rejected player="
                    + playerName() + " action=" + action
                    + " castle=" + (castle == null ? 0 : castle.castleId())
                    + " phase=" + phase + " context=" + activeInteractionContext());
            return null;
        }
        return castle;
    }

    /** Opens the proved castle-4 S40 employment catalog. */
    private void openMercenarySelection() throws IOException {
        pendingMercenaryAdmin = null;
        pendingCastleSecurity = null;
        CastleSummary castle = mercenaryAuthority(false, "employ");
        if (castle == null) return;
        GameStateStore.CastleState snapshot = state.castle(
                selectedClassicServerName, castle);
        List<CastleMercenaryCatalog.Entry> catalog =
                CastleMercenaryCatalog.forCastle(castle.castleId());
        if (catalog.isEmpty()) {
            System.out.println("[LiTo] mercenary employ rejected no-proved-catalog castle="
                    + castle.castleId() + " player=" + playerName());
            return;
        }
        Set<Integer> offered = catalog.stream()
                .map(CastleMercenaryCatalog.Entry::id)
                .collect(java.util.stream.Collectors.toUnmodifiableSet());
        pendingMercenaryAdmin = new PendingMercenaryAdmin(
                castle.castleId(), castleStewardNpcObjectId(), activeInteractionContext(),
                MercenaryAdminAction.EMPLOY, snapshot, offered,
                -1, 0, 0, "", GameStateStore.MercenaryAssignment.empty(),
                0, System.nanoTime() + CASTLE_ADMIN_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.mercenaryEmploy(
                        castleStewardNpcObjectId(), snapshot.publicMoney(),
                        catalog.stream().map(CastleMercenaryCatalog.Entry::wireRow).toList()),
                "S_MERCENARYEMPLOY castle=" + castle.castleId()
                        + " budget=" + snapshot.publicMoney()
                        + " count=" + catalog.size());
        System.out.println("[LiTo] mercenary employ opened native catalog castle="
                + castle.castleId() + " player=" + playerName()
                + " hired=" + snapshot.mercenaries().total());
    }

