    private void broadcastRoomOwner(long roomId, String trigger) throws IOException {
        String owner = hub.roomOwnerDisplayName(roomId);
        if (owner.isBlank()) return;
        byte[] changed = Protocol.litoRoomOwner(roomId, owner);
        for (ClientSession member : hub.roomMembers(roomId)) {
            try {
                member.sendEncrypted(changed,
                        "S_LITO_GAME_INFO owner subtype=5 owner=" + owner
                                + " trigger=" + trigger);
            } catch (IOException error) {
                // A successor can close immediately before the old owner
                // leaves.  That stale recipient must not abort the active
                // owner's ROOM -> CHANNEL transition or suppress its S_CC.
                System.out.println("[LiTo] room-owner peer notification failed recipient="
                        + member.playerName() + " room=" + roomId
                        + " trigger=" + trigger + ": " + error.getMessage());
            }
        }
    }

    private volatile long battleCombatExitDeadlineNanos;

    private synchronized void markBattleCombat() {
        if (phase != Phase.BATTLE) return;
        int seconds = Math.max(1, Math.min(300,
                Integer.getInteger("lito.combatExitDelaySeconds", 10)));
        battleCombatExitDeadlineNanos = System.nanoTime() + seconds * 1_000_000_000L;
    }

    private int battleExitRemainingSeconds() {
        long deadline = battleCombatExitDeadlineNanos;
        if (deadline == 0) return 0;
        long remaining = deadline - System.nanoTime();
        return remaining <= 0 ? 0 : (int)((remaining + 999_999_999L) / 1_000_000_000L);
    }

    private void markBattleCombatWith(ClientSession attacker) {
        markBattleCombat();
        if (attacker != null) attacker.markBattleCombat();
    }

