    private void qualifyRestoredSourceWeapon() throws IOException {
        RuntimeInventory.Item item = inventory.equippedWeaponItem();
        if (item == null || !item.sourceBound() || item.litoOwned()) return;
        SourceWeaponPhysicalStats weapon = sourceEquipmentMagicStats.physical().weapon();
        if (!weapon.present() || weapon.itemId() != item.definition().catalogId()
                || (byte)weapon.enchantLevel() != item.enchantLevel()
                || weapon.walkAction() != item.definition().weaponWalkAction()) {
            throw new IOException("restored source weapon and qualified SQL evaluation differ");
        }
        inventory.qualifySourceWeapon(item.objectId(), weapon);
    }

    private void settleRequestedBattleExit() throws IOException {
        int remaining = battleExitRemainingSeconds();
        if (remaining > 0) {
            sendEncrypted(Protocol.systemMessage(9,
                    "戰鬥中無法退出，請停止攻擊並等待 " + remaining + " 秒。"),
                    "battle-exit blocked remaining-seconds=" + remaining);
            return;
        }
        long roomId = currentRoomId;
        List<ClientSession> members = List.copyOf(hub.roomMembers(roomId));
        Set<Long> winners = new LinkedHashSet<>();
        Set<Long> losers = new LinkedHashSet<>();
        for (ClientSession member : members) {
            if (member.observer) continue;
            (member == this ? losers : winners).add(member.playerObjectId());
        }
        BattleRules.Resolution result = new BattleRules.Resolution(
                true, false, winners, losers, "player-withdrawal");
        IOException failure = null;
        try {
            for (ClientSession member : members) {
                try { member.serverEndBattle(result); }
                catch (IOException error) { if (failure == null) failure = error; }
            }
        } finally {
            hub.endBattle(roomId);
        }
        // Keep membership until the normal RESULT D9/F0 then Confirm/D0.
        if (failure != null) throw failure;
    }

