    private void requestRestart(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != Protocol.C_RESTART || in.remaining() != 0) {
            throw new IllegalArgumentException("invalid C_RESTART payload");
        }
        if (phase.ordinal() < Phase.AUTHENTICATED.ordinal()) {
            System.out.println("[LiTo] C_RESTART ignored before authentication phase=" + phase);
            return;
        }
        if (pendingTransition != PendingTransition.NONE) {
            System.out.println("[LiTo] C_RESTART ignored pending=" + pendingTransition);
            return;
        }
        if (phase == Phase.WORLD && playerHp == 0) {
            restartClassicWorldAfterDeath();
            return;
        }
        pendingWarehousePassword = null;
        pendingSlaveTarget = null;
        pendingPetRename = null;
        cancelActivePlayerTrade("restart", true);
        pendingTransition = PendingTransition.RESTART_AWAIT_QUIT_FIGHT;
        sendEncrypted(Protocol.restart(), "S_RESTART native source-refresh transition");
    }

    private void restartClassicWorldAfterDeath() throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$restartClassicWorldAfterDeath(scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

