    /**
     * Isolated original-client acceptance fixture for the unresolved S_CLONE
     * producer. It changes only the requesting client's cached local actor,
     * schedules an exact five-second restore, and never mutates hub, combat or
     * persistence state. The automatic fixture performs its own inline restore;
     * the chat token is ordinary text everywhere except the dedicated loopback
     * fixture.
     */
    private boolean sendCloneAppearanceProbe(String message) throws IOException {
        if (!config.cloneAppearanceProbeEnabled() || !"cloneprobe".equals(message)) {
            return false;
        }
        serverCloneAppearanceProbeMutation(currentRoomId, true);
        return true;
    }

    void serverCloneAppearanceProbeAutoBattle(int channelId) throws IOException {
        boolean isolated = "memory".equals(config.databaseMode())
                && config.databaseReadOnly() && !config.statePersistenceEnabled()
                && config.port() == 32100
                && socket.getInetAddress().isLoopbackAddress();
        if (!config.cloneAppearanceProbeEnabled() || !isolated
                || !isAdministrator() || phase != Phase.CHANNEL
                || currentChannelId != channelId) return;
        byte[] create = new Protocol.Writer().c(Protocol.C_LITO_CREATE_ROOM)
                .s("S_CLONE Probe").c(0).s("").h(2).bytes();
        createRoom(create);
        if (phase != Phase.ROOM || currentRoomId == 0) {
            throw new IllegalStateException("clone probe automatic room was not joined");
        }
        long roomId = currentRoomId;
        hub.scheduleCloneAppearanceProbeAutoReady(this, roomId);
        System.out.println("[LiTo] clone-appearance fixture room handoff room="
                + roomId + " client-request-state=unchanged");
    }

    void serverCloneAppearanceProbeAutoReady(long roomId) throws IOException {
        boolean isolated = "memory".equals(config.databaseMode())
                && config.databaseReadOnly() && !config.statePersistenceEnabled()
                && config.port() == 32100
                && socket.getInetAddress().isLoopbackAddress();
        if (!config.cloneAppearanceProbeEnabled() || !isolated
                || !isAdministrator() || phase != Phase.ROOM
                || currentRoomId != roomId) return;
        setReady(new Protocol.Writer().c(Protocol.C_LITO_READY_GAME).c(1).bytes());
        System.out.println("[LiTo] clone-appearance fixture auto-battle room="
                + roomId + " native-room-handoff-ms="
                + GameHub.CLONE_PROBE_NATIVE_ROOM_HANDOFF_MILLIS
                + " client-request-state=unchanged");
    }

    private void serverCloneAppearanceProbeMutation(
            long roomId, boolean scheduleDelayedRestore) throws IOException {
        boolean isolated = "memory".equals(config.databaseMode())
                && config.databaseReadOnly() && !config.statePersistenceEnabled()
                && config.port() == 32100
                && socket.getInetAddress().isLoopbackAddress();
        if (!isolated || !isAdministrator() || phase != Phase.BATTLE
                || currentRoomId != roomId || observer || playerHp <= 0) {
            System.out.println("[LiTo] clone-appearance probe rejected isolated="
                    + isolated + " administrator=" + isAdministrator()
                    + " phase=" + phase + " room=" + roomId);
            return;
        }
        sendEncrypted(Protocol.cloneAppearance(
                        playerObjectId(), hub.clanEmblemId(sourceCharacterIdentity()),
                        138, nativeLawful(characterLawful()), BattleActionCodes.WALK,
                        "S_CLONE probe"),
                "S_CLONE fixture-only object=" + playerObjectId()
                        + " gfx=138 title=S_CLONE probe"
                        + " client-cache-only restore-after-ms="
                        + (scheduleDelayedRestore ? 5000 : 1500));
        if (scheduleDelayedRestore) {
            hub.scheduleCloneAppearanceProbeRestore(this, roomId);
        }
    }

    void serverCloneAppearanceProbeRestore(long roomId) throws IOException {
        if (!config.cloneAppearanceProbeEnabled() || phase != Phase.BATTLE
                || currentRoomId != roomId) return;
        sendEncrypted(Protocol.cloneAppearance(
                        playerObjectId(), hub.clanEmblemId(sourceCharacterIdentity()),
                        battleGfx(), nativeLawful(characterLawful()),
                        battleWalkAction(), classicTitle),
                "S_CLONE fixture-only restore object=" + playerObjectId()
                        + " gfx=" + battleGfx() + " title=" + classicTitle
                        + " client-cache-only no-server-state-mutation");
    }

    /**
     * Loopback-only native-client animation probe for the unresolved 0x2E
     * trigger.  It deliberately changes no HP or match state and is disabled
     * in every production/development configuration.  The exact chat token is
     * ordinary text when the fixture is disabled, so a live server never gains
     * an accidental hidden command.
     */
    private boolean sendAttackAllProbe(String message) throws IOException {
        if (!config.attackAllProbeEnabled() || !"attackallprobe".equals(message)) {
            return false;
        }
        boolean isolated = "memory".equals(config.databaseMode())
                && config.databaseReadOnly() && !config.statePersistenceEnabled()
                && config.port() == 32100
                && socket.getInetAddress().isLoopbackAddress();
        if (!isolated || !isAdministrator() || phase != Phase.BATTLE
                || observer || currentRoomId == 0 || playerHp <= 0) {
            System.out.println("[LiTo] attack-all probe rejected isolated=" + isolated
                    + " administrator=" + isAdministrator() + " phase=" + phase);
            return true;
        }
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        List<ClientSession> combatants = hub.visibleBattleCombatants(currentRoomId, this);
        boolean includesBot = rules.mode() != BattleRules.Mode.QUEST_BATTLE
                && rules.mode() != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2;
        List<Protocol.AttackAllTarget> targets = new ArrayList<>();
        if (includesBot) targets.add(new Protocol.AttackAllTarget(2, true));
        for (ClientSession combatant : combatants) {
            if (combatant != this && combatant.playerHp > 0) {
                targets.add(new Protocol.AttackAllTarget(
                        combatant.playerObjectId(), true));
            }
        }
        for (BattleCompanion.Snapshot companion : controlledCompanionSnapshots()) {
            if (!companion.active()) continue;
            // Keep the adjacent companion as a zero-marker target. The
            // native receiver still consumes the complete five-byte entry,
            // but its impact loop only schedules reaction action 2 for a
            // signed-positive marker. This keeps the actor animation probe
            // visually separable from an overlapping target reaction.
            targets.add(new Protocol.AttackAllTarget(companion.objectId(), false));
        }
        if (targets.isEmpty()) {
            System.out.println("[LiTo] attack-all probe rejected no published targets");
            return true;
        }
        BattleAnimationCatalog.get().requireTimedAction(
                battleGfx(), BattleActionCodes.ATTACK);
        sendEncrypted(Protocol.attackAll(
                        BattleActionCodes.ATTACK, playerObjectId(), targets),
                "S_ATTACK_ALL fixture-only actor=" + playerObjectId()
                        + " targets=" + targets.size() + " no-state-mutation");
        return true;
    }

    /**
     * Encrypted loopback-only framing probe for the dormant native
     * {@code S_BOOK_LIST} receiver.  The selected LiTo image has no reachable
     * {@code C_BOOK} producer and the receiver discards every parsed field, so
     * this path is deliberately diagnostic-only and never supplies gameplay
     * state or a fabricated request/response origin.
     */
    private boolean sendBookListProbe(String message) throws IOException {
        if (!config.bookListProbeEnabled() || !"booklistprobe".equals(message)) {
            return false;
        }
        boolean isolated = "memory".equals(config.databaseMode())
                && config.databaseReadOnly() && !config.statePersistenceEnabled()
                && config.port() == 32100
                && socket.getInetAddress().isLoopbackAddress();
        if (!isolated || !isAdministrator() || phase != Phase.BATTLE
                || observer || currentRoomId == 0 || playerHp <= 0) {
            System.out.println("[LiTo] book-list probe rejected isolated=" + isolated
                    + " administrator=" + isAdministrator() + " phase=" + phase);
            return true;
        }
        sendEncrypted(Protocol.bookList(0xA5, List.of(
                        new Protocol.BookListEntry("LiTo Archive", 946_684_800L),
                        new Protocol.BookListEntry("Native Record", 1_182_732_300L))),
                "S_BOOK_LIST fixture-only legacyTag=165 rows=2 "
                        + "receiver-discards-values no-state-mutation");
        return true;
    }

    private void tell(byte[] payload) throws IOException {
        Protocol.TellRequest request = Protocol.tellRequest(payload);
        if (phase != Phase.ROOM && phase != Phase.BATTLE
                && phase != Phase.CHANNEL && phase != Phase.WORLD) return;
        if (hub.chatSilenced(sourceCharacterIdentity(), System.nanoTime())) {
            System.out.println("[LiTo] C_TELL suppressed by C_SILENCE player=" + playerName());
            return;
        }
        ClientSession target = rentalTownRoomState
                ? hub.onlineMemberByName(this, request.target())
                : hub.activeMemberByName(this, request.target());
        if (target == null || !target.canWhisper || target.excludes(playerName())) {
            System.out.println("[LiTo] C_TELL target offline sender=" + playerName()
                    + " target=" + request.target() + " accepts-whisper="
                    + (target != null && target.canWhisper)
                    + " excluded=" + (target != null && target.excludes(playerName())));
            return;
        }
        target.sendEncrypted(Protocol.tell(litoDisplayName(), request.message()),
                "S_TELL sender=" + playerName() + " target=" + target.playerName());
    }

    private void changeChatPreference(byte[] payload) {
        Protocol.OnOffRequest request = Protocol.onOffRequest(payload);
        switch (request.selector()) {
            case 0 -> showWorldChat = request.value() != 0;
            case 2 -> canWhisper = request.value() != 0;
            case 6 -> showTradeChat = request.value() != 0;
            case 0xFF -> applyCombinedChatPreference(request.value());
            default -> {
                // LiTo emits selectors 3/4/5/7/8 for client-only UI options.
                // Same-family 3.81 servers consume the ccc frame and deliberately
                // perform no server-side mutation for those selectors.
            }
        }
        System.out.println("[LiTo] C_ONOFF player=" + playerName()
                + " selector=" + request.selector() + " value=" + request.value()
                + " world=" + showWorldChat + " whisper=" + canWhisper
                + " trade=" + showTradeChat);
    }

    private void applyCombinedChatPreference(int value) {
        switch (value) {
            case 95, 127 -> {
                showWorldChat = true;
                canWhisper = true;
            }
            case 91, 123 -> {
                showWorldChat = true;
                canWhisper = false;
            }
            case 94, 126 -> {
                showWorldChat = false;
                canWhisper = true;
            }
            case 90, 122 -> {
                showWorldChat = false;
                canWhisper = false;
            }
            default -> {
                // The native 0xFF producer forwards a byte from client state;
                // the original server ignores combination values it does not know.
            }
        }
    }

    private void exclude(byte[] payload) throws IOException {
        String name = Protocol.namedCommandRequest(payload, Protocol.C_EXCLUDE, true);
        if (phase != Phase.CHANNEL && phase != Phase.ROOM && phase != Phase.BATTLE
                && phase != Phase.RESULT) return;
        if (name.isEmpty()) {
            excludedNames.clear();
            System.out.println("[LiTo] C_EXCLUDE reset player=" + playerName());
            return;
        }
        String normalized = normalizePlayerName(name);
        if (excludedNames.contains(normalized)) return;
        if (excludedNames.size() >= MAX_EXCLUDED_NAMES) {
            sendEncrypted(Protocol.messageCode(472),
                    "S_MESSAGE_CODE exclude-list-full player=" + playerName());
            return;
        }
        excludedNames.add(normalized);
        System.out.println("[LiTo] C_EXCLUDE add player=" + playerName() + " target=" + name
                + " count=" + excludedNames.size());
    }

    private void include(byte[] payload) {
        String name = Protocol.namedCommandRequest(payload, Protocol.C_INCLUDE, false);
        if (phase != Phase.CHANNEL && phase != Phase.ROOM && phase != Phase.BATTLE
                && phase != Phase.RESULT) return;
        boolean removed = excludedNames.remove(normalizePlayerName(name));
        System.out.println("[LiTo] C_INCLUDE player=" + playerName() + " target=" + name
                + " removed=" + removed + " count=" + excludedNames.size());
    }

    private boolean excludes(String name) {
        return name != null && excludedNames.contains(normalizePlayerName(name));
    }

    private static String normalizePlayerName(String name) {
        return name.trim().toLowerCase(java.util.Locale.ROOT);
    }

    private boolean acceptsChatType(int type) {
        return switch (type) {
            case 3 -> showWorldChat;
            case 12 -> showTradeChat;
            default -> true;
        };
    }

    private void who(byte[] payload) throws IOException {
        String requested = Protocol.whoRequest(payload);
        if (phase != Phase.ROOM && phase != Phase.BATTLE && phase != Phase.CHANNEL) return;
        ClientSession target = requested.isEmpty()
                ? null : rentalTownRoomState
                    ? hub.onlineMemberByName(this, requested)
                    : hub.activeMemberByName(this, requested);
        if (target == null) {
            int count = rentalTownRoomState
                    ? rentalTownOnlineCharacterCount()
                    : hub.tournamentUserCount();
            sendEncrypted(Protocol.messageCode(0x51, Integer.toString(count)),
                    "S_MESSAGE_CODE who-count=" + count + " requested=" + requested);
            return;
        }
        String title = target.classicTitle.isBlank() ? "" : target.classicTitle + " ";
        long lawful = target.characterLawful();
        String lawfulness = lawful < 0 ? "($1503)" : lawful < 500 ? "($1502)" : "($1501)";
        String clanName = hub.clanData(target.sourceCharacterIdentity()).name();
        String clan = clanName.isBlank() ? "" : "[" + clanName + "]";
        sendEncrypted(Protocol.messageCode(0xA6,
                        title + target.playerName() + " " + lawfulness + " " + clan),
                "S_MESSAGE_CODE who-character=" + target.playerName());
    }

    /**
     * The native rental village is a gameplay scene, but its S_FB group-1 id
     * is deliberately absent from GameHub's ordinary battle-room catalog.
     * Social delivery therefore uses connected, selected sessions that are
     * currently in the same exact town map instead of fabricating a room.
     */
    private List<ClientSession> rentalTownMembers() {
        if (!rentalTownRoomState || phase != Phase.BATTLE) return List.of();
        return hub.connectedSessionsSnapshot().stream()
                .filter(member -> member.rentalTownRoomState
                        && member.phase == Phase.BATTLE
                        && member.currentRoomId == currentRoomId
                        && member.rentalTownMapId == rentalTownMapId
                        && sameRentalTownVisibilityInstance(member))
                .toList();
    }

    private List<ClientSession> rentalTownPeers() {
        if (!rentalTownRoomState || currentRoomId == 0 || rentalTownMapId == 0) {
            return List.of();
        }
        return hub.connectedSessionsSnapshot().stream()
                .filter(member -> member != this
                        && member.rentalTownRoomState
                        && member.phase == Phase.BATTLE
                        && member.currentRoomId == currentRoomId
                        && member.rentalTownMapId == rentalTownMapId
                        && sameRentalTownVisibilityInstance(member))
                .toList();
    }

    private boolean sameRentalTownVisibilityInstance(ClientSession member) {
        if (!NativeLitoRentalHotelCatalog.supportsMap(rentalTownMapId)) return true;
        RentalHotelLease ours = rentalHotelLease;
        RentalHotelLease theirs = member.rentalHotelLease;
        return ours != null && theirs != null && ours.token() == theirs.token();
    }

    private int rentalTownOccupancy(long roomId, int mapId) {
        return Math.toIntExact(hub.connectedSessionsSnapshot().stream()
                .filter(member -> member != this
                        && member.rentalTownRoomState
                        && member.phase == Phase.BATTLE
                        && member.currentRoomId == roomId
                        && member.rentalTownMapId == mapId)
                .count());
    }

    private String rentalTownOwnerName(long roomId, int mapId) {
        return hub.connectedSessionsSnapshot().stream()
                .filter(member -> member != this
                        && member.rentalTownRoomState
                        && member.currentRoomId == roomId
                        && member.rentalTownMapId == mapId)
                .map(ClientSession::playerName)
                .filter(name -> name != null && !name.isBlank())
                .findFirst()
                .orElseGet(this::playerName);
    }

    private int rentalTownOnlineCharacterCount() {
        return Math.toIntExact(hub.connectedSessionsSnapshot().stream()
                .filter(member -> member.selectedCharacter != null
                        && !member.selectedCharacter.isEmpty())
                .count());
    }

    private void gameInfo(byte[] payload) throws IOException {
        Protocol.LitoGameInfoRequest request = Protocol.litoGameInfoRequest(payload);
        System.out.println("[LiTo] C_LITO_GAME_INFO request=" + request
                + " plain=" + Protocol.hex(payload));
        if (phase != Phase.ROOM || currentRoomId == 0) {
            System.out.println("[LiTo] C_LITO_GAME_INFO ignored invalid-phase=" + phase);
            return;
        }
        if (rentalTownRoomState) {
            handleRentalTownGameInfo(request);
            return;
        }
        if (request instanceof Protocol.LitoModeStepRequest modeStep) {
            changeRoomMode(modeStep.direction());
        } else if (request instanceof Protocol.LitoMapSelectionRequest mapSelection) {
            changeRoomMap(mapSelection.mapId());
        } else {
            throw new IllegalStateException("unknown native C_D1 request " + request);
        }
    }

    private void handleRentalTownGameInfo(Protocol.LitoGameInfoRequest request)
            throws IOException {
        if (request instanceof Protocol.LitoMapSelectionRequest mapSelection) {
            int requestedMap = mapSelection.mapId();
            if (NativeLitoTownCatalog.forMap(requestedMap) != null) {
                rentalTownMapId = requestedMap;
                System.out.println("[LiTo] rental-town map selected=" + requestedMap
                        + " room=" + currentRoomId);
            } else {
                System.out.println("[LiTo] rental-town map rejected=" + requestedMap
                        + " retained=" + rentalTownMapId);
            }
            sendEncrypted(Protocol.litoRoomMap(currentRoomId, rentalTownMapId),
                    "S_LITO_GAME_INFO rental-town map=" + rentalTownMapId);
            return;
        }
        // Mode 6 has no client-generated successor mode.  Restore the
        // authoritative mode/map pair and keep S_WORLD/S_D2 gated until the
        // historical local-player S_PUT_OBJECT coordinates are recovered.
        Protocol.LitoModeStepRequest modeStep = (Protocol.LitoModeStepRequest) request;
        sendRentalTownGameInfoSnapshot("mode-step=" + modeStep.direction());
    }

    private void sendRentalTownGameInfoSnapshot(String reason) throws IOException {
        sendEncrypted(Protocol.litoRoomMode(
                        currentRoomId, BattleRules.Mode.TOWN),
                "S_LITO_GAME_INFO rental-town mode=6 reason=" + reason);
        sendEncrypted(Protocol.litoRoomMap(currentRoomId, rentalTownMapId),
                "S_LITO_GAME_INFO rental-town map=" + rentalTownMapId
                        + " reason=" + reason);
    }

    private void sendGameInfoSnapshot() throws IOException {
        // Native S_D5 splits room state across two records. Subtype 0 carries
        // the room summary/mode/map/owner; subtype 1 carries the editable
        // password, attributes, capacity, four options and selection list.
        GameHub.RoomSettings settings = hub.roomSettings(currentRoomId);
        int mapId = hub.roomRules(currentRoomId).mapId();
        String owner = hub.roomOwnerDisplayName(currentRoomId);
        sendEncrypted(Protocol.litoRoomSummary(currentRoomId, settings, mapId, owner),
                "S_LITO_GAME_INFO summary subtype=0 owner=" + owner);
        sendEncrypted(Protocol.litoRoomConfiguration(currentRoomId, settings),
                "S_LITO_GAME_INFO configuration subtype=1");
    }

    private void broadcastGameInfoSnapshot() throws IOException {
        GameHub.RoomSettings settings = hub.roomSettings(currentRoomId);
        int mapId = hub.roomRules(currentRoomId).mapId();
        String owner = hub.roomOwnerDisplayName(currentRoomId);
        byte[] summary = Protocol.litoRoomSummary(currentRoomId, settings, mapId, owner);
        byte[] configuration = Protocol.litoRoomConfiguration(currentRoomId, settings);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(summary,
                    "S_LITO_GAME_INFO summary subtype=0 owner=" + owner + " settings-change");
            member.sendEncrypted(configuration,
                    "S_LITO_GAME_INFO configuration subtype=1 settings-change");
        }
    }

    private void changeRoomMode(Protocol.LitoModeStepDirection direction) throws IOException {
        GameHub.RoomSettings current = hub.roomSettings(currentRoomId);
        BattleRules.Mode previousMode = BattleRules.Mode.fromWire(
                current.option0() & 0x7F);
        if (!previousMode.isBattleScene()) {
            // Native type 6 is a server-gated town scene.  The exact C_D1
            // request carries only a direction, so there is no evidence for
            // interpreting an ordinary room-mode click as a transition out
            // of that special state.  Preserve the authoritative snapshot.
            sendGameInfoSnapshot();
            return;
        }
        BattleRules.Mode mode = BattleRules.Mode.stepNative(current.option0() & 0x7F, direction);
        GameHub.RoomSettings replacement = new GameHub.RoomSettings(
                current.name(), current.password(), current.capacity(),
                mode.teamBased()
                        ? current.attributes() | GameHub.RoomSettings.EQUAL_SIDES
                        : current.attributes() & ~GameHub.RoomSettings.EQUAL_SIDES,
                mode.wireId(), current.option1(), current.option2(),
                current.option3(), current.option4(),
                current.selections());
        if (!hub.updateSettings(currentRoomId, this, replacement)) {
            sendGameInfoSnapshot();
            return;
        }

        resetRoomReadyAfterSettingsChange();
        byte[] modeChanged = Protocol.litoRoomMode(currentRoomId, mode);
        int mapId = BattleRules.decode(replacement).mapId();
        byte[] mapChanged = Protocol.litoRoomMap(currentRoomId, mapId);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(modeChanged, "S_LITO_GAME_INFO mode=" + mode.wireId()
                    + " name=" + mode.displayName());
            member.sendEncrypted(mapChanged, "S_LITO_GAME_INFO map=" + mapId + " mode-reset");
        }
        boolean soleCombatant = hub.roomCombatantCount(currentRoomId) < 2;
        boolean previousUsesBot = NativeRoomRules.bot(previousMode, this);
        boolean nextUsesBot = NativeRoomRules.bot(mode, this);
        if (soleCombatant && previousUsesBot && !nextUsesBot) {
            byte[] botLeft = new Protocol.Writer().c(Protocol.S_LITO_EXIT_ROOM)
                    .d(currentRoomId).s("ArenaBot").bytes();
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendEncrypted(botLeft,
                        "S_LITO_EXIT_ROOM ArenaBot disabled mode=" + mode.key());
            }
        } else if (soleCombatant && !previousUsesBot && nextUsesBot) {
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendRoomParticipant(currentRoomId, "ArenaBot",
                        Protocol.LitoForce.FORCE_1, 0, 0,
                        "", 0, "bot-enabled-mode-" + mode.key());
            }
        }
        retryWaitingMatchMakingSessions("room-mode=" + mode.key());
    }

    private void changeRoomMap(int mapId) throws IOException {
        GameHub.RoomSettings current = hub.roomSettings(currentRoomId);
        BattleRules.Mode mode = BattleRules.Mode.fromWire(current.option0() & 0x7F);
        if (!mode.maps().contains(mapId) || mapId == 0xFFFF) {
            System.out.println("[LiTo] C_LITO_GAME_INFO rejected map=" + mapId
                    + " mode=" + mode.displayName());
            int selected = BattleRules.decode(current).mapId();
            sendEncrypted(Protocol.litoRoomMap(currentRoomId, selected),
                    "S_LITO_GAME_INFO restore-map=" + selected);
            return;
        }

        if (!hub.updateMap(currentRoomId, this, mapId)) {
            sendGameInfoSnapshot();
            return;
        }

        resetRoomReadyAfterSettingsChange();
        byte[] changed = Protocol.litoRoomMap(currentRoomId, mapId);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(changed, "S_LITO_GAME_INFO map=" + mapId);
        }
    }

    private void resetRoomReadyAfterSettingsChange() throws IOException {
        List<ClientSession> members = hub.roomMembers(currentRoomId);
        for (ClientSession member : members) {
            if (!member.ready) continue;
            member.ready = false;
            byte[] changed = Protocol.readyState(member.litoDisplayName(), false);
            for (ClientSession recipient : members) {
                recipient.sendEncrypted(changed,
                        "S_LITO_READY_GAME reset player=" + member.playerName());
            }
        }
    }

    private void setForce(byte[] payload) throws IOException {
        Protocol.LitoForce force = Protocol.litoForceRequest(payload);
        if (phase != Phase.ROOM || currentRoomId == 0) {
            System.out.println("[LiTo] C_LITO_SET_FORCE ignored invalid-phase=" + phase);
            return;
        }
        if (rentalTownRoomState) {
            // Mode 6 is a non-battle town and the direct room deliberately has
            // no GameHub force map.  The self participant was introduced as
            // force 0, so restore that authoritative row instead of silently
            // dropping C_D3 and leaving the native roster on the clicked team.
            sendEncrypted(Protocol.litoForceChanged(
                            litoDisplayName(), Protocol.LitoForce.FORCE_0),
                    "S_LITO_SET_FORCE rental-town restore player=" + playerName()
                            + " requested=" + force.wireValue() + " force=0");
            return;
        }
        GameHub.ForceUpdate update = hub.setForce(
                currentRoomId, this, force.wireValue());
        if (update.firstDisallowedPlayersPerForceWarning() > 0) {
            sendEncrypted(Protocol.litoForceUpperBoundWarning(
                            update.firstDisallowedPlayersPerForceWarning()),
                    "S_WARNING_CODE siege-force-first-disallowed="
                            + update.firstDisallowedPlayersPerForceWarning());
        }
        byte[] changed = Protocol.litoForceChanged(
                litoDisplayName(), Protocol.LitoForce.fromWire(update.force()));
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(changed, "S_LITO_SET_FORCE player=" + playerName()
                    + " force=" + update.force() + " changed=" + update.changed());
        }
        if (update.transition() == GameHub.ReadyTransition.COUNTDOWN_CANCELLED) {
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.serverCountdown(0);
            }
        }
    }

    private void kickUser(byte[] payload) throws IOException {
        String requested = Protocol.litoKickRequest(payload);
        ClientSession target = hub.memberByName(currentRoomId, this, requested);
        boolean accepted = phase == Phase.ROOM
                && hub.markRoomKick(currentRoomId, this, target);
        sendEncrypted(Protocol.litoKickStatus(accepted
                        ? Protocol.LitoKickStatusResult.ACCEPTED
                        : Protocol.LitoKickStatusResult.REJECTED),
                "S_LITO_KICK_STATUS target=" + requested + " accepted=" + accepted);
        if (accepted) {
            // Native S_D6 parses exactly one string.  The outcome code belongs
            // to S_FC and must not be appended to this packet.
            byte[] response = new Protocol.Writer().c(Protocol.S_LITO_KICK_USER)
                    .s(requested).bytes();
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendEncrypted(response, "S_LITO_KICK_USER target=" + requested);
            }
            target.exitRoom();
        }
    }

    private void inviteUser(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        String requested = in.s();
        if (in.remaining() != 0) {
            throw new IllegalArgumentException("invalid C_LITO_INVITE_USER payload");
        }
        if (rentalTownRoomState) {
            // The direct town id is a one-session capability advertised by
            // S_FB and is deliberately absent from GameHub.  Forwarding that
            // synthetic id through S_D7 would show the target an invitation
            // that C_CF can never authorize.  Keep ordinary room invitation
            // semantics unchanged and reject this cross-session leak at the
            // source.
            sendEncrypted(Protocol.roomInvitationReply(
                            requested.isBlank() ? "Unknown" : requested,
                            Protocol.LitoInvitationReply.NOT_ACCEPTED),
                    "S_LITO_INVITE_REPLY unavailable rental-town target=" + requested);
            return;
        }
        ClientSession target = hub.channelMemberByName(currentChannelId, this, requested);
        boolean available = phase == Phase.ROOM && target != null && target != this
                && target.phase == Phase.CHANNEL && target.currentChannelId == currentChannelId;
        if (!available) {
            sendEncrypted(Protocol.roomInvitationReply(
                            requested.isBlank() ? "Unknown" : requested,
                            Protocol.LitoInvitationReply.NOT_ACCEPTED),
                    "S_LITO_INVITE_REPLY unavailable target=" + requested);
            return;
        }
        GameHub.RoomSettings settings = hub.roomSettings(currentRoomId);
        PendingLitoRoomInvitation invitation = new PendingLitoRoomInvitation(
                this, litoDisplayName(), currentChannelId, currentRoomId,
                settings.password(), System.nanoTime() + LITO_ROOM_INVITE_TIMEOUT_NANOS);
        target.acceptedLitoRoomInvitation = null;
        target.pendingLitoRoomInvitation = invitation;
        try {
            target.sendEncrypted(
                    Protocol.roomInvitation(
                            litoDisplayName(), currentRoomId, settings.password()),
                    "S_LITO_INVITE_USER inviter=" + playerName()
                            + " room=" + currentRoomId);
        } catch (IOException error) {
            if (target.pendingLitoRoomInvitation == invitation) {
                target.pendingLitoRoomInvitation = null;
            }
            throw error;
        }
        System.out.println("[LiTo] room invitation inviter=" + playerName()
                + " target=" + target.playerName() + " room=" + currentRoomId);
    }

    private void inviteReply(byte[] payload) throws IOException {
        Protocol.LitoInviteReplyRequest request = Protocol.litoInviteReplyRequest(payload);
        String inviterName = request.inviterName();
        Protocol.LitoInvitationReply reply = request.reply();
        PendingLitoRoomInvitation invitation = pendingLitoRoomInvitation;
        pendingLitoRoomInvitation = null;
        ClientSession inviter = hub.channelMemberByName(currentChannelId, this, inviterName);
        boolean inviterStillOwnsInvitationRoom = invitation != null && inviter != null
                && inviter.currentRoomId == invitation.roomId()
                && (inviter.phase == Phase.ROOM || inviter.phase == Phase.BATTLE
                    || inviter.phase == Phase.RESULT);
        boolean valid = phase == Phase.CHANNEL && invitation != null
                && System.nanoTime() - invitation.expiresAtNanos() < 0
                && invitation.inviter() == inviter && inviter != this
                && invitation.inviterName().equalsIgnoreCase(inviterName)
                && invitation.channelId() == currentChannelId
                && inviter.currentChannelId == currentChannelId
                && inviterStillOwnsInvitationRoom
                && hub.roomExists(currentChannelId, invitation.roomId());
        if (!valid) {
            System.out.println("[LiTo] ignored invite reply player=" + playerName()
                    + " inviter=" + inviterName
                    + " reason=missing-stale-or-mismatched-S_D7-capability");
            return;
        }
        acceptedLitoRoomInvitation = reply.accepted() ? invitation : null;
        inviter.sendEncrypted(Protocol.roomInvitationReply(litoDisplayName(), reply),
                "S_LITO_INVITE_REPLY invitee=" + playerName()
                        + " reply=" + reply.wireValue());
        // On reply=1 the native accept callback immediately emits C_CF using
        // the room id/password saved by S_D7. The server must not force a
        // second synthetic join here.
        System.out.println("[LiTo] room invitation reply inviter=" + inviter.playerName()
                + " invitee=" + playerName() + " reply=" + reply.wireValue());
    }

    private void editRoom(byte[] payload) throws IOException {
        Protocol.LitoRoomSettingsRequest request = Protocol.litoRoomSettingsRequest(
                payload, Protocol.C_LITO_EDIT_ROOM);
        if (phase != Phase.ROOM) return;
        if (rentalTownRoomState) {
            // The direct group-1 rental state has no ordinary editable room
            // owner/settings record.  Parse the exact request, then restore
            // the server-owned town mode and map without consulting GameHub.
            sendRentalTownGameInfoSnapshot("edit-rejected");
            return;
        }
        if (!GameHub.nativeRoomCapacity(request.capacity())) {
            System.out.println("[LiTo] C_LITO_EDIT_ROOM rejected capacity="
                    + request.capacity() + " selected-Taiwan-range=2..100");
            sendGameInfoSnapshot();
            return;
        }
        GameHub.RoomSettings current = hub.roomSettings(currentRoomId);
        int option1 = request.hasOptions() ? request.option1() : current.option1();
        int option2 = request.hasOptions() ? request.option2() : current.option2();
        int option3 = request.hasOptions() ? request.option3() : current.option3();
        int option4 = request.hasOptions() ? request.option4() : current.option4();
        List<Integer> selections = request.hasOptions()
                ? request.selections() : current.selections();
        // C_DD edits the common room fields only. Preserve option0 because
        // the native mode arrows use C_D1 subtype 2 and S_D5 subtype 2.
        boolean accepted = hub.updateSettings(currentRoomId, this, new GameHub.RoomSettings(
                request.name(), request.password(), request.capacity(), request.attributes(),
                current.option0(), option1, option2, option3, option4, selections));
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        System.out.println("[LiTo] C_LITO_EDIT_ROOM room=" + currentRoomId + " accepted=" + accepted
                + " layout=" + request.layout()
                + " mode=" + rules.mode().key() + " map=" + rules.mapId()
                + " selections=" + selections);
        if (accepted) {
            resetRoomReadyAfterSettingsChange();
            broadcastGameInfoSnapshot();
            retryWaitingMatchMakingSessions("room-edited=" + currentRoomId);
        } else {
            sendGameInfoSnapshot();
        }
        LobbyRoomDirectory.refresh(this, "room-edited");
    }

    private void sendRanking(byte[] byArray) throws IOException {
        Protocol.LitoRankingScope litoRankingScope = Protocol.litoRankingRequest(byArray);
        if (this.phase != Phase.LOBBY && this.phase != Phase.CHANNEL) {
            System.out.println("[LiTo] C_LITO_RANKING rejected phase=" + String.valueOf((Object)this.phase) + " scope=" + String.valueOf((Object)litoRankingScope));
            return;
        }
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        int n = characterSummary == null ? -1 : characterSummary.level();
        int n2 = characterSummary == null ? -1 : characterSummary.type();
        int n3 = this.currentChannelId >= 0 && this.currentChannelId < GameHub.CHANNEL_COUNT ? this.currentChannelId : GameHub.characterRankingSelector(n);
        GameStateStore.RankingQuery rankingQuery = new GameStateStore.RankingQuery(this.selectedClassicServerName, n3, n, n2);
        List<GameStateStore.Ranking> list = this.state.ranking(litoRankingScope, rankingQuery, 100);
        LiveBattleStats.persistRankingRoster(this);
        this.sendEncrypted(Protocol.litoRanking(list), "S_LITO_RANKING entries=" + list.size() + " scope=" + String.valueOf((Object)litoRankingScope) + " selector=" + litoRankingScope.wireValue());
    }

    private void acknowledgeLitoNews(byte[] payload) throws IOException {
        Protocol.litoNewsRequest(payload);
        if (endpoint != Endpoint.GAME || phase != Phase.AUTHENTICATED
                || !litoNewsAcknowledgementPending) {
            System.out.println("[LiTo] C_LITO_READ_NEWS ignored without pending S_E6 phase="
                    + phase + " endpoint=" + endpoint);
            return;
        }
        litoNewsAcknowledgementPending = false;
        completeGameBootstrap();
    }

    private boolean isAdministrator() {
        return SourceAdministration.administrator(this.selectedSourceAccounts(), this.account, this);
    }

    private boolean requireAdministrator(int opcode) {
        if (isAdministrator()) return true;
        System.out.printf("[LiTo] rejected privileged C opcode=0x%02X account=%s phase=%s%n",
                opcode, account == null ? "" : account, phase);
        return false;
    }

    private void wish(byte[] payload) {
        String request = Protocol.wishRequest(payload);
        if (!requireAdministrator(Protocol.C_WISH)) return;
        int encodedBytes = request.getBytes(Protocol.LEGACY_TEXT).length;
        if (phase != Phase.BATTLE || currentRoomId == 0) {
            System.out.println("[LiTo] C_WISH rejected outside active world"
                    + " phase=" + phase + " room=" + currentRoomId
                    + " encoded-bytes=" + encodedBytes);
            return;
        }
        // LiTo.bin proves this is a builder-only cs request, but neither the
        // exact client nor the same-version server fork establishes the
        // original server's item/catalogue mutation or response. Tournament
        // sessions therefore consume the exact envelope without inventing a
        // classic-world side effect. Keep the request itself out of logs.
        System.out.println("[LiTo] C_WISH rejected unproven classic builder mutation"
                + " profile=Tournament room=" + currentRoomId
                + " encoded-bytes=" + encodedBytes);
    }

    private void summon(byte[] payload) {
        Protocol.SummonRequest request = Protocol.summonRequest(payload);
        if (!requireAdministrator(Protocol.C_SUMMON)) return;
        int encodedBytes = request.argument().getBytes(Protocol.LEGACY_TEXT).length;
        if (phase != Phase.BATTLE || observer || currentRoomId == 0) {
            System.out.println("[LiTo] C_SUMMON rejected outside active world"
                    + " phase=" + phase + " room=" + currentRoomId
                    + " mode=" + request.mode() + " encoded-bytes=" + encodedBytes);
            return;
        }
        if (request.mode() <= 1) {
            // LiTo.bin proves the summon/summonf envelope, but no exact C39
            // route, NPC catalogue mutation, mode-1 distinction, or response
            // exists in the same-version server source. Do not substitute the
            // unrelated chat-command L1Summon executor or the Tournament bot.
            System.out.println("[LiTo] C_SUMMON rejected unproven classic summon mutation"
                    + " profile=Tournament room=" + currentRoomId
                    + " mode=" + request.mode() + " encoded-bytes=" + encodedBytes);
            return;
        }
        // Modes 2..8 are protected native bot-management commands. The current
        // ArenaBot is a structural single-player opponent, not an evidenced
        // original bot session, so consuming C39 must not mutate match state.
        System.out.println("[LiTo] C_SUMMON rejected unproven bot-management mutation"
                + " profile=Tournament room=" + currentRoomId
                + " mode=" + request.mode() + " encoded-bytes=" + encodedBytes);
    }

    private void classicBuilderControl(byte[] payload) {
        Protocol.BuilderControlRequest request = Protocol.builderControlRequest(payload);
        if (!requireAdministrator(Protocol.C_BUILDER_CONTROL)) return;
        // LiTo.bin proves the complete client envelope family and named
        // command producers, but the same-version server fork retains only
        // the opcode declaration: it has no route, subtype handler, state
        // transition, or response.  In particular, Tournament player state,
        // ArenaBot, castle state, account bans, max-user limits and notices
        // must not be mutated by guessing from names such as purge/immortal.
        // Do not log free-form text or numeric operands supplied by the client.
        System.out.println("[LiTo] C_BUILDER_CONTROL rejected unproven original-server operation"
                + " profile=Tournament phase=" + phase + " room=" + currentRoomId
                + " subtype=0x" + String.format("%02X", request.subtype())
                + " layout=" + request.layout());
    }

    private void silencePlayer(byte[] payload) {
        Protocol.SilenceRequest request = Protocol.silenceRequest(payload);
        if (!requireAdministrator(Protocol.C_SILENCE)) return;
        if (request.durationSeconds() > 0x7D00) {
            System.out.println("[LiTo] C_SILENCE rejected duration-out-of-contract seconds="
                    + request.durationSeconds());
            return;
        }
        ClientSession target = hub.activeMemberByName(this, request.target());
        if (target == null) {
            System.out.println("[LiTo] C_SILENCE target offline");
            return;
        }
        long expiresAt = hub.setChatSilence(
                target.sourceCharacterIdentity(), request.durationSeconds(),
                System.nanoTime());
        System.out.println("[LiTo] C_SILENCE applied target=" + target.playerName()
                + " seconds=" + request.durationSeconds()
                + " active=" + (expiresAt != 0)
                + " target-administrator=" + target.isAdministrator());
    }

    private void wantedLoginMonitor(byte[] payload) throws IOException {
        Protocol.WantedRequest request = Protocol.wantedRequest(payload);
        if (!requireAdministrator(Protocol.C_WANTED)) return;
        if (endpoint != Endpoint.GAME || phase.ordinal() < Phase.LOBBY.ordinal()) {
            System.out.println("[LiTo] C_WANTED rejected outside gameplay-active"
                    + " endpoint=" + endpoint + " phase=" + phase);
            return;
        }
        if (request.mode() == 0) {
            // The exact client proves this query producer, but S_WANTED_LOGIN
            // is an asynchronous "has just logged in" overlay, not a list
            // response. S_BOOK_LIST only has a dormant receiver and no proven
            // producer or visible state mutation. Consume mode zero without
            // fabricating either response until original-server evidence fixes
            // the query contract.
            System.out.println("[LiTo] C_WANTED query accepted tracked="
                    + hub.wantedAccountSnapshot().size() + " response=none-unproven");
            return;
        }
        int encodedBytes = request.operand().getBytes(Protocol.LEGACY_TEXT).length;
        if (encodedBytes > 0x3F) {
            System.out.println("[LiTo] C_WANTED rejected operand exceeds S_WANTED_LOGIN account buffer"
                    + " mode=" + request.mode() + " bytes=" + encodedBytes);
            return;
        }
        GameHub.WantedWatchMutation mutation = request.mode() == 1
                ? hub.addWantedAccount(request.operand())
                : hub.removeWantedAccount(request.operand());
        // The operand can identify an account and is deliberately never logged.
        System.out.println("[LiTo] C_WANTED mode=" + request.mode()
                + " mutation=" + mutation + " operand-bytes=" + encodedBytes);
    }

    private void notifyWantedAccountLogin() {
        if (endpoint != Endpoint.GAME || account == null || account.isBlank()) return;
        String source = socket.getInetAddress().getHostAddress();
        if (!hub.recordWantedLogin(account, source)) return;
        byte[] notification = Protocol.wantedLogin(account, source);
        int recipients = 0;
        for (ClientSession recipient : hub.connectedSessionsSnapshot()) {
            if (!recipient.acceptsWantedLoginOverlay()) continue;
            try {
                recipient.sendEncrypted(notification,
                        "S_WANTED_LOGIN account/source masked");
                recipients++;
            } catch (IOException error) {
                System.out.println("[LiTo] S_WANTED_LOGIN delivery failed recipient="
                        + mask(recipient.accountName()) + ": " + error.getMessage());
            }
        }
        System.out.println("[LiTo] wanted account authenticated account=" + mask(account)
                + " recipients=" + recipients + " source-masked=true");
    }

    private void sms(byte[] payload) throws IOException {
        Protocol.SmsRequest request = Protocol.smsRequest(payload);
        // LiTo.bin proves the request envelopes and the matching native
        // S_EVENT/6 count result, but no external SMS transport, credentials,
        // billing contract or destination registry survives.  Never retain or
        // transmit either private field.  Count zero is the exact native
        // failure result and closes the original UI flow safely.
        sendEncrypted(Protocol.smsResult(0), "S_EVENT subtype=6 SMS unavailable count=0");
        System.out.println("[LiTo] C_SMS rejected unavailable external service"
                + " profile=Tournament phase=" + phase
                + " mode=" + request.mode()
                + " native-artifact-bytes=" + request.nativeProducerArtifact().length);
    }

    private void exitGhost(byte[] payload) {
        Protocol.requireExitGhost(payload);
        if (!requireAdministrator(Protocol.C_EXIT_GHOST)) return;
        if (phase != Phase.BATTLE || currentRoomId == 0) {
            System.out.println("[LiTo] C_EXIT_GHOST rejected outside active world"
                    + " phase=" + phase + " room=" + currentRoomId);
            return;
        }
        // The exact LiTo producer is the builder-only `exitghost` command.
        // The same-family classic source acts only when a server-owned ghost
        // state exists, then returns through the teleport handshake. This
        // Tournament server has no such classic-world state, so consuming the
        // exact request without mutating death/respawn state is authoritative.
        System.out.println("[LiTo] C_EXIT_GHOST rejected unavailable classic ghost state"
                + " profile=Tournament room=" + currentRoomId
                + " player=" + playerName());
    }

    private void builderControl(byte[] payload) throws IOException {
        Protocol.LitoBuilderAdminRequest request = Protocol.litoBuilderAdminRequest(payload);
        if (!requireAdministrator(Protocol.C_LITO_BUILDER_CONTROL)) return;
        switch (request.operation()) {
            case FORCE_WIN -> forceWin(request.firstWord());
            case PREPARE, LOAD -> {
                // The native producer proves the three-short contract, but no
                // receive-side artifact names these values. Preserve exact
                // transport and audit evidence without inventing a world edit.
                System.out.println("[LiTo] C_LITO_BUILDER_CONTROL subtype=" + request.subtype()
                        + " operation=" + request.operation()
                        + " opaque-values=" + request.firstWord() + ","
                        + request.secondWord() + "," + request.thirdWord());
            }
            case ITEM -> System.out.println(
                    "[LiTo] C_LITO_BUILDER_CONTROL subtype=3 opaque-item="
                            + request.firstWord());
            case KICK -> administratorKick(request.targetName());
            case ARENA_WHO -> {
                int count = hub.tournamentUserCount();
                // The compatibility branch of native /arwho emits ordinary
                // C_71 subtype 3.  The recovered S_MESSAGE_CODE handler parses
                // hc+s*count and has a dedicated 0x51 branch; the legacy WHO
                // server packet uses exactly h(0x51), c(1), s(amount).
                sendEncrypted(Protocol.messageCode(0x51, Integer.toString(count)),
                        "S_MESSAGE_CODE arena-who users=" + count);
                System.out.println("[LiTo] C_LITO_BUILDER_CONTROL arwho users=" + count);
            }
            case TELEPORT -> {
                System.out.println("[LiTo] C_LITO_BUILDER_CONTROL subtype=10"
                        + " accepted-no-native-response");
            }
        }
    }

    private static void requireNoRemaining(Protocol.Reader in, String operation) {
        if (in.remaining() != 0) {
            throw new IllegalArgumentException("trailing " + operation + " bytes=" + in.remaining());
        }
    }

    private void forceWin(int force) throws IOException {
        if (phase != Phase.BATTLE || currentRoomId == 0 || (force != 0 && force != 1)) {
            System.out.println("[LiTo] C_LITO_BUILDER_CONTROL forcewin rejected force=" + force
                    + " phase=" + phase + " room=" + currentRoomId);
            return;
        }
        BattleRules.Resolution resolution = hub.forceWinner(currentRoomId, force);
        if (!resolution.ended()) return;
        for (ClientSession member : hub.roomMembers(currentRoomId)) member.serverEndBattle(resolution);
        hub.endBattle(currentRoomId);
    }

    private void administratorKick(String targetName) throws IOException {
        ClientSession target = currentRoomId == 0
                ? null : hub.memberByName(currentRoomId, this, targetName);
        if (target == null || target == this) {
            System.out.println("[LiTo] C_LITO_BUILDER_CONTROL kick rejected target=" + targetName);
            return;
        }
        target.exitRoom();
        System.out.println("[LiTo] C_LITO_BUILDER_CONTROL kick target=" + targetName);
    }

    private void administratorKick(byte[] payload) {
        String targetName = Protocol.namedCommandRequest(payload, Protocol.C_KICK, false);
        if (!requireAdministrator(Protocol.C_KICK)) return;
        ClientSession target = hub.activeMemberByName(this, targetName);
        if (target == null || target == this) {
            System.out.println("[LiTo] C_KICK rejected target=" + targetName);
            return;
        }
        target.sendNativeKickAndDisconnect("C_KICK administrator=" + playerName());
        System.out.println("[LiTo] C_KICK disconnected target=" + targetName
                + " administrator=" + playerName());
    }

    private void administratorBan(byte[] byArray) {
        String string = Protocol.namedCommandRequest(byArray, 36, false);
        if (!this.requireAdministrator(36)) {
            return;
        }
        ClientSession clientSession = this.hub.activeMemberByName(this, string);
        if (clientSession == null || clientSession == this || clientSession.accountName().isBlank()) {
            System.out.println("[LiTo] C_BAN rejected target=" + string);
            return;
        }
        try {
            ClientSession clientSession2 = clientSession;
            this.state.banAccount(SourceLogin.account(clientSession2, clientSession2.accountName()));
        }
        catch (IOException iOException) {
            System.out.println("[LiTo] C_BAN sidecar commit failed target=" + string + ": " + iOException.getMessage());
            return;
        }
        clientSession.sendNativeKickAndDisconnect("C_BAN administrator=" + this.playerName());
        System.out.println("[LiTo] C_BAN account-blocked target=" + string + " administrator=" + this.playerName());
    }

    private void exroom(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != Protocol.C_LITO_EXROOM) {
            throw new IllegalArgumentException("invalid C_LITO_EXROOM opcode");
        }
        requireNoRemaining(in, "exroom");
        if (!requireAdministrator(Protocol.C_LITO_EXROOM)) return;
        if (phase != Phase.BATTLE || currentRoomId == 0) {
            System.out.println("[LiTo] C_LITO_EXROOM rejected phase=" + phase
                    + " room=" + currentRoomId);
            return;
        }
        // Ordinary native result exit calls sub_46A260 locally immediately
        // before it emits C_D9; the following S_F0 performs the phase change.
        // /exroom emits only C_EA and performs neither local operation. S_DA
        // dispatches to the identical sub_46A260 reset in both receive states,
        // so S_DA -> S_F0 is the structurally equivalent remote-exit sequence.
        // Keep the two frames adjacent: S_DA alone leaves phase 4 with an empty
        // world, while S_F0 alone leaves stale world/object/UI state behind.
        sendEncrypted(Protocol.litoReset(), "S_LITO_RESET privileged-exroom");
        quitFight();
        System.out.println("[LiTo] C_LITO_EXROOM completed reset-then-quit-transition");
    }

