    private void authoritativeMove(int n, int n2, String string) throws IOException {
        if (this.phase != Phase.BATTLE || this.currentRoomId == 0L) {
            System.out.println("[LiTo] authoritative move rejected phase=" + String.valueOf((Object)this.phase) + " reason=" + string);
            return;
        }
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(this.hub.battleMapId(this.currentRoomId, this));
        if (!arena.contains(n, n2)) {
            System.out.println("[LiTo] authoritative move rejected outside-map=" + n + "," + n2 + " map=" + arena.mapId() + " reason=" + string);
            return;
        }
        int n3 = this.positionX;
        int n4 = this.positionY;
        this.positionX = n;
        this.positionY = n2;
        this.cancelMeditation("authoritative-move");
        this.naturalHpRegen.noteMove();
        this.naturalMpRegen.noteMove();
        byte[] byArray = NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(n).h(n2).c(0).bytes());
        for (ClientSession clientSession : this.hub.roomMembers(this.currentRoomId)) {
            clientSession.sendEncrypted(byArray, "S_MOVE_OBJECT " + string + " object=" + this.playerObjectId() + " x=" + n + " y=" + n2);
            clientSession.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), n, n2, clientSession.minimapAlliedWith(this)), "S_LITO_MINIMAP " + string + " player=" + this.playerName() + " x=" + n + " y=" + n2);
        }
    }

    private void toggleRoomSilence(byte[] payload) {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != Protocol.C_LITO_SILENCE) {
            throw new IllegalArgumentException("invalid C_LITO_SILENCE opcode");
        }
        requireNoRemaining(in, "silence");
        if (!requireAdministrator(Protocol.C_LITO_SILENCE)) return;
        if (currentRoomId == 0 || (phase != Phase.ROOM && phase != Phase.BATTLE && phase != Phase.RESULT)) {
            System.out.println("[LiTo] C_LITO_SILENCE rejected phase=" + phase);
            return;
        }
        if (rentalTownRoomState) {
            // This command toggles a GameHub room-wide flag and has no
            // evidenced meaning for the isolated non-battle town.  Consume the
            // exact privileged envelope without looking up the synthetic id.
            System.out.println("[LiTo] C_LITO_SILENCE rejected rental-town room="
                    + currentRoomId);
            return;
        }
        boolean silenced = hub.toggleRoomSilence(currentRoomId);
        System.out.println("[LiTo] C_LITO_SILENCE room=" + currentRoomId + " silenced=" + silenced);
    }

