    private void showPkCount(byte[] payload) throws IOException {
        Protocol.requireCheckPk(payload);
        if (phase != Phase.BATTLE || observer || playerObjectId() == 0) {
            System.out.println("[LiTo] C_CHECK_PK ignored outside active player world player="
                    + playerName() + " phase=" + phase + " observer=" + observer);
            return;
        }
        if (selectedCharacterSummary() == null) return;
        // Arena kills remain Tournament-only. Ordinary classic-WORLD PK and
        // L1Guard absolution are stored in the LiTo overlay, never legacy SQL.
        int pkCount = Math.max(0, generalPkCount);
        sendEncrypted(Protocol.messageCode(562, Integer.toString(pkCount)),
                "S_MESSAGE_CODE pk-count=562 value=" + pkCount
                        + " source=legacy-plus-LiTo-overlay");
    }

