    private void createClassicClan(byte[] payload) throws IOException {
        String clanName = Protocol.createPledgeRequest(payload);
        if (!classicClanEligible() && !classicCastleClanEligible()) {
            System.out.println("[LiTo] C_CREATE_PLEDGE ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        int encodedLength = clanName.getBytes(Protocol.LEGACY_TEXT).length;
        if (encodedLength > 16) {
            sendEncrypted(Protocol.messageCode(98),
                    "S_MESSAGE_CODE clan-create-name-too-long=98 bytes=" + encodedLength);
            return;
        }
        if (!Protocol.validClanName(clanName)) {
            System.out.println("[LiTo] C_CREATE_PLEDGE rejected invalid native name player="
                    + playerName() + " bytes=" + encodedLength);
            return;
        }
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || character.type() != 0) {
            sendEncrypted(Protocol.messageCode(85),
                    "S_MESSAGE_CODE clan-create-not-crown=85 player=" + playerName());
            return;
        }
        GameHub.ClassicClanCreateStatus available =
                hub.classicClanCreateStatus(sourceCharacterIdentity(), clanName);
        if (available == GameHub.ClassicClanCreateStatus.OWNER_ALREADY_MEMBER) {
            sendEncrypted(Protocol.messageCode(86),
                    "S_MESSAGE_CODE clan-create-already-member=86 player=" + playerName());
            return;
        }
        if (available == GameHub.ClassicClanCreateStatus.DUPLICATE_NAME) {
            sendEncrypted(Protocol.messageCode(99),
                    "S_MESSAGE_CODE clan-create-duplicate=99 clan=" + clanName);
            return;
        }
        if (available != GameHub.ClassicClanCreateStatus.CREATED) {
            System.out.println("[LiTo] C_CREATE_PLEDGE rejected invalid authority player="
                    + playerName() + " clan=" + clanName);
            return;
        }

        RuntimeInventory previousInventory = inventory;
        RuntimeInventory nextInventory = inventory.copy();
        if (!nextInventory.removeCatalog(InventoryCatalog.ADENA, CLASSIC_CLAN_CREATE_ADENA)) {
            sendEncrypted(Protocol.messageCode(189),
                    "S_MESSAGE_CODE clan-create-insufficient-adena=189 required="
                            + CLASSIC_CLAN_CREATE_ADENA);
            return;
        }
        RepositoryClanMutation repositoryCreated;
        try {
            repositoryCreated = selectedSourceAccounts().createClan(
                    character.objectId(), clanName);
        } catch (Exception databaseError) {
            System.out.println("[LiTo] C_CREATE_PLEDGE SQL clan-create failed player="
                    + playerName() + " clan=" + clanName + ": "
                    + databaseError.getClass().getSimpleName() + ": "
                    + databaseError.getMessage());
            return;
        }
        boolean sqlClanCreated = repositoryCreated.status()
                == RepositoryClanMutationStatus.SUCCESS;
        GameHub.ClassicClanCreateStatus created;
        if (sqlClanCreated) {
            hub.reconcileSqlClan(sourceCharacterIdentity(), repositoryCreated.snapshot());
            created = GameHub.ClassicClanCreateStatus.CREATED;
        } else if (repositoryCreated.status()
                == RepositoryClanMutationStatus.UNAVAILABLE) {
            created = hub.createClassicClan(sourceCharacterIdentity(), clanName);
        } else if (repositoryCreated.status()
                == RepositoryClanMutationStatus.OWNER_ALREADY_MEMBER) {
            created = GameHub.ClassicClanCreateStatus.OWNER_ALREADY_MEMBER;
        } else if (repositoryCreated.status()
                == RepositoryClanMutationStatus.DUPLICATE_NAME) {
            created = GameHub.ClassicClanCreateStatus.DUPLICATE_NAME;
        } else {
            System.out.println("[LiTo] C_CREATE_PLEDGE SQL clan-create rejected player="
                    + playerName() + " clan=" + clanName
                    + " status=" + repositoryCreated.status());
            return;
        }
        if (created == GameHub.ClassicClanCreateStatus.OWNER_ALREADY_MEMBER) {
            sendEncrypted(Protocol.messageCode(86),
                    "S_MESSAGE_CODE clan-create-already-member=86 player=" + playerName());
            return;
        }
        if (created == GameHub.ClassicClanCreateStatus.DUPLICATE_NAME) {
            sendEncrypted(Protocol.messageCode(99),
                    "S_MESSAGE_CODE clan-create-duplicate=99 clan=" + clanName);
            return;
        }
        if (created != GameHub.ClassicClanCreateStatus.CREATED) {
            System.out.println("[LiTo] C_CREATE_PLEDGE rejected invalid authority player="
                    + playerName() + " clan=" + clanName);
            return;
        }

        NativeDeItemApplication.replace(this, nextInventory, 0);
        try {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        } catch (IOException error) {
            NativeDeItemApplication.replace(this, previousInventory, 0);
            if (sqlClanCreated) {
                try {
                    if (selectedSourceAccounts().rollbackCreatedClan(
                            character.objectId(), repositoryCreated.snapshot().clanId())) {
                        hub.reconcileSqlClan(sourceCharacterIdentity(),
                                RepositoryClanSnapshot.empty());
                    } else {
                        error.addSuppressed(new IOException(
                                "SQL clan creation compensation was refused"));
                    }
                } catch (Exception compensation) {
                    error.addSuppressed(compensation);
                }
            } else {
                hub.rollbackClassicClanCreation(sourceCharacterIdentity(), clanName);
            }
            throw error;
        }
        sendInventoryDelta(previousInventory, inventory);
        updateLocalClanRosterState(
                Protocol.LitoClanActivity.fromBuddy(buddyActivityState()));
        sendEncrypted(Protocol.messageCode(84, clanName),
                "S_MESSAGE_CODE clan-created=84 clan=" + clanName);
        publishClassicClanIdentity(this, clanName, "create");
        publishClanRoster(hub.clanData(sourceCharacterIdentity()), "classic-create");
        System.out.println("[LiTo] C_CREATE_PLEDGE created owner=" + playerName()
                + " clan=" + clanName + " adena=" + CLASSIC_CLAN_CREATE_ADENA);
    }

    private void requestClassicClanJoin(byte[] payload) throws IOException {
        Protocol.requireJoinPledge(payload);
        if (!classicClanEligible()) {
            System.out.println("[LiTo] C_JOIN_PLEDGE ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        if (!hub.clanData(sourceCharacterIdentity()).name().isBlank()) {
            sendEncrypted(Protocol.messageCode(89),
                    "S_MESSAGE_CODE clan-join-already-member=89 player=" + playerName());
            return;
        }

        ClientSession target = faceToFaceCombatant();
        if (target == null) {
            sendEncrypted(Protocol.messageCode(93),
                    "S_MESSAGE_CODE clan-join-no-face-target=93 player=" + playerName());
            return;
        }
        if ((target.playerHeading & 7) != ((playerHeading + 4) & 7)) {
            sendEncrypted(Protocol.messageCode(91, target.playerName()),
                    "S_MESSAGE_CODE clan-join-not-facing=91 target=" + target.playerName());
            return;
        }

        GameHub.ClanData targetClan = hub.clanData(target.sourceCharacterIdentity());
        if (targetClan.name().isBlank()) {
            sendEncrypted(Protocol.messageCode(90, target.playerName()),
                    "S_MESSAGE_CODE clan-join-target-no-clan=90 target=" + target.playerName());
            return;
        }
        boolean targetOwnsClan = targetClan.members().stream()
                .anyMatch(member -> member.name().equalsIgnoreCase(target.playerName())
                        && member.role() == Protocol.LitoClanRole.OWNER);
        if (!targetOwnsClan) {
            sendEncrypted(Protocol.messageCode(92, target.playerName()),
                    "S_MESSAGE_CODE clan-join-target-not-authorized=92 target="
                            + target.playerName());
            return;
        }

        // The native client owns one generic S_ASK callback. This prompt
        // supersedes only unopened prompts, never a committed/open exchange.
        hub.cancelPendingPlayerTradePrompt(target);
        target.clearPendingAskCallbacks();
        target.pendingClanJoin = new PendingClanJoin(this, targetClan.name(), currentRoomId,
                System.nanoTime() + CLAN_JOIN_TIMEOUT_NANOS);
        target.sendEncrypted(Protocol.clanJoinAsk(playerName()),
                "S_ASK question=97 applicant=" + playerName() + " clan=" + targetClan.name());
        System.out.println("[LiTo] C_JOIN_PLEDGE pending applicant=" + playerName()
                + " owner=" + target.playerName() + " clan=" + targetClan.name());
    }

    private void answerClassicClanJoin(Protocol.AskAnswer answer) throws IOException {
        PendingClanJoin pending = pendingClanJoin;
        pendingClanJoin = null;
        if (pending == null || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER rejected question=97 owner=" + playerName()
                    + " result=pending-clan-join-unavailable-or-nonempty-tail");
            return;
        }
        ClientSession applicant = pending.applicant();
        if (answer.answer() == 0) {
            if (applicant != null) {
                applicant.sendEncrypted(Protocol.messageCode(96, playerName()),
                        "S_MESSAGE_CODE clan-join-refused=96 owner=" + playerName());
            }
            System.out.println("[LiTo] C_ANSWER question=97 refused owner=" + playerName()
                    + " applicant=" + (applicant == null ? "" : applicant.playerName()));
            return;
        }

        long now = System.nanoTime();
        GameHub.ClanData ownerClan = hub.clanData(sourceCharacterIdentity());
        boolean ownerStillOwns = ownerClan.name().equalsIgnoreCase(pending.clanName())
                && ownerClan.members().stream().anyMatch(member ->
                        member.name().equalsIgnoreCase(playerName())
                                && member.role() == Protocol.LitoClanRole.OWNER);
        boolean validState = applicant != null && now - pending.expiresAtNanos() < 0
                && pending.roomId() == currentRoomId && applicant.currentRoomId == currentRoomId
                && classicClanEligible() && applicant.classicClanEligible()
                && hub.roomCombatants(currentRoomId).contains(applicant) && ownerStillOwns;
        if (!validState) {
            System.out.println("[LiTo] C_ANSWER rejected question=97 owner=" + playerName()
                    + " result=state-mismatch-or-expired");
            return;
        }
        if (!hub.clanData(applicant.sourceCharacterIdentity()).name().isBlank()) {
            applicant.sendEncrypted(Protocol.messageCode(89),
                    "S_MESSAGE_CODE clan-join-already-member=89 player=" + applicant.playerName());
            return;
        }
        if (!selectedClassicServerName.equalsIgnoreCase(applicant.selectedClassicServerName)) {
            System.out.println("[LiTo] C_ANSWER rejected question=97 owner=" + playerName()
                    + " applicant=" + applicant.playerName()
                    + " result=cross-dynamic-source");
            return;
        }

        List<ClientSession> existingMembers = hub.clanSessions(sourceCharacterIdentity());
        RepositoryClanMutation repositoryJoined;
        try {
            CharacterSummary ownerCharacter = selectedCharacterSummary();
            repositoryJoined = ownerCharacter == null
                    ? RepositoryClanMutation.unavailable()
                    : selectedSourceAccounts().joinClan(ownerCharacter.objectId(),
                            applicant.playerName(), classicClanCapacity());
        } catch (Exception databaseError) {
            System.out.println("[LiTo] C_ANSWER SQL clan-join failed owner=" + playerName()
                    + " applicant=" + applicant.playerName() + ": "
                    + databaseError.getClass().getSimpleName() + ": "
                    + databaseError.getMessage());
            return;
        }
        GameHub.ClassicClanJoinResult joined;
        if (repositoryJoined.status() == RepositoryClanMutationStatus.SUCCESS) {
            GameHub.ClanData reconciled = hub.reconcileSqlClan(
                    sourceCharacterIdentity(), repositoryJoined.snapshot());
            joined = new GameHub.ClassicClanJoinResult(
                    GameHub.ClassicClanJoinStatus.JOINED, reconciled);
        } else if (repositoryJoined.status() == RepositoryClanMutationStatus.UNAVAILABLE) {
            joined = hub.joinClassicClan(sourceCharacterIdentity(),
                    applicant.sourceCharacterIdentity(), classicClanCapacity());
        } else if (repositoryJoined.status() == RepositoryClanMutationStatus.FULL) {
            joined = new GameHub.ClassicClanJoinResult(
                    GameHub.ClassicClanJoinStatus.FULL,
                    hub.clanData(sourceCharacterIdentity()));
        } else {
            System.out.println("[LiTo] C_ANSWER SQL clan-join rejected owner=" + playerName()
                    + " applicant=" + applicant.playerName()
                    + " status=" + repositoryJoined.status());
            return;
        }
        if (joined.status() == GameHub.ClassicClanJoinStatus.FULL) {
            applicant.sendEncrypted(Protocol.messageCode(188, playerName()),
                    "S_MESSAGE_CODE clan-join-full=188 owner=" + playerName());
            return;
        }
        if (joined.status() != GameHub.ClassicClanJoinStatus.JOINED) {
            System.out.println("[LiTo] C_ANSWER rejected question=97 owner=" + playerName()
                    + " applicant=" + applicant.playerName() + " result=join-race-invalid");
            return;
        }

        applicant.updateLocalClanRosterState(
                Protocol.LitoClanActivity.fromBuddy(applicant.buddyActivityState()));

        for (ClientSession member : existingMembers) {
            member.sendEncrypted(Protocol.messageCode(94, applicant.playerName()),
                    "S_MESSAGE_CODE clan-member-joined=94 applicant=" + applicant.playerName());
        }
        applicant.sendEncrypted(Protocol.messageCode(95, joined.clan().name()),
                "S_MESSAGE_CODE clan-joined=95 clan=" + joined.clan().name());
        applicant.publishClassicClanIdentity(applicant, joined.clan().name(), "join");
        publishClanRoster(joined.clan(), "classic-join");
        System.out.println("[LiTo] C_ANSWER question=97 joined owner=" + playerName()
                + " applicant=" + applicant.playerName() + " clan=" + joined.clan().name());
    }

    private void requestClassicClanWar(byte[] payload) throws IOException {
        Protocol.ClanWarRequest request = Protocol.clanWarRequest(payload);
        if (!classicClanEligible() && !classicCastleClanEligible()) {
            System.out.println("[LiTo] C_WAR ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        if (request.type() == Protocol.ClanWarRequestType.ALLIANCE) {
            // The native producer is proven, but its question/acceptance
            // contract is not. Keep it visible and inert instead of guessing.
            System.out.println("[LiTo] C_WAR type=5 alliance withheld pending native answer proof"
                    + " player=" + playerName() + " target=" + request.targetClan());
            return;
        }

        CastleSummary targetCastle = " ".equals(request.targetClan())
                ? unownedClassicCastleWarTarget()
                : effectiveClassicCastleForClan(request.targetClan());
        if (" ".equals(request.targetClan()) && targetCastle == null) {
            System.out.println("[LiTo] C_WAR unowned castle rejected player="
                    + playerName() + " npc-temp=" + lastClassicNpcActionObjectId
                    + " map=" + classicWorldMapId
                    + " reason=no-current-unowned-castle-context");
            return;
        }
        if (targetCastle != null && requestClassicCastleWar(
                request, targetCastle)) return;

        GameHub.ClassicClanWarProposal proposal = hub.proposeClassicClanWar(
                sourceCharacterIdentity(), request.targetClan(), request.type());
        switch (proposal.status()) {
            case NOT_OWNER -> {
                GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
                int code = clan.name().isBlank() ? 272 : 478;
                sendEncrypted(Protocol.messageCode(code),
                        "S_MESSAGE_CODE clan-war-not-owner=" + code + " player=" + playerName());
                return;
            }
            case TARGET_OWNER_OFFLINE -> {
                sendEncrypted(Protocol.messageCode(218, proposal.targetClan()),
                        "S_MESSAGE_CODE clan-war-target-offline=218 clan="
                                + proposal.targetClan());
                return;
            }
            case REQUESTER_AT_WAR -> {
                sendEncrypted(Protocol.messageCode(234),
                        "S_MESSAGE_CODE clan-war-requester-busy=234 clan="
                                + proposal.requesterClan());
                return;
            }
            case TARGET_AT_WAR -> {
                sendEncrypted(Protocol.messageCode(236, proposal.targetClan()),
                        "S_MESSAGE_CODE clan-war-target-busy=236 clan="
                                + proposal.targetClan());
                return;
            }
            case PENDING -> { }
            default -> {
                System.out.println("[LiTo] C_WAR rejected player=" + playerName()
                        + " type=" + request.type() + " target=" + request.targetClan()
                        + " result=" + proposal.status());
                return;
            }
        }

        ClientSession target = proposal.targetOwner();
        if (target == null || !target.classicClanEligible()) {
            sendEncrypted(Protocol.messageCode(218, proposal.targetClan()),
                    "S_MESSAGE_CODE clan-war-target-unavailable=218 clan="
                            + proposal.targetClan());
            return;
        }

        // LiTo owns one generic S_ASK callback. Replace only unopened prompt
        // capabilities; a committed/open exchange remains independent.
        hub.cancelPendingPlayerTradePrompt(target);
        target.clearPendingAskCallbacks();
        target.pendingClanWar = new PendingClanWar(
                this, proposal.requesterClan(), proposal.targetClan(), request.type(),
                currentRoomId, target.currentRoomId,
                System.nanoTime() + CLAN_WAR_TIMEOUT_NANOS);
        target.sendEncrypted(Protocol.clanWarAsk(
                        request.type(), proposal.requesterClan(), playerName()),
                "S_ASK question=" + clanWarQuestion(request.type())
                        + " requester=" + playerName()
                        + " clan=" + proposal.requesterClan()
                        + " target=" + proposal.targetClan());
        System.out.println("[LiTo] C_WAR pending requester=" + playerName()
                + " requesterClan=" + proposal.requesterClan()
                + " targetOwner=" + target.playerName()
                + " targetClan=" + proposal.targetClan()
                + " type=" + request.type());
    }

    /** Retained C_War.war_castle path: no defender Y/N callback is used. */
    private boolean requestClassicCastleWar(
            Protocol.ClanWarRequest request, CastleSummary targetCastle)
            throws IOException {
        if (targetCastle == null || phase != Phase.WORLD) return false;
        CharacterSummary character = selectedCharacterSummary();
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        if (character == null || character.type() != 0
                || hub.clanRole(sourceCharacterIdentity()) != GameHub.CLAN_ROLE_OWNER
                || clan.name().isBlank()) {
            sendEncrypted(Protocol.messageCode(
                            clan.name().isBlank() ? 272 : 478),
                    "S_MESSAGE_CODE castle-war-not-owner player=" + playerName());
            return true;
        }
        if (character.level() < 25) {
            sendEncrypted(Protocol.messageCode(475),
                    "S_MESSAGE_CODE castle-war-level=475 player=" + playerName());
            return true;
        }
        if (request.type() == Protocol.ClanWarRequestType.DECLARE
                && selectedLegacyCastle() != null) {
            sendEncrypted(Protocol.messageCode(474),
                    "S_MESSAGE_CODE castle-war-already-owner=474 player=" + playerName());
            return true;
        }
        if (!hub.classicCastleWarActive(
                selectedClassicServerName, targetCastle.castleId())) {
            if (request.type() == Protocol.ClanWarRequestType.DECLARE) {
                sendEncrypted(Protocol.messageCode(476),
                        "S_MESSAGE_CODE castle-war-not-time=476 castle="
                                + targetCastle.castleId());
            }
            sendEncrypted(Protocol.closeHypertext(playerObjectId()),
                    "S_CLOSE_LIST castle-war-not-active player=" + playerName());
            return true;
        }
        if (request.type() == Protocol.ClanWarRequestType.DECLARE
                && hub.clanEmblemId(sourceCharacterIdentity()) == 0
                && !isAdministrator()) {
            sendEncrypted(Protocol.messageCode(812),
                    "S_MESSAGE_CODE castle-war-emblem=812 player=" + playerName());
            return true;
        }
        if (request.type() == Protocol.ClanWarRequestType.DECLARE) {
            ClassicWorldCastleWarField.Area area =
                    ClassicWorldCastleWarField.area(targetCastle.castleId());
            boolean memberInside = hub.clanSessions(sourceCharacterIdentity()).stream()
                    .anyMatch(member -> member.phase == Phase.WORLD
                            && area.contains(member.classicWorldMapId,
                                member.positionX, member.positionY));
            if (memberInside) {
                sendEncrypted(Protocol.messageCode(477),
                        "S_MESSAGE_CODE castle-war-member-inside=477 castle="
                                + targetCastle.castleId());
                return true;
            }
        }
        GameHub.ClassicCastleSiegeResult result = hub.mutateClassicCastleSiege(
                selectedClassicServerName, targetCastle.castleId(), clan.name(),
                targetCastle.clanName(), request.type());
        if (result.mutation() == GameHub.ClassicCastleSiegeMutation.ALREADY_DECLARED) {
            sendEncrypted(Protocol.messageCode(234),
                    "S_MESSAGE_CODE castle-war-already-declared=234 clan=" + clan.name());
            return true;
        }
        if (result.mutation() == GameHub.ClassicCastleSiegeMutation.NOT_PARTICIPANT
                || result.mutation() == GameHub.ClassicCastleSiegeMutation.INVALID
                || result.mutation() == GameHub.ClassicCastleSiegeMutation.NOT_ACTIVE) {
            System.out.println("[LiTo] C_WAR castle rejected player=" + playerName()
                    + " castle=" + targetCastle.castleId()
                    + " type=" + request.type()
                    + " result=" + result.mutation());
            return true;
        }
        List<ClientSession> recipients = hub.connectedSessionsSnapshot().stream()
                .filter(session -> session.usesClassicSource(
                        selectedClassicServerName)).toList();
        GameHub.deliverClassicCastleWarNotices(
                selectedClassicServerName, result.notices(), recipients);
        sendEncrypted(Protocol.closeHypertext(playerObjectId()),
                "S_CLOSE_LIST castle-war-" + result.mutation().name()
                        .toLowerCase(Locale.ROOT) + " castle="
                        + targetCastle.castleId());
        System.out.println("[LiTo] C_WAR castle player=" + playerName()
                + " clan=" + clan.name() + " defender=" + targetCastle.clanName()
                + " castle=" + targetCastle.castleId()
                + " type=" + request.type() + " result=" + result.mutation());
        return true;
    }

    private CastleSummary unownedClassicCastleWarTarget() {
        int n;
        if (this.phase != Phase.WORLD || this.lastClassicNpcActionObjectId == 0L) {
            return null;
        }
        ClassicWorldCastleWarField.WarObject warObject = this.hub.classicCastleWarObject(this.selectedClassicServerName, this.classicWorldMapId, this.lastClassicNpcActionObjectId);
        int n2 = n = warObject == null ? 0 : warObject.castleId();
        if (n == 0) {
            ClassicWorldNpcCatalog.StaticNpc staticNpc = ClassicWorldNpcCatalog.npc(this.classicWorldMapId, this.lastClassicNpcActionObjectId);
            if (staticNpc == null) {
                return null;
            }
            n = ClassicWorldCastleWarField.castleIdAt(staticNpc.mapId(), NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this));
        }
        if (n == 0) {
            return null;
        }
        try {
            if (this.effectiveClassicCastleById(n) != null) {
                return null;
            }
        }
        catch (Exception exception) {
            System.out.println("[LiTo] C_WAR unowned castle lookup failed player=" + this.playerName() + " castle=" + n + " error=" + exception.getMessage());
            return null;
        }
        return new CastleSummary(n, "NPC", "NPC", ClientSession.classicCastleName(n), 0L, 0, 0L, 0L);
    }

    private static String classicCastleName(int castleId) {
        return switch (castleId) {
            case 1 -> "肯特城";
            case 2 -> "妖魔城";
            case 3 -> "風木城";
            case 4 -> "奇巖城";
            case 5 -> "海音城";
            case 6 -> "侏儒城";
            case 7 -> "亞丁城";
            case 8 -> "狄亞得要塞";
            default -> throw new IllegalArgumentException(
                    "unknown classic castle " + castleId);
        };
    }

    private void answerClassicClanWar(Protocol.AskAnswer answer) throws IOException {
        PendingClanWar pending = pendingClanWar;
        pendingClanWar = null;
        int expectedQuestion = pending == null ? -1 : clanWarQuestion(pending.type());
        if (pending == null || answer.questionId() != expectedQuestion
                || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER rejected question=" + answer.questionId()
                    + " owner=" + playerName()
                    + " result=pending-clan-war-unavailable-or-nonempty-tail");
            return;
        }

        ClientSession requester = pending.requester();
        long now = System.nanoTime();
        boolean validState = requester != null && now - pending.expiresAtNanos() < 0
                && pending.targetRoomId() == currentRoomId
                && pending.requesterRoomId() == requester.currentRoomId
                && classicClanEligible() && requester.classicClanEligible();
        if (!validState) {
            System.out.println("[LiTo] C_ANSWER rejected question=" + answer.questionId()
                    + " owner=" + playerName() + " result=state-mismatch-or-expired");
            return;
        }

        boolean accepted = answer.answer() == 1;
        GameHub.ClassicClanWarResolution resolution = hub.resolveClassicClanWar(
                requester.sourceCharacterIdentity(), sourceCharacterIdentity(),
                pending.requesterClan(),
                pending.targetClan(), pending.type(), accepted);
        if (resolution.status() == GameHub.ClassicClanWarResolutionStatus.REFUSED) {
            int code = pending.type() == Protocol.ClanWarRequestType.DECLARE ? 236 : 237;
            requester.sendEncrypted(Protocol.messageCode(code, pending.targetClan()),
                    "S_MESSAGE_CODE clan-war-refused=" + code
                            + " target=" + pending.targetClan());
            return;
        }
        if (resolution.status() == GameHub.ClassicClanWarResolutionStatus.INVALID) {
            System.out.println("[LiTo] C_ANSWER rejected question=" + answer.questionId()
                    + " requester=" + requester.playerName()
                    + " result=atomic-clan-war-revalidation-failed");
            return;
        }

        List<ClientSession> requesterClan = hub.clanSessions(
                requester.sourceCharacterIdentity()).stream()
                .filter(ClientSession::classicClanEligible).toList();
        List<ClientSession> targetClan = hub.clanSessions(sourceCharacterIdentity()).stream()
                .filter(ClientSession::classicClanEligible).toList();
        LinkedHashSet<ClientSession> all = new LinkedHashSet<>(requesterClan);
        all.addAll(targetClan);
        switch (resolution.status()) {
            case STARTED -> sendClanWarPacket(all, Protocol.ClanWarNoticeType.DECLARED,
                    pending.requesterClan(), pending.targetClan(), "started");
            case SURRENDERED -> {
                sendClanWarPacket(requesterClan, Protocol.ClanWarNoticeType.SURRENDERED,
                        pending.requesterClan(), pending.targetClan(), "surrendered");
                sendClanWarPacket(targetClan, Protocol.ClanWarNoticeType.WON,
                        pending.targetClan(), pending.requesterClan(), "won");
                sendClanWarPacket(all, Protocol.ClanWarNoticeType.ENDED,
                        pending.requesterClan(), pending.targetClan(), "ended-after-surrender");
            }
            case CEASED -> sendClanWarPacket(all, Protocol.ClanWarNoticeType.ENDED,
                    pending.requesterClan(), pending.targetClan(), "ceased");
            default -> throw new IllegalStateException(
                    "unexpected clan-war resolution " + resolution.status());
        }
        System.out.println("[LiTo] C_ANSWER question=" + answer.questionId()
                + " requester=" + requester.playerName() + " owner=" + playerName()
                + " result=" + resolution.status()
                + " war=" + resolution.war());
    }

    private void sendClanWarPacket(Iterable<ClientSession> recipients,
                                   Protocol.ClanWarNoticeType type,
                                   String clanOne, String clanTwo, String reason)
            throws IOException {
        byte[] packet = Protocol.clanWar(type, clanOne, clanTwo);
        IOException firstError = null;
        for (ClientSession recipient : recipients) {
            try {
                recipient.sendEncrypted(packet,
                        "S_WAR type=" + type.wireValue() + " clanOne=" + clanOne
                                + " clanTwo=" + clanTwo + " reason=" + reason);
            } catch (IOException error) {
                if (firstError == null) firstError = error;
            }
        }
        if (firstError != null) throw firstError;
    }

    /** Same-family login restoration: type 8 names the local clan first. */
    private void sendCurrentClassicClanWarState() throws IOException {
        GameHub.ClassicClanWarData war = hub.classicClanWarData(sourceCharacterIdentity());
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        if (!war.active() || clan.name().isBlank()) return;
        String enemy = clan.name().equalsIgnoreCase(war.clanOne())
                ? war.clanTwo() : war.clanOne();
        sendEncrypted(Protocol.clanWar(
                        Protocol.ClanWarNoticeType.CURRENT_WAR, clan.name(), enemy),
                "S_WAR type=8 current clanOne=" + clan.name() + " clanTwo=" + enemy);
    }

    private static int clanWarQuestion(Protocol.ClanWarRequestType type) {
        return switch (type) {
            case DECLARE -> 217;
            case SURRENDER -> 221;
            case CEASE -> 222;
            default -> -1;
        };
    }

    private void marriage(byte[] payload) throws IOException {
        int mode = Protocol.marriageRequest(payload);
        if (mode == 0) requestMarriageProposal();
        else requestDivorce();
    }

    private void requestMarriageProposal() throws IOException {
        if (!classicMarriageEligible()) {
            System.out.println("[LiTo] C_MARRIAGE propose ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        if (!state.marriagePartner(stateCharacter()).isBlank()) {
            sendEncrypted(Protocol.messageCode(657),
                    "S_MESSAGE_CODE marriage-already-married=657 player=" + playerName());
            return;
        }

        ClientSession target = faceToFaceCombatant();
        if (target == null || !target.classicMarriageEligible() || target.invisible) {
            sendEncrypted(Protocol.messageCode(93),
                    "S_MESSAGE_CODE marriage-no-face-target=93 player=" + playerName());
            return;
        }
        if ((target.playerHeading & 7) != ((playerHeading + 4) & 7)) {
            sendEncrypted(Protocol.messageCode(91, target.playerName()),
                    "S_MESSAGE_CODE marriage-target-not-facing=91 target="
                            + target.playerName());
            return;
        }
        if (!state.marriagePartner(target.sourceCharacterIdentity()).isBlank()) {
            sendEncrypted(Protocol.messageCode(658),
                    "S_MESSAGE_CODE marriage-target-already-married=658 target="
                            + target.playerName());
            return;
        }
        CharacterSummary proposerCharacter = selectedCharacterSummary();
        CharacterSummary targetCharacter = target.selectedCharacterSummary();
        if (proposerCharacter == null || targetCharacter == null) return;
        if (proposerCharacter.sex() == targetCharacter.sex()) {
            sendEncrypted(Protocol.messageCode(661),
                    "S_MESSAGE_CODE marriage-same-sex=661 target=" + target.playerName());
            return;
        }

        hub.cancelPendingPlayerTradePrompt(target);
        target.clearPendingAskCallbacks();
        target.pendingMarriageProposal = new PendingMarriageProposal(
                this, currentRoomId, System.nanoTime() + MARRIAGE_ANSWER_TIMEOUT_NANOS);
        target.sendEncrypted(Protocol.marriageProposalAsk(playerName()),
                "S_ASK question=654 marriage-proposer=" + playerName());
        System.out.println("[LiTo] C_MARRIAGE propose pending proposer=" + playerName()
                + " target=" + target.playerName());
    }

    private void answerMarriageProposal(Protocol.AskAnswer answer) throws IOException {
        PendingMarriageProposal pending = pendingMarriageProposal;
        pendingMarriageProposal = null;
        if (pending == null || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER rejected question=654 player=" + playerName()
                    + " result=pending-marriage-unavailable-or-nonempty-tail");
            return;
        }
        ClientSession proposer = pending.proposer();
        if (answer.answer() == 0) {
            if (proposer != null) {
                proposer.sendEncrypted(Protocol.messageCode(656, playerName()),
                        "S_MESSAGE_CODE marriage-refused=656 target=" + playerName());
            }
            System.out.println("[LiTo] C_ANSWER question=654 refused proposer="
                    + (proposer == null ? "" : proposer.playerName())
                    + " target=" + playerName());
            return;
        }

        long now = System.nanoTime();
        CharacterSummary proposerCharacter = proposer == null
                ? null : proposer.selectedCharacterSummary();
        CharacterSummary targetCharacter = selectedCharacterSummary();
        boolean validState = proposer != null && now - pending.expiresAtNanos() < 0
                && pending.roomId() == currentRoomId
                && proposer.currentRoomId == currentRoomId
                && classicMarriageEligible() && proposer.classicMarriageEligible()
                && hub.roomCombatants(currentRoomId).contains(proposer)
                && proposer.faceToFaceCombatant() == this
                && (playerHeading & 7) == ((proposer.playerHeading + 4) & 7)
                && proposerCharacter != null && targetCharacter != null
                && proposerCharacter.sex() != targetCharacter.sex();
        if (!validState) {
            System.out.println("[LiTo] C_ANSWER rejected question=654 target=" + playerName()
                    + " result=state-mismatch-or-expired");
            return;
        }

        if (!proposer.usesClassicSource(selectedClassicServerName)) {
            System.out.println("[LiTo] C_ANSWER rejected question=654 proposer="
                    + proposer.playerName() + " target=" + playerName()
                    + " result=cross-source-marriage");
            return;
        }
        RepositoryMarriageMutation sqlResult;
        try {
            sqlResult = proposer.selectedSourceAccounts().persistMarriage(
                    proposerCharacter.objectId(), targetCharacter.objectId());
        } catch (Exception failure) {
            throw new IOException("cannot persist selected-source marriage", failure);
        }
        if (sqlResult.status() != RepositoryMarriageMutationStatus.UNAVAILABLE) {
            if (sqlResult.succeeded()) {
                state.reconcileSqlMarriage(proposer.sourceCharacterIdentity(),
                        sourceCharacterIdentity());
                sendMarriageSuccess(proposer);
            } else if (sqlResult.status()
                    == RepositoryMarriageMutationStatus.ALREADY_MARRIED) {
                boolean proposerMarried = sqlResult.first().married();
                proposer.sendEncrypted(Protocol.messageCode(proposerMarried ? 657 : 658),
                        "S_MESSAGE_CODE marriage-race-sql-married="
                                + (proposerMarried ? 657 : 658)
                                + " proposer=" + proposer.playerName()
                                + " target=" + playerName());
            } else {
                proposer.sendEncrypted(Protocol.messageCode(79),
                        "S_MESSAGE_CODE marriage-sql-persistence-rejected=79 status="
                                + sqlResult.status());
            }
            System.out.println("[LiTo] C_ANSWER question=654 proposer="
                    + proposer.playerName() + " target=" + playerName()
                    + " sql-result=" + sqlResult.status());
            return;
        }

        GameStateStore.MarriageMutation result = state.marry(
                proposer.sourceCharacterIdentity(), sourceCharacterIdentity());
        switch (result.status()) {
            case MARRIED -> sendMarriageSuccess(proposer);
            case FIRST_ALREADY_MARRIED -> proposer.sendEncrypted(Protocol.messageCode(657),
                    "S_MESSAGE_CODE marriage-race-proposer-married=657 player="
                            + proposer.playerName());
            case SECOND_ALREADY_MARRIED -> proposer.sendEncrypted(Protocol.messageCode(658),
                    "S_MESSAGE_CODE marriage-race-target-married=658 target=" + playerName());
            case INVALID -> {
                System.out.println("[LiTo] C_ANSWER rejected question=654 proposer="
                        + proposer.playerName() + " target=" + playerName()
                        + " result=invalid-marriage-transition");
                return;
            }
        }
        System.out.println("[LiTo] C_ANSWER question=654 proposer=" + proposer.playerName()
                + " target=" + playerName() + " result=" + result.status());
    }

    private void sendMarriageSuccess(ClientSession proposer) throws IOException {
        IOException firstError = null;
        try {
            proposer.sendEncrypted(Protocol.marriedEvent(),
                    "S_EVENT subtype=9 married partner=" + playerName());
            proposer.sendEncrypted(Protocol.messageCode(655, playerName()),
                    "S_MESSAGE_CODE marriage-accepted=655 partner=" + playerName());
        } catch (IOException error) {
            firstError = error;
        }
        try {
            sendEncrypted(Protocol.marriedEvent(),
                    "S_EVENT subtype=9 married partner=" + proposer.playerName());
            sendEncrypted(Protocol.messageCode(655, proposer.playerName()),
                    "S_MESSAGE_CODE marriage-accepted=655 partner=" + proposer.playerName());
        } catch (IOException error) {
            if (firstError == null) firstError = error;
        }
        if (firstError != null) throw firstError;
    }

    private void requestDivorce() throws IOException {
        if (!classicMarriageEligible()) {
            System.out.println("[LiTo] C_MARRIAGE divorce ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        String partner = state.marriagePartner(stateCharacter());
        String partnerIdentity = state.marriagePartnerIdentity(stateCharacter());
        if (partner.isBlank() || partnerIdentity.isBlank()) {
            sendEncrypted(Protocol.messageCode(662),
                    "S_MESSAGE_CODE marriage-not-married=662 player=" + playerName());
            return;
        }
        hub.cancelPendingPlayerTradePrompt(this);
        clearPendingAskCallbacks();
        pendingDivorce = new PendingDivorce(partner, partnerIdentity, currentRoomId,
                System.nanoTime() + MARRIAGE_ANSWER_TIMEOUT_NANOS);
        sendEncrypted(Protocol.marriageDivorceAsk(),
                "S_ASK question=653 divorce partner=" + partner);
        System.out.println("[LiTo] C_MARRIAGE divorce pending player=" + playerName()
                + " partner=" + partner);
    }

    private void answerDivorce(Protocol.AskAnswer answer) throws IOException {
        PendingDivorce pending = pendingDivorce;
        pendingDivorce = null;
        if (pending == null || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER rejected question=653 player=" + playerName()
                    + " result=pending-divorce-unavailable-or-nonempty-tail");
            return;
        }
        if (answer.answer() == 0) {
            System.out.println("[LiTo] C_ANSWER question=653 divorce-cancelled player="
                    + playerName());
            return;
        }
        long now = System.nanoTime();
        if (now - pending.expiresAtNanos() >= 0 || pending.roomId() != currentRoomId
                || !classicMarriageEligible()) {
            System.out.println("[LiTo] C_ANSWER rejected question=653 player=" + playerName()
                    + " result=state-mismatch-or-expired");
            return;
        }
        String divorcedPartner;
        CharacterSummary selected = selectedCharacterSummary();
        if (selected == null) return;
        RepositoryMarriageState sqlMarriage;
        try {
            sqlMarriage = selectedSourceAccounts().marriage(selected.objectId());
        } catch (Exception failure) {
            throw new IOException("cannot reload selected-source marriage", failure);
        }
        if (sqlMarriage.authoritative()) {
            if (!sqlMarriage.married()
                    || !sqlMarriage.partnerName().equalsIgnoreCase(pending.partnerName())) {
                sendEncrypted(Protocol.messageCode(79),
                        "S_MESSAGE_CODE divorce-sql-stale=79 player=" + playerName());
                System.out.println("[LiTo] C_ANSWER rejected question=653 player="
                        + playerName() + " result=sql-stale-partner");
                return;
            }
            RepositoryMarriageMutation sqlResult;
            try {
                sqlResult = selectedSourceAccounts().persistDivorce(
                        selected.objectId(), sqlMarriage.partnerObjectId());
            } catch (Exception failure) {
                throw new IOException("cannot persist selected-source divorce", failure);
            }
            if (!sqlResult.succeeded()) {
                sendEncrypted(Protocol.messageCode(79),
                        "S_MESSAGE_CODE divorce-sql-persistence-rejected=79 status="
                                + sqlResult.status());
                System.out.println("[LiTo] C_ANSWER rejected question=653 player="
                        + playerName() + " sql-result=" + sqlResult.status());
                return;
            }
            state.reconcileSqlMarriage(stateCharacter(), "");
            divorcedPartner = pending.partnerName();
        } else {
            GameStateStore.DivorceMutation result = state.divorce(
                    stateCharacter(), pending.partnerIdentity());
            if (!result.divorced()) {
                System.out.println("[LiTo] C_ANSWER rejected question=653 player="
                        + playerName() + " result=stale-partner");
                return;
            }
            divorcedPartner = result.partner();
        }
        sendEncrypted(Protocol.messageCode(662),
                "S_MESSAGE_CODE marriage-divorced=662 player=" + playerName());
        for (ClientSession partner : hub.onlineCharacterSessions(
                this, List.of(divorcedPartner))) {
            if (partner == this) continue;
            partner.sendEncrypted(Protocol.messageCode(662),
                    "S_MESSAGE_CODE marriage-divorced=662 player=" + partner.playerName());
        }
        System.out.println("[LiTo] C_ANSWER question=653 divorced player=" + playerName()
                + " partner=" + divorcedPartner);
    }

    private boolean classicMarriageEligible() {
        return phase == Phase.BATTLE && currentRoomId != 0 && !observer && playerHp > 0
                && pendingPortal == null && playerObjectId() != 0;
    }

    private void inviteClassicParty(byte[] payload) throws IOException {
        Protocol.requireClassicPartyOpcodeOnly(payload, Protocol.C_INVITE_PARTY);
        if (!classicPartyEligible()) {
            System.out.println("[LiTo] C_INVITE_PARTY ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        ClientSession target = faceToFaceCombatant();
        if (target == null || (target.playerHeading & 7) != ((playerHeading + 4) & 7)
                || !target.classicPartyEligible() || target.invisible) {
            System.out.println("[LiTo] C_INVITE_PARTY rejected inviter=" + playerName()
                    + " result=no-valid-face-target");
            return;
        }

        GameHub.ClassicPartyData targetParty = hub.classicPartyData(
                target.sourceCharacterIdentity());
        if (targetParty.inParty()) {
            sendEncrypted(Protocol.messageCode(415),
                    "S_MESSAGE_CODE party-target-already-member=415 target="
                            + target.playerName());
            return;
        }
        GameHub.ClassicPartyData inviterParty = hub.classicPartyData(sourceCharacterIdentity());
        if (inviterParty.inParty()
                && !inviterParty.leader().equalsIgnoreCase(playerName())) {
            sendEncrypted(Protocol.messageCode(416),
                    "S_MESSAGE_CODE party-inviter-not-leader=416 player=" + playerName());
            return;
        }
        if (inviterParty.members().size() >= CLASSIC_PARTY_CAPACITY) {
            sendEncrypted(Protocol.messageCode(417),
                    "S_MESSAGE_CODE party-full=417 leader=" + playerName());
            return;
        }

        // The native client owns one generic S_ASK callback. A party prompt
        // supersedes only unopened prompts on the invitee.
        hub.cancelPendingPlayerTradePrompt(target);
        target.clearPendingAskCallbacks();
        target.pendingPartyInvite = new PendingPartyInvite(this, currentRoomId,
                System.nanoTime() + PARTY_INVITE_TIMEOUT_NANOS);
        target.sendEncrypted(Protocol.partyInviteAsk(playerName()),
                "S_ASK question=953 party-inviter=" + playerName());
        System.out.println("[LiTo] C_INVITE_PARTY pending inviter=" + playerName()
                + " invitee=" + target.playerName());
    }

    private void answerClassicPartyInvite(Protocol.AskAnswer answer) throws IOException {
        PendingPartyInvite pending = pendingPartyInvite;
        pendingPartyInvite = null;
        if (pending == null || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER rejected question=953 player=" + playerName()
                    + " result=pending-party-invite-unavailable-or-nonempty-tail");
            return;
        }
        ClientSession inviter = pending.inviter();
        if (answer.answer() == 0) {
            if (inviter != null) {
                inviter.sendEncrypted(Protocol.messageCode(423, playerName()),
                        "S_MESSAGE_CODE party-invite-refused=423 invitee=" + playerName());
            }
            System.out.println("[LiTo] C_ANSWER question=953 refused inviter="
                    + (inviter == null ? "" : inviter.playerName()) + " invitee=" + playerName());
            return;
        }

        long now = System.nanoTime();
        boolean validState = inviter != null && now - pending.expiresAtNanos() < 0
                && pending.roomId() == currentRoomId && inviter.currentRoomId == currentRoomId
                && classicPartyEligible() && inviter.classicPartyEligible()
                && hub.roomCombatants(currentRoomId).contains(inviter);
        if (!validState) {
            System.out.println("[LiTo] C_ANSWER rejected question=953 invitee=" + playerName()
                    + " result=state-mismatch-or-expired");
            return;
        }

        GameHub.ClassicPartyJoinResult joined = hub.joinClassicParty(
                inviter.sourceCharacterIdentity(), sourceCharacterIdentity(),
                CLASSIC_PARTY_CAPACITY);
        switch (joined.status()) {
            case JOINED -> {
                inviter.classicPartyParticipant = true;
                classicPartyParticipant = true;
                inviter.sendEncrypted(Protocol.messageCode(424, playerName()),
                        "S_MESSAGE_CODE party-member-joined=424 invitee=" + playerName());
            }
            case ALREADY_MEMBER -> inviter.sendEncrypted(Protocol.messageCode(415),
                    "S_MESSAGE_CODE party-target-already-member=415 invitee=" + playerName());
            case NOT_LEADER -> inviter.sendEncrypted(Protocol.messageCode(416),
                    "S_MESSAGE_CODE party-inviter-not-leader=416 player="
                            + inviter.playerName());
            case FULL -> inviter.sendEncrypted(Protocol.messageCode(417),
                    "S_MESSAGE_CODE party-full=417 leader=" + inviter.playerName());
            case INVALID -> {
                System.out.println("[LiTo] C_ANSWER rejected question=953 inviter="
                        + inviter.playerName() + " invitee=" + playerName()
                        + " result=join-race-invalid");
                return;
            }
        }
        System.out.println("[LiTo] C_ANSWER question=953 inviter=" + inviter.playerName()
                + " invitee=" + playerName() + " result=" + joined.status()
                + " members=" + joined.party().members());
    }

    private void showClassicParty(byte[] payload) throws IOException {
        Protocol.requireClassicPartyOpcodeOnly(payload, Protocol.C_WHO_PARTY);
        if (!classicPartyEligible()) return;
        GameHub.ClassicPartyData party = hub.classicPartyData(sourceCharacterIdentity());
        if (!party.inParty()) {
            sendEncrypted(Protocol.messageCode(425),
                    "S_MESSAGE_CODE party-unavailable=425 player=" + playerName());
            return;
        }
        sendEncrypted(Protocol.partyList(playerObjectId(), party.leader(), party.members()),
                "S_HYPERTEXT html=party leader=" + party.leader()
                        + " members=" + party.members());
    }

    private void leaveClassicParty(byte[] payload) throws IOException {
        Protocol.requireClassicPartyOpcodeOnly(payload, Protocol.C_LEAVE_PARTY);
        if (!classicPartyEligible()) return;
        leaveClassicParty("command", true);
    }

    private void leaveClassicParty(String reason, boolean notifySelf) throws IOException {
        GameHub.ClassicPartyRemoveResult outcome = hub.leaveClassicParty(
                sourceCharacterIdentity());
        if (outcome.status() == GameHub.ClassicPartyRemoveStatus.NOT_MEMBER) {
            classicPartyParticipant = false;
            if (notifySelf) {
                sendEncrypted(Protocol.messageCode(425),
                        "S_MESSAGE_CODE party-unavailable=425 player=" + playerName());
            }
            return;
        }
        List<ClientSession> recipients = partyRecipients(outcome.before(), notifySelf);
        classicPartyParticipant = false;
        if (outcome.status() == GameHub.ClassicPartyRemoveStatus.LEFT_AND_DISBANDED
                || outcome.status() == GameHub.ClassicPartyRemoveStatus.LEADER_DISBANDED) {
            recipients.forEach(recipient -> recipient.classicPartyParticipant = false);
        }
        switch (outcome.status()) {
            case LEFT -> sendPartyMessage(recipients, 420,
                    "party-member-left=420 reason=" + reason, outcome.removedName());
            case LEFT_AND_DISBANDED -> {
                sendPartyMessage(recipients, 420,
                        "party-member-left=420 reason=" + reason, outcome.removedName());
                sendPartyMessage(recipients, 418,
                        "party-disbanded=418 reason=" + reason);
            }
            case LEADER_DISBANDED -> sendPartyMessage(recipients, 418,
                    "party-disbanded=418 reason=" + reason);
            default -> throw new IllegalStateException(
                    "unexpected leave-party result " + outcome.status());
        }
        System.out.println("[LiTo] C_LEAVE_PARTY player=" + playerName()
                + " reason=" + reason + " result=" + outcome.status());
    }

    private void banishClassicParty(byte[] payload) throws IOException {
        String requestedName = Protocol.partyBanishRequest(payload);
        if (!classicPartyEligible()) return;
        GameHub.ClassicPartyRemoveResult outcome = hub.kickClassicParty(
                sourceCharacterIdentity(), requestedName);
        switch (outcome.status()) {
            case NOT_MEMBER -> sendEncrypted(Protocol.messageCode(425),
                    "S_MESSAGE_CODE party-unavailable=425 player=" + playerName());
            case NOT_LEADER -> sendEncrypted(Protocol.messageCode(427),
                    "S_MESSAGE_CODE party-banish-not-leader=427 player=" + playerName());
            case TARGET_NOT_FOUND -> sendEncrypted(Protocol.messageCode(426, requestedName),
                    "S_MESSAGE_CODE party-member-not-found=426 target=" + requestedName);
            case KICKED, KICKED_AND_DISBANDED -> {
                List<ClientSession> recipients = partyRecipients(outcome.before(), true);
                List<ClientSession> kicked = recipients.stream()
                        .filter(session -> session.sourceCharacterIdentity()
                                .equalsIgnoreCase(outcome.removedIdentity()))
                        .toList();
                kicked.forEach(session -> session.classicPartyParticipant = false);
                if (outcome.status() == GameHub.ClassicPartyRemoveStatus.KICKED_AND_DISBANDED) {
                    recipients.forEach(recipient -> recipient.classicPartyParticipant = false);
                }
                sendPartyMessage(recipients, 420,
                        "party-member-left=420 reason=banish", outcome.removedName());
                if (outcome.status() == GameHub.ClassicPartyRemoveStatus.KICKED_AND_DISBANDED) {
                    sendPartyMessage(recipients, 418,
                            "party-disbanded=418 reason=banish");
                }
                sendPartyMessage(kicked, 419,
                        "party-member-kicked=419 leader=" + playerName());
            }
            default -> throw new IllegalStateException(
                    "unexpected banish-party result " + outcome.status());
        }
        System.out.println("[LiTo] C_BANISH_PARTY leader=" + playerName()
                + " target=" + requestedName + " result=" + outcome.status());
    }

    private List<ClientSession> partyRecipients(GameHub.ClassicPartyData before,
                                                boolean notifySelf) {
        return hub.onlineCharacterSessionsByIdentity(before.memberIdentities()).stream()
                .filter(recipient -> notifySelf || recipient != this)
                .toList();
    }

    private void sendPartyMessage(List<ClientSession> recipients, int code,
                                  String note, String... arguments) throws IOException {
        byte[] packet = Protocol.messageCode(code, arguments);
        IOException firstError = null;
        for (ClientSession recipient : recipients) {
            try {
                recipient.sendEncrypted(packet,
                        "S_MESSAGE_CODE " + note + " recipient=" + recipient.playerName());
            } catch (IOException error) {
                if (firstError == null) firstError = error;
            }
        }
        if (firstError != null) throw firstError;
    }

    private ClientSession faceToFaceCombatant() {
        int[] headingX = {0, 1, 1, 1, 0, -1, -1, -1};
        int[] headingY = {-1, -1, 0, 1, 1, 1, 0, -1};
        int targetX = positionX + headingX[playerHeading & 7];
        int targetY = positionY + headingY[playerHeading & 7];
        return hub.roomCombatants(currentRoomId).stream()
                .filter(candidate -> candidate != this && candidate.positionX == targetX
                        && candidate.positionY == targetY)
                .findFirst().orElse(null);
    }

    private boolean classicClanEligible() {
        return phase == Phase.BATTLE && currentRoomId != 0 && !observer && playerHp > 0
                && pendingPortal == null && playerObjectId() != 0;
    }

    private boolean classicCastleClanEligible() {
        return phase == Phase.WORLD && !observer && playerHp > 0
                && pendingPortal == null && playerObjectId() != 0;
    }

    private boolean classicPartyEligible() {
        return phase == Phase.BATTLE && currentRoomId != 0 && !observer && playerHp > 0
                && pendingPortal == null && playerObjectId() != 0;
    }

    private int classicClanCapacity() {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return 0;
        // The read-only source uses the non-quest branch: level 50+ => CHA*3,
        // otherwise CHA*2. No trusted quest-completion field is imported.
        int multiplier = character.level() >= 50 ? 3 : 2;
        return Math.max(0, character.charisma()) * multiplier;
    }

    private void publishClassicClanIdentity(ClientSession actor, String clanName, String reason)
            throws IOException {
        long emblemId = hub.clanEmblemId(actor.sourceCharacterIdentity());
        actor.sendEncrypted(Protocol.pledgeMetadata(
                        actor.playerObjectId(), clanName, actor.classicTitle, emblemId),
                "S_PLEDGE object=" + actor.playerObjectId() + " clan=" + clanName
                        + " emblem=" + emblemId + " reason=" + reason);
        byte[] metadata = Protocol.battleClanMetadata(actor.playerObjectId(), 0, clanName, true);
        for (ClientSession recipient : hub.roomMembers(actor.currentRoomId)) {
            if (actor.invisible && recipient != actor) continue;
            recipient.sendEncrypted(metadata,
                    "S_LITO_CLAN object=" + actor.playerObjectId() + " clan=" + clanName
                            + " reason=" + reason);
        }
    }

    private void publishClanRoster(GameHub.ClanData clan, String reason) throws IOException {
        byte[] roster = Protocol.clanInfo(clan);
        List<ClientSession> recipients = hub.clanSessions(sourceCharacterIdentity());
        if (recipients.isEmpty()) recipients = List.of(this);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(roster,
                    "S_LITO_CLAN_INFO clan=" + clan.name() + " members="
                            + clan.members().size() + " reason=" + reason);
        }
    }

    private void sendClanInfo() throws IOException {
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        sendEncrypted(Protocol.clanInfo(clan), "S_LITO_CLAN_INFO clan=" + clan.name()
                + " members=" + clan.members().size());
    }

    private void requestPledgeMetadata(byte[] payload) throws IOException {
        Protocol.requireWhoPledge(payload);
        if (phase != Phase.BATTLE || observer || currentRoomId == 0 || playerObjectId() == 0) {
            System.out.println("[LiTo] C_WHO_PLEDGE ignored outside active player world player="
                    + playerName() + " phase=" + phase + " observer=" + observer);
            return;
        }
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        if (clan.name().isBlank()) {
            sendEncrypted(Protocol.messageCode(1064),
                    "S_MESSAGE_CODE pledge-unavailable=1064 player=" + playerName());
            return;
        }
        long emblemId = hub.clanEmblemId(sourceCharacterIdentity());
        sendEncrypted(Protocol.pledgeMetadata(
                        playerObjectId(), clan.name(), classicTitle, emblemId),
                "S_PLEDGE object=" + playerObjectId() + " clan=" + clan.name()
                        + " title=" + classicTitle + " emblem=" + emblemId);
    }

    private void requestClanEmblem(byte[] payload) throws IOException {
        long emblemId = Protocol.emblemRequest(payload);
        if (selectedCharacter.isBlank()) {
            System.out.println("[LiTo] C_EMBLEM ignored before character selection id="
                    + emblemId);
            return;
        }
        byte[] pixels = hub.clanEmblem(emblemId);
        if (pixels == null) {
            // Same-family C_Clan returns without a packet when the identity is
            // stale or unknown. The native client keeps the request uncached.
            System.out.println("[LiTo] C_EMBLEM unknown id=" + emblemId
                    + " player=" + playerName());
            return;
        }
        sendEncrypted(Protocol.emblem(emblemId, pixels),
                "S_EMBLEM id=" + emblemId + " bytes=" + pixels.length);
    }

    private void listBoardTopics(byte[] payload) throws IOException {
        Protocol.BoardPageRequest request = Protocol.boardPageRequest(payload);
        if (!classicBoardEligible()) {
            System.out.println("[LiTo] C_BOARD_LIST ignored outside active player world player="
                    + playerName() + " phase=" + phase);
            return;
        }
        activeBoardObjectId = request.boardObjectId();
        activeBoardRoomId = currentRoomId;
        List<GameStateStore.BoardTopic> topics;
        try {
            RepositoryBoardSnapshot snapshot = selectedSourceAccounts()
                    .boardTopicsBefore(request.cursor(), Protocol.BOARD_PAGE_SIZE);
            if (snapshot.authoritative()) {
                topics = snapshot.topics();
            } else {
                if ("lito_mysql".equals(config.databaseMode())) {
                    throw new IOException("selected LiTo board snapshot is unavailable");
                }
                topics = state.boardTopicsBefore(selectedClassicServerName,
                        request.cursor(), Protocol.BOARD_PAGE_SIZE);
            }
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot load selected-source LiTo board page", failure);
        }
        sendEncrypted(Protocol.boardList(request.boardObjectId(), request.cursor(),
                        CLASSIC_BOARD_NAME, Protocol.BOARD_WRITE_FEE, topics),
                "S_BOARD_LIST object=" + request.boardObjectId()
                        + " cursor=" + request.cursor() + " count=" + topics.size());
    }

    private void readBoardTopic(byte[] payload) throws IOException {
        Protocol.BoardReadRequest request = Protocol.boardReadRequest(payload);
        if (!classicBoardEligible() || request.boardObjectId() != activeBoardObjectId
                || activeBoardRoomId != currentRoomId) {
            System.out.println("[LiTo] C_BOARD_READ rejected inactive board object="
                    + request.boardObjectId() + " topic=" + request.topicId());
            return;
        }
        GameStateStore.BoardTopic topic;
        try {
            RepositoryBoardLookup lookup = selectedSourceAccounts()
                    .boardTopic(request.topicId());
            if (lookup.authoritative()) {
                topic = lookup.topic();
            } else {
                if ("lito_mysql".equals(config.databaseMode())) {
                    throw new IOException("selected LiTo board topic is unavailable");
                }
                topic = state.boardTopic(selectedClassicServerName, request.topicId());
            }
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot load selected-source LiTo board topic", failure);
        }
        if (topic == null) {
            // Same-family handlers keep a missing/stale topic silent.  There
            // is no proven LiTo-specific board-error response for this path.
            System.out.println("[LiTo] C_BOARD_READ unknown topic=" + request.topicId()
                    + " player=" + playerName());
            return;
        }
        sendEncrypted(Protocol.boardRead(topic),
                "S_BOARD_READ object=" + request.boardObjectId()
                        + " topic=" + request.topicId());
    }

    private void deleteBoardTopic(byte[] payload) throws IOException {
        Protocol.BoardDeleteRequest request = Protocol.boardDeleteRequest(payload);
        if (!classicBoardEligible() || request.boardObjectId() != activeBoardObjectId
                || activeBoardRoomId != currentRoomId) {
            System.out.println("[LiTo] C_BOARD_DELETE rejected inactive board object="
                    + request.boardObjectId() + " topic=" + request.topicId());
            return;
        }
        boolean deleted;
        try {
            AccountRepository repository = selectedSourceAccounts();
            RepositoryBoardLookup lookup = repository.boardTopic(request.topicId());
            if (lookup.authoritative()) {
                if (lookup.topic() == null) {
                    deleted = false;
                } else {
                    CharacterSummary selected = selectedCharacterSummary();
                    if (selected == null) return;
                    RepositoryBoardMutation mutation = repository.deleteBoardTopic(
                            selected.objectId(), lookup.topic());
                    deleted = mutation.status() == RepositoryBoardMutationStatus.SUCCESS;
                    System.out.println("[LiTo] SQL board delete status=" + mutation.status()
                            + " source=" + selectedClassicServerName
                            + " topic=" + request.topicId() + " author=" + playerName());
                }
            } else {
                if ("lito_mysql".equals(config.databaseMode())) {
                    throw new IOException("selected LiTo board topic is unavailable");
                }
                deleted = state.deleteBoardTopic(stateCharacter(), request.topicId());
            }
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot delete selected-source LiTo board topic", failure);
        }
        System.out.println("[LiTo] C_BOARD_DELETE topic=" + request.topicId()
                + " author=" + playerName() + " deleted=" + deleted);
        // The recovered callback removes the selected row from its local
        // vector immediately after sending C57; there is no paired S packet.
    }

    private void writeBoardTopic(byte[] payload) throws IOException {
        Protocol.BoardWriteRequest request = Protocol.boardWriteRequest(payload);
        if (!classicBoardEligible() || request.boardObjectId() != activeBoardObjectId
                || activeBoardRoomId != currentRoomId) {
            System.out.println("[LiTo] C_BOARD_WRITE rejected inactive board object="
                    + request.boardObjectId() + " player=" + playerName());
            return;
        }

        RuntimeInventory previousInventory = inventory;
        RuntimeInventory nextInventory = inventory.copy();
        if (!nextInventory.removeCatalog(InventoryCatalog.ADENA, Protocol.BOARD_WRITE_FEE)) {
            sendEncrypted(Protocol.messageCode(189),
                    "S_MESSAGE_CODE board-write-insufficient-adena=189 required="
                            + Protocol.BOARD_WRITE_FEE);
            return;
        }
        String date = LocalDate.now(CLASSIC_BOARD_ZONE).format(CLASSIC_BOARD_DATE);
        GameStateStore.BoardTopic topic;
        try {
            AccountRepository repository = selectedSourceAccounts();
            CharacterSummary selected = selectedCharacterSummary();
            if (selected == null) return;
            Map<Long, Long> localToSource = state.sourceInventoryBindings(
                    stateCharacter()).stream().collect(
                            java.util.stream.Collectors.toMap(
                                    GameStateStore.SourceInventoryBinding::localObjectId,
                                    GameStateStore.SourceInventoryBinding::sourceObjectId,
                                    (left, right) -> left, LinkedHashMap::new));
            RepositoryBoardMutation mutation = repository.postBoardTopic(
                    selected.objectId(), date, request.title(), request.content(),
                    previousInventory, nextInventory, localToSource);
            if (mutation.status() == RepositoryBoardMutationStatus.SUCCESS) {
                topic = mutation.topic();
                NativeDeItemApplication.replace(this, nextInventory, 0);
                // SQL is authoritative; this is only the local economy cache.
                state.saveEconomyState(stateCharacter(), shopPoints,
                        inventory.catalogCounts(), inventory.catalogItemStates());
            } else if (mutation.status() == RepositoryBoardMutationStatus.UNAVAILABLE) {
                if ("lito_mysql".equals(config.databaseMode())) {
                    throw new IOException("selected LiTo board persistence is unavailable");
                }
                topic = state.postBoardTopic(stateCharacter(), shopPoints,
                        nextInventory.catalogCounts(), date,
                        request.title(), request.content());
                NativeDeItemApplication.replace(this, nextInventory, 0);
            } else {
                System.out.println("[LiTo] SQL board post refused status="
                        + mutation.status() + " source=" + selectedClassicServerName
                        + " author=" + playerName());
                return;
            }
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot post selected-source LiTo board topic", failure);
        }
        sendInventoryDelta(previousInventory, inventory);
        System.out.println("[LiTo] C_BOARD_WRITE posted topic=" + topic.id()
                + " author=" + topic.author() + " object=" + request.boardObjectId()
                + " fee=" + Protocol.BOARD_WRITE_FEE);
    }

    private boolean classicBoardEligible() {
        return phase == Phase.BATTLE && !observer && currentRoomId != 0
                && playerHp > 0 && !selectedCharacter.isBlank();
    }

    private void listFixableItems(byte[] payload) throws IOException {
        Protocol.requireFixableItemRequest(payload);
        PendingRepairNpc context = validRepairContext(0);
        if (context == null) {
            System.out.println("[LiTo] C_FIXABLE_ITEM rejected missing/stale repair context player="
                    + playerName());
            return;
        }
        List<Protocol.RepairableItem> repairable = inventory.repairableWeapons().stream()
                .map(item -> new Protocol.RepairableItem(item.objectId(), item.durability()))
                .toList();
        sendEncrypted(Protocol.fixableItemList(REPAIR_UNIT_PRICE, repairable),
                "S_FIXABLE_ITEM_LIST npc=" + context.npcObjectId()
                        + " price=" + REPAIR_UNIT_PRICE + " count=" + repairable.size());
    }

    private void repairInventoryItem(byte[] payload) throws IOException {
        Protocol.RepairRequest request = Protocol.repairRequest(payload);
        PendingRepairNpc context = validRepairContext(request.npcObjectId());
        RuntimeInventory.Item item = inventory.item(request.inventoryObjectId());
        if (context == null || item == null || !item.definition().weapon()
                || item.durability() <= 0) {
            System.out.println("[LiTo] C_FIX rejected context-or-item item="
                    + request.inventoryObjectId() + " npc=" + request.npcObjectId()
                    + " player=" + playerName());
            return;
        }
        long cost = Math.multiplyExact((long) item.durability(), REPAIR_UNIT_PRICE);
        RuntimeInventory nextInventory = inventory.copy();
        if (!nextInventory.repairWeapon(item.objectId())) {
            throw new IllegalStateException("validated repair item could not be staged");
        }
        if (!nextInventory.removeCatalog(InventoryCatalog.ADENA, cost)) {
            sendEncrypted(Protocol.messageCode(189),
                    "S_MESSAGE_CODE repair-insufficient-adena=189 required=" + cost);
            return;
        }

        RuntimeInventory previousInventory = inventory;
        NativeDeItemApplication.replace(this, nextInventory, 0);
        try {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        } catch (IOException failure) {
            NativeDeItemApplication.replace(this, previousInventory, 0);
            throw failure;
        }
        sendInventoryDelta(previousInventory, inventory);
        sendEncrypted(Protocol.messageCode(464, item.definition().name()),
                "S_MESSAGE_CODE repair-complete=464 item=" + item.objectId()
                        + " damage=" + item.durability() + " cost=" + cost);
        RuntimeInventory.Item repaired = inventory.item(item.objectId());
        sendEncrypted(Protocol.changeInventoryDescriptionExtended(
                        repaired.objectId(), repaired.nativeViewName(), repaired.quantity(),
                        repaired.nativeStatusDetail()),
                "S_CHANGE_ITEM_DESC_EX repair-complete object=" + repaired.objectId()
                        + " count=" + repaired.quantity() + " durability=" + repaired.durability());
        System.out.println("[LiTo] C_FIX repaired item=" + item.objectId()
                + " catalog=" + item.definition().catalogId()
                + " damage=" + item.durability() + " cost=" + cost
                + " npc=" + context.npcObjectId());
    }

    private PendingRepairNpc validRepairContext(long requestedNpcObjectId) {
        PendingRepairNpc context = pendingRepairNpc;
        ArenaMapCatalog.Point npc = context == null ? null
                : activeRepairNpcPoint(context.npcObjectId());
        boolean valid = context != null
                && (phase == Phase.BATTLE || phase == Phase.WORLD) && !observer
                && playerHp > 0 && activeInteractionContext() != 0
                && context.phase() == phase
                && context.interactionContext() == activeInteractionContext()
                && (requestedNpcObjectId == 0 || requestedNpcObjectId == context.npcObjectId())
                && System.nanoTime() <= context.expiresAtNanos()
                && npc != null && repairNpcDistance(npc) <= 3;
        if (!valid) pendingRepairNpc = null;
        return valid ? context : null;
    }

    private void listBuyableSpells(byte[] payload) throws IOException {
        Protocol.SpellShopRequest request = Protocol.spellShopRequest(payload);
        pendingSpellMaterialShop = null;
        ArenaMapCatalog.Point npc = activeSpellShopNpcPoint(request.npcObjectId());
        boolean nativeTeacher = phase == Phase.WORLD;
        boolean valid = (phase == Phase.BATTLE || phase == Phase.WORLD)
                && !observer && playerHp > 0 && activeInteractionContext() != 0
                && npc != null && spellShopNpcDistance(npc) <= 5;
        if (!valid) {
            pendingSpellShop = null;
            System.out.println("[LiTo] C_BUYABLE_SPELL rejected context npc="
                    + request.npcObjectId() + " player=" + playerName());
            return;
        }
        CharacterSummary character = selectedCharacterSummary();
        List<Integer> available = nativeTeacher
                ? SpellShopCatalog.availableNativeTeacherWireSkillIds(character, learnedSkills)
                : SpellShopCatalog.availableWireSkillIds(character, learnedSkills);
        int basePrice = nativeTeacher
                ? SpellShopCatalog.nativeTeacherBasePrice(character)
                : SpellShopCatalog.BASE_PRICE;
        pendingSpellShop = new PendingSpellShop(request.npcObjectId(), phase,
                activeInteractionContext(), basePrice, nativeTeacher,
                System.nanoTime() + SPELL_SHOP_CONTEXT_TIMEOUT_NANOS,
                Set.copyOf(available));
        sendEncrypted(Protocol.buyableSpellList(
                        basePrice, available, request.npcObjectId()),
                "S_BUYABLE_SPELL_LIST npc=" + request.npcObjectId()
                        + " price=" + basePrice
                        + " count=" + available.size());
    }

    private void buySpells(byte[] payload) throws IOException {
        Protocol.SpellPurchaseRequest request = Protocol.spellPurchaseRequest(payload);
        PendingSpellShop context = validSpellShopContext();
        LinkedHashSet<Integer> requestedWireIds = new LinkedHashSet<>(request.wireSkillIds());
        List<Integer> currentAvailable = context != null && context.nativeTeacher()
                ? SpellShopCatalog.availableNativeTeacherWireSkillIds(
                        selectedCharacterSummary(), learnedSkills)
                : SpellShopCatalog.availableWireSkillIds(
                        selectedCharacterSummary(), learnedSkills);
        boolean valid = context != null
                && requestedWireIds.size() == request.wireSkillIds().size()
                && context.offeredWireSkillIds().containsAll(requestedWireIds)
                && currentAvailable.containsAll(requestedWireIds);
        if (!valid) {
            pendingSpellShop = null;
            System.out.println("[LiTo] C_BUY_SPELL rejected stale/forged rows="
                    + request.wireSkillIds() + " player=" + playerName());
            return;
        }

        long totalPrice = SpellShopCatalog.totalPrice(
                request.wireSkillIds(), context.basePrice());
        RuntimeInventory nextInventory = inventory.copy();
        if (!nextInventory.removeCatalog(InventoryCatalog.ADENA, totalPrice)) {
            sendEncrypted(Protocol.messageCode(189),
                    "S_MESSAGE_CODE spell-shop-insufficient-adena=189 required=" + totalPrice);
            return;
        }

        LinkedHashSet<Integer> newlyLearned = new LinkedHashSet<>();
        for (int wireSkillId : request.wireSkillIds()) newlyLearned.add(wireSkillId + 1);
        LinkedHashSet<Integer> nextPurchased = new LinkedHashSet<>(purchasedSkills);
        nextPurchased.addAll(newlyLearned);
        LinkedHashSet<Integer> nextLearned = new LinkedHashSet<>(learnedSkills);
        nextLearned.addAll(newlyLearned);

        RuntimeInventory previousInventory = inventory;
        state.saveSpellPurchase(stateCharacter(), shopPoints,
                nextInventory.catalogCounts(), nextPurchased);
        NativeDeItemApplication.replace(this, nextInventory, 0);
        purchasedSkills = Set.copyOf(nextPurchased);
        learnedSkills = Set.copyOf(nextLearned);
        pendingSpellShop = null;
        pendingSpellMaterialShop = null;
        pendingCastleAdmin = null;
        pendingMercenaryAdmin = null;
        pendingCastleSecurity = null;
        pendingHouseAuctionBid = null;
        clearPendingClassicList();
        sendInventoryDelta(previousInventory, inventory);
        sendEncrypted(Protocol.addSpells(Set.copyOf(newlyLearned)),
                "S_ADD_SPELL purchased-count=" + newlyLearned.size()
                        + " total-cost=" + totalPrice);
        byte[] effect = Protocol.effectObject(playerObjectId(), 224);
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            member.sendEncrypted(effect, "S_EFFECT learned-spell object=" + playerObjectId()
                    + " gfx=224");
        }
        System.out.println("[LiTo] C_BUY_SPELL accepted player=" + playerName()
                + " rows=" + request.wireSkillIds() + " cost=" + totalPrice
                + " learned-total=" + learnedSkills.size());
    }

