    private void persistArmorProtectionOnDisconnect() throws IOException {
        if (selectedCharacter.isBlank() || inventoryCharacter.isBlank()) return;
        BattleAbilityStatus.ArmorProtection active =
                abilityStatus.armorProtection(System.nanoTime());
        GameStateStore.TimedArmorProtection durable = active.skillId() != 0
                && active.remainingSeconds() > 0
                ? new GameStateStore.TimedArmorProtection(
                        active.skillId(), active.remainingSeconds())
                : GameStateStore.TimedArmorProtection.none();
        state.saveTimedArmorProtection(stateCharacter(), durable);
        System.out.println("[LiTo] persisted armor protection disconnect player="
                + playerName() + " skill=" + durable.skillId()
                + " remaining=" + durable.remainingSeconds());
    }

    private void clearDurableMovementBuff(String reason) throws IOException {
        activeMovementBuffSkillId = 0;
        if (!selectedCharacter.isBlank() && !inventoryCharacter.isBlank()) {
            state.saveTimedMovementBuff(
                    stateCharacter(), GameStateStore.TimedMovementBuff.none());
        }
        System.out.println("[LiTo] cleared durable movement buff player="
                + playerName() + " reason=" + reason);
    }

    private void getRentalHotelGroundKey(Protocol.GroundPickup groundPickup) throws IOException {
        long l = this.rentalHotelGroundInstanceToken();
        RentalTownHotelRegistry.GroundItem groundItem = l < 0L ? null : this.hub.rentalHotelGroundKey(this.currentRoomId, this.rentalTownMapId, l, groundPickup.worldObjectId());
        long l2 = System.nanoTime();
        RentalTownHotelRegistry.Lease lease = groundItem == null ? null : this.hub.rentalHotelLeaseForInventory(List.of(groundItem.inventoryItem()), l2);
        RentalHotelLease rentalHotelLease = this.activeRentalHotelLease(l2);
        if (this.observer || this.playerHp <= 0 || this.invisible || this.rejectWhileParalyzed("C_GET rental-hotel-key") || groundItem == null || lease == null || rentalHotelLease != null && rentalHotelLease.token() != lease.token() || groundPickup.x() != Protocol.groundPickupWireX(groundItem.x()) || groundPickup.y() != groundItem.y() || groundPickup.quantity() != 1L || Math.max(Math.abs(this.positionX - groundItem.x()), Math.abs(this.positionY - groundItem.y())) > 3) {
            System.out.println("[LiTo] C_GET rental-hotel-key rejected object=" + groundPickup.worldObjectId() + " map=" + this.rentalTownMapId + " instance=" + l);
            return;
        }
        RuntimeInventory runtimeInventory = this.rentalTownInventory.copy();
        if (!runtimeInventory.addTransferred(groundItem.inventoryItem(), 1L)) {
            this.sendInventoryCapacityOver("rental-hotel-key-pickup");
            return;
        }
        RentalTownHotelRegistry.GroundItem groundItem2 = this.hub.takeRentalHotelGroundKey(this.currentRoomId, this.rentalTownMapId, l, groundItem.objectId());
        if (groundItem2 == null) {
            return;
        }
        RuntimeInventory runtimeInventory2 = this.rentalTownInventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 1);
        this.rentalHotelLease = ClientSession.localRentalHotelLease(lease);
        this.broadcastRentalHotelGroundRemoval(groundItem2, "key-pickup");
        this.sendInventoryDelta(runtimeInventory2, this.rentalTownInventory, false);
        System.out.println("[LiTo] C_GET rental-hotel-key accepted player=" + this.playerName() + " object=" + groundItem2.objectId() + " token=" + lease.token());
    }

    private void dropRentalHotelInventoryKey(Protocol.InventoryDrop inventoryDrop) throws IOException {
        RuntimeInventory.Item item = this.rentalTownInventory.item(inventoryDrop.inventoryObjectId());
        long l = System.nanoTime();
        RentalHotelLease rentalHotelLease = this.activeRentalHotelLease(l);
        long l2 = this.rentalHotelGroundInstanceToken();
        if (this.observer || this.playerHp <= 0 || this.rejectWhileParalyzed("C_DROP rental-hotel-key") || item == null || item.definition().catalogId() != 40312L || !item.transferable() || item.equipped() || inventoryDrop.quantity() != 1L || inventoryDrop.x() != this.positionX || inventoryDrop.y() != this.positionY || rentalHotelLease == null || l2 < 0L || !this.hub.rentalHotelInventoryOwnsCredential(rentalHotelLease.token(), List.of(item), l)) {
            System.out.println("[LiTo] C_DROP rental-hotel-key rejected object=" + inventoryDrop.inventoryObjectId() + " map=" + this.rentalTownMapId + " instance=" + l2);
            return;
        }
        RuntimeInventory runtimeInventory = this.rentalTownInventory.copy();
        if (!runtimeInventory.remove(item.objectId(), 1L)) {
            return;
        }
        RentalTownHotelRegistry.GroundItem groundItem = this.hub.putRentalHotelGroundKey(this.currentRoomId, this.rentalTownMapId, l2, item, inventoryDrop.x(), inventoryDrop.y(), l);
        if (groundItem == null) {
            return;
        }
        RuntimeInventory runtimeInventory2 = this.rentalTownInventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 1);
        this.sendInventoryDelta(runtimeInventory2, this.rentalTownInventory, false);
        this.broadcastRentalHotelGroundKey(groundItem, "key-drop");
        System.out.println("[LiTo] C_DROP rental-hotel-key accepted player=" + this.playerName() + " object=" + groundItem.objectId() + " token=" + rentalHotelLease.token());
    }

    private void sendRentalHotelGroundKeys(String reason) throws IOException {
        long instanceToken = rentalHotelGroundInstanceToken();
        if (instanceToken < 0) return;
        for (RentalTownHotelRegistry.GroundItem item
                : hub.rentalHotelGroundKeys(
                        currentRoomId, rentalTownMapId, instanceToken)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    positionX, positionY, item.x(), item.y())) {
                sendRentalHotelGroundKey(item, reason);
            }
        }
    }

    private void sendRentalHotelGroundKey(
            RentalTownHotelRegistry.GroundItem item, String reason)
            throws IOException {
        sendEncrypted(Protocol.groundItem(
                        item.objectId(), item.x(), item.y(),
                        item.definition().groundGfx(), 1, item.displayName()),
                "S_PUT_OBJECT rental-hotel-key=" + item.objectId()
                        + " token=" + item.instanceToken()
                        + " reason=" + reason);
    }

    private void broadcastRentalHotelGroundKey(
            RentalTownHotelRegistry.GroundItem item, String reason)
            throws IOException {
        for (ClientSession member : hub.connectedSessionsSnapshot()) {
            if (!member.rentalHotelGroundScopeMatches(item)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            item.x(), item.y())) continue;
            member.sendRentalHotelGroundKey(item, reason);
        }
    }

    private void broadcastRentalHotelGroundRemoval(
            RentalTownHotelRegistry.GroundItem item, String reason)
            throws IOException {
        byte[] removed = Protocol.removeObject(item.objectId());
        for (ClientSession member : hub.connectedSessionsSnapshot()) {
            if (!member.rentalHotelGroundScopeMatches(item)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            item.x(), item.y())) continue;
            member.sendEncrypted(removed,
                    "S_REMOVE_OBJECT rental-hotel-key=" + item.objectId()
                            + " reason=" + reason);
        }
    }

    private void updateRentalHotelGroundVisibility(
            int previousX, int previousY, int x, int y) throws IOException {
        long instanceToken = rentalHotelGroundInstanceToken();
        if (instanceToken < 0) return;
        for (RentalTownHotelRegistry.GroundItem item
                : hub.rentalHotelGroundKeys(
                        currentRoomId, rentalTownMapId, instanceToken)) {
            boolean before = BattleSpellCatalog.isInNativeScreen(
                    previousX, previousY, item.x(), item.y());
            boolean after = BattleSpellCatalog.isInNativeScreen(
                    x, y, item.x(), item.y());
            if (!before && after) {
                sendRentalHotelGroundKey(item, "movement-screen-enter");
            } else if (before && !after) {
                sendEncrypted(Protocol.removeObject(item.objectId()),
                        "S_REMOVE_OBJECT rental-hotel-key screen-exit="
                                + item.objectId());
            }
        }
    }

    private void getGroundItem(byte[] payload) throws IOException {
        Protocol.GroundPickup request = Protocol.groundPickup(payload);
        if (rentalTownRoomState && phase == Phase.BATTLE) {
            getRentalHotelGroundKey(request);
            return;
        }
        if (phase == Phase.WORLD) {
            getClassicWorldGroundItem(request);
            return;
        }
        if (phase != Phase.BATTLE || observer || playerHp <= 0
                || invisible || rejectWhileParalyzed("C_GET")) {
            System.out.printf("[LiTo] C_GET rejected invalid-state object=%d phase=%s observer=%s hp=%d invisible=%s%n",
                    request.worldObjectId(), phase, observer, playerHp, invisible);
            return;
        }
        BattleGroundItems.Item item = hub.groundItem(currentRoomId, request.worldObjectId());
        if (item == null
                || request.x() != Protocol.groundPickupWireX(item.x())
                || request.y() != item.y()
                || Math.max(Math.abs(positionX - item.x()), Math.abs(positionY - item.y())) > 3
                || (!item.definition().stackable() && request.quantity() != 1)) {
            System.out.printf("[LiTo] C_GET rejected stale-or-out-of-range object=%d wire-x=%d y=%d quantity=%d auxiliary=%d%n",
                    request.worldObjectId(), request.x(), request.y(), request.quantity(), request.auxiliary());
            return;
        }

        RuntimeInventory next = inventory.copy();
        if (!next.addGroundTransferred(item.inventoryItem(), request.quantity())) {
            sendInventoryCapacityOver("ground-pickup");
            System.out.printf("[LiTo] C_GET rejected capacity object=%d quantity=%d%n",
                    request.worldObjectId(), request.quantity());
            return;
        }
        if (!permitsInventoryAddition(inventory, item.definition(), request.quantity())) {
            sendInventoryWeightOver("ground-pickup");
            System.out.printf("[LiTo] C_GET rejected weight object=%d quantity=%d stage=%d%n",
                    request.worldObjectId(), request.quantity(),
                    currentWeight240(System.nanoTime()));
            return;
        }
        GameHub.GroundTake take = hub.takeGroundItemPersisted(
                currentRoomId, this, request.worldObjectId(), request.quantity(),
                () -> state.saveEconomyState(
                        stateCharacter(), shopPoints,
                        next.catalogCounts(), next.catalogItemStates()));
        if (take == null) {
            System.out.printf("[LiTo] C_GET rejected raced-ground-state object=%d quantity=%d%n",
                    request.worldObjectId(), request.quantity());
            return;
        }

        RuntimeInventory previous = inventory;
        NativeDeItemApplication.replace(this, next, 0);
        broadcastGroundTake(take, "player-pickup");
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(403, take.taken().displayName()),
                "S_MESSAGE_CODE battle-pickup=403 item="
                        + take.taken().displayName());
        broadcastLightState("C_GET-player");
        playerHeading = heading(positionX, positionY, item.x(), item.y());
        byte[] changed = new Protocol.Writer().c(Protocol.S_CHANGE_DIRECTION)
                .d(playerObjectId()).c(playerHeading).bytes();
        byte[] action = Protocol.objectAction(playerObjectId(), BattleActionCodes.PICKUP);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            if (member != this && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(changed,
                    "S_CHANGE_DIRECTION battle-pickup object="
                            + playerObjectId() + " heading=" + playerHeading);
            member.sendEncrypted(action,
                    "S_ACTION battle-pickup object=" + playerObjectId()
                            + " action=" + BattleActionCodes.PICKUP);
        }
        System.out.printf("[LiTo] C_GET accepted object=%d catalog=%d quantity=%d auxiliary=%d%n",
                take.taken().objectId(), take.taken().definition().catalogId(),
                take.taken().quantity(), request.auxiliary());
    }

    private void getClassicWorldGroundItem(Protocol.GroundPickup request)
            throws IOException {
        if (observer || playerHp <= 0 || invisible || rejectWhileParalyzed("C_GET")) {
            System.out.printf("[LiTo] C_GET WORLD rejected invalid-state object=%d phase=%s observer=%s hp=%d invisible=%s%n",
                    request.worldObjectId(), phase, observer, playerHp, invisible);
            return;
        }
        ClassicWorldGroundItems.Item item = hub.classicWorldGroundItem(
                classicWorldMapId, classicWorldInstanceId,
                request.worldObjectId());
        if (item == null
                || request.x() != Protocol.groundPickupWireX(item.x())
                || request.y() != item.y()
                || Math.max(Math.abs(positionX - item.x()),
                            Math.abs(positionY - item.y())) > 3
                || (!item.definition().stackable() && request.quantity() != 1)) {
            System.out.printf("[LiTo] C_GET WORLD rejected stale-or-out-of-range object=%d wire-x=%d y=%d quantity=%d auxiliary=%d%n",
                    request.worldObjectId(), request.x(), request.y(), request.quantity(),
                    request.auxiliary());
            return;
        }

        RuntimeInventory next = inventory.copy();
        if (!next.addGroundTransferred(item.inventoryItem(), request.quantity())) {
            sendInventoryCapacityOver("classic-world-ground-pickup");
            System.out.printf("[LiTo] C_GET WORLD rejected capacity object=%d quantity=%d%n",
                    request.worldObjectId(), request.quantity());
            return;
        }
        if (!permitsInventoryAddition(inventory, item.definition(), request.quantity())) {
            sendInventoryWeightOver("classic-world-ground-pickup");
            System.out.printf("[LiTo] C_GET WORLD rejected weight object=%d quantity=%d stage=%d%n",
                    request.worldObjectId(), request.quantity(),
                    currentWeight240(System.nanoTime()));
            return;
        }
        GameHub.ClassicGroundTake take = hub.takeClassicWorldGroundItemPersisted(
                classicWorldMapId, classicWorldInstanceId,
                request.worldObjectId(), request.quantity(),
                () -> state.saveEconomyState(
                        stateCharacter(), shopPoints,
                        next.catalogCounts(), next.catalogItemStates()));
        if (take == null) {
            System.out.printf("[LiTo] C_GET WORLD rejected raced-ground-state object=%d quantity=%d%n",
                    request.worldObjectId(), request.quantity());
            return;
        }

        RuntimeInventory previous = inventory;
        NativeDeItemApplication.replace(this, next, 0);
        broadcastClassicWorldGroundTake(take, "player-pickup");
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(403, take.taken().displayName()),
                "S_MESSAGE_CODE classic-world-pickup=403 item="
                        + take.taken().displayName());
        broadcastLightState("C_GET-player");
        playerHeading = heading(positionX, positionY, item.x(), item.y());
        hub.updateClassicWorld(this, classicWorldMapId,
                positionX, positionY, playerHeading);
        byte[] changed = new Protocol.Writer().c(Protocol.S_CHANGE_DIRECTION)
                .d(playerObjectId()).c(playerHeading).bytes();
        byte[] action = Protocol.objectAction(playerObjectId(), BattleActionCodes.PICKUP);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (member != this && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            if (invisible && member != this) continue;
            member.sendEncrypted(changed,
                    "S_CHANGE_DIRECTION classic-world-pickup object="
                            + playerObjectId() + " heading=" + playerHeading);
            member.sendEncrypted(action,
                    "S_ACTION classic-world-pickup object=" + playerObjectId()
                            + " action=" + BattleActionCodes.PICKUP);
        }
        System.out.printf("[LiTo] C_GET WORLD accepted object=%d catalog=%d quantity=%d auxiliary=%d%n",
                take.taken().objectId(), take.taken().definition().catalogId(),
                take.taken().quantity(), request.auxiliary());
    }

    private void dropInventoryItem(byte[] payload) throws IOException {
        Protocol.InventoryDrop request = Protocol.inventoryDrop(payload);
        if (rentalTownRoomState && phase == Phase.BATTLE) {
            dropRentalHotelInventoryKey(request);
            return;
        }
        RuntimeInventory.Item item = inventory.item(request.inventoryObjectId());
        String rejection = null;
        boolean classicWorld = phase == Phase.WORLD;
        if ((phase != Phase.BATTLE && !classicWorld) || observer || playerHp <= 0
                || (classicWorld && !ClassicWorldMapCatalog.supports(classicWorldMapId))) {
            rejection = "invalid-phase";
        }
        else if (rejectWhileParalyzed("C_DROP")) rejection = "fully-paralyzed";
        else if (item == null || request.quantity() > item.quantity()) rejection = "not-owned";
        else if (!NativePlayerDropCatalog.permits(
                config.nativePlayerDropEnabled(), isAdministrator(),
                item.definition().catalogId())) rejection = "drop-disabled";
        else if (!isAdministrator() && !item.transferable()) rejection = "not-tradable";
        else if (!isAdministrator() && item.timed()) rejection = "timed-item";
        else if (item.sourceBound()
                && (item.definition().weapon()
                    || item.definition().sourceArmor()
                    || item.definition().projectile())) rejection = "source-bound";
        else if (activePetCollar(item)) rejection = "active-pet-collar";
        else if (activeMagicDoll(item.objectId())) {
            rejection = "active-magic-doll";
        }
        else if (item.blocksNativeTransferAsEquipped()) rejection = "equipped";
        else if (item.sealed()) rejection = "sealed-item";
        else if (!item.definition().stackable() && request.quantity() != 1) rejection = "nonstackable-quantity";
        if (rejection != null) {
            if (rejection.equals("equipped") || rejection.equals("drop-disabled")) {
                sendEncrypted(Protocol.messageCode(125),
                        "S_MESSAGE_CODE C_DROP-" + rejection + "=125 object="
                                + request.inventoryObjectId());
            } else if (rejection.equals("active-magic-doll")) {
                sendEncrypted(Protocol.messageCode(1181),
                        "S_MESSAGE_CODE C_DROP-active-magic-doll=1181 object="
                                + request.inventoryObjectId());
            } else if ((rejection.equals("active-pet-collar")
                    || rejection.equals("not-tradable")
                    || rejection.equals("timed-item")
                    || rejection.equals("sealed-item")
                    || rejection.equals("source-bound")) && item != null) {
                sendEncrypted(Protocol.messageCode(210, item.nativeLogName()),
                        "S_MESSAGE_CODE C_DROP-" + rejection + "=210 item="
                                + item.definition().catalogId());
            }
            System.out.printf("[LiTo] C_DROP rejected reason=%s object=%d catalog=%s x=%d y=%d quantity=%d%n",
                    rejection, request.inventoryObjectId(),
                    item == null ? "none" : item.definition().catalogId(),
                    request.x(), request.y(), request.quantity());
            return;
        }

        RuntimeInventory next = inventory.copy();
        if (!next.remove(request.inventoryObjectId(), request.quantity())) {
            throw new IllegalStateException("validated C_DROP could not stage inventory removal");
        }
        BattleGroundItems.Item battleGround = null;
        ClassicWorldGroundItems.Item worldGround = null;
        DurableCommit commit = () -> state.saveEconomyState(
                stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        if (classicWorld) {
            worldGround = hub.putClassicWorldGroundItemPersisted(
                    classicWorldMapId, classicWorldInstanceId,
                    item, Math.toIntExact(request.quantity()),
                    request.x(), request.y(),
                    Math.toIntExact(playerObjectId()), commit);
        } else {
            battleGround = hub.putGroundItemPersisted(
                    currentRoomId, this, item, request.quantity(),
                    request.x(), request.y(), commit);
        }
        if (battleGround == null && worldGround == null) {
            System.out.printf("[LiTo] C_DROP rejected ground-state object=%d catalog=%d quantity=%d%n",
                    request.inventoryObjectId(), item.definition().catalogId(), request.quantity());
            return;
        }

        RuntimeInventory previous = inventory;
        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);
        if (classicWorld) {
            broadcastClassicWorldGroundItem(worldGround, "player-drop");
        } else {
            broadcastGroundItem(battleGround, "player-drop");
        }
        broadcastLightState("C_DROP-player");
        System.out.printf("[LiTo] C_DROP accepted inventory-object=%d ground-object=%d catalog=%d quantity=%d x=%d y=%d%n",
                request.inventoryObjectId(),
                classicWorld ? worldGround.objectId() : battleGround.objectId(),
                item.definition().catalogId(), request.quantity(), request.x(), request.y());
    }

    /** Runtime registration boundary used by the native magic-doll lifecycle. */
    boolean setNativeMagicDollActive(long inventoryObjectId, boolean active) {
        if (inventoryObjectId <= 0
                || active && inventory.item(inventoryObjectId) == null) {
            return false;
        }
        synchronized (activeMagicDollObjectIds) {
            return active ? activeMagicDollObjectIds.add(inventoryObjectId)
                    : activeMagicDollObjectIds.remove(inventoryObjectId);
        }
    }

    private boolean activeMagicDoll(long inventoryObjectId) {
        synchronized (activeMagicDollObjectIds) {
            return activeMagicDollObjectIds.contains(inventoryObjectId);
        }
    }

    /** Retained Magic_Doll executor: same item recalls, otherwise one active doll. */
    private void useNativeMagicDoll(RuntimeInventory.Item item) throws IOException {
        SourceMagicDollType type = sourceMagicDolls.get(item.objectId());
        if (type == null || type.itemId() != item.definition().catalogId()) {
            System.out.println("[LiTo] C_USE_ITEM magic-doll rejected missing source type object="
                    + item.objectId() + " catalog=" + item.definition().catalogId());
            return;
        }
        synchronized (activeMagicDollObjectIds) {
            if (activeMagicDoll != null
                    && activeMagicDoll.backingItemObjectId() == item.objectId()) {
                recallNativeMagicDollLocked("item-recall", true);
                return;
            }
            if ((phase != Phase.BATTLE && phase != Phase.WORLD)
                    || observer || playerHp <= 0 || activeMagicDoll != null) {
                if (activeMagicDoll != null) {
                    sendEncrypted(Protocol.messageCode(319),
                            "S_MESSAGE_CODE magic-doll-limit=319");
                }
                System.out.println("[LiTo] C_USE_ITEM magic-doll rejected phase=" + phase
                        + " observer=" + observer + " hp=" + playerHp
                        + " active=" + (activeMagicDoll != null));
                return;
            }
            Map<Long, Integer> available = inventory.catalogCounts();
            for (int index = 0; index < type.materialIds().size(); index++) {
                long materialId = type.materialIds().get(index);
                int required = type.materialCounts().get(index);
                if (available.getOrDefault(materialId, 0) < required) {
                    sendEncrypted(Protocol.messageCode(337),
                            "S_MESSAGE_CODE magic-doll-material-shortage=337 catalog="
                                    + materialId + " required=" + required);
                    return;
                }
            }

            RuntimeInventory previous = inventory;
            RuntimeInventory candidate = inventory.copy();
            for (int index = 0; index < type.materialIds().size(); index++) {
                if (!candidate.removeCatalog(type.materialIds().get(index),
                        type.materialCounts().get(index))) {
                    throw new IOException("validated magic-doll material debit failed");
                }
            }
            state.saveEconomyState(stateCharacter(), shopPoints,
                    candidate.catalogCounts(), candidate.catalogItemStates());
            long nowNanos = System.nanoTime();
            int mapId = phase == Phase.WORLD
                    ? classicWorldMapId : hub.battleMapId(currentRoomId, this);
            long instanceId = phase == Phase.WORLD
                    ? classicWorldInstanceId : currentRoomId;
            NativeMagicDoll summoned = NativeMagicDoll.summon(
                    item.objectId(), type, positionX, positionY,
                    mapId, instanceId, nowNanos);
            NativeMagicDollPowers summonedPowers =
                    NativeMagicDollPowers.from(type);
            NativeDeItemApplication.replace(this, candidate, 0);
            activeMagicDoll = summoned;
            magicDollPeriodicState = NativeMagicDollEffects.PeriodicState.from(
                    summonedPowers);
            magicDollAutoSkillIds = summonedPowers.autoSkillIds();
            nextMagicDollAutoSkillCheckNanos = Math.addExact(
                    nowNanos, TimeUnit.SECONDS.toNanos(10));
            activeMagicDollObjectIds.add(item.objectId());
            sendInventoryDelta(previous, inventory);
            broadcastNativeMagicDoll(summoned, true, "summon");
            applyNativeMagicDollStatusPowers(summonedPowers, true, "summon");
            sendNativeMagicDollIcon(summoned, nowNanos, false);
            maintainNativeMagicDollAutoSkills(nowNanos, "summon");
            sendEquipmentStatusRefresh("magic-doll-summon");
            System.out.println("[LiTo] C_USE_ITEM magic-doll summoned object="
                    + summoned.objectId() + " item-object=" + item.objectId()
                    + " catalog=" + type.itemId() + " gfx=" + type.gfxId()
                    + " duration=" + type.durationSeconds()
                    + " powers=" + type.powerIds());
        }
    }

    void serverMagicDollTick(long nowNanos) throws IOException {
        synchronized (activeMagicDollObjectIds) {
            if (activeMagicDoll == null) return;
            if (inventory.item(activeMagicDoll.backingItemObjectId()) == null
                    || activeMagicDoll.remainingSeconds(nowNanos) == 0) {
                recallNativeMagicDollLocked("timer-or-item-expiry", true);
                return;
            }
            List<NativeMagicDollEffects.PeriodicAward> awards =
                    magicDollPeriodicState.advance(
                            playerHp > 0 && playerHp < playerMaxHp,
                            playerHp > 0 && playerMp < playerMaxMp);
            for (NativeMagicDollEffects.PeriodicAward award : awards) {
                applyNativeMagicDollPeriodicAward(award);
            }
            if (!magicDollAutoSkillIds.isEmpty()
                    && nowNanos >= nextMagicDollAutoSkillCheckNanos) {
                nextMagicDollAutoSkillCheckNanos = Math.addExact(
                        nowNanos, TimeUnit.SECONDS.toNanos(10));
                maintainNativeMagicDollAutoSkills(nowNanos, "ten-second-check");
            }
        }
    }

    private void applyNativeMagicDollPeriodicAward(
            NativeMagicDollEffects.PeriodicAward award) throws IOException {
        switch (award.type()) {
            case HP -> {
                int before = playerHp;
                playerHp = Math.min(playerMaxHp,
                        Math.addExact(playerHp, award.amount()));
                if (playerHp == before) return;
                sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                                .h(playerHp).h(playerMaxHp).bytes(),
                        "S_HIT_POINT magic-doll-periodic=" + playerHp
                                + "/" + playerMaxHp);
                broadcastOwnHitRatio("magic-doll-periodic-hp");
            }
            case MP -> {
                int before = playerMp;
                playerMp = Math.min(playerMaxMp,
                        Math.addExact(playerMp, award.amount()));
                if (playerMp == before) return;
                sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                        "S_MANA_POINT magic-doll-periodic=" + playerMp
                                + "/" + playerMaxMp);
            }
            case ITEM -> grantNativeMagicDollPeriodicItem(
                    award.itemId(), award.itemCount());
        }
        System.out.println("[LiTo] magic-doll periodic player=" + playerName()
                + " type=" + award.type() + " amount=" + award.amount()
                + " item=" + award.itemId() + " count=" + award.itemCount());
    }

    private void grantNativeMagicDollPeriodicItem(int n, int n2) throws IOException {
        NativeDeItemPublication.grant(this, n, n2);
    }

