    private void publishNativeMagicDollAutoSkillEffect(
            int skillId, int effectGfx, String reason) throws IOException {
        if (effectGfx <= 0) return;
        NativeMagicDoll doll = activeMagicDoll;
        if (doll == null) return;
        byte[] effect = Protocol.effectObject(playerObjectId(), effectGfx);
        for (ClientSession viewer : nativeMagicDollRecipients(doll)) {
            viewer.sendEncrypted(effect,
                    "S_EFFECT magic-doll-auto skill=" + skillId
                            + " target=" + playerObjectId() + " gfx="
                            + effectGfx + " reason=" + reason);
        }
    }

