    private void recallNativeMagicDollLocked(String reason, boolean notifyOwner)
            throws IOException {
        NativeMagicDoll recalled = activeMagicDoll;
        if (recalled == null) return;
        NativeMagicDollPowers recalledPowers =
                NativeMagicDollPowers.from(recalled.type());
        activeMagicDoll = null;
        magicDollPeriodicState = NativeMagicDollEffects.PeriodicState.empty();
        clearNativeMagicDollAutoSkills(System.nanoTime(), reason, notifyOwner);
        magicDollAutoSkillIds = List.of();
        nextMagicDollAutoSkillCheckNanos = 0;
        activeMagicDollObjectIds.remove(recalled.backingItemObjectId());
        byte[] effect = Protocol.effectObject(recalled.objectId(), 5936);
        byte[] remove = Protocol.removeObject(recalled.objectId());
        for (ClientSession viewer : nativeMagicDollRecipients(recalled)) {
            viewer.sendEncrypted(effect, "S_EFFECT magic-doll-recall object="
                    + recalled.objectId() + " gfx=5936 reason=" + reason);
            viewer.sendEncrypted(remove, "S_REMOVE_OBJECT magic-doll="
                    + recalled.objectId() + " reason=" + reason);
        }
        if (notifyOwner) {
            applyNativeMagicDollStatusPowers(
                    recalledPowers, false, reason);
        }
        if (notifyOwner) sendNativeMagicDollIcon(recalled, System.nanoTime(), true);
        if (notifyOwner && (phase == Phase.BATTLE || phase == Phase.WORLD)) {
            sendEquipmentStatusRefresh("magic-doll-recall");
        }
        System.out.println("[LiTo] magic-doll recalled object=" + recalled.objectId()
                + " item-object=" + recalled.backingItemObjectId()
                + " reason=" + reason);
    }

    private void broadcastNativeMagicDoll(
            NativeMagicDoll doll, boolean summonEffect, String reason)
            throws IOException {
        byte[] actor = Protocol.magicDoll(doll, playerName());
        byte[] effect = Protocol.effectObject(doll.objectId(), 5935);
        for (ClientSession viewer : nativeMagicDollRecipients(doll)) {
            viewer.sendEncrypted(actor, "S_PUT_OBJECT magic-doll=" + doll.objectId()
                    + " gfx=" + doll.type().gfxId() + " reason=" + reason);
            if (summonEffect) {
                viewer.sendEncrypted(effect, "S_EFFECT magic-doll-summon object="
                        + doll.objectId() + " gfx=5935");
            }
        }
    }

    private List<ClientSession> nativeMagicDollRecipients(NativeMagicDoll doll) {
        List<ClientSession> candidates = phase == Phase.WORLD
                ? classicWorldMembers(doll.mapId()) : hub.roomMembers(doll.instanceId());
        return candidates.stream().filter(viewer -> {
            if (phase == Phase.WORLD && (viewer.phase != Phase.WORLD
                    || viewer.classicWorldMapId != doll.mapId()
                    || viewer.classicWorldInstanceId != doll.instanceId())) return false;
            return BattleSpellCatalog.isInNativeScreen(
                    viewer.positionX, viewer.positionY, doll.x(), doll.y());
        }).toList();
    }

    private void sendNativeMagicDollIcon(
            NativeMagicDoll doll, long nowNanos, boolean remove) throws IOException {
        SourceMagicDollType type = doll.type();
        int seconds = remove ? 0 : doll.remainingSeconds(nowNanos);
        byte[] icon = type.iconId() > 0
                ? Protocol.magicDollCustomIcon(type.iconId(), seconds, remove)
                : Protocol.magicDollIcon(seconds);
        sendEncrypted(icon, "S_PACKET_BOX magic-doll-icon=" + type.iconId()
                + " remaining=" + seconds + " remove=" + remove);
    }

    /** Retained L1EquipmentSlot STATUS_UNDERWATER_BREATH lifecycle. */
    private void applyNativeMagicDollStatusPowers(
            NativeMagicDollPowers powers, boolean apply, String reason)
            throws IOException {
        if (powers.value("STATUS_UNDERWATER") <= 0) return;
        if (apply) timedStatus.cancelBreath();
        sendEncrypted(Protocol.underwaterBreath(
                        playerObjectId(), apply ? -1 : 0),
                "S_BREATH object=" + playerObjectId()
                        + " duration=" + (apply ? -1 : 0)
                        + " source=magic-doll reason=" + reason);
    }

    private boolean activePetCollar(RuntimeInventory.Item item) {
        if (item == null
                || item.definition().effect() != InventoryCatalog.Effect.PET_COLLAR) {
            return false;
        }
        synchronized (tamedCompanions) {
            return tamedCompanions.stream()
                    .map(BattleCompanion::snapshot)
                    .anyMatch(pet -> pet.active()
                            && pet.kind() == BattleCompanion.Kind.PET
                            && pet.collarObjectId() == item.objectId());
        }
    }

    private void giveInventoryItem(byte[] payload) throws IOException {
        Protocol.GiveRequest request = Protocol.giveRequest(payload);
        RuntimeInventory.Item item = inventory.item(request.inventoryObjectId());
        String rejection = null;
        boolean classicWorld = phase == Phase.WORLD;
        if ((phase != Phase.BATTLE && !classicWorld) || observer
                || (classicWorld && (playerHp <= 0
                    || !ClassicWorldMapCatalog.supports(classicWorldMapId)))) {
            rejection = "invalid-phase";
        } else if (classicWorld && rejectWhileParalyzed("C_GIVE")) {
            return;
        } else if (timedStatus.actionLocked(System.nanoTime())) {
            rejection = "action-locked";
        } else if (item == null || request.quantity() > item.quantity()) {
            rejection = "not-owned";
        } else if (item.blocksNativeTransferAsEquipped()) {
            rejection = "equipped";
        } else if (!item.transferable()) {
            rejection = "not-tradable";
        } else if (Math.abs(positionX - request.targetX()) >= 3
                || Math.abs(positionY - request.targetY()) >= 3) {
            rejection = "out-of-range";
        }
        if (rejection != null) {
            if (rejection.equals("equipped")) {
                sendEncrypted(Protocol.messageCode(141),
                        "S_MESSAGE_CODE C_GIVE-equipped=141");
            } else if (rejection.equals("not-tradable") && item != null) {
                sendEncrypted(Protocol.messageCode(210, item.nativeLogName()),
                        "S_MESSAGE_CODE C_GIVE-not-tradable=210 item="
                                + item.definition().catalogId());
            } else if (rejection.equals("out-of-range")) {
                sendEncrypted(Protocol.messageCode(142),
                        "S_MESSAGE_CODE C_GIVE-out-of-range=142");
            }
            System.out.printf("[LiTo] C_GIVE rejected reason=%s target=%d x=%d y=%d object=%d quantity=%d%n",
                    rejection, request.targetObjectId(), request.targetX(), request.targetY(),
                    request.inventoryObjectId(), request.quantity());
            return;
        }

        RuntimeInventory next = inventory.copy();
        if (!next.remove(request.inventoryObjectId(), request.quantity())) {
            throw new IllegalStateException("validated C_GIVE could not stage inventory removal");
        }
        BattleCompanion owned = ownedCompanion(request.targetObjectId());
        BattleCompanion.Snapshot companion = owned == null ? null : owned.snapshot();
        GameHub.NpcGiveResult result;
        boolean classicStaticNpc = false;
        if (companion != null) {
            if (!companion.active()
                    || (classicWorld && !companion.kind().classicWorldEligible())) {
                result = GameHub.NpcGiveResult.UNKNOWN_TARGET;
            } else if (request.targetX() != companion.x() || request.targetY() != companion.y()) {
                result = GameHub.NpcGiveResult.STALE_POSITION;
            } else {
                result = owned.canReceiveItem(item, request.quantity())
                        ? GameHub.NpcGiveResult.ACCEPTED : GameHub.NpcGiveResult.CAPACITY;
            }
        } else if (!classicWorld) {
            result = hub.canGiveToNpc(currentRoomId,
                    request.targetObjectId(), request.targetX(), request.targetY(),
                    item, request.quantity());
        } else {
            result = hub.canGiveToClassicWorldMonster(
                    classicWorldMapId, classicWorldInstanceId,
                    request.targetObjectId(), request.targetX(), request.targetY(),
                    item, request.quantity());
            if (result == GameHub.NpcGiveResult.UNKNOWN_TARGET) {
                classicStaticNpc = true;
                result = hub.canGiveToClassicWorldStaticNpc(
                        classicWorldMapId, classicWorldInstanceId,
                        request.targetObjectId(), request.targetX(), request.targetY(),
                        item, request.quantity());
            }
        }
        // The retained ServerItemGiveTable whitelist applies to every
        // L1NpcInstance target (monster, pet, summon and arena NPC), with a
        // GM-only bypass.
        if (result == GameHub.NpcGiveResult.ACCEPTED && !isAdministrator()) {
            int maximum = ClassicWorldMonsterItemLifecycleCatalog.giveMaximum(
                    Math.toIntExact(item.definition().catalogId()));
            if (maximum < 0) {
                sendEncrypted(Protocol.messageCode(210, item.nativeLogName()),
                        "S_MESSAGE_CODE monster-give-not-permitted=210 item="
                                + item.definition().catalogId());
                result = GameHub.NpcGiveResult.UNKNOWN_TARGET;
            } else if (maximum > 0 && request.quantity() > maximum) {
                sendEncrypted(Protocol.messageCode(166,
                                item.nativeLogName() + "最多只能給予" + maximum + "個"),
                        "S_MESSAGE_CODE monster-give-maximum=166 item="
                                + item.definition().catalogId() + " maximum=" + maximum);
                result = GameHub.NpcGiveResult.UNKNOWN_TARGET;
            }
        }
        if (result != GameHub.NpcGiveResult.ACCEPTED) {
            if (result == GameHub.NpcGiveResult.CAPACITY) {
                sendEncrypted(Protocol.messageCode(942),
                        "S_MESSAGE_CODE C_GIVE-target-capacity=942");
            }
            System.out.printf("[LiTo] C_GIVE rejected reason=%s target=%d x=%d y=%d object=%d quantity=%d%n",
                    result.name().toLowerCase(java.util.Locale.ROOT), request.targetObjectId(),
                    request.targetX(), request.targetY(), request.inventoryObjectId(),
                    request.quantity());
            return;
        }

        ClassicWorldMonsterPopulation.Snapshot tameTarget = classicWorld
                && companion == null && !classicStaticNpc ? hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        request.targetObjectId()) : null;
        PetTamingAttempt taming = tameTarget == null ? null
                : prepareClassicWorldPetTaming(tameTarget, item, next);
        PetEvolution evolution = companion != null
                ? preparePetEvolution(owned, companion, item, next) : null;
        if (evolution != null) next = evolution.inventory();
        if (taming != null && taming.success()) next = taming.inventory();
        RuntimeInventory committedInventory = next;
        RuntimeInventory previous = inventory;
        ClassicWorldMonsterPopulation.TamedItemReceipt tameReceipt = null;
        BattleCompanion.GivenItemReceipt companionItemReceipt = null;
        BattleCompanion createdPet = null;
        if (taming != null && taming.success()) {
            java.util.concurrent.atomic.AtomicReference<GameStateStore.PetState> durable =
                    new java.util.concurrent.atomic.AtomicReference<>();
            SourcePetTemplate petTemplate = taming.template();
            long collarObjectId = taming.collarObjectId();
            tameReceipt = hub.giveToClassicWorldMonsterAndCapturePersisted(
                    classicWorldMapId, classicWorldInstanceId,
                    request.targetObjectId(), request.targetX(), request.targetY(),
                    item, request.quantity(), (captured, carriedItems) ->
                            durable.set(state.saveEconomyStateCreatingPet(
                                    stateCharacter(), shopPoints,
                                    committedInventory.catalogCounts(),
                                    committedInventory.catalogItemStates(),
                                    collarObjectId, petTemplate)));
            if (tameReceipt == null || durable.get() == null) {
                System.out.printf("[LiTo] C_GIVE tamePet rejected raced-target target=%d object=%d quantity=%d%n",
                        request.targetObjectId(), request.inventoryObjectId(),
                        request.quantity());
                return;
            }
            createdPet = BattleCompanion.petFromTaming(
                    durable.get(), petTemplate, tameReceipt.capture().captured(),
                    tameReceipt.carriedItems());
            synchronized (tamedCompanions) {
                tamedCompanions.add(createdPet);
            }
            hub.abandonClassicWorldTamedMonster(
                    classicWorldMapId, classicWorldInstanceId,
                    tameReceipt.capture().captured().objectId());
        } else if (evolution == null) {
            DurableCommit commit = () -> state.saveEconomyState(
                    stateCharacter(), shopPoints,
                    committedInventory.catalogCounts(),
                    committedInventory.catalogItemStates());
            if (companion != null) {
                companionItemReceipt = owned.receiveItemAndOnGetItemPersisted(
                        item, request.quantity(), System.nanoTime(), commit);
                if (companionItemReceipt == null) {
                    throw new IllegalStateException(
                            "validated companion give could not commit");
                }
            } else {
                result = classicWorld
                        ? classicStaticNpc
                            ? hub.giveToClassicWorldStaticNpcPersisted(
                                    classicWorldMapId, classicWorldInstanceId,
                                    request.targetObjectId(), request.targetX(),
                                    request.targetY(), item, request.quantity(), commit)
                            : hub.giveToClassicWorldMonsterPersisted(
                                    classicWorldMapId, classicWorldInstanceId,
                                    request.targetObjectId(), request.targetX(),
                                    request.targetY(), item, request.quantity(), commit)
                        : hub.giveToNpcPersisted(
                                currentRoomId, request.targetObjectId(),
                                request.targetX(), request.targetY(), item,
                                request.quantity(), commit);
                if (result != GameHub.NpcGiveResult.ACCEPTED) {
                    System.out.printf("[LiTo] C_GIVE rejected raced-target reason=%s target=%d object=%d quantity=%d%n",
                            result.name().toLowerCase(java.util.Locale.ROOT),
                            request.targetObjectId(), request.inventoryObjectId(),
                            request.quantity());
                    return;
                }
            }
        } else {
            state.saveEconomyStateEvolvingPet(
                    stateCharacter(), shopPoints,
                    committedInventory.catalogCounts(),
                    committedInventory.catalogItemStates(),
                    companion.collarObjectId(), evolution.pet());
            BattleCompanion.Snapshot evolved = owned.evolve(
                    evolution.pet(), evolution.targetTemplate());
            publishPetEvolution(companion, evolved);
        }
        NativeDeItemApplication.replace(this, committedInventory, 0);
        sendInventoryDelta(previous, inventory);
        if (companionItemReceipt != null) {
            publishCompanionGivenItemUse(companionItemReceipt);
        }
        int targetLightRange;
        if (companionItemReceipt != null) {
            targetLightRange = companionItemReceipt.lightRange();
        } else if (tameReceipt != null) {
            targetLightRange = tameReceipt.item().lightRange();
        } else if (companion != null) {
            targetLightRange = owned.lightRange();
        } else if (classicWorld) {
            targetLightRange = classicStaticNpc
                    ? hub.classicWorldStaticNpcLightRange(
                            classicWorldMapId, classicWorldInstanceId,
                            request.targetObjectId())
                    : hub.classicWorldMonsterLightRange(
                            classicWorldMapId, classicWorldInstanceId,
                            request.targetObjectId());
        } else {
            targetLightRange = hub.npcLightRange(
                    currentRoomId, request.targetObjectId());
        }
        // Retained C_GiveItem order after target.onGetItem: target light first,
        // then the giver light.  This is deliberately before tame removal.
        broadcastGivenTargetLight(
                request.targetObjectId(), request.targetX(), request.targetY(),
                targetLightRange, "C_GIVE-target");
        broadcastLightState("C_GIVE-player");
        if (createdPet != null) {
            publishClassicWorldItemTaming(tameReceipt, createdPet);
        } else if (taming != null
                && taming.disposition() == PetTamingDisposition.CONTROL_CAPACITY) {
            sendEncrypted(Protocol.messageCode(489),
                    "S_MESSAGE_CODE tamePet-control-capacity=489");
        } else if (taming != null
                && taming.disposition() == PetTamingDisposition.FAILED) {
            sendEncrypted(Protocol.messageCode(324),
                    "S_MESSAGE_CODE tamePet-failure=324");
        }
        System.out.printf("[LiTo] C_GIVE accepted target=%d x=%d y=%d object=%d catalog=%d quantity=%d%n",
                request.targetObjectId(), request.targetX(), request.targetY(),
                request.inventoryObjectId(), item.definition().catalogId(), request.quantity());
    }

    private record PetEvolution(
            RuntimeInventory inventory, GameStateStore.PetState pet,
            SourcePetTemplate targetTemplate) {}

    private enum PetTamingDisposition {
        SUCCESS,
        FAILED,
        CONTROL_CAPACITY,
        INVENTORY_CAPACITY
    }

    private record PetTamingAttempt(
            SourcePetTemplate template, PetTamingDisposition disposition,
            RuntimeInventory inventory, long collarObjectId, int roll) {
        PetTamingAttempt {
            if (template == null || disposition == null || inventory == null
                    || (disposition == PetTamingDisposition.SUCCESS
                        && collarObjectId <= 0)) {
                throw new IllegalArgumentException("invalid native tamePet attempt");
            }
        }

        boolean success() {
            return disposition == PetTamingDisposition.SUCCESS;
        }
    }

    /** Selected C_GIVE/tamePet rule: control, bag, HP&lt;1/3, then TameRate. */
    private PetTamingAttempt prepareClassicWorldPetTaming(
            ClassicWorldMonsterPopulation.Snapshot target,
            RuntimeInventory.Item item, RuntimeInventory ownerAfterGive)
            throws IOException {
        if (target == null || item == null || ownerAfterGive == null
                || !isSelectedPetTamingItem(item.definition().catalogId())) {
            return null;
        }
        SourcePetTemplate template;
        try {
            template = selectedSourceAccounts().petTemplate(target.npcId());
        } catch (Exception notPetType) {
            return null;
        }
        if (template.tamingItemCatalogId() <= 0
                || item.definition().catalogId() != template.tamingItemCatalogId()) {
            return null;
        }
        if (!canTakeControlledCompanion(template.charismaCost())) {
            return new PetTamingAttempt(template,
                    PetTamingDisposition.CONTROL_CAPACITY,
                    ownerAfterGive, 0, -1);
        }
        if (ownerAfterGive.size() >= RuntimeInventory.MAX_SLOTS) {
            return new PetTamingAttempt(template,
                    PetTamingDisposition.INVENTORY_CAPACITY,
                    ownerAfterGive, 0, -1);
        }
        int roll = classicPetTamingRollOverride >= 0
                ? classicPetTamingRollOverride
                : ThreadLocalRandom.current().nextInt(10000);
        if (target.maximumHp() / 3 <= target.currentHp()
                || roll >= template.tameRate()) {
            return new PetTamingAttempt(template, PetTamingDisposition.FAILED,
                    ownerAfterGive, 0, roll);
        }

        RuntimeInventory staged = ownerAfterGive.copy();
        java.util.Set<Long> beforeIds = staged.items().stream()
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toSet());
        if (!staged.add(InventoryCatalog.require(template.collarCatalogId()), 1)) {
            return new PetTamingAttempt(template,
                    PetTamingDisposition.INVENTORY_CAPACITY,
                    ownerAfterGive, 0, roll);
        }
        RuntimeInventory.Item collar = staged.items().stream()
                .filter(candidate -> !beforeIds.contains(candidate.objectId()))
                .filter(candidate -> candidate.definition().catalogId()
                        == template.collarCatalogId())
                .findFirst().orElseThrow(() -> new IOException(
                        "tamePet collar allocation was not observable"));
        return new PetTamingAttempt(template, PetTamingDisposition.SUCCESS,
                staged, collar.objectId(), roll);
    }

    private static boolean isSelectedPetTamingItem(long catalogId) {
        return catalogId == 40057 || catalogId == 40060
                || (catalogId >= 41301 && catalogId <= 41304);
    }

    private void publishClassicWorldItemTaming(
            ClassicWorldMonsterPopulation.TamedItemReceipt receipt,
            BattleCompanion pet) throws IOException {
        BattleCompanion.Snapshot snapshot = pet.snapshot();
        byte[] removed = Protocol.removeObject(receipt.capture().captured().objectId());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, snapshot.x(), snapshot.y())) {
                continue;
            }
            member.sendEncrypted(removed,
                    "S_REMOVE_OBJECT classic-world-monster="
                            + receipt.capture().captured().objectId()
                            + " reason=item-tamed");
            member.sendClassicWorldCompanionObject(this, snapshot, "item-taming");
        }
        System.out.println("[LiTo] C_GIVE tamePet success owner=" + playerName()
                + " monster=" + receipt.capture().captured().objectId()
                + " pet=" + snapshot.objectId() + " npc=" + snapshot.npcId()
                + " collar=" + snapshot.collarObjectId()
                + " hp=" + snapshot.hp() + "/" + snapshot.maxHp()
                + " carried-items=" + receipt.carriedItems().size());
    }

    /** Retained C_GIVE -> pettypes evolution; an under-level fruit stays in the pet bag. */
    private PetEvolution preparePetEvolution(
            BattleCompanion owned, BattleCompanion.Snapshot companion,
            RuntimeInventory.Item item, RuntimeInventory ownerAfterGive)
            throws IOException {
        if (companion.kind() != BattleCompanion.Kind.PET) return null;
        SourcePetTemplate source;
        try {
            source = selectedSourceAccounts().petTemplate(companion.npcId());
        } catch (Exception sourceFailure) {
            throw new IOException("cannot load selected-source pet evolution row for NPC "
                    + companion.npcId(), sourceFailure);
        }
        if (!source.canEvolve()
                || item.definition().catalogId() != source.evolutionItemCatalogId()
                || companion.level() < source.minimumEvolutionLevel()) {
            return null;
        }

        SourcePetTemplate target;
        try {
            target = selectedSourceAccounts().petTemplate(source.evolutionNpcId());
        } catch (Exception sourceFailure) {
            throw new IOException("cannot load selected-source evolved pet row for NPC "
                    + source.evolutionNpcId(), sourceFailure);
        }
        RuntimeInventory staged = ownerAfterGive.copy();
        RuntimeInventory.Item oldCollar = staged.item(companion.collarObjectId());
        if (oldCollar == null || oldCollar.definition().catalogId()
                != companion.collarCatalogId()
                || !staged.remove(companion.collarObjectId(), 1)) {
            throw new IOException("persistent pet collar disappeared before evolution");
        }
        java.util.Set<Long> beforeIds = staged.items().stream()
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toSet());
        InventoryCatalog.Definition targetCollar = InventoryCatalog.require(
                target.collarCatalogId());
        if (!staged.add(targetCollar, 1)) {
            throw new IOException("native inventory cannot admit evolved pet collar");
        }
        RuntimeInventory.Item newCollar = staged.items().stream()
                .filter(candidate -> !beforeIds.contains(candidate.objectId()))
                .filter(candidate -> candidate.definition().catalogId()
                        == target.collarCatalogId())
                .findFirst().orElseThrow(() -> new IOException(
                        "evolved pet collar allocation was not observable"));
        GameStateStore.PetState durable = owned.durablePetState();
        if (durable == null || durable.collarObjectId() != companion.collarObjectId()) {
            throw new IOException("persistent pet identity disappeared before evolution");
        }
        GameStateStore.PetState evolved = new GameStateStore.PetState(
                durable.sourceKey(), newCollar.objectId(), durable.objectId(),
                target.collarCatalogId(), target.npcId(), durable.name(), 1,
                Math.max(1, durable.maxHp() / 2), durable.maxMp() / 2,
                0, durable.lawful(), true);
        return new PetEvolution(staged, evolved, target);
    }

    private void publishPetEvolution(
            BattleCompanion.Snapshot before, BattleCompanion.Snapshot after)
            throws IOException {
        byte[] shape = Protocol.polymorph(
                after.objectId(), after.gfx(), BattleActionCodes.WALK);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y())) continue;
            member.sendEncrypted(shape,
                    "S_POLYMORPH pet-evolution=" + after.objectId()
                            + " npc=" + before.npcId() + "->" + after.npcId()
                            + " gfx=" + before.gfx() + "->" + after.gfx());
        }
        sendEncrypted(Protocol.classicPet(after, playerName(), true),
                "S_PUT_OBJECT pet-evolution=" + after.objectId()
                        + " level=" + before.level() + "->" + after.level()
                        + " collar=" + before.collarObjectId() + "->"
                        + after.collarObjectId());
        System.out.println("[LiTo] persistent pet evolved owner=" + playerName()
                + " object=" + after.objectId() + " npc=" + before.npcId()
                + "->" + after.npcId() + " collar=" + before.collarObjectId()
                + "->" + after.collarObjectId() + " hp-max=" + before.maxHp()
                + "->" + after.maxHp() + " mp-max=" + before.maxMp()
                + "->" + after.maxMp() + " level=1 exp=0 bag-cleared=true");
    }

    private void checkInventory(byte[] payload) {
        long objectId = Protocol.inventoryObjectRequest(payload, Protocol.C_CHECK_INVENTORY);
        RuntimeInventory.Item item = inventory.item(objectId);
        // Native C_63 has no proven paired response. The authoritative lookup
        // is still performed so stale client ids never become catalog ids.
        System.out.printf("[LiTo] C_CHECK_INVENTORY object=%d present=%s count=%d%n",
                objectId, item != null, item == null ? 0 : item.quantity());
    }

    private void destroyInventoryItem(byte[] payload) throws IOException {
        long objectId = Protocol.inventoryObjectRequest(payload, Protocol.C_DESTROY_ITEM);
        RuntimeInventory.Item existing = inventory.item(objectId);
        if (existing != null && existing.equipped()) {
            sendEncrypted(Protocol.messageCode(125),
                    "S_MESSAGE_CODE cannot-destroy-equipped-item=125 object=" + objectId);
            System.out.println("[LiTo] C_DESTROY_ITEM rejected equipped object=" + objectId
                    + " catalog=" + existing.definition().catalogId());
            return;
        }
        if (existing != null && existing.sourceBound()
                && (existing.definition().weapon()
                    || existing.definition().sourceArmor())) {
            sendEncrypted(Protocol.messageCode(125),
                    "S_MESSAGE_CODE cannot-destroy-source-equipment=125 object=" + objectId);
            System.out.println("[LiTo] C_DESTROY_ITEM rejected source equipment object="
                    + objectId + " catalog=" + existing.definition().catalogId());
            return;
        }
        if (activePetCollar(existing)) {
            sendEncrypted(Protocol.messageCode(125),
                    "S_MESSAGE_CODE cannot-destroy-active-pet-collar=125 object="
                            + objectId);
            System.out.println("[LiTo] C_DESTROY_ITEM rejected active-pet-collar object="
                    + objectId);
            return;
        }
        if (existing != null && sqlLetterSnapshot.authoritative()
                && letterObjectBindings.containsKey(objectId)) {
            destroySqlPhysicalLetter(existing);
            return;
        }
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        RuntimeInventory.Item removed = next.removeEntire(objectId);
        if (removed == null) {
            System.out.println("[LiTo] C_DESTROY_ITEM ignored unknown object=" + objectId);
            return;
        }
        Long letterId = letterObjectBindings.get(objectId);
        if (letterId != null) {
            GameStateStore.LetterDeleteMutation mutation = state.deleteLetter(
                    stateCharacter(), letterId);
            if (!mutation.deleted()) {
                System.out.println("[LiTo] C_DESTROY_ITEM physical-letter rejected object="
                        + objectId + " letter=" + letterId + " durable-row-mismatch");
                return;
            }
            letterObjectBindings.remove(objectId);
        } else if (removed.definition().effect() == InventoryCatalog.Effect.PET_COLLAR) {
            state.saveEconomyStateDeletingPet(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates(), objectId);
        } else {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
        }
        NativeDeItemApplication.replace(this, next, 0);
        if (removed.equipped() && removed.definition().sourceArmor()) {
            removeSolidCarriageUnlessEquipped("destroy-equipped-armor");
        }
        sendInventoryDelta(previous, inventory);
        if (removed.equipped() && phase == Phase.BATTLE) {
            if (removed.definition().weapon()) broadcastWieldState();
            if (removed.definition().light()) broadcastLightState("destroy-item");
        }
        System.out.println("[LiTo] C_DESTROY_ITEM object=" + objectId
                + " catalog=" + removed.definition().catalogId()
                + " quantity=" + removed.quantity());
    }

    private void destroySqlPhysicalLetter(RuntimeInventory.Item existing) throws IOException {
        RepositoryLetter expected = sqlLetterSnapshot.letters().stream()
                .filter(letter -> letter.itemObjectId() == existing.objectId())
                .findFirst().orElse(null);
        if (expected == null) {
            System.out.println("[LiTo] C_DESTROY_ITEM SQL physical-letter rejected object="
                    + existing.objectId() + " snapshot-row-missing");
            return;
        }
        RepositoryLetterMutation mutation;
        try {
            CharacterSummary character = selectedCharacterSummary();
            if (character == null) return;
            mutation = selectedSourceAccounts().deleteLetter(character.objectId(), expected);
        } catch (Exception failure) {
            throw new IOException("cannot delete SQL physical letter object="
                    + existing.objectId(), failure);
        }
        if (mutation.status() != RepositoryLetterMutationStatus.SUCCESS) {
            System.out.println("[LiTo] C_DESTROY_ITEM SQL physical-letter rejected object="
                    + existing.objectId() + " status=" + mutation.status());
            return;
        }
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (next.removeEntire(existing.objectId()) == null) {
            throw new IllegalStateException(
                    "deleted SQL physical letter lost runtime object");
        }
        NativeDeItemApplication.replace(this, next, 0);
        removeSqlLetter(existing.objectId());
        saveSqlLetterEconomyBestEffort();
        sendInventoryDelta(previous, inventory);
        System.out.println("[LiTo] C_DESTROY_ITEM SQL physical-letter object="
                + existing.objectId());
    }

    private void sendInventoryEquipmentState(RuntimeInventory.Item item, String state)
            throws IOException {
        sendEncrypted(Protocol.changeInventoryDescription(item.objectId(), item.nativeViewName()),
                "S_CHANGE_ITEM_DESC object=" + item.objectId() + " " + state
                        + "=" + item.equipped());
    }

    /**
     * The selected client changes the equipment marker only after it receives
     * S_CHANGE_ITEM_DESC. Publish only after source evaluation and the memory
     * state commit succeed; rejected candidates must never appear equipped.
     */
    private void sendStagedSourceEquipmentState(
            List<RuntimeInventory.Item> stagedChanges) throws IOException {
        for (RuntimeInventory.Item staged : stagedChanges) {
            sendInventoryEquipmentState(staged, "committed-equipped");
        }
    }

    private void rollbackStagedSourceEquipmentState(
            List<RuntimeInventory.Item> stagedChanges, String reason) throws IOException {
        for (RuntimeInventory.Item staged : stagedChanges) {
            RuntimeInventory.Item live = inventory.item(staged.objectId());
            if (live != null) sendInventoryEquipmentState(live, "rollback-" + reason);
        }
    }

    private void rollbackStagedSourceWeaponState(
            List<RuntimeInventory.Item> stagedChanges, String reason) throws IOException {
        rollbackStagedSourceEquipmentState(stagedChanges, reason);
        broadcastWieldState(battleWalkAction(), "source-weapon-rollback-" + reason);
    }

