    private NativeLitoRentalTeleportEndpointCatalog.Endpoint
            rentalTownTransferStoneDestination() {
        List<NativeLitoRentalTeleportEndpointCatalog.Endpoint> endpoints =
                config.rentalTeleportEndpoints();
        if (endpoints == null || endpoints.isEmpty()) return null;
        NativeLitoRentalTeleportEndpointCatalog.Endpoint destination = endpoints.get(0);
        for (NativeLitoRentalTeleportEndpointCatalog.Endpoint endpoint : endpoints) {
            if (endpoint.ipv4() != destination.ipv4()
                    || endpoint.port() != destination.port()) {
                return null;
            }
        }
        return destination;
    }

