    private void useDragonEye(RuntimeInventory.Item item) throws IOException {
        if ((Phase)((Object)CombatSpecialBuffs.eyePhase((Object)this.phase, (Object)Phase.BATTLE, this)) != Phase.BATTLE || this.observer || this.playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM Dragon Eye rejected phase=" + String.valueOf((Object)this.phase) + " observer=" + this.observer + " hp=" + this.playerHp);
            return;
        }
        BattleDragonEyeCatalog.Eye eye = BattleDragonEyeCatalog.find(item.definition().catalogId());
        if (eye == null) {
            System.out.println("[LiTo] C_USE_ITEM Dragon Eye rejected unknown catalog=" + item.definition().catalogId());
            return;
        }
        long l = System.nanoTime();
        BattleDragonEyeStatus.Activation activation = this.dragonEyeStatus.activate(item.objectId(), eye, l);
        if (activation.outcome() == BattleDragonEyeStatus.Outcome.ITEM_COOLDOWN) {
            long l2 = Math.max(1L, ((long)activation.remainingCooldownMillis() + 59999L) / 60000L);
            this.sendEncrypted(Protocol.messageCode(1139, eye.nameId() + " " + l2), "S_MESSAGE_CODE dragon-eye-delay=1139 item=" + eye.itemId() + " remaining-ms=" + activation.remainingCooldownMillis());
            return;
        }
        if (activation.outcome() == BattleDragonEyeStatus.Outcome.GROUP_CONFLICT) {
            this.sendEncrypted(Protocol.systemMessage(9, "\\fX\u8207\u73fe\u6709\u72c0\u614b\u885d\u7a81\uff0c\u5269\u9918\u6642\u9593(\u79d2): " + activation.remainingSeconds()), "S_MESSAGE dragon-eye-group-conflict item=" + eye.itemId() + " remaining-seconds=" + activation.remainingSeconds());
            return;
        }
        this.cancelAbsoluteBarrier("item-dragon-eye");
        byte[] byArray = Protocol.effectObject(this.playerObjectId(), eye.castGfx());
        for (ClientSession clientSession : CombatSpecialBuffs.eyeRecipients(this.hub, this.currentRoomId, this)) {
            if (clientSession != this && Math.max(Math.abs(this.positionX - clientSession.positionX), Math.abs(this.positionY - clientSession.positionY)) > 8) continue;
            clientSession.sendEncrypted(byArray, "S_EFFECT Dragon Eye object=" + this.playerObjectId() + " item=" + eye.itemId() + " buff=" + eye.buffId() + " gfx=" + eye.castGfx());
        }
        System.out.println("[LiTo] C_USE_ITEM Dragon Eye object=" + item.objectId() + " catalog=" + eye.itemId() + " buff=" + eye.buffId() + " duration=" + eye.durationSeconds() + " melee-damage=" + eye.meleeDamage() + " magic-hit=" + eye.magicHit() + " damage-reduction=" + eye.damageReduction() + " er=" + eye.evasionRate() + " stone-resistance=" + eye.stoneResistance() + " sleep-resistance=" + eye.sleepResistance() + " freeze-resistance=" + eye.freezeResistance() + " poison-resistance=" + eye.poisonResistance() + " item-consumed=false status-icon-wire=selected-client-incompatible");
    }

    private void useExperienceGem(RuntimeInventory.Item item) throws IOException {
        if ((phase != Phase.BATTLE && phase != Phase.WORLD)
                || observer || playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM Dragon Gem rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        BattleExperienceGemCatalog.Gem gem = BattleExperienceGemCatalog.find(
                item.definition().catalogId());
        if (gem == null) {
            System.out.println("[LiTo] C_USE_ITEM Dragon Gem rejected unknown catalog="
                    + item.definition().catalogId());
            return;
        }
        if (playerClassicLevel < BattleExperienceGemCatalog.MINIMUM_LEVEL) {
            // The retained server uses legacy PacketBox subtype ItemLv for
            // min level 49. Selected LiTo opcode FA is S_LITO_CLAN, so use its
            // compatible parameterized message path instead.
            sendEncrypted(Protocol.messageCode(318,
                            Integer.toString(BattleExperienceGemCatalog.MINIMUM_LEVEL)),
                    "S_MESSAGE_CODE Dragon-Gem-level=318 minimum="
                            + BattleExperienceGemCatalog.MINIMUM_LEVEL);
            return;
        }

        RuntimeInventory previous = inventory.copy();
        if (!inventory.remove(item.objectId(), 1)) return;
        GameStateStore.TimedExperienceBuff durable =
                new GameStateStore.TimedExperienceBuff(
                        gem.bonusExperience(), gem.durationSeconds());
        try {
            state.saveEconomyStateActivatingExperienceBuff(
                    stateCharacter(), shopPoints, inventory.catalogCounts(),
                    inventory.catalogItemStates(), durable);
        } catch (IOException | RuntimeException failure) {
            NativeDeItemApplication.replace(this, previous, 0);
            throw failure;
        }
        long nowNanos = System.nanoTime();
        BattleExperienceGemStatus.Snapshot active =
                experienceGemStatus.activate(gem, nowNanos);
        cancelAbsoluteBarrier("item-dragon-gem");
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.systemMessage(9,
                        "\\fT龍之寶石祝福: " + active.remainingSeconds()
                                + "秒內每次狩獵額外經驗 +"
                                + active.bonusExperience()),
                "S_MESSAGE Dragon Gem active item=" + gem.itemId()
                        + " bonus=" + gem.bonusExperience()
                        + " duration=" + active.remainingSeconds());
        System.out.println("[LiTo] C_USE_ITEM Dragon Gem object=" + item.objectId()
                + " catalog=" + gem.itemId() + " skill="
                + BattleExperienceGemCatalog.SKILL_ID
                + " bonus=" + gem.bonusExperience()
                + " duration=" + active.remainingSeconds()
                + " replaced=true legacy-icon=selected-client-incompatible");
    }

    private void useLetterPaper(RuntimeInventory.Item paper,
                                Protocol.LetterComposeInventoryUse request)
            throws Exception {
        if (phase != Phase.BATTLE || observer || playerHp <= 0 || request == null) {
            System.out.println("[LiTo] C_USE_ITEM letter-paper rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        String requestedReceiver = request.receiver();
        boolean exists = requestedReceiver.equalsIgnoreCase(playerName())
                || state.createdCharacterExists(stateAccount(), requestedReceiver)
                || selectedSourceAccounts().characterExists(requestedReceiver);
        if (!exists) {
            sendEncrypted(Protocol.messageCode(109, requestedReceiver),
                    "S_MESSAGE_CODE letter-recipient-not-found=109 receiver="
                            + requestedReceiver);
            System.out.println("[LiTo] C_USE_ITEM letter-paper rejected missing receiver="
                    + requestedReceiver);
            return;
        }

        ClientSession target = requestedReceiver.equalsIgnoreCase(playerName()) ? this
                : hub.onlineCharacterSessions(this, List.of(requestedReceiver)).stream()
                .filter(session -> session.sourceCharacterIdentity()
                        .equalsIgnoreCase(stateCharacter(requestedReceiver)))
                .filter(session -> session.inventoryCharacter
                        .equalsIgnoreCase(session.sourceCharacterIdentity()))
                .findFirst().orElse(null);
        if (sqlLetterSnapshot.authoritative()) {
            useSqlLetterPaper(paper, request, target);
            return;
        }
        RuntimeInventory senderBefore = inventory;
        RuntimeInventory senderAfter = inventory.copy();
        if (!senderAfter.remove(paper.objectId(), 1)) return;

        RuntimeInventory receiverBefore = target == null ? null
                : target == this ? senderBefore : target.inventory;
        RuntimeInventory receiverAfter = target == null ? null
                : target == this ? senderAfter : target.inventory.copy();
        if (receiverAfter != null && !receiverAfter.add(
                InventoryCatalog.require(InventoryCatalog.LETTER_CLOSED), 1)) {
            sendEncrypted(Protocol.messageCode(942),
                    "S_MESSAGE_CODE letter-recipient-inventory-full=942 receiver="
                            + requestedReceiver);
            return;
        }

        String date = CLASSIC_BOARD_DATE.format(ZonedDateTime.now(CLASSIC_BOARD_ZONE));
        String receiverIdentity = target == null
                ? stateCharacter(requestedReceiver) : target.sourceCharacterIdentity();
        GameStateStore.LetterDelivery delivery = state.deliverLetter(
                stateCharacter(), receiverIdentity, request.letterCode(), date,
                request.subject(), request.content());
        if (!delivery.delivered()) {
            if (delivery.status() == GameStateStore.LetterDeliveryStatus.RECIPIENT_FULL) {
                sendEncrypted(Protocol.messageCode(942),
                        "S_MESSAGE_CODE letter-delivery-failed=942 status="
                                + delivery.status());
            }
            System.out.println("[LiTo] C_USE_ITEM letter-paper rejected status="
                    + delivery.status() + " receiver=" + requestedReceiver);
            return;
        }

        if (target == this) {
            NativeDeItemApplication.replace(this, receiverAfter, 0);
            bindNewLetterObject(senderBefore, inventory, delivery.letter());
            if (inventoryBootstrapSent) sendInventoryDelta(senderBefore, inventory);
            sendLetterDeliveryNotice(delivery.letter());
        } else {
            NativeDeItemApplication.replace(this, senderAfter, 0);
            if (inventoryBootstrapSent) sendInventoryDelta(senderBefore, inventory);
            if (target != null) {
                target.receiveLetterDelivery(receiverBefore, receiverAfter, delivery.letter());
            }
        }
        System.out.println("[LiTo] C_USE_ITEM letter-paper delivered sender=" + playerName()
                + " receiver=" + delivery.letter().receiver()
                + " letter=" + delivery.letter().id()
                + " online=" + (target != null)
                + " subjectUnits=" + request.subject().length()
                + " contentUnits=" + request.content().length());
    }

    private void useSqlLetterPaper(RuntimeInventory.Item paper,
                                   Protocol.LetterComposeInventoryUse request,
                                   ClientSession target) throws Exception {
        CharacterSummary senderCharacter = selectedCharacterSummary();
        if (senderCharacter == null) return;
        if (target != null) {
            RuntimeInventory capacityProbe = target == this ? inventory.copy()
                    : target.inventory.copy();
            if (target == this && !capacityProbe.remove(paper.objectId(), 1)) return;
            if (capacityProbe.size() >= RuntimeInventory.MAX_SLOTS) {
                sendEncrypted(Protocol.messageCode(942),
                        "S_MESSAGE_CODE SQL-letter-recipient-runtime-full=942 receiver="
                                + request.receiver());
                return;
            }
        }
        long sqlPaperObjectId = state.sourceInventoryBindings(stateCharacter()).stream()
                .filter(binding -> binding.localObjectId() == paper.objectId())
                .mapToLong(GameStateStore.SourceInventoryBinding::sourceObjectId)
                .findFirst().orElse(paper.objectId());
        String date = CLASSIC_BOARD_DATE.format(ZonedDateTime.now(CLASSIC_BOARD_ZONE));
        RepositoryLetterDelivery delivery = selectedSourceAccounts().deliverLetter(
                senderCharacter.objectId(), sqlPaperObjectId, request.receiver(),
                request.letterCode(), date, request.subject(), request.content());
        if (!delivery.delivered()) {
            if (delivery.status() == RepositoryLetterDeliveryStatus.RECIPIENT_NOT_FOUND) {
                sendEncrypted(Protocol.messageCode(109, request.receiver()),
                        "S_MESSAGE_CODE SQL-letter-recipient-not-found=109 receiver="
                                + request.receiver());
            } else if (delivery.status() == RepositoryLetterDeliveryStatus.RECIPIENT_FULL) {
                sendEncrypted(Protocol.messageCode(942),
                        "S_MESSAGE_CODE SQL-letter-recipient-full=942 receiver="
                                + request.receiver());
            }
            System.out.println("[LiTo] C_USE_ITEM SQL physical-letter rejected status="
                    + delivery.status() + " receiver=" + request.receiver()
                    + " paper=" + sqlPaperObjectId);
            return;
        }

        RepositoryLetter repositoryLetter = delivery.letter();
        GameStateStore.Letter letter = repositoryLetter.gameStateLetter();
        RuntimeInventory senderBefore = inventory;
        RuntimeInventory senderAfter = inventory.copy();
        if (!senderAfter.remove(paper.objectId(), 1)) {
            throw new IllegalStateException(
                    "SQL physical-letter delivery lost sender runtime paper");
        }
        if (target == this) {
            if (!addSqlLetterObject(senderAfter, repositoryLetter)) {
                throw new IllegalStateException(
                        "SQL physical-letter delivery cannot admit receiver runtime item");
            }
            NativeDeItemApplication.replace(this, senderAfter, 0);
            reconcileSqlLetter(repositoryLetter);
            letterObjectBindings.put(repositoryLetter.itemObjectId(),
                    repositoryLetter.itemObjectId());
            saveSqlLetterEconomyBestEffort();
            if (inventoryBootstrapSent) sendInventoryDelta(senderBefore, inventory);
            sendLetterDeliveryNotice(letter);
        } else {
            NativeDeItemApplication.replace(this, senderAfter, 0);
            saveSqlLetterEconomyBestEffort();
            if (inventoryBootstrapSent) sendInventoryDelta(senderBefore, inventory);
            if (target != null) target.receiveSqlLetterDelivery(repositoryLetter);
        }
        System.out.println("[LiTo] C_USE_ITEM SQL physical-letter delivered sender="
                + playerName() + " receiver=" + repositoryLetter.receiver()
                + " object=" + repositoryLetter.itemObjectId()
                + " online=" + (target != null));
    }

    private void receiveSqlLetterDelivery(RepositoryLetter repositoryLetter) throws IOException {
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        if (!ClientSession.addSqlLetterObject(runtimeInventory2, repositoryLetter)) {
            throw new IllegalStateException("SQL physical-letter delivery cannot admit online receiver item");
        }
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        this.reconcileSqlLetter(repositoryLetter);
        this.letterObjectBindings.put(repositoryLetter.itemObjectId(), repositoryLetter.itemObjectId());
        this.saveSqlLetterEconomyBestEffort();
        if (this.inventoryBootstrapSent) {
            this.sendInventoryDelta(runtimeInventory, this.inventory);
        }
        if (this.phase == Phase.BATTLE) {
            this.sendLetterDeliveryNotice(repositoryLetter.gameStateLetter());
        }
    }

    private static boolean addSqlLetterObject(RuntimeInventory target,
                                              RepositoryLetter letter) {
        InventoryCatalog.Definition definition = InventoryCatalog.require(letter.opened()
                ? InventoryCatalog.LETTER_OPEN : InventoryCatalog.LETTER_CLOSED);
        RuntimeInventory.PersistentItem state = new RuntimeInventory.PersistentItem(
                letter.itemObjectId(), 1, 0, 0, true, definition.blessing(),
                true, false, false, null, definition.initialChargeCount(),
                0L, false, true);
        return target.addDistinctState(definition, state) == letter.itemObjectId();
    }

    private void reconcileSqlLetter(RepositoryLetter replacement) {
        List<RepositoryLetter> rows = new ArrayList<>(sqlLetterSnapshot.letters());
        rows.removeIf(row -> row.itemObjectId() == replacement.itemObjectId());
        rows.add(replacement);
        sqlLetterSnapshot = new RepositoryLetterSnapshot(true, rows);
        state.reconcileSqlLetters(stateCharacter(), sqlLetterSnapshot.letters().stream()
                .map(RepositoryLetter::gameStateLetter).toList());
    }

    private void removeSqlLetter(long itemObjectId) {
        List<RepositoryLetter> rows = new ArrayList<>(sqlLetterSnapshot.letters());
        rows.removeIf(row -> row.itemObjectId() == itemObjectId);
        sqlLetterSnapshot = new RepositoryLetterSnapshot(true, rows);
        state.reconcileSqlLetters(stateCharacter(), sqlLetterSnapshot.letters().stream()
                .map(RepositoryLetter::gameStateLetter).toList());
        letterObjectBindings.remove(itemObjectId);
    }

    private void saveSqlLetterEconomyBestEffort() {
        try {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        } catch (IOException cacheFailure) {
            // SQL is authoritative; a reconnect reconstructs the sidecar cache
            // from character_items + character_letter without duplicating data.
            System.out.println("[LiTo] SQL physical-letter sidecar cache refresh failed player="
                    + playerName() + ": " + cacheFailure.getMessage());
        }
    }

    private void receiveLetterDelivery(RuntimeInventory runtimeInventory, RuntimeInventory runtimeInventory2, GameStateStore.Letter letter) throws IOException {
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        this.bindNewLetterObject(runtimeInventory, this.inventory, letter);
        if (this.inventoryBootstrapSent) {
            this.sendInventoryDelta(runtimeInventory, this.inventory);
        }
        if (this.phase == Phase.BATTLE) {
            this.sendLetterDeliveryNotice(letter);
        }
    }

    private void bindNewLetterObject(RuntimeInventory before, RuntimeInventory after,
                                     GameStateStore.Letter letter) {
        Set<Long> oldIds = before.items().stream().map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toSet());
        RuntimeInventory.Item added = after.items().stream()
                .filter(item -> !oldIds.contains(item.objectId()))
                .filter(item -> item.definition().catalogId() == InventoryCatalog.LETTER_CLOSED)
                .findFirst().orElseThrow(() ->
                        new IllegalStateException("delivered physical letter has no runtime item"));
        letterObjectBindings.put(added.objectId(), letter.id());
    }

    private void sendLetterDeliveryNotice(GameStateStore.Letter letter) throws IOException {
        sendEncrypted(Protocol.effectObject(
                        playerObjectId(), InventoryCatalog.LETTER_DELIVERY_EFFECT_GFX),
                "S_EFFECT physical-letter-delivery object=" + playerObjectId()
                        + " gfx=" + InventoryCatalog.LETTER_DELIVERY_EFFECT_GFX
                        + " letter=" + letter.id());
        sendEncrypted(Protocol.messageCode(428),
                "S_MESSAGE_CODE physical-letter-arrived=428 letter=" + letter.id());
    }

    private void usePhysicalLetter(RuntimeInventory.Item item) throws IOException {
        if (phase != Phase.BATTLE || observer || playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM physical-letter rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        Long letterId = letterObjectBindings.get(item.objectId());
        if (letterId == null) {
            System.out.println("[LiTo] C_USE_ITEM physical-letter rejected unbound object="
                    + item.objectId());
            return;
        }
        if (sqlLetterSnapshot.authoritative()) {
            useSqlPhysicalLetter(item);
            return;
        }
        GameStateStore.Letter letter = state.letters(stateCharacter()).stream()
                .filter(candidate -> candidate.id() == letterId)
                .findFirst().orElse(null);
        if (letter == null) {
            System.out.println("[LiTo] C_USE_ITEM physical-letter rejected missing row="
                    + letterId + " object=" + item.objectId());
            return;
        }

        boolean transitioned = false;
        if (item.definition().effect() == InventoryCatalog.Effect.LETTER_CLOSED) {
            GameStateStore.LetterOpenMutation opened = state.openLetter(stateCharacter(), letterId);
            if (opened.status() != GameStateStore.LetterOpenStatus.OPENED
                    && opened.status() != GameStateStore.LetterOpenStatus.ALREADY_OPEN) {
                System.out.println("[LiTo] C_USE_ITEM physical-letter open rejected status="
                        + opened.status() + " letter=" + letterId);
                return;
            }
            letter = opened.letter();
            if (opened.status() == GameStateStore.LetterOpenStatus.OPENED) {
                if (!inventory.replaceDefinition(item.objectId(),
                        InventoryCatalog.require(InventoryCatalog.LETTER_OPEN))) {
                    throw new IllegalStateException("persisted physical-letter transition lost runtime item");
                }
                transitioned = true;
            }
        }
        sendEncrypted(Protocol.readMail(
                        item.objectId(), InventoryCatalog.LETTER_OPEN_INVENTORY_GFX,
                        letter.code(), letter.sender(), letter.receiver(), letter.subject(),
                        letter.content(), letter.templateId(), letter.date()),
                "S_READ_MAIL object=" + item.objectId() + " letter=" + letter.id()
                        + " opened=" + letter.opened() + " transitioned=" + transitioned);
        System.out.println("[LiTo] C_USE_ITEM physical-letter object=" + item.objectId()
                + " letter=" + letter.id() + " transitioned=" + transitioned);
    }

    private void useSqlPhysicalLetter(RuntimeInventory.Item item) throws IOException {
        RepositoryLetter expected = sqlLetterSnapshot.letters().stream()
                .filter(letter -> letter.itemObjectId() == item.objectId())
                .findFirst().orElse(null);
        if (expected == null) {
            System.out.println("[LiTo] C_USE_ITEM SQL physical-letter rejected object="
                    + item.objectId() + " snapshot-row-missing");
            return;
        }
        boolean transitioned = false;
        RepositoryLetter letter = expected;
        if (item.definition().effect() == InventoryCatalog.Effect.LETTER_CLOSED) {
            RepositoryLetterMutation mutation;
            try {
                CharacterSummary character = selectedCharacterSummary();
                if (character == null) return;
                mutation = selectedSourceAccounts().openLetter(character.objectId(), expected);
            } catch (Exception failure) {
                throw new IOException("cannot open SQL physical letter object="
                        + item.objectId(), failure);
            }
            if (mutation.status() != RepositoryLetterMutationStatus.SUCCESS
                    && mutation.status() != RepositoryLetterMutationStatus.ALREADY_OPEN) {
                System.out.println("[LiTo] C_USE_ITEM SQL physical-letter open rejected object="
                        + item.objectId() + " status=" + mutation.status());
                return;
            }
            letter = mutation.letter();
            if (letter == null) throw new IllegalStateException(
                    "successful SQL physical-letter mutation has no row");
            reconcileSqlLetter(letter);
            if (mutation.status() == RepositoryLetterMutationStatus.SUCCESS
                    || mutation.status() == RepositoryLetterMutationStatus.ALREADY_OPEN) {
                if (!inventory.replaceDefinition(item.objectId(),
                        InventoryCatalog.require(InventoryCatalog.LETTER_OPEN))) {
                    throw new IllegalStateException(
                            "opened SQL physical letter lost runtime object");
                }
                transitioned = true;
                saveSqlLetterEconomyBestEffort();
            }
        }
        sendEncrypted(Protocol.readMail(item.objectId(),
                        InventoryCatalog.LETTER_OPEN_INVENTORY_GFX,
                        letter.code(), letter.sender(), letter.receiver(), letter.subject(),
                        letter.content(), letter.templateId(), letter.date()),
                "S_READ_MAIL SQL object=" + item.objectId()
                        + " opened=" + letter.opened() + " transitioned=" + transitioned);
        System.out.println("[LiTo] C_USE_ITEM SQL physical-letter object="
                + item.objectId() + " transitioned=" + transitioned);
    }

    private void useAppraisalScroll(RuntimeInventory.Item scroll, long targetObjectId)
            throws IOException {
        if (phase != Phase.BATTLE || observer || playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM appraisal rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        RuntimeInventory.Item target = inventory.item(targetObjectId);
        if (target == null) {
            System.out.println("[LiTo] C_USE_ITEM appraisal rejected unknown target="
                    + targetObjectId);
            return;
        }

        RuntimeInventory previous = inventory.copy();
        if (!inventory.identify(targetObjectId) || !inventory.remove(scroll.objectId(), 1)) {
            return;
        }

        InventoryCatalog.Definition definition = target.definition();
        String name = switch (target.blessing()) {
            case 1 -> "$227 " + definition.name();
            case 2 -> "$228 " + definition.name();
            default -> definition.name();
        };
        InventoryCatalog.NativeWeaponStatus weapon =
                InventoryCatalog.nativeWeaponStatus(definition.catalogId());
        List<String> arguments;
        int messageId;
        if (weapon != null) {
            messageId = 134;
            arguments = List.of(name, weapon.damageSmall() + "+0", weapon.damageLarge() + "+0");
        } else {
            messageId = 138;
            arguments = List.of(name, Long.toString(definition.packetWeight(target.quantity())));
        }
        sendEncrypted(Protocol.identifyCode(
                        definition.itemDescriptionId(), messageId, arguments),
                "S_IDENTIFY_CODE target=" + targetObjectId + " catalog="
                        + definition.catalogId() + " message=" + messageId);
        sendInventoryDelta(previous, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        System.out.println("[LiTo] C_USE_ITEM appraisal scroll=" + scroll.objectId()
                + " target=" + targetObjectId + " message=" + messageId);
    }

    private void useCurseRemovalScroll(RuntimeInventory.Item item) throws IOException {
        if (this.phase != Phase.BATTLE || this.observer || this.playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM curse-removal rejected phase=" + String.valueOf((Object)this.phase) + " observer=" + this.observer + " hp=" + this.playerHp);
            return;
        }
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        List<RuntimeInventory.Item> list = runtimeInventory2.removeCurses();
        if (!runtimeInventory2.remove(item.objectId(), 1L)) {
            return;
        }
        this.cancelAbsoluteBarrier("item-curse-removal");
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, runtimeInventory2.catalogCounts(), runtimeInventory2.catalogItemStates());
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        for (RuntimeInventory.Item item2 : list) {
            this.sendEncrypted(Protocol.changeInventoryBlessing(item2.objectId(), item2.blessing()), "S_CHANGE_ITEM_BLESS object=" + item2.objectId() + " state=" + item2.blessing() + " curse-removal");
        }
        this.sendInventoryDelta(runtimeInventory, this.inventory);
        this.sendEncrypted(Protocol.messageCode(155, new String[0]), "S_MESSAGE_CODE curse-removal-complete=155 changed=" + list.size());
        System.out.println("[LiTo] C_USE_ITEM curse-removal scroll=" + item.objectId() + " changed=" + list.size());
    }

    private void useHomeTeleportScroll(
            RuntimeInventory.Item scroll,
            Protocol.HomeTeleportInventoryUse request) throws IOException {
        long now = System.nanoTime();
        GameHub.ClassicWorldLocation location = hub.classicWorldLocation(this);
        ClassicWorldMapCatalog.ClassicMap sourceMap =
                ClassicWorldMapCatalog.supports(classicWorldMapId)
                ? ClassicWorldMapCatalog.forMap(classicWorldMapId) : null;
        long readyAt = itemReadyNanos.getOrDefault(4, 0L);
        if (request == null || phase != Phase.WORLD || observer || playerHp <= 0
                || sourceMap == null || location == null
                || location.mapId() != classicWorldMapId
                || request.currentMapId() != classicWorldMapId
                || !sourceMap.allowsEscape() || pendingPortal != null
                || hub.hasPrivateShop(this) || now < readyAt) {
            System.out.println("[LiTo] C_USE_ITEM home-scroll rejected player="
                    + playerName() + " phase=" + phase + " map=" + classicWorldMapId
                    + " request-map=" + (request == null ? -1 : request.currentMapId())
                    + " cooldownNanos=" + Math.max(0L, readyAt - now)
                    + " pending-portal=" + (pendingPortal != null));
            return;
        }
        if (rejectWhileParalyzed("C_USE_ITEM home-scroll")) return;

        CharacterSummary character = selectedCharacterSummary();
        int characterType = character == null ? 0 : character.type();
        ClassicWorldGetbackCatalog.Destination getback =
                ClassicWorldGetbackCatalog.resolve(
                        classicWorldMapId, positionX, positionY, characterType);
        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(getback.mapId());
        if (!destinationMap.standingPassable(getback.x(), getback.y())) {
            throw new IOException("home-scroll getback is outside imported classic map");
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.remove(scroll.objectId(), 1)) return;
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        NativeDeItemApplication.replace(this, next, 0);
        itemReadyNanos.put(4, now + 1_500_000_000L);
        cancelAbsoluteBarrier("item-home-scroll");
        sendInventoryDelta(previous, inventory);

        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                getback.mapId(), getback.x(), getback.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, 5, 0, "home-scroll-40079");
        pendingPortal = destination;
        pendingPortalReady = true;

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT home-scroll target=" + playerObjectId()
                                + " gfx="
                                + ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
            }
        }
        sendEncrypted(Protocol.portal(destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL home-scroll map=" + destination.mapId()
                        + " x=" + destination.x() + " y=" + destination.y());
        System.out.println("[LiTo] C_USE_ITEM home-scroll accepted player="
                + playerName() + " source=" + classicWorldMapId + ":"
                + positionX + "," + positionY + " destination="
                + destination.mapId() + ":" + destination.x() + ","
                + destination.y() + " heading=5 item-delay=4/1500ms"
                + " result=awaiting-C_GOTO_PORTAL");
    }

    private void useClassicWorldWeakSoul(RuntimeInventory.Item item) throws IOException {
        boolean bl;
        GameHub.ClassicWorldLocation classicWorldLocation = this.hub.classicWorldLocation(this);
        boolean bl2 = bl = item != null && item.definition().catalogId() == 41208L && this.phase == Phase.WORLD && !this.observer && this.playerHp > 0 && classicWorldLocation != null && classicWorldLocation.mapId() == this.classicWorldMapId && this.pendingPortal == null && !this.movementLockPending && !this.hub.hasPrivateShop(this);
        if (!bl) {
            this.sendEncrypted(Protocol.messageCode(79, new String[0]), "S_MESSAGE_CODE Ship-Grave-weak-soul-rejected=79 map=" + this.classicWorldMapId + " x=" + this.positionX + " y=" + this.positionY);
            System.out.println("[LiTo] C_USE_ITEM Weak-Soul rejected player=" + this.playerName() + " phase=" + String.valueOf((Object)this.phase) + " map=" + this.classicWorldMapId + " x=" + this.positionX + " y=" + this.positionY + " pending-portal=" + (this.pendingPortal != null));
            return;
        }
        if (this.rejectWhileParalyzed("C_USE_ITEM Weak-Soul")) {
            return;
        }
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        InventoryCatalog.Definition definition = InventoryCatalog.find(41207L);
        if (definition == null) {
            throw new IOException("Weak Soul crew corpse definition vanished");
        }
        if (!runtimeInventory2.removeCatalog(41208L, 1L)) {
            throw new IOException("validated Weak Soul removal failed");
        }
        if (!runtimeInventory2.add(definition, 1L)) {
            this.sendEncrypted(Protocol.messageCode(263, new String[0]), "S_MESSAGE_CODE Ship-Grave-weak-soul-capacity=263");
            return;
        }
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, runtimeInventory2.catalogCounts(), runtimeInventory2.catalogItemStates());
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        this.sendInventoryDelta(runtimeInventory, this.inventory);
        System.out.println("[LiTo] C_USE_ITEM Weak-Soul accepted player=" + this.playerName() + " consumed=41208 rewarded=41207 result=inventory-conversion");
    }

    /** Exact selected CustomAreaTeleport capability for the secret-room key. */
    private void useCustomAreaTeleportItem(RuntimeInventory.Item item) throws IOException {
        ClassicWorldCustomAreaTeleportCatalog.Route configured =
                ClassicWorldCustomAreaTeleportCatalog.route(
                        item.definition().catalogId());
        GameHub.ClassicWorldLocation location = hub.classicWorldLocation(this);
        ClassicWorldCustomAreaTeleportCatalog.Route route =
                ClassicWorldCustomAreaTeleportCatalog.resolve(
                        item.definition().catalogId(), classicWorldMapId,
                        positionX, positionY);
        boolean admitted = configured != null && route != null
                && phase == Phase.WORLD && !observer && playerHp > 0
                && location != null && location.mapId() == classicWorldMapId
                && pendingPortal == null && !movementLockPending
                && !hub.hasPrivateShop(this);
        if (!admitted) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE custom-area-teleport-rejected=79 item="
                            + item.definition().catalogId());
            System.out.println("[LiTo] C_USE_ITEM custom-area-teleport rejected player="
                    + playerName() + " item=" + item.definition().catalogId()
                    + " phase=" + phase + " map=" + classicWorldMapId
                    + " x=" + positionX + " y=" + positionY
                    + " pending-portal=" + (pendingPortal != null));
            return;
        }
        if (rejectWhileParalyzed("C_USE_ITEM custom-area-teleport")) return;

        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(route.destinationMapId());
        if (route.destinationRandomRange() != 0
                || !destinationMap.standingPassable(
                        route.destinationX(), route.destinationY())) {
            throw new IOException("custom-area teleport destination contract changed");
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.remove(item.objectId(), 1)) return;
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        NativeDeItemApplication.replace(this, next, 0);
        cancelAbsoluteBarrier("item-custom-area-teleport");
        sendInventoryDelta(previous, inventory);

        clearPendingClassicList();
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                route.destinationMapId(), route.destinationX(),
                route.destinationY(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, route.destinationHeading(), 0,
                "custom-area-item-" + route.itemId());
        pendingPortal = destination;
        pendingPortalReady = true;

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT custom-area-teleport target=" + playerObjectId()
                                + " gfx="
                                + ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
            }
        }
        sendEncrypted(Protocol.portal(destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL custom-area-item=" + route.itemId()
                        + " map=" + destination.mapId() + " x="
                        + destination.x() + " y=" + destination.y());
        System.out.println("[LiTo] C_USE_ITEM custom-area-teleport accepted player="
                + playerName() + " row=" + route.rowId() + " item=" + route.itemId()
                + " source=" + classicWorldMapId + ":" + positionX + "," + positionY
                + " destination=" + destination.mapId() + ":"
                + destination.x() + "," + destination.y()
                + " heading=" + route.destinationHeading()
                + " consumed=1 result=awaiting-C_GOTO_PORTAL");
    }

    /**
     * Exact quest122 Key2/Key3/Teleport executor semantics, adapted only at
     * the final transport boundary to LiTo's proved S_PORTAL -> C_GOTO_PORTAL
     * capability handshake.
     */
    private void useClassicWorldCkewStageTeleport(RuntimeInventory.Item item)
            throws IOException {
        long itemId = item == null ? 0 : item.definition().catalogId();
        if (ClassicWorldCkewCatalog.stageItem(itemId) == null) {
            throw new IOException("unknown CKEW stage item=" + itemId);
        }
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE CKEW-stage-outside-map=79 item=" + itemId);
            return;
        }

        int showId = classicWorldInstanceId;
        List<ClientSession> members = showId >= ClassicWorldCkewCatalog.FIRST_SHOW_ID
                ? hub.classicWorldMembers(ClassicWorldCkewCatalog.MAP_ID, showId)
                : List.of();
        List<Integer> characterTypes = members.stream()
                .map(ClientSession::selectedCharacterType).toList();
        if (!ClassicWorldCkewCatalog.exactNativeParty(characterTypes)) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE CKEW-stage-invalid-party=79 item=" + itemId
                            + " show=" + showId + " types=" + characterTypes);
            if (showId >= ClassicWorldCkewCatalog.FIRST_SHOW_ID) {
                hub.endClassicWorldCkew(showId, "invalid-party");
            }
            return;
        }

        for (ClientSession member : members) {
            ClassicWorldCkewCatalog.Location destination =
                    ClassicWorldCkewCatalog.stageDestination(
                            itemId, member.selectedCharacterType());
            if (destination == null || destination.mapId()
                    != ClassicWorldCkewCatalog.MAP_ID
                    || !ClassicWorldMapCatalog.forMap(destination.mapId())
                            .standingPassable(destination.x(), destination.y())) {
                throw new IOException("CKEW stage destination contract changed item="
                        + itemId + " type=" + member.selectedCharacterType());
            }
        }
        for (ClientSession member : members) {
            member.serverClassicWorldCkewStageTeleport(
                    itemId, showId, ClassicWorldCkewCatalog.stageDestination(
                            itemId, member.selectedCharacterType()));
        }
    }

    private void useRentalTownItem(byte[] payload, RuntimeInventory.Item requested)
            throws IOException {
        Protocol.InventoryUse use = Protocol.defaultInventoryUse(payload);
        if (!use.argument().isEmpty()) {
            System.out.println("[LiTo] C_USE_ITEM rental-town rejected non-empty argument"
                    + " object=" + requested.objectId());
            return;
        }
        InventoryCatalog.Definition definition = requested.definition();
        if (!definition.weapon() && !definition.sourceArmor()) {
            System.out.println("[LiTo] C_USE_ITEM rental-town auxiliary ignored object="
                    + requested.objectId() + " catalog=" + definition.catalogId());
            return;
        }
        RuntimeInventory candidate = rentalTownInventory.copy();
        List<RuntimeInventory.Item> changes = definition.weapon()
                ? candidate.toggleWeapon(requested.objectId())
                : candidate.toggleNativeArmor(requested.objectId());
        if (changes.isEmpty()) {
            System.out.println("[LiTo] C_USE_ITEM rental-town equipment rejected object="
                    + requested.objectId() + " catalog=" + definition.catalogId());
            return;
        }
        NativeDeItemApplication.replace(this, candidate, 1);
        for (RuntimeInventory.Item changed : changes) {
            sendInventoryEquipmentState(changed, "rental-town-equipped");
        }
        resetAndSendRentalTownStatus();
        if (definition.weapon()) {
            int walkAction = rentalTownWalkAction();
            byte[] wield = Protocol.wield(playerObjectId(), walkAction);
            for (ClientSession member : rentalTownMembers()) {
                if (member != this && !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, positionX, positionY)) {
                    continue;
                }
                member.sendEncrypted(wield,
                        "S_WIELD rental-town player=" + playerName()
                                + " walk-action=" + walkAction);
            }
        }
        RentalEquipmentBonuses bonuses =
                RentalEquipmentBonuses.from(rentalTownInventory.items());
        System.out.println("[LiTo] C_USE_ITEM rental-town equipment object="
                + requested.objectId() + " catalog=" + definition.catalogId()
                + " equipped=" + rentalTownInventory.item(requested.objectId()).equipped()
                + " matched-items=" + bonuses.matchedItems()
                + " matched-weapons=" + bonuses.matchedWeapons()
                + " matched-armors=" + bonuses.matchedArmors());
    }

    private void serverClassicWorldCkewStageTeleport(
            long itemId, int showId,
            ClassicWorldCkewCatalog.Location landing) throws IOException {
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID
                || classicWorldInstanceId != showId || landing == null) return;

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        int removed = next.catalogCounts().getOrDefault(itemId, 0);
        if (removed > 0) {
            if (!next.removeCatalog(itemId, removed)) {
                throw new IOException("validated CKEW stack removal failed item=" + itemId);
            }
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            InventoryCatalog.Definition definition = InventoryCatalog.find(itemId);
            sendEncrypted(Protocol.messageCode(165,
                            definition == null ? Long.toString(itemId) : definition.name()),
                    "S_MESSAGE_CODE CKEW-stage-item-removed=165 item=" + itemId
                            + " count=" + removed + " show=" + showId);
            sendInventoryDelta(previous, inventory);
        }

        clearPendingClassicList();
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                landing.mapId(), landing.x(), landing.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, landing.heading(), 0,
                "CKEW-item-" + itemId + "-show-" + showId, showId);
        pendingPortal = destination;
        pendingPortalReady = true;

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT CKEW-stage target=" + playerObjectId()
                                + " item=" + itemId + " show=" + showId);
            }
        }
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL CKEW-stage item=" + itemId + " show=" + showId
                        + " class=" + selectedCharacterType() + " destination="
                        + destination.x() + "," + destination.y());
        System.out.println("[LiTo] C_USE_ITEM CKEW-stage accepted player="
                + playerName() + " item=" + itemId + " show=" + showId
                + " removed=" + removed + " destination=" + landing.x()
                + "," + landing.y() + " heading=" + landing.heading()
                + " result=awaiting-C_GOTO_PORTAL");
    }

    /** Exact retained 49167 cooperative show validation, stack removal and summons. */
    private void useClassicWorldCkewMagicFlute(RuntimeInventory.Item item)
            throws IOException {
        if (item == null || item.definition().catalogId()
                != ClassicWorldCkewCatalog.MAGIC_FLUTE) {
            throw new IOException("invalid CKEW magic flute object");
        }
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE CKEW-flute-outside-map=79");
            return;
        }

        int showId = classicWorldInstanceId;
        List<ClientSession> members = showId >= ClassicWorldCkewCatalog.FIRST_SHOW_ID
                ? hub.classicWorldMembers(ClassicWorldCkewCatalog.MAP_ID, showId)
                : List.of();
        List<Integer> characterTypes = members.stream()
                .map(ClientSession::selectedCharacterType).toList();
        boolean existingChino = hub.classicWorldCkewHasMonsterNpc(
                showId, ClassicWorldCkewCatalog.CHINO_NPC_IDS);
        if (!ClassicWorldCkewCatalog.exactNativeParty(characterTypes)
                || existingChino) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE CKEW-flute-invalid-show=79 show=" + showId
                            + " types=" + characterTypes
                            + " existing-chino=" + existingChino);
            if (showId >= ClassicWorldCkewCatalog.FIRST_SHOW_ID) {
                hub.endClassicWorldCkew(showId, "invalid-flute-show");
            }
            return;
        }

        Map<ClientSession, ClassicWorldCkewCatalog.Location> summonLocations =
                new LinkedHashMap<>();
        Set<Long> reservedCells = new LinkedHashSet<>();
        for (ClientSession member : members) {
            ClassicWorldCkewCatalog.Location location =
                    member.classicWorldCkewSummonLocation(showId, reservedCells);
            if (location == null) {
                throw new IOException("no CKEW flute summon location for "
                        + member.playerName());
            }
            summonLocations.put(member, location);
            reservedCells.add((Integer.toUnsignedLong(location.x()) << 32)
                    | Integer.toUnsignedLong(location.y()));
        }

        for (ClientSession member : members) {
            member.serverClassicWorldCkewRemoveMagicFlute(showId);
        }
        for (ClientSession member : members) {
            ClassicWorldCkewCatalog.Location location = summonLocations.get(member);
            int npcId = ClassicWorldCkewCatalog.characterClass(
                    member.selectedCharacterType()).chinoNpcId();
            ClassicWorldMonsterPopulation.Snapshot summon =
                    hub.spawnClassicWorldCkewMonster(
                            showId, npcId, location.x(), location.y(),
                            location.heading());
            if (summon == null) {
                hub.endClassicWorldCkew(showId, "flute-spawn-failed");
                throw new IOException("CKEW flute summon failed npc=" + npcId);
            }
            byte[] effect = Protocol.effectLocation(
                    summon.x(), summon.y(), ClassicWorldCkewCatalog.MAGIC_FLUTE_GFX);
            for (ClientSession recipient : members) {
                if (Math.max(Math.abs(recipient.positionX - summon.x()),
                        Math.abs(recipient.positionY - summon.y()))
                        <= ClassicWorldCkewCatalog.MAGIC_FLUTE_EFFECT_RANGE) {
                    recipient.sendEncrypted(effect,
                            "S_EFFECT_LOC CKEW-flute show=" + showId
                                    + " npc=" + npcId + " x=" + summon.x()
                                    + " y=" + summon.y() + " gfx="
                                    + ClassicWorldCkewCatalog.MAGIC_FLUTE_GFX);
                }
                recipient.serverClassicWorldMonsterSpawned(summon);
            }
        }
        System.out.println("[LiTo] C_USE_ITEM CKEW-flute accepted player="
                + playerName() + " show=" + showId + " summons=" + members.size());
    }

    private ClassicWorldCkewCatalog.Location classicWorldCkewSummonLocation(int n, Set<Long> set) {
        ClassicWorldMapCatalog.ClassicMap classicMap = ClassicWorldMapCatalog.forMap(2000);
        int n2 = ThreadLocalRandom.current().nextInt(25);
        List<ClientSession> list = this.hub.classicWorldMembers(2000, n);
        for (int i = 0; i < 25; ++i) {
            int n3 = (n2 + i) % 25;
            int n4 = this.positionX + n3 % 5 - 2;
            int n5 = this.positionY + n3 / 5 - 2;
            long l = Integer.toUnsignedLong(n4) << 32 | Integer.toUnsignedLong(n5);
            if (set.contains(l) || !classicMap.standingPassable(n4, n5) || NativeStaticNpcMotion.occupies(2000, n4, n5, this) || this.hub.classicWorldMonsterOccupies(2000, n, n4, n5) || list.stream().anyMatch(clientSession -> clientSession.positionX == n4 && clientSession.positionY == n5)) continue;
            return new ClassicWorldCkewCatalog.Location(2000, n4, n5, this.playerHeading);
        }
        return null;
    }

    private void serverClassicWorldCkewRemoveMagicFlute(int n) throws IOException {
        if (this.phase != Phase.WORLD || this.classicWorldMapId != 2000 || this.classicWorldInstanceId != n) {
            return;
        }
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        int n2 = runtimeInventory2.catalogCounts().getOrDefault(49167L, 0);
        if (n2 <= 0) {
            return;
        }
        if (!runtimeInventory2.removeCatalog(49167L, n2)) {
            throw new IOException("validated CKEW flute stack removal failed");
        }
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, runtimeInventory2.catalogCounts(), runtimeInventory2.catalogItemStates());
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        this.sendEncrypted(Protocol.messageCode(165, "$5587"), "S_MESSAGE_CODE CKEW-flute-removed=165 count=" + n2 + " show=" + n);
        this.sendInventoryDelta(runtimeInventory, this.inventory);
    }

    /** Exact retained CKEWLv50Medicine executor for quest122 item49168. */
    private void useClassicWorldCkewDestructionMedicine(
            RuntimeInventory.Item medicine) throws IOException {
        if (medicine == null || medicine.definition().catalogId()
                != ClassicWorldCkewCatalog.DESTRUCTION_POTION) {
            throw new IOException("invalid CKEW destruction medicine capability");
        }
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE CKEW-destruction-medicine-outside-map=79");
            return;
        }

        int characterType = selectedCharacterType();
        boolean sourceWeaponActive = !sourceWeaponSuppressed
                && sourceEquipmentMagicStats != null
                && sourceEquipmentMagicStats.physical().weapon().present();
        boolean forceUnequip = characterType != 0
                && (inventory.hasEquippedWeapon() || sourceWeaponActive);
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        List<RuntimeInventory.Item> unequipped = forceUnequip
                ? next.unequipWeapons() : List.of();
        if (!next.remove(medicine.objectId(), 1)) return;

        boolean previousSourceWeaponSuppressed = sourceWeaponSuppressed;
        try {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            if (forceUnequip) sourceWeaponSuppressed = true;
        } catch (IOException | RuntimeException failure) {
            NativeDeItemApplication.replace(this, previous, 0);
            sourceWeaponSuppressed = previousSourceWeaponSuppressed;
            throw failure;
        }

        // Retained executor removes these in this exact order before replacing
        // 4007 with the 1,500,000 ms quest lease.
        storySkillEffectDeadlines.remove(4003);
        storySkillEffectDeadlines.remove(4006);
        storySkillEffectDeadlines.remove(4005);
        storySkillEffectDeadlines.remove(4007);
        long nowNanos = System.nanoTime();
        storySkillEffectDeadlines.put(
                ClassicWorldCkewCatalog.DESTRUCTION_MEDICINE_EFFECT,
                nowNanos + ClassicWorldCkewCatalog
                        .DESTRUCTION_MEDICINE_DURATION_MILLIS * 1_000_000L);

        if (forceUnequip) {
            removeCounterBarrierUnlessTwoHand("CKEW-destruction-medicine");
            for (RuntimeInventory.Item changed : unequipped) {
                sendInventoryEquipmentState(
                        changed, "CKEW-destruction-medicine-forced-unequip");
            }
            broadcastWieldState();
            sendEncrypted(Protocol.messageCode(1027),
                    "S_MESSAGE_CODE CKEW-destruction-medicine-unequip=1027");
        }

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldCkewCatalog.DESTRUCTION_MEDICINE_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (Math.max(Math.abs(member.positionX - positionX),
                    Math.abs(member.positionY - positionY)) <= 8) {
                member.sendEncrypted(effect,
                        "S_EFFECT CKEW-destruction-medicine target="
                                + playerObjectId() + " gfx="
                                + ClassicWorldCkewCatalog.DESTRUCTION_MEDICINE_GFX);
            }
        }
        sendEncrypted(Protocol.messageCode(1300),
                "S_MESSAGE_CODE CKEW-destruction-medicine-active=1300");
        // removeItem(item, 1) is last in the retained executor.
        sendInventoryDelta(previous, inventory);
        System.out.println("[LiTo] C_USE_ITEM CKEW-destruction-medicine player="
                + playerName() + " show=" + classicWorldInstanceId
                + " type=" + characterType + " forced-unequip=" + forceUnequip
                + " effect=4007 duration-ms="
                + ClassicWorldCkewCatalog.DESTRUCTION_MEDICINE_DURATION_MILLIS);
    }

    private int classicWorldMainlandShipSecondsOfDay() {
        return config.classicWorldShipFixtureSecondOfDay() >= 0
                ? config.classicWorldShipFixtureSecondOfDay()
                : ClassicLineageClock.nativeClientSecondOfDay(
                        ClassicLineageClock.now());
    }

    private int classicWorldMainlandShipSecondsOfDay(
            ClassicWorldShipSchedule.Window window) {
        if (config.classicWorldShipFixtureWindowOpening()) {
            return window.openingSecond();
        }
        return classicWorldMainlandShipSecondsOfDay();
    }

    private int classicWorldPirateShipSecondsOfDay() {
        return config.classicWorldPirateShipFixtureSecondOfDay() >= 0
                ? config.classicWorldPirateShipFixtureSecondOfDay()
                : ClassicLineageClock.nativeClientSecondOfDay(
                        ClassicLineageClock.now());
    }

    void serverClassicWorldShipDeparture() throws IOException {
        ClassicWorldShipDepartureCatalog.Departure departure = ClassicWorldShipDepartureCatalog.find(this.classicWorldMapId);
        if (departure == null) {
            return;
        }
        int n = departure.sourceMapId() == 447 ? this.classicWorldPirateShipSecondsOfDay() : this.classicWorldMainlandShipSecondsOfDay();
        this.serverClassicWorldShipDeparture(n);
    }

    void serverClassicWorldShipDeparture(int n) throws IOException {
        ClassicWorldShipSchedule.requireSecondsOfDay(n);
        ClassicWorldShipDepartureCatalog.Departure departure = ClassicWorldShipDepartureCatalog.find(this.classicWorldMapId);
        if (this.phase != Phase.WORLD || this.observer || this.playerHp <= 0 || departure == null || !departure.openAt(n) || this.hub.classicWorldLocation(this) == null || this.pendingPortal != null || this.movementLockPending) {
            return;
        }
        if (!ClassicWorldMapCatalog.forMap(departure.destinationMapId()).standingPassable(departure.destinationX(), departure.destinationY())) {
            throw new IOException("classic-world timed ship landing is not passable");
        }
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        if (!runtimeInventory2.removeCatalog(departure.ticketCatalogId(), 1L)) {
            return;
        }
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, runtimeInventory2.catalogCounts(), runtimeInventory2.catalogItemStates());
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        this.sendInventoryDelta(runtimeInventory, this.inventory);
        this.clearPendingClassicList();
        this.pendingCallClanPortal = null;
        this.pendingRunClanPortal = null;
        Protocol.PortalDestination portalDestination = new Protocol.PortalDestination(departure.destinationMapId(), departure.destinationX(), departure.destinationY(), true);
        this.pendingClassicWorldPortal = new PendingClassicWorldPortal(portalDestination, departure.destinationHeading(), 0L, "timed-native-ship-departure-" + departure.sourceMapId());
        this.pendingPortal = portalDestination;
        this.pendingPortalReady = true;
        this.sendEncrypted(Protocol.portal(portalDestination.mapId(), portalDestination.x(), portalDestination.y()), "S_PORTAL timed-native-ship-departure source=" + departure.sourceMapId() + " target=" + portalDestination.mapId() + ":" + portalDestination.x() + "," + portalDestination.y() + " ticket=" + departure.ticketCatalogId() + " consumed=true seconds-of-day=" + n);
        System.out.println("[LiTo] native timed ship departure player=" + this.playerName() + " source=" + departure.sourceMapId() + " target=" + portalDestination.mapId() + ":" + portalDestination.x() + "," + portalDestination.y() + " ticket=" + departure.ticketCatalogId() + " consumed=true result=awaiting-C_GOTO_PORTAL");
    }

    private void gotoMap(byte[] payload) throws IOException {
        Protocol.GotoMapRequest request = Protocol.gotoMapRequest(payload);
        if (request.cancelled()) {
            pendingShipTicket = null;
            System.out.println("[LiTo] C_GOTO_MAP native cancellation");
            return;
        }

        PendingShipTicket pending = pendingShipTicket;
        pendingShipTicket = null;
        if (phase == Phase.WORLD) {
            gotoClassicWorldShip(request, pending);
            return;
        }
        if (phase != Phase.BATTLE || observer || playerHp <= 0 || currentRoomId == 0) {
            System.out.println("[LiTo] C_GOTO_MAP rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        int sourceMap = hub.battleMapId(currentRoomId, this);
        ShipRouteCatalog.Route route = ShipRouteCatalog.resolve(
                sourceMap, request.destinationMap(), request.x(), request.y());
        if (route == null) {
            System.out.println("[LiTo] C_GOTO_MAP rejected route source=" + sourceMap
                    + " destination=" + request.destinationMap()
                    + " x=" + request.x() + " y=" + request.y());
            return;
        }
        RuntimeInventory.Item ticket = pending == null
                ? null : inventory.item(pending.inventoryObjectId());
        long now = System.nanoTime();
        if (pending == null || pending.interactionContext() != currentRoomId
                || pending.sourceMap() != sourceMap
                || pending.expiresAtNanos() < now
                || pending.catalogId() != route.ticketCatalogId()
                || ticket == null || ticket.definition().catalogId() != route.ticketCatalogId()) {
            System.out.println("[LiTo] C_GOTO_MAP rejected ticket source=" + sourceMap
                    + " required=" + route.ticketCatalogId());
            return;
        }

        // LiTo Tournament rooms are authoritative 500-series instances. The
        // four exact ship source maps are classic-world maps and therefore
        // cannot be entered through a room. Keep this final guard explicit so
        // the embedded Lineage packet cannot split one room across worlds.
        System.out.println("[LiTo] C_GOTO_MAP rejected classic-world route in Tournament room"
                + " source=" + sourceMap + " destination=" + request.destinationMap());
    }

    private void gotoClassicWorldShip(
            Protocol.GotoMapRequest request, PendingShipTicket pending)
            throws IOException {
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)
                || hub.classicWorldLocation(this) == null) {
            System.out.println("[LiTo] C_GOTO_MAP classic-world rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp
                    + " map=" + classicWorldMapId);
            return;
        }
        if (pendingPortal != null || movementLockPending
                || hub.hasPrivateShop(this)
                || rejectWhileParalyzed("C_GOTO_MAP")) {
            System.out.println("[LiTo] C_GOTO_MAP classic-world rejected"
                    + " transition-or-shop-pending player=" + playerName());
            return;
        }

        int sourceMap = classicWorldMapId;
        ShipRouteCatalog.Route route = ShipRouteCatalog.resolve(
                sourceMap, request.destinationMap(), request.x(), request.y());
        if (route == null) {
            System.out.println("[LiTo] C_GOTO_MAP classic-world rejected route source="
                    + sourceMap + " destination=" + request.destinationMap()
                    + " x=" + request.x() + " y=" + request.y());
            return;
        }
        RuntimeInventory.Item ticket = pending == null
                ? null : inventory.item(pending.inventoryObjectId());
        long now = System.nanoTime();
        if (pending == null
                || pending.interactionContext() != activeInteractionContext()
                || pending.sourceMap() != sourceMap
                || pending.expiresAtNanos() < now
                || pending.catalogId() != route.ticketCatalogId()
                || ticket == null
                || ticket.definition().catalogId() != route.ticketCatalogId()) {
            System.out.println("[LiTo] C_GOTO_MAP classic-world rejected ticket source="
                    + sourceMap + " required=" + route.ticketCatalogId());
            return;
        }
        int secondsOfDay = classicWorldMainlandShipSecondsOfDay(route.schedule());
        if (!route.openAt(secondsOfDay)) {
            System.out.println("[LiTo] C_GOTO_MAP classic-world rejected closed-schedule"
                    + " source=" + sourceMap + " seconds-of-day=" + secondsOfDay);
            return;
        }
        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(route.destinationMap());
        ArenaMapCatalog.Point landing = classicWorldShipLanding(
                route, destinationMap, request.x(), request.y());

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.remove(ticket.objectId(), 1)) {
            System.out.println("[LiTo] C_GOTO_MAP classic-world rejected vanished-ticket="
                    + ticket.objectId());
            return;
        }
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);

        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                route.destinationMap(), landing.x(), landing.y(), true);
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, 0, 0, "native-ship-exit-" + sourceMap);
        pendingPortal = destination;
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL native-ship-exit source=" + sourceMap
                        + " target=" + destination.mapId() + ":"
                        + destination.x() + "," + destination.y()
                        + " requested=" + request.x() + "," + request.y()
                        + " ticket=" + route.ticketCatalogId()
                        + " consumed=true seconds-of-day=" + secondsOfDay);
        System.out.println("[LiTo] C_GOTO_MAP classic-world accepted player="
                + playerName() + " source=" + sourceMap + " target="
                + destination.mapId() + ":" + destination.x() + ","
                + destination.y() + " requested=" + request.x() + ","
                + request.y() + " ticket=" + route.ticketCatalogId()
                + " consumed=true result=awaiting-C_GOTO_PORTAL");
    }

    private ArenaMapCatalog.Point classicWorldShipLanding(
            ShipRouteCatalog.Route route,
            ClassicWorldMapCatalog.ClassicMap destinationMap,
            int requestedX, int requestedY) throws IOException {
        if (destinationMap.standingPassable(requestedX, requestedY)) {
            return new ArenaMapCatalog.Point(requestedX, requestedY);
        }
        ArenaMapCatalog.Point best = null;
        int bestChebyshev = Integer.MAX_VALUE;
        int bestManhattan = Integer.MAX_VALUE;
        for (int x = route.minX(); x <= route.maxX(); x++) {
            for (int y = route.minY(); y <= route.maxY(); y++) {
                if (!destinationMap.standingPassable(x, y)) continue;
                int dx = Math.abs(x - requestedX);
                int dy = Math.abs(y - requestedY);
                int chebyshev = Math.max(dx, dy);
                int manhattan = dx + dy;
                if (chebyshev < bestChebyshev
                        || (chebyshev == bestChebyshev
                            && manhattan < bestManhattan)) {
                    best = new ArenaMapCatalog.Point(x, y);
                    bestChebyshev = chebyshev;
                    bestManhattan = manhattan;
                }
            }
        }
        if (best == null) {
            throw new IOException("classic-world native ship envelope has no passable landing");
        }
        return best;
    }

    private void enterShip(byte[] payload) throws IOException {
        Protocol.EnterShipRequest request = Protocol.enterShipRequest(payload);
        pendingShipTicket = null;
        if (phase == Phase.WORLD) {
            enterClassicWorldShip(request);
            return;
        }
        if (phase != Phase.BATTLE || observer || playerHp <= 0 || currentRoomId == 0) {
            System.out.println("[LiTo] C_ENTER_SHIP rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }

        ShipRouteCatalog.Boarding boarding = ShipRouteCatalog.boarding(request.selector());
        int sourceMap = hub.battleMapId(currentRoomId, this);
        if (boarding == null || !boarding.accepts(sourceMap, positionX, positionY)) {
            System.out.println("[LiTo] C_ENTER_SHIP rejected selector=" + request.selector()
                    + " source=" + sourceMap + " x=" + positionX + " y=" + positionY);
            return;
        }
        boolean hasTicket = inventory.items().stream().anyMatch(item ->
                item.definition().catalogId() == boarding.ticketCatalogId());
        if (!hasTicket) {
            System.out.println("[LiTo] C_ENTER_SHIP rejected missing-ticket="
                    + boarding.ticketCatalogId() + " source=" + sourceMap);
            return;
        }

        // The current product state is an authoritative Tournament instance,
        // while both proven boarding routes enter classic-world maps 5/6.
        // Do not consume the ticket or feed these destinations into the arena
        // rebuild handshake until a separate classic-world session exists.
        System.out.println("[LiTo] C_ENTER_SHIP rejected classic-world route in Tournament room"
                + " source=" + sourceMap + " destination=" + boarding.destinationMap());
    }

    private void enterClassicWorldShip(Protocol.EnterShipRequest request)
            throws IOException {
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)
                || hub.classicWorldLocation(this) == null) {
            System.out.println("[LiTo] C_ENTER_SHIP classic-world rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp
                    + " map=" + classicWorldMapId);
            return;
        }
        if (pendingPortal != null || movementLockPending
                || hub.hasPrivateShop(this)
                || rejectWhileParalyzed("C_ENTER_SHIP")) {
            System.out.println("[LiTo] C_ENTER_SHIP classic-world rejected"
                    + " transition-or-shop-pending player=" + playerName());
            return;
        }
        ShipRouteCatalog.Boarding boarding =
                ShipRouteCatalog.boarding(request.selector());
        if (boarding == null
                || !boarding.accepts(classicWorldMapId, positionX, positionY)) {
            System.out.println("[LiTo] C_ENTER_SHIP classic-world rejected selector="
                    + request.selector() + " source=" + classicWorldMapId
                    + " x=" + positionX + " y=" + positionY);
            return;
        }
        if (inventory.catalogCounts().getOrDefault(
                boarding.ticketCatalogId(), 0) <= 0) {
            System.out.println("[LiTo] C_ENTER_SHIP classic-world rejected missing-ticket="
                    + boarding.ticketCatalogId() + " source=" + classicWorldMapId);
            return;
        }
        int secondsOfDay = classicWorldMainlandShipSecondsOfDay(boarding.schedule());
        if (!boarding.openAt(secondsOfDay)) {
            System.out.println("[LiTo] C_ENTER_SHIP classic-world rejected closed-schedule"
                    + " selector=" + boarding.selector()
                    + " seconds-of-day=" + secondsOfDay);
            return;
        }
        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(boarding.destinationMap());
        if (!destinationMap.standingPassable(
                boarding.destinationX(), boarding.destinationY())) {
            throw new IOException("classic-world native ship boarding is not passable");
        }

        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                boarding.destinationMap(), boarding.destinationX(),
                boarding.destinationY(), true);
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, boarding.destinationHeading(), 0,
                "native-ship-boarding-" + boarding.selector());
        pendingPortal = destination;
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL native-ship-boarding selector=" + boarding.selector()
                        + " source=" + classicWorldMapId
                        + " target=" + destination.mapId() + ":"
                        + destination.x() + "," + destination.y()
                        + " animation-state=" + boarding.clientAnimationState()
                        + " ticket=" + boarding.ticketCatalogId()
                        + " consumed=false seconds-of-day=" + secondsOfDay);
        System.out.println("[LiTo] C_ENTER_SHIP classic-world accepted player="
                + playerName() + " selector=" + boarding.selector()
                + " source=" + classicWorldMapId + " target="
                + destination.mapId() + ":" + destination.x() + ","
                + destination.y() + " heading=" + boarding.destinationHeading()
                + " ticket=" + boarding.ticketCatalogId()
                + " consumed=false result=awaiting-C_GOTO_PORTAL");
    }

    private void enterPortal(byte[] payload) throws IOException {
        Protocol.EnterPortalRequest request = Protocol.enterPortalRequest(payload);
        if (phase == Phase.WORLD) {
            enterClassicWorldPortal(request);
            return;
        }
        if (rentalTownRoomState) {
            enterRentalTownPortal(request);
            return;
        }
        if (phase != Phase.BATTLE || observer || playerHp <= 0 || currentRoomId == 0) {
            System.out.println("[LiTo] C_ENTER_PORTAL rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        if (pendingPortal != null || movementLockPending
                || rejectWhileParalyzed("C_ENTER_PORTAL")) {
            System.out.println("[LiTo] C_ENTER_PORTAL rejected transition-pending player="
                    + playerName());
            return;
        }

        int sourceMap = hub.battleMapId(currentRoomId, this);
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(sourceMap);
        int distance = Math.max(Math.abs(request.x() - positionX),
                Math.abs(request.y() - positionY));
        if (distance > 3 || !arena.contains(request.x(), request.y())) {
            System.out.println("[LiTo] C_ENTER_PORTAL rejected coordinates source=" + sourceMap
                    + " requested=" + request.x() + "," + request.y()
                    + " player=" + positionX + "," + positionY);
            return;
        }

        ArenaPortalCatalog.Route route = ArenaPortalCatalog.find(
                sourceMap, request.x(), request.y());
        if (route == null) {
            System.out.println("[LiTo] C_ENTER_PORTAL rejected unknown native Layer7 source="
                    + sourceMap + ":" + request.x() + "," + request.y());
            return;
        }
        // All current Tournament Layer7 destinations stay inside their source
        // arena.  Keep that authoritative-room invariant explicit so a future
        // cross-map resource cannot silently split a running match.
        if (route.targetMapId() != sourceMap) {
            System.out.println("[LiTo] C_ENTER_PORTAL rejected cross-arena native route source="
                    + sourceMap + " destination=" + route.targetMapId());
            return;
        }
        // Do not consult route.rawTag() here.  The exact C_ENTER_PORTAL wire
        // contains only source X/Y; current resource classification also pins
        // all four Quest routes to NO_TAG.  Siege role authorization is
        // independent server-owned match state, not an interpretation of the
        // opaque Layer7 suffix.
        if (!hub.canUseGroundPortal(currentRoomId, this)) {
            System.out.println("[LiTo] C_ENTER_PORTAL rejected Siege attacker route player="
                    + playerName() + " force=" + hub.forceOf(currentRoomId, this)
                    + " source=" + sourceMap + ":" + request.x() + "," + request.y());
            return;
        }

        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
        pendingPortal = new Protocol.PortalDestination(route.targetMapId(),
                route.target().x(), route.target().y(), true);
        // Ground portals are already approved by the native tile/reachability
        // check and the server's exact source lookup.  Unlike C_TELEPORT and
        // C_TELEPORT_USER, sub_48BFA0 does not enter the summon-readiness
        // exchange: S_PORTAL is immediate, followed by opcode-only C_GOTO_PORTAL.
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(route.targetMapId(),
                        route.target().x(), route.target().y()),
                "S_PORTAL ground player=" + playerName()
                        + " source=" + sourceMap + ":" + request.x() + "," + request.y()
                        + " target=" + route.targetMapId() + ":"
                        + route.target().x() + "," + route.target().y()
                        + " raw-tag=" + route.rawTag());
        System.out.println("[LiTo] C_ENTER_PORTAL accepted native Layer7 player="
                + playerName() + " source=" + sourceMap + ":"
                + request.x() + "," + request.y() + " target="
                + route.targetMapId() + ":" + route.target().x() + ","
                + route.target().y() + " raw-tag=" + route.rawTag()
                + " result=awaiting-C_GOTO_PORTAL");
    }

    private void enterRentalTownPortal(Protocol.EnterPortalRequest request)
            throws IOException {
        if (phase != Phase.BATTLE || observer || playerHp <= 0
                || currentRoomId == 0 || pendingPortal != null
                || movementLockPending || rejectWhileParalyzed("C_ENTER_PORTAL")) {
            System.out.println("[LiTo] C_ENTER_PORTAL rental-town rejected state player="
                    + playerName() + " phase=" + phase + " map=" + rentalTownMapId);
            return;
        }
        int distance = Math.max(Math.abs(request.x() - positionX),
                Math.abs(request.y() - positionY));
        NativeLitoTownPortalCatalog.Route route = NativeLitoTownPortalCatalog.find(
                rentalTownMapId, request.x(), request.y());
        if (distance > 3 || route == null
                || route.targetMapId() != rentalTownMapId
                || !NativeLitoTownPassabilityCatalog.get().isStandingPassable(
                        route.targetMapId(), route.target().x(), route.target().y())) {
            System.out.println("[LiTo] C_ENTER_PORTAL rental-town rejected source="
                    + rentalTownMapId + ":" + request.x() + "," + request.y()
                    + " player=" + positionX + "," + positionY
                    + " distance=" + distance);
            return;
        }
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
        pendingPortal = new Protocol.PortalDestination(
                route.targetMapId(), route.target().x(), route.target().y(), true);
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(route.targetMapId(),
                        route.target().x(), route.target().y()),
                "S_PORTAL rental-town source=" + route.sourceMapId() + ":"
                        + route.source().x() + "," + route.source().y()
                        + " target=" + route.targetMapId() + ":"
                        + route.target().x() + "," + route.target().y()
                        + " slot=" + route.slotName() + " raw-tag=" + route.rawTag());
        System.out.println("[LiTo] C_ENTER_PORTAL rental-town accepted player="
                + playerName() + " slot=" + route.slotName()
                + " result=awaiting-C_GOTO_PORTAL");
    }

    /**
     * Handles imported retained dungeon rows through the selected client's
     * generic {@code C_ENTER_PORTAL chh} producer. Pirate rows additionally
     * enforce ticket 40302 and the repeating retained sailing window; ordinary
     * rows such as map4/map17 are always open and item-free.
     */
    private void enterClassicWorldPortal(Protocol.EnterPortalRequest request)
            throws IOException {
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)
                || hub.classicWorldLocation(this) == null) {
            System.out.println("[LiTo] C_ENTER_PORTAL classic-world rejected phase="
                    + phase + " observer=" + observer + " hp=" + playerHp
                    + " map=" + classicWorldMapId);
            return;
        }
        if (pendingPortal != null || movementLockPending
                || hub.hasPrivateShop(this)
                || rejectWhileParalyzed("C_ENTER_PORTAL")) {
            System.out.println("[LiTo] C_ENTER_PORTAL classic-world rejected"
                    + " transition-or-shop-pending player=" + playerName());
            return;
        }

        ClassicWorldMapCatalog.ClassicMap sourceMap =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        int distance = Math.max(Math.abs(request.x() - positionX),
                Math.abs(request.y() - positionY));
        if (distance > 3 || !sourceMap.contains(request.x(), request.y())) {
            System.out.println("[LiTo] C_ENTER_PORTAL classic-world rejected coordinates source="
                    + classicWorldMapId + " requested=" + request.x() + "," + request.y()
                    + " player=" + positionX + "," + positionY);
            return;
        }

        ClassicWorldDungeonCatalog.Route route = ClassicWorldDungeonCatalog.find(
                classicWorldMapId, request.x(), request.y());
        if (route == null) {
            System.out.println("[LiTo] C_ENTER_PORTAL classic-world rejected unknown source="
                    + classicWorldMapId + ":" + request.x() + "," + request.y());
            return;
        }
        int secondsOfDay = route.scheduledPirateShip()
                ? classicWorldPirateShipSecondsOfDay()
                : classicWorldMainlandShipSecondsOfDay(route.schedule());
        if (!route.openAt(secondsOfDay)) {
            System.out.println("[LiTo] C_ENTER_PORTAL classic-world rejected closed-schedule"
                    + " route=" + route.routeId() + " seconds-of-day=" + secondsOfDay);
            return;
        }
        if (route.requiredItemCatalogId() != 0
                && inventory.catalogCounts().getOrDefault(
                        route.requiredItemCatalogId(), 0) <= 0) {
            System.out.println("[LiTo] C_ENTER_PORTAL classic-world rejected missing-ticket="
                    + route.requiredItemCatalogId() + " route=" + route.routeId());
            return;
        }

        if (!ClassicWorldDungeonCatalog.destinationLandingSafe(route)) {
            throw new IOException("classic-world dungeon destination is stranded");
        }

        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                route.destinationMapId(), route.destinationX(),
                route.destinationY(), true);
        int destinationInstanceId =
                classicWorldMapId == ClassicWorldWaterDragonCatalog.MAP_ID
                        && route.destinationMapId()
                            == ClassicWorldWaterDragonCatalog.MAP_ID
                        && classicWorldInstanceId > 0
                        ? classicWorldInstanceId : -1;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, route.destinationHeading(), 0,
                "ground-dungeon-route-" + route.routeId(),
                destinationInstanceId);
        pendingPortal = destination;
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL classic-world-ground route=" + route.routeId()
                        + " source=" + classicWorldMapId + ":" + request.x() + ","
                        + request.y() + " target=" + destination.mapId() + ":"
                        + destination.x() + "," + destination.y()
                        + " ticket=" + route.requiredItemCatalogId()
                        + " consumed=false seconds-of-day=" + secondsOfDay);
        System.out.println("[LiTo] C_ENTER_PORTAL classic-world accepted player="
                + playerName() + " route=" + route.routeId() + " source="
                + classicWorldMapId + ":" + request.x() + "," + request.y()
                + " target=" + destination.mapId() + ":" + destination.x() + ","
                + destination.y() + " ticket=" + route.requiredItemCatalogId()
                + " consumed=false result=awaiting-C_GOTO_PORTAL");
    }

    private void usePolymorphScroll(RuntimeInventory.Item item, String selection)
            throws IOException {
        Phase originPhase = phase;
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        if ((originPhase != Phase.BATTLE && originPhase != Phase.WORLD)
                || observer || playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM polymorph rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }

        String requested = selection == null ? "" : selection.trim();
        BattlePolymorphCatalog.Form form = BattlePolymorphCatalog.find(requested);
        if (!requested.isEmpty() && form == null) {
            System.out.println("[LiTo] C_USE_ITEM polymorph rejected unknown selection="
                    + requested);
            return;
        }
        if (form != null && characterLevel() < form.minimumLevel()) {
            System.out.println("[LiTo] C_USE_ITEM polymorph rejected level=" + characterLevel()
                    + " required=" + form.minimumLevel() + " selection=" + form.selection());
            return;
        }

        RuntimeInventory previousInventory;
        BattlePolymorphCatalog.Form previousForm;
        PolymorphEquipmentChange equipmentChange;
        int duration = BattlePolymorphCatalog.scrollDurationSeconds(
                item.blessing());
        long nowNanos = System.nanoTime();
        synchronized (this) {
            boolean contextStillValid = originPhase == Phase.BATTLE
                    ? phase == Phase.BATTLE && currentRoomId == originRoomId
                    : originPhase == Phase.WORLD && phase == Phase.WORLD
                        && classicWorldMapId == originMapId
                        && classicWorldInstanceId == originInstanceId;
            if (!contextStillValid || observer || playerHp <= 0) return;
            previousInventory = inventory.copy();
            if (!inventory.remove(item.objectId(), 1)) return;
            equipmentChange = PolymorphEquipmentChange.none();
            if (form == null) {
                previousForm = polymorphStatus.clear();
            } else {
                previousForm = polymorphStatus.active(nowNanos);
                polymorphStatus.activate(nowNanos, form, duration);
                equipmentChange = preparePolymorphEquipment(form);
            }
        }
        cancelAbsoluteBarrier("item-polymorph");
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());

        publishPolymorphEquipmentChange(equipmentChange, "scroll-polymorph");
        if (form != null || previousForm != null) {
            broadcastPolymorphAppearance(form == null ? "scroll-cancel" : "scroll-activate");
        }
        System.out.println("[LiTo] C_USE_ITEM polymorph object=" + item.objectId()
                + " selection=" + (form == null ? "base" : form.selection())
                + " gfx=" + battleGfx() + " walk-action=" + battleWalkAction()
                + " duration=" + (form == null ? 0 : duration));
    }

    private void useCookingItem(RuntimeInventory.Item item) throws IOException {
        if (phase != Phase.BATTLE || observer || playerHp <= 0) {
            System.out.println("[LiTo] C_USE_ITEM cooking rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        BattleCookingCatalog.Recipe recipe = BattleCookingCatalog.require(
                item.definition().catalogId());
        CharacterSummary character = selectedCharacterSummary();
        int food = character == null ? 40 : character.food();
        if (recipe.dessert() && food != 225) {
            // Same-family S_ServerMessage(74): dessert requires full satiety.
            sendEncrypted(Protocol.messageCode(74, item.definition().detail()),
                    "S_MESSAGE_CODE cooking-dessert-rejected=74 catalog="
                            + recipe.catalogId() + " food=" + food);
            return;
        }
        RuntimeInventory previousInventory = inventory.copy();

        long nowNanos = System.nanoTime();
        BattleCookingCatalog.Recipe previousCooking = cookingStatus.remove(recipe.slot());
        if (previousCooking != null) {
            applyCookingTransition(previousCooking, null, nowNanos,
                    "cooking-replaced-remove");
        }
        cookingStatus.activate(nowNanos, recipe, recipe.durationSeconds());
        applyCookingTransition(null, recipe, nowNanos, "cooking-active");

        // Same-family S_ServerMessage(76, item.getNumberedName(1, true)).
        sendEncrypted(Protocol.messageCode(76, item.definition().detail()),
                "S_MESSAGE_CODE cooking-consumed=76 catalog=" + recipe.catalogId());
        // L1Cooking removes the item after applying the status and message.
        if (!inventory.remove(item.objectId(), 1)) {
            throw new IllegalStateException("cooking item vanished before consumption");
        }
        cancelAbsoluteBarrier("item-cooking");
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        // The legacy cooking icon is S_PacketBox subtype 53. LiTo opcode FA
        // is S_LITO_CLAN, therefore no guessed or incompatible icon follows.
        System.out.println("[LiTo] C_USE_ITEM cooking object=" + item.objectId()
                + " catalog=" + recipe.catalogId() + " status=" + recipe.statusId()
                + " type=" + recipe.cookingType() + " slot=" + recipe.slot()
                + " duration=" + recipe.durationSeconds()
                + " max-hp=" + recipe.maxHp() + " max-mp=" + recipe.maxMp()
                + " ac=" + recipe.armorClass()
                + " all-element=" + recipe.allElementResistance()
                + " mr=" + recipe.magicResistance()
                + " hpr=" + recipe.hpRegen() + " mpr=" + recipe.mpRegen()
                + " sp=" + recipe.spellPower()
                + " melee-hit=" + recipe.meleeHit()
                + " melee-damage=" + recipe.meleeDamage()
                + " ranged-hit=" + recipe.rangedHit()
                + " ranged-damage=" + recipe.rangedDamage()
                + " reduction=" + recipe.damageReduction()
                + " exp-percent=" + recipe.experiencePercent()
                + " replaced=" + (previousCooking == null
                    ? "none" : previousCooking.statusId()));
    }

    private void useCookingFuel(RuntimeInventory.Item item) throws IOException {
        if (phase != Phase.BATTLE || observer || playerHp <= 0 || currentRoomId == 0) {
            System.out.println("[LiTo] C_USE_ITEM cooking-fuel rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        if (characterLevel() < InventoryCatalog.COOKING_FUEL_MIN_LEVEL) {
            sendEncrypted(Protocol.messageCode(318,
                            Integer.toString(InventoryCatalog.COOKING_FUEL_MIN_LEVEL)),
                    "S_MESSAGE_CODE cooking-fuel-level=318 minimum="
                            + InventoryCatalog.COOKING_FUEL_MIN_LEVEL);
            return;
        }
        long nowNanos = System.nanoTime();
        GameHub.CookingFirePlacement placement = hub.placeCookingFire(
                currentRoomId, this, positionX, positionY, playerHeading & 7, nowNanos);
        if (placement.status() == GameHub.CookingFireStatus.NEARBY) {
            sendEncrypted(Protocol.messageCode(1162),
                    "S_MESSAGE_CODE cooking-fire-nearby=1162");
            return;
        }
        if (placement.status() != GameHub.CookingFireStatus.PLACED
                || placement.fire() == null) {
            System.out.println("[LiTo] C_USE_ITEM cooking-fuel rejected placement room="
                    + currentRoomId + " x=" + positionX + " y=" + positionY
                    + " heading=" + (playerHeading & 7));
            return;
        }

        RuntimeInventory previous = inventory.copy();
        if (!inventory.remove(item.objectId(), 1)) {
            throw new IllegalStateException("cooking fuel vanished before consumption");
        }
        cancelAbsoluteBarrier("item-cooking-fuel");
        BattleCookingFires.Fire fire = placement.fire();
        byte[] packet = Protocol.cookingFire(fire);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(packet,
                    "S_PUT_OBJECT cooking-fire=" + fire.objectId()
                            + " npc=" + BattleCookingFires.NPC_ID
                            + " gfx=" + BattleCookingFires.GFX
                            + " x=" + fire.x() + " y=" + fire.y());
        }
        sendInventoryDelta(previous, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        System.out.println("[LiTo] C_USE_ITEM cooking-fuel object=" + item.objectId()
                + " fire=" + fire.objectId() + " room=" + currentRoomId
                + " x=" + fire.x() + " y=" + fire.y()
                + " duration=" + BattleCookingFires.DURATION_SECONDS);
    }

    private void applyCookingTransition(BattleCookingCatalog.Recipe removed,
                                        BattleCookingCatalog.Recipe added,
                                        long nowNanos, String reason) throws IOException {
        int hpDelta = (added == null ? 0 : added.maxHp())
                - (removed == null ? 0 : removed.maxHp());
        int mpDelta = (added == null ? 0 : added.maxMp())
                - (removed == null ? 0 : removed.maxMp());
        if (hpDelta != 0) {
            playerMaxHp = NumericBreakthrough.clampVital(
                    Math.addExact((long) playerMaxHp, hpDelta));
            playerHp = Math.min(playerHp, playerMaxHp);
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(playerHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT " + reason + " player=" + playerHp
                            + "/" + playerMaxHp);
            broadcastOwnHitRatio(reason + "-max-hp");
        }
        if (mpDelta != 0) {
            playerMaxMp = NumericBreakthrough.clampVital(
                    Math.addExact((long) playerMaxMp, mpDelta));
            playerMp = Math.min(playerMp, playerMaxMp);
            sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                    "S_MANA_POINT " + reason + " player=" + playerMp
                            + "/" + playerMaxMp);
        }

        boolean statusRefresh = hpDelta != 0 || mpDelta != 0
                || (removed != null && (removed.armorClass() != 0
                    || removed.allElementResistance() != 0))
                || (added != null && (added.armorClass() != 0
                    || added.allElementResistance() != 0));
        if (statusRefresh) {
            sendNativeBattleStatus(nowNanos, reason);
        }

        boolean magicRefresh = (removed != null
                && (removed.spellPower() != 0 || removed.magicResistance() != 0))
                || (added != null
                && (added.spellPower() != 0 || added.magicResistance() != 0));
        if (magicRefresh) {
            sendMagicStatus(nowNanos, reason);
        }
    }

    private void broadcastPolymorphAppearance(String reason) throws IOException {
        int gfx = battleGfx();
        int walkAction = battleWalkAction();
        byte[] appearance = Protocol.polymorph(playerObjectId(), gfx, walkAction);
        Phase originPhase = phase;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY))) continue;
            member.sendEncrypted(appearance, "S_POLYMORPH object=" + playerObjectId()
                    + " gfx=" + gfx + " walk-action=" + walkAction
                    + " reason=" + reason + " phase=" + originPhase);
        }
    }

    /** Must be called while this session is locked. */
    private PolymorphEquipmentChange preparePolymorphEquipment(
            BattlePolymorphCatalog.Form form) {
        int currentWalkAction = currentWeaponWalkAction();
        if (form == null || form.supportsWalkAction(currentWalkAction)) {
            return PolymorphEquipmentChange.none();
        }
        List<RuntimeInventory.Item> changed = inventory.unequipWeapons();
        // The legacy database is a read-only source.  Suppress its immutable
        // equipped snapshot after the equivalent native forced takeoff so it
        // cannot silently reappear as the active weapon on the next attack.
        sourceWeaponSuppressed = true;
        removeCounterBarrierUnlessTwoHand("polymorph-forced-unequip");
        return new PolymorphEquipmentChange(changed, true);
    }

    private int currentWeaponWalkAction() {
        if (inventory.hasEquippedWeapon()) return inventory.equippedWalkAction();
        if (sourceWeaponSuppressed || sourceEquipmentMagicStats == null) {
            return BattleActionCodes.WALK;
        }
        SourceWeaponPhysicalStats source = sourceEquipmentMagicStats.physical().weapon();
        return source.present() ? source.walkAction() : BattleActionCodes.WALK;
    }

    private void publishPolymorphEquipmentChange(
            PolymorphEquipmentChange change, String reason) throws IOException {
        for (RuntimeInventory.Item item : change.items()) {
            sendInventoryEquipmentState(item, reason + "-forced-unequip");
        }
        if (change.wieldChanged()) broadcastWieldState();
    }

    private void broadcastWieldState() throws IOException {
        broadcastWieldState(battleWalkAction(), "equipment-change");
    }

    private void broadcastWieldState(int requestedWalkAction, String reason)
            throws IOException {
        int walkAction = BattleAnimationCatalog.get().resolveEquippedWalkAction(
                battleGfx(), requestedWalkAction);
        byte[] wield = Protocol.wield(playerObjectId(), walkAction);
        Phase originPhase = phase;
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY))) {
                continue;
            }
            member.sendEncrypted(wield, "S_WIELD object=" + playerObjectId()
                    + " walk-action=" + walkAction + " reason=" + reason);
        }
    }

    private void broadcastLightState(String reason) throws IOException {
        int lightRange = battleLightRange();
        byte[] light = Protocol.changeLight(playerObjectId(), lightRange);
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY))) continue;
            member.sendEncrypted(light, "S_CHANGE_LIGHT object=" + playerObjectId()
                    + " range=" + lightRange + " reason=" + reason);
        }
    }

    /** Retained turnOnOffLight publication for the C_GIVE target. */
    private void broadcastGivenTargetLight(
            long targetObjectId, int targetX, int targetY,
            int lightRange, String reason) throws IOException {
        byte[] light = Protocol.changeLight(targetObjectId, lightRange);
        boolean world = phase == Phase.WORLD;
        List<ClientSession> recipients = world
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (world && (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY))) continue;
            member.sendEncrypted(light, "S_CHANGE_LIGHT object=" + targetObjectId
                    + " range=" + lightRange + " reason=" + reason);
        }
    }

    private void publishCompanionGivenItemUse(BattleCompanion.GivenItemReceipt givenItemReceipt) throws IOException {
        if (givenItemReceipt == null || givenItemReceipt.useKind() == BattleCompanion.GivenItemUseKind.NONE) {
            return;
        }
        BattleCompanion.Snapshot snapshot = givenItemReceipt.afterUse();
        boolean bl = this.phase == Phase.WORLD;
        List<ClientSession> list = bl ? this.classicWorldMembers(this.classicWorldMapId) : this.hub.roomMembers(this.currentRoomId);
        byte[] byArray = Protocol.effectObject(snapshot.objectId(), givenItemReceipt.effectGfx());
        for (ClientSession clientSession : list) {
            if (bl && (!this.sameClassicWorldMap(clientSession) || !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y()))) continue;
            if (givenItemReceipt.useKind() == BattleCompanion.GivenItemUseKind.HASTE) {
                clientSession.sendEncrypted(Protocol.speed(snapshot.objectId(), Protocol.SpeedMode.HASTE, clientSession == this ? givenItemReceipt.durationSeconds() : 0), "S_SPEED companion-onGetItem=" + snapshot.objectId() + " type=1 duration=" + (clientSession == this ? givenItemReceipt.durationSeconds() : 0));
            }
            clientSession.sendEncrypted(byArray, "S_EFFECT companion-onGetItem=" + snapshot.objectId() + " gfx=" + givenItemReceipt.effectGfx() + " kind=" + String.valueOf((Object)givenItemReceipt.useKind()) + " consumed=" + givenItemReceipt.consumedCatalogId());
        }
        if (givenItemReceipt.useKind() == BattleCompanion.GivenItemUseKind.HEAL && givenItemReceipt.appliedHp() != 0) {
            this.sendEncrypted(NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), snapshot.hp(), snapshot.maxHp()), "S_HIT_RATIO companion-onGetItem=" + snapshot.objectId() + " hp=" + snapshot.hp() + "/" + snapshot.maxHp());
        }
        System.out.println("[LiTo] C_GIVE companion onGetItem owner=" + this.playerName() + " target=" + snapshot.objectId() + " received=" + givenItemReceipt.receivedCatalogId() + " kind=" + String.valueOf((Object)givenItemReceipt.useKind()) + " consumed=" + givenItemReceipt.consumedCatalogId() + " gfx=" + givenItemReceipt.effectGfx() + " duration=" + givenItemReceipt.durationSeconds() + " hp-delta=" + givenItemReceipt.appliedHp());
    }

    private void setObserver(byte[] payload) throws IOException {
        Protocol.LitoObserverState requested = Protocol.litoObserverRequest(payload);
        if (phase != Phase.LOBBY && phase != Phase.CHANNEL && phase != Phase.ROOM) {
            System.out.println("[LiTo] C_LITO_SET_OBSERVER rejected phase=" + phase
                    + " requested=" + requested);
            return;
        }
        observer = requested.enabled();
        hub.observerChanged(this);
        sendEncrypted(Protocol.litoObserverResult(
                        Protocol.LitoObserverState.fromEnabled(observer)),
                "S_LITO_SET_OBSERVER_RESULT enabled=" + observer);
        System.out.println("[LiTo] observer=" + observer);
    }

    private void askMatchMaking(byte[] payload) throws IOException {
        Protocol.MatchMakingRequest request = Protocol.matchMakingRequest(payload);
        if (phase != Phase.CHANNEL) {
            sendEncrypted(Protocol.litoAskMatchMakingResult(
                            Protocol.LitoMatchMakingResult.NO_TRANSITION),
                    "S_LITO_ASK_MATCH_MAKING_RESULT no-transition invalid-phase=" + phase);
            return;
        }
        System.out.println("[LiTo] C_LITO_ASK_MATCH_MAKING fixed=" + request.fixedSelector()
                + " channel-restriction=" + request.channelRestriction()
                + " match-method=" + request.matchMethod()
                + " participant-restriction=" + request.participantRestriction());
        if (!GameHub.canRequestMatchMakingChannel(
                characterLevel(), request.channelRestriction())) {
            sendEncrypted(Protocol.litoAskMatchMakingResult(
                            Protocol.LitoMatchMakingResult.NO_TRANSITION),
                    "S_LITO_ASK_MATCH_MAKING_RESULT no-transition unreachable-channel="
                            + request.channelRestriction());
            return;
        }
        if (observer) {
            sendEncrypted(Protocol.litoAskMatchMakingResult(
                            Protocol.LitoMatchMakingResult.OBSERVER_REJECTED),
                    "S_LITO_ASK_MATCH_MAKING_RESULT observer-rejected=0x11");
            return;
        }
        // Matchmaking is a lobby action. Tournament consumables affect the
        // subsequent match only and must not turn the visible Match button
        // into a no-op for a freshly selected database character.
        // S_EB=1 acknowledges the request and moves the native client into
        // its waiting state.  It is not a failed room lookup result.
        hub.cancelMatchMaking(this);
        pendingMatchMakingRequest = request;
        sendEncrypted(Protocol.litoAskMatchMakingResult(
                        Protocol.LitoMatchMakingResult.ACCEPTED),
                "S_LITO_ASK_MATCH_MAKING_RESULT accepted=1");
        // The LTstring labels prove the selector-to-room-mode permutation and
        // identify lower/middle/upper/high as per-force participant intervals.
        // Mode filtering and exact interval equality are therefore safe;
        // channel policy and numeric interval cutoffs remain evidence-gated.
        long roomId = hub.matchRoom(currentChannelId, characterLevel(), observer,
                request.requestedMode());
        if (roomId == 0) {
            GameHub.MatchMakingQueueResult queued = hub.enqueueMatchMaking(
                    this, currentChannelId, request,
                    state.tournamentStatistics(sourceCharacterIdentity()));
            if (queued.matched()) {
                completeQueuedMatchMaking(queued, "native-random-queue");
            } else {
                System.out.println("[LiTo] matchmaking waiting no-eligible-public-room"
                        + " queued=" + hub.queuedMatchMakingCount());
            }
            return;
        }
        completePendingMatchMaking(roomId, "initial-request");
    }

    /**
     * Applies the native S_EB=0x10 admission boundary without treating a
     * retained source item or a battle reward as proof of a waiting-room
     * purchase.  The selected client's LTstring 164 and bundled Help1/3/4
     * prove that Tournament matchmaking requires a currently owned
     * match-local consumable bought from the per-match point shop.  The exact
     * original 3.81C server predicate is unavailable, so this deliberately
     * narrow policy is enabled only with the evidence-backed native economy.
     */
    private boolean hasNativeTournamentMatchConsumable() {
        if (!config.nativeTournamentEconomyEnabled()) return true;
        List<TournamentShopCatalog.Offer> offers = tournamentShopOffers;
        if (offers == null) return false;
        return inventory.items().stream().anyMatch(item ->
                item.quantity() > 0
                        && !item.sourceBound()
                        && !item.tournamentReward()
                        && TournamentShopCatalog.find(offers,
                                item.definition().catalogId()) != null);
    }

    /** Completes every member selected by one synchronized GameHub queue decision. */
    private void completeQueuedMatchMaking(GameHub.MatchMakingQueueResult result,
                                           String trigger) {
        for (ClientSession session : result.sessions()) {
            try {
                session.completePendingMatchMaking(result.roomId(), trigger);
            } catch (IOException error) {
                System.out.println("[LiTo] matchmaking cohort completion failed player="
                        + session.playerName() + " room=" + result.roomId()
                        + " trigger=" + trigger + ": " + error.getMessage());
            }
        }
    }

    /**
     * Completes an already acknowledged native matchmaking wait when an
     * eligible public room exists.  S_EB=1 was sent when the request entered
     * the wait state, so completion emits only the normal S_CE room chain.
     */
    private void completePendingMatchMaking(long roomId, String trigger) throws IOException {
        Protocol.MatchMakingRequest request = pendingMatchMakingRequest;
        if (request == null || phase != Phase.CHANNEL) return;
        Protocol.Writer matched = new Protocol.Writer().c(Protocol.C_LITO_JOIN)
                .d(roomId).s("");
        hub.cancelMatchMaking(this);
        pendingMatchMakingRequest = null;
        joinRoom(matched.bytes(), "match-making-" + trigger, false);
        if (phase != Phase.ROOM) pendingMatchMakingRequest = request;
    }

    private void retryPendingMatchMaking(String trigger) {
        Protocol.MatchMakingRequest request = pendingMatchMakingRequest;
        if (request == null || phase != Phase.CHANNEL || observer
                || currentChannelId < 0 || currentChannelId >= GameHub.CHANNEL_COUNT) return;
        long roomId = hub.matchRoom(currentChannelId, characterLevel(), false,
                request.requestedMode());
        if (roomId == 0) return;
        try {
            completePendingMatchMaking(roomId, trigger);
        } catch (IOException error) {
            pendingMatchMakingRequest = request;
            System.out.println("[LiTo] matchmaking completion failed player=" + playerName()
                    + " room=" + roomId + " trigger=" + trigger + ": " + error.getMessage());
        }
    }

    private void retryWaitingMatchMakingSessions(String trigger) {
        for (ClientSession session : hub.connectedSessionsSnapshot()) {
            session.retryPendingMatchMaking(trigger);
        }
    }

    private void quitMatchMaking(byte[] payload) throws IOException {
        Protocol.litoQuitMatchMakingRequest(payload);
        if (phase != Phase.CHANNEL) {
            sendEncrypted(Protocol.litoQuitMatchMakingResult(
                            Protocol.LitoQuitMatchMakingResult.NO_TRANSITION),
                    "S_LITO_QUIT_MATCH_MAKING_RESULT rejected invalid-phase=" + phase);
            return;
        }
        hub.cancelMatchMaking(this);
        pendingMatchMakingRequest = null;
        sendEncrypted(Protocol.litoQuitMatchMakingResult(
                        Protocol.LitoQuitMatchMakingResult.ACCEPTED),
                "S_LITO_QUIT_MATCH_MAKING_RESULT accepted");
        sendRoomList();
    }

    private void confirmDeath(byte[] var1) throws IOException {
      Protocol.litoConfirmDeathRequest(var1);
      if (!this.consumeDeathConfirmation()) {
         System.out
            .println("[LiTo] C_LITO_CONFIRM_DEATH rejected without pending death phase=" + this.phase + " observer=" + this.observer + " hp=" + this.playerHp);
      } else {
         BattleRules.Resolution var2 = CombatPoisonLifecycle.defeated(this.hub, this.currentRoomId, this.lastAttacker, this);
         System.out
            .println(
               "[LiTo] battle resolution room=" + this.currentRoomId + " ended=" + var2.ended() + " respawn=" + var2.respawn() + " reason=" + var2.reason()
            );
         if (!var2.ended()) {
            this.terminalEffectResultNotBeforeNanos = 0L;
            if (var2.respawn()) {
               if (this.hub.roomRules(this.currentRoomId).mode() == BattleRules.Mode.HONOR_MATCH) {
                  long var8 = this.beginHonorRespawn();
                  if (!this.hub.scheduleHonorRespawn(this.currentRoomId, this, var8, this.positionX, this.positionY)) {
                     this.cancelPendingHonorRespawn();
                     System.out.println("[LiTo] Honor respawn schedule rejected room=" + this.currentRoomId + " player=" + this.playerName());
                  } else {
                     System.out
                        .println(
                           "[LiTo] Honor respawn scheduled room="
                              + this.currentRoomId
                              + " player="
                              + this.playerName()
                              + " delay-ms=5000 position="
                              + this.positionX
                              + ","
                              + this.positionY
                        );
                  }
               } else {
                  this.respawnAtBattleSpawn();
               }
            }
         } else {
            long var3 = this.consumeTerminalEffectResultDelayMillis();
            if (var3 > 0L && this.hub.scheduleBattleEndAfterTerminalEffect(this.currentRoomId, var2, var3)) {
               System.out.println("[LiTo] terminal player effect retained room=" + this.currentRoomId + " player=" + this.playerName() + " delay-ms=" + var3);
            } else {
               for (ClientSession var7 : this.hub.roomMembers(this.currentRoomId)) {
                  var7.serverEndBattle(var2);
               }

               this.hub.endBattle(this.currentRoomId);
            }
         }
      }
   }

    private synchronized long consumeTerminalEffectResultDelayMillis() {
        long deadline = terminalEffectResultNotBeforeNanos;
        terminalEffectResultNotBeforeNanos = 0;
        long remainingNanos = deadline - System.nanoTime();
        if (remainingNanos <= 0) return 0;
        return Math.max(1L, (remainingNanos + 999_999L) / 1_000_000L);
    }

    private synchronized boolean consumeDeathConfirmation() {
        if (!deathConfirmationPending || phase != Phase.BATTLE || observer || playerHp > 0) {
            return false;
        }
        deathConfirmationPending = false;
        return true;
    }

    private synchronized long beginHonorRespawn() {
        pendingHonorRespawnToken = ++honorRespawnGeneration;
        return pendingHonorRespawnToken;
    }

    private synchronized void cancelPendingHonorRespawn() {
        pendingHonorRespawnToken = 0;
    }

    boolean honorRespawnPending(long l, long l2) {
        return NativeLightAction.honorPending(this, l, l2);
    }

    /*
     * WARNING - Removed try catching itself - possible behaviour change.
     */
    void serverHonorRespawnDue(long l, long l2, int n, int n2) throws IOException {
        byte[] objectPacket;
        NativePlayerActionScope.Ticket ticket;
        int n3;
        int n4;
        int n5;
        ticket = NativeSourceManualScope.enterRespawn(this);
        block4: {
            try {
                if (!this.honorRespawnPending(l, l2)) break block4;
                this.pendingHonorRespawnToken = 0L;
                int restoredHp = this.playerMaxHp;
                NativePlayerCommit.advance(this);
                this.playerHp = restoredHp;
                CombatPoisonLifecycle.last(this, null);
                this.positionX = n;
                this.positionY = n2;
                n3 = this.playerHp;
                n4 = this.playerMaxHp;
                n5 = this.battleGfx();
            }
            catch (Throwable throwable) {
                NativeSourceManualScope.exitRespawn(this, ticket, throwable);
                throw throwable;
            }
            NativeSourceManualScope.exitRespawn(this, ticket, null);
            objectPacket = Protocol.resurrect(this.playerObjectId(), 0, this.playerObjectId(), n5);
            for (ClientSession clientSession : this.hub.roomMembers(l)) {
                clientSession.sendEncrypted(objectPacket, "S_RESURRECT honor target=" + this.playerObjectId() + " source=" + this.playerObjectId() + " gfx=" + n5 + " position=" + n + "," + n2);
            }
            this.sendEncrypted(new Protocol.Writer().c(13).h(n3).h(n4).bytes(), "S_HIT_POINT honor-respawn=" + n3 + "/" + n4);
            this.broadcastOwnHitRatio("honor-respawn");
            System.out.println("[LiTo] Honor respawn completed room=" + l + " player=" + this.playerName() + " position=" + n + "," + n2);
            return;
        }
        NativeSourceManualScope.exitRespawn(this, ticket, null);
    }

    private void respawnAtBattleSpawn() throws IOException {
        int restoredHp = this.playerMaxHp;
        NativePlayerCommit.advance(this);
        this.playerHp = restoredHp;
        CombatPoisonLifecycle.last(this, null);
        this.terminalEffectResultNotBeforeNanos = 0L;
        this.hub.respawn(this.currentRoomId, this);
        int n = this.hub.battleSpawnIndex(this.currentRoomId, this);
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(this.hub.battleMapId(this.currentRoomId, this));
        ArenaMapCatalog.Point point = this.battleSpawn(arena, n);
        this.positionX = point.x();
        this.positionY = point.y();
        int n2 = this.battleGfx();
        byte[] byArray = Protocol.resurrect(this.playerObjectId(), 0, this.playerObjectId(), n2);
        byte[] byArray2 = NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(0).bytes());
        for (ClientSession clientSession : this.hub.roomMembers(this.currentRoomId)) {
            clientSession.sendEncrypted(byArray, "S_RESURRECT target=" + this.playerObjectId() + " source=" + this.playerObjectId() + " gfx=" + n2);
            clientSession.sendEncrypted(byArray2, "S_MOVE_OBJECT respawn object=" + this.playerObjectId() + " x=" + this.positionX + " y=" + this.positionY);
            boolean bl = clientSession.minimapAlliedWith(this);
            clientSession.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, bl), "S_LITO_MINIMAP respawn player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY + " allied=" + bl);
        }
        this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(13).h(this.playerHp).h(this.playerMaxHp).bytes()), "S_HIT_POINT respawn=" + this.playerHp + "/" + this.playerMaxHp);
        this.broadcastOwnHitRatio("respawn");
    }

    private void sendRoomWho(byte[] payload) throws IOException {
        long requestedRoomId = Protocol.litoRoomWhoRequest(payload);
        if (!requireAdministrator(Protocol.C_LITO_ROOM_WHO)) return;
        if (phase != Phase.CHANNEL && phase != Phase.ROOM) {
            System.out.println("[LiTo] C_LITO_ROOM_WHO rejected phase=" + phase);
            return;
        }
        long roomId = requestedRoomId == 0 ? currentRoomId : requestedRoomId;
        if (!hub.roomExists(currentChannelId, roomId)) {
            System.out.println("[LiTo] C_LITO_ROOM_WHO unknown room=" + roomId);
            return;
        }
        List<ClientSession> members = hub.roomMembers(roomId);
        for (ClientSession member : members) {
            sendRoomParticipant(roomId, member,
                    Protocol.LitoForce.fromWire(hub.forceOf(roomId, member)),
                    member.observer ? "observer" : "room-who");
        }
        for (GameHub.RoomVirtualPlayer member : hub.roomVirtualPlayers(roomId)) {
            sendRoomVirtualPlayer(roomId, member, "room-who-gm-virtual-player");
        }
        BattleRules.Mode roomMode = hub.roomRules(roomId).mode();
        if (NativeRoomRules.bot(roomMode, hub, roomId) && hub.roomCombatantCount(roomId) < 2) {
            sendRoomParticipant(roomId, "ArenaBot", Protocol.LitoForce.FORCE_1,
                    0, 0, "", 0,
                    "room-who-bot");
        }
        System.out.println("[LiTo] C_LITO_ROOM_WHO requested=" + requestedRoomId
                + " room=" + roomId + " members=" + members.size());
    }

    private boolean rejectWhileParalyzed(String string) {
        if (!NativeLightAction.nativeSourceSelfIngressValid(this)) {
            return true;
        }
        if (!CombatBindControl.actionLocked(this.timedStatus, System.nanoTime())) {
            return false;
        }
        System.out.println("[LiTo] " + string + " rejected action-locked player=" + this.playerName());
        return true;
    }

    private void move(byte[] byArray) throws IOException {
        if (this.phase != Phase.BATTLE && this.phase != Phase.WORLD || this.observer || this.pendingPortal != null || this.phase == Phase.BATTLE && this.playerHp <= 0) {
            return;
        }
        this.closePersonalShopIfOpen("move");
        Protocol.MoveRequest moveRequest = Protocol.moveRequest(byArray);
        int n = moveRequest.sourceX();
        int n2 = moveRequest.sourceY();
        int n3 = moveRequest.heading();
        int n4 = moveRequest.x();
        int n5 = moveRequest.y();
        if (this.nativeRejectMovementLocked("C_MOVE")) {
            return;
        }
        long l = System.nanoTime();
        if (this.cubeQuakeMovementStopped(l)) {
            System.out.println("[LiTo] C_MOVE rejected Cube: Quake MOVE_STOP player=" + this.playerName() + " remaining-millis<=1000");
            return;
        }
        if (this.phase == Phase.WORLD) {
            this.moveClassicWorld(n, n2, n4, n5, n3);
            return;
        }
        if (this.rentalTownRoomState) {
            this.moveRentalTown(n, n2, n4, n5, n3);
            return;
        }
        if (n != this.positionX || n2 != this.positionY) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(this.playerHeading).bytes()), "S_MOVE_OBJECT rejected-stale-source requested=" + n + "," + n2 + " authoritative=" + this.positionX + "," + this.positionY);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-stale-source correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-stale-source");
            return;
        }
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(this.hub.battleMapId(this.currentRoomId, this));
        if (!arena.contains(n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-outside-map requested=" + n4 + "," + n5 + " map=" + arena.mapId());
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-move correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-outside-map");
            return;
        }
        if (!arena.nativeCanStep(this.positionX, this.positionY, n4, n5) || this.hub.questBoundaryBlocks(this.currentRoomId, this, this.positionX, this.positionY, n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-native-edge requested=" + n4 + "," + n5 + " source=" + this.positionX + "," + this.positionY + " map=" + arena.mapId());
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-native-edge correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-native-edge");
            return;
        }
        if (this.hub.battleDoorBlocks(this.currentRoomId, n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-closed-door requested=" + n4 + "," + n5);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-closed-door correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-closed-door");
            return;
        }
        if (this.hub.siegeGateBlocks(this.currentRoomId, n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-siege-inner-gate requested=" + n4 + "," + n5);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-siege-inner-gate correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-siege-inner-gate");
            return;
        }
        if (this.hub.guardianTowerBlocks(this.currentRoomId, n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-guardian-tower requested=" + n4 + "," + n5);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-guardian-tower correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-guardian-tower");
            return;
        }
        if (this.hub.questMonsterBlocks(this.currentRoomId, this, n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-quest-monster requested=" + n4 + "," + n5);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-quest-monster correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-quest-monster");
            return;
        }
        if (this.hub.timeAttackActorBlocks(this.currentRoomId, n4, n5)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(n3).bytes()), "S_MOVE_OBJECT rejected-timeattack-actor requested=" + n4 + "," + n5);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, false), "S_LITO_MINIMAP rejected-timeattack-actor correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rejected-timeattack-actor");
            return;
        }
        int n6 = this.positionX;
        int n7 = this.positionY;
        this.positionX = n4;
        this.positionY = n5;
        this.playerHeading = n3;
        this.cancelMeditation("move");
        this.naturalHpRegen.noteMove();
        this.naturalMpRegen.noteMove();
        byte[] byArray2 = NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(n4).h(n5).c(n3).bytes());
        for (ClientSession clientSession : this.hub.battleRecipients(this.currentRoomId, this.hub.forceOf(this.currentRoomId, this))) {
            if (clientSession == this) continue;
            if (!this.invisible) {
                clientSession.sendEncrypted(byArray2, "S_MOVE_OBJECT object=" + this.playerObjectId() + " x=" + n4 + " y=" + n5 + " heading=" + n3);
            }
            boolean bl = clientSession.minimapAlliedWith(this);
            clientSession.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), n4, n5, bl), "S_LITO_MINIMAP player=" + this.playerName() + " x=" + n4 + " y=" + n5 + " allied=" + bl);
        }
        NativeBattleVisibility.afterMove(this, byArray);
        this.handlePetRaceMove(n6, n7, n4, n5);
        this.handleDeathmatchFatalityMove(n6, n7, n4, n5);
    }

    private void moveRentalTown(int n, int n2, int n3, int n4, int n5) throws IOException {
        boolean bl;
        boolean bl2 = bl = n != this.positionX || n2 != this.positionY;
        if (bl || !this.rentalMapCanStep(this.rentalTownMapId, this.positionX, this.positionY, n3, n4)) {
            this.sendEncrypted(NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(this.positionX).h(this.positionY).c(this.playerHeading).bytes()), "S_MOVE_OBJECT rental-town rejected-native-edge requested=" + n3 + "," + n4 + " packet-source=" + n + "," + n2 + " authoritative-source=" + this.positionX + "," + this.positionY + " map=" + this.rentalTownMapId);
            this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), this.positionX, this.positionY, true), "S_LITO_MINIMAP rental-town rejected-move correction player=" + this.playerName() + " x=" + this.positionX + " y=" + this.positionY);
            this.issueMovementLock("rental-town-rejected-native-edge");
            return;
        }
        int n6 = this.positionX;
        int n7 = this.positionY;
        this.positionX = n3;
        this.positionY = n4;
        this.playerHeading = n5;
        this.cancelMeditation("rental-town-move");
        this.naturalHpRegen.noteMove();
        this.naturalMpRegen.noteMove();
        this.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), n3, n4, true), "S_LITO_MINIMAP rental-town player=" + this.playerName() + " x=" + n3 + " y=" + n4);
        this.publishRentalTownMovement(n6, n7, n3, n4, n5);
        this.updateRentalHotelGroundVisibility(n6, n7, n3, n4);
        System.out.println("[LiTo] C_MOVE rental-town accepted player=" + this.playerName() + " map=" + this.rentalTownMapId + " from=" + n6 + "," + n7 + " to=" + n3 + "," + n4 + " heading=" + n5);
    }

    private boolean rentalMapCanStep(
            int mapId, int fromX, int fromY, int toX, int toY) {
        if (NativeLitoTownCatalog.forMap(mapId) != null) {
            return NativeLitoTownPassabilityCatalog.get().canStep(
                    mapId, fromX, fromY, toX, toY);
        }
        return NativeLitoRentalHotelCatalog.supportsMap(mapId)
                && NativeLitoRentalHotelCatalog.get().canStep(
                        mapId, fromX, fromY, toX, toY);
    }

    private boolean rentalMapStandingPassable(int mapId, int x, int y) {
        if (NativeLitoTownCatalog.forMap(mapId) != null) {
            return NativeLitoTownPassabilityCatalog.get()
                    .isStandingPassable(mapId, x, y);
        }
        return NativeLitoRentalHotelCatalog.supportsMap(mapId)
                && NativeLitoRentalHotelCatalog.get()
                        .isStandingPassable(mapId, x, y);
    }

    private void publishRentalTownMovement(int n, int n2, int n3, int n4, int n5) throws IOException {
        byte[] byArray = NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(n3).h(n4).c(n5).bytes());
        for (ClientSession clientSession : this.rentalTownPeers()) {
            boolean bl = BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, n, n2);
            boolean bl2 = BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, n3, n4);
            if (!bl && bl2) {
                clientSession.sendRentalTownActorOf(this, "movement-screen-enter");
                this.sendRentalTownActorOf(clientSession, "movement-screen-enter");
            } else if (bl && !bl2) {
                clientSession.sendEncrypted(Protocol.removeObject(this.playerObjectId()), "S_REMOVE_OBJECT rental-town screen-exit=" + this.playerName());
                this.sendEncrypted(Protocol.removeObject(clientSession.playerObjectId()), "S_REMOVE_OBJECT rental-town screen-exit=" + clientSession.playerName());
            } else if (bl2) {
                clientSession.sendEncrypted(byArray, "S_MOVE_OBJECT rental-town object=" + this.playerObjectId() + " x=" + n3 + " y=" + n4 + " heading=" + n5);
            }
            clientSession.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), n3, n4, true), "S_LITO_MINIMAP rental-town peer-move=" + this.playerName() + " x=" + n3 + " y=" + n4);
        }
    }

    private void publishRentalTownPortalRebuild(
            int previousX, int previousY, String reason) throws IOException {
        for (ClientSession peer : rentalTownPeers()) {
            boolean visibleBefore = BattleSpellCatalog.isInNativeScreen(
                    peer.positionX, peer.positionY, previousX, previousY);
            boolean visibleAfter = BattleSpellCatalog.isInNativeScreen(
                    peer.positionX, peer.positionY, positionX, positionY);
            if (visibleAfter) {
                // C_GOTO_PORTAL rebuilds the local actor.  Publish a complete
                // actor rather than a movement delta so peers cannot retain a
                // stale walk-action, light, heading or location.
                peer.sendRentalTownActorOf(this, reason + "-relocated-peer");
                sendRentalTownActorOf(peer, reason + "-local-peer-rebuild");
            } else if (visibleBefore) {
                peer.sendEncrypted(Protocol.removeObject(playerObjectId()),
                        "S_REMOVE_OBJECT rental-town portal-exit=" + playerName());
                sendEncrypted(Protocol.removeObject(peer.playerObjectId()),
                        "S_REMOVE_OBJECT rental-town portal-exit=" + peer.playerName());
            }
            sendEncrypted(Protocol.minimapPlayer(
                            peer.playerObjectId(), peer.positionX, peer.positionY, true),
                    "S_LITO_MINIMAP rental-town portal-peer=" + peer.playerName());
            peer.sendEncrypted(Protocol.minimapPlayer(
                            playerObjectId(), positionX, positionY, true),
                    "S_LITO_MINIMAP rental-town portal-player=" + playerName());
        }
    }

    private void handlePetRaceMove(int fromX, int fromY, int toX, int toY)
            throws IOException {
        long nowNanos = System.nanoTime();
        GameHub.PetRaceMove move = hub.petRaceMoved(currentRoomId, this,
                fromX, fromY, toX, toY, nowNanos);
        applyPetRacePanel(move.panel(), nowNanos);
        BattlePetRaceCourseCatalog.Transition transition = move.transition();
        if (!transition.lapCompleted()) return;

        if (!transition.finished()) {
            sendEncrypted(Protocol.raceValues(
                            BattlePetRaceCourseCatalog.LAPS, transition.currentLap()),
                    "S_LITO_RACE_INFO subtype=2 maximum-laps="
                            + BattlePetRaceCourseCatalog.LAPS
                            + " current-lap=" + transition.currentLap());
            return;
        }

        byte[] finish = Protocol.raceTime(
                litoDisplayName(), transition.elapsedMilliseconds());
        List<ClientSession> members = hub.roomMembers(currentRoomId);
        for (ClientSession member : members) {
            member.sendEncrypted(finish,
                    "S_LITO_RACE_INFO subtype=3 finisher=" + playerName()
                            + " placement=" + transition.placement()
                            + " elapsed-ms=" + transition.elapsedMilliseconds()
                            + " finish-window-deadline-nanos="
                            + transition.finishDeadlineNanos());
        }
        if (!move.resolution().ended()) return;
        for (ClientSession member : members) member.serverEndBattle(move.resolution());
        hub.endBattle(currentRoomId);
    }

    /**
     * Server-owned map-508 symbol entry.  Coordinates and spell resources are
     * native-resource facts; equal family/Heal-subtype selection, immediate
     * re-arm and the neutral raw spell amounts remain explicit compatibility
     * policy pending an original LiTo server trace.
     */
    private void handleDeathmatchFatalityMove(
            int fromX, int fromY, int toX, int toY) throws IOException {
        int mapId = hub.battleMapId(currentRoomId, this);
        BattleRules.Mode mode = hub.roomRules(currentRoomId).mode();
        if (phase != Phase.BATTLE || observer || playerHp <= 0
                || mode != BattleRules.Mode.DEATHMATCH
                || mapId != BattleDeathmatchFatalityCatalog.MAP_ID
                || fromX == toX && fromY == toY
                || !BattleDeathmatchFatalityCatalog.isSymbol(toX, toY)) {
            return;
        }
        int configuredSlot = config.deathmatchFatalityFixtureSlot();
        BattleDeathmatchFatalityCatalog.Effect selectedEffect;
        String selection;
        if (configuredSlot == -2) {
            int selectedSlot = Math.floorMod(deathmatchFatalityFixtureCursor++,
                    BattleDeathmatchFatalityCatalog.fixtureEffects().size());
            selectedEffect = BattleDeathmatchFatalityCatalog
                    .selectFixtureEffect(selectedSlot);
            selection = "test-fixture-cycle-effect-" + selectedSlot;
        } else if (configuredSlot >= 0) {
            selectedEffect = BattleDeathmatchFatalityCatalog
                    .selectFixtureEffect(configuredSlot);
            selection = "test-fixture-effect-" + configuredSlot;
        } else {
            int familySlot = ThreadLocalRandom.current().nextInt(
                    BattleDeathmatchFatalityCatalog
                            .provisionalEqualFamilies().size());
            int healSlot = ThreadLocalRandom.current().nextInt(
                    BattleDeathmatchFatalityCatalog
                            .provisionalEqualHeals().size());
            selectedEffect = BattleDeathmatchFatalityCatalog
                    .selectProvisionalEffect(familySlot, healSlot);
            selection = "random-family-" + familySlot
                    + (selectedEffect.family()
                            == BattleDeathmatchFatalityCatalog.Family.HEAL
                            ? "-heal-" + healSlot : "");
        }
        BattleDeathmatchFatalityCatalog.Trigger trigger =
                BattleDeathmatchFatalityCatalog.entered(
                        mode, mapId, fromX, fromY, toX, toY,
                        selectedEffect);
        if (trigger == null) return;

        BattleDeathmatchFatalityCatalog.Effect effect = trigger.effect();
        switch (effect) {
            case HASTE -> applyFatalityHaste(effect);
            case BASIC_HEAL, EXTRA_HEAL, GREATER_HEAL, FULL_HEAL ->
                    applyFatalityHeal(effect);
            case CANCELLATION -> applyFatalityCancellation(effect);
            case FIRE_STORM -> applyFatalityAreaDamage(
                    effect, BattleSpellCatalog.areaAttackSpell(
                            BattleSpellCatalog.FIRE_STORM).areaRadius());
            case FROZEN_CLOUD -> applyFatalityAreaDamage(
                    effect,
                    BattleDeathmatchFatalityCatalog.FROZEN_CLOUD_AREA_RADIUS);
            case DISINTEGRATE -> applyFatalitySingleDamage(effect);
        }
        System.out.println("[LiTo] FATALITY trap player=" + playerName()
                + " map=" + mapId + " cell=" + trigger.x() + "," + trigger.y()
                + " effect=" + effect.label() + " skill=" + effect.skillId()
                + " gfx=" + effect.effectGfx()
                + " distribution=provisional-equal-6-families"
                + (effect.family() == BattleDeathmatchFatalityCatalog.Family.HEAL
                        ? "/heal-equal-4" : "")
                + " selection=" + selection
                + " rearm=provisional-on-reentry");
    }

    private void applyFatalityHaste(BattleDeathmatchFatalityCatalog.Effect effect)
            throws IOException {
        BattleSpellCatalog.HasteSpell spell =
                BattleSpellCatalog.hasteSpell(effect.skillId());
        long now = System.nanoTime();
        timedStatus.clearDrunken();
        BattleTimedStatus.SpeedChange speed = timedStatus.activateHaste(
                now, spell.durationSeconds(), spell.skillId());
        broadcastFatalityEffect(effect, List.of(this));
        broadcastMovementSpeed(speed.type(), speed.durationSeconds(),
                "fatality-trap-haste");
    }

    private void applyFatalityHeal(BattleDeathmatchFatalityCatalog.Effect effect)
            throws IOException {
        // The missing original-server caster template is kept neutral and
        // reproducible: INT 11 adds no external heal dice and lawful zero adds
        // no multiplier.  Native spell dice/gfx still come from retained rows.
        int restored = BattleDeathmatchFatalityCatalog.rollNeutralHeal(
                effect, sides -> ThreadLocalRandom.current().nextInt(1, sides + 1));
        int before = playerHp;
        playerHp = Math.min(playerMaxHp, playerHp + restored);
        broadcastFatalityEffect(effect, List.of(this));
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Fatality-heal=" + playerHp + "/" + playerMaxHp
                        + " skill=" + effect.skillId() + " restored="
                        + (playerHp - before));
        broadcastOwnHitRatio("fatality-trap-heal-" + effect.skillId());
    }

    private void applyFatalityCancellation(BattleDeathmatchFatalityCatalog.Effect effect) throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$applyFatalityCancellation(effect, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    private void applyFatalityAreaDamage(BattleDeathmatchFatalityCatalog.Effect effect, int n) throws IOException {
        NativeSourceFatalityDamage.enter(this, effect, n);
    }

    private void applyFatalitySingleDamage(BattleDeathmatchFatalityCatalog.Effect effect) throws IOException {
        NativeSourceFatalityDamage.enter(this, effect, -1);
    }

    private void broadcastFatalityEffect(BattleDeathmatchFatalityCatalog.Effect effect, List<ClientSession> list) throws IOException {
        List<ClientSession> list2 = this.hub.roomMembers(this.currentRoomId);
        for (ClientSession clientSession : list) {
            byte[] byArray = Protocol.effectObject(clientSession.playerObjectId(), effect.effectGfx());
            for (ClientSession clientSession2 : list2) {
                NativeSourceFatalityDamage.send(clientSession2, byArray, "S_EFFECT Fatality target=" + clientSession.playerObjectId() + " skill=" + effect.skillId() + " gfx=" + effect.effectGfx() + " policy=server-owned-trap", clientSession, this);
            }
        }
    }

    private void applyPetRacePanel(BattlePetRaceCourseCatalog.PanelTransition panel,
                                   long nowNanos) throws IOException {
        if (panel == null || !panel.activated()) return;
        if (panel.type() == BattlePetRaceCourseCatalog.PanelType.TRANSFORM) {
            petRaceTemporaryGfx = panel.form().gfx();
            petRaceTemporaryDeadlineNanos = saturatingDeadline(
                    nowNanos, panel.durationSeconds());
            broadcastPetRaceAppearance("pet-race-transform-panel-"
                    + panel.form().key());
            System.out.println("[LiTo] PET_RACE transform player=" + playerName()
                    + " gfx=" + panel.form().gfx() + " form=" + panel.form().key()
                    + " pace=" + panel.form().pace() + " trailing=" + panel.trailing()
                    + " duration=" + panel.durationSeconds());
            return;
        }
        BattleTimedStatus.SpeedChange speed = timedStatus.activateHaste(
                nowNanos, panel.durationSeconds());
        timedStatus.activateBrave(
                nowNanos, panel.durationSeconds(), BattleTimedStatus.BRAVE_SECOND);
        clearDurableMovementBuff("pet-race-speed-replacement");
        broadcastMovementSpeed(speed.type(), speed.durationSeconds(),
                "pet-race-speed-panel");
        broadcastBraveSpeed(Protocol.BraveMode.SECOND_STAGE,
                panel.durationSeconds(), "pet-race-speed-panel");
        System.out.println("[LiTo] PET_RACE speed player=" + playerName()
                + " trailing=" + panel.trailing()
                + " duration=" + panel.durationSeconds());
    }

    private void broadcastPetRaceAppearance(String reason) throws IOException {
        int gfx = battleGfx();
        byte[] appearance = Protocol.petRacePolymorph(
                playerObjectId(), gfx, BattleActionCodes.WALK);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(appearance,
                    "S_POLYMORPH PET_RACE object=" + playerObjectId()
                            + " gfx=" + gfx + " walk-action="
                            + BattleActionCodes.WALK + " reason=" + reason);
        }
    }

    private static long saturatingDeadline(long nowNanos, int durationSeconds) {
        long duration = durationSeconds * 1_000_000_000L;
        return nowNanos > Long.MAX_VALUE - duration
                ? Long.MAX_VALUE : nowNanos + duration;
    }

    private void clearPetRaceAppearance() {
        petRaceBaseGfx = 0;
        petRaceTemporaryGfx = 0;
        petRaceTemporaryDeadlineNanos = 0;
    }

