    private void updateClassicWorldCompanionVisibility(
            int previousX, int previousY, int currentX, int currentY) throws IOException {
        for (ClientSession owner : classicWorldMembers(classicWorldMapId)) {
            for (BattleCompanion.Snapshot companion
                    : owner.classicWorldCompanionSnapshots()) {
                if (!companion.active()) continue;
                boolean sawBefore = BattleSpellCatalog.isInNativeScreen(
                        previousX, previousY, companion.x(), companion.y());
                boolean seesAfter = BattleSpellCatalog.isInNativeScreen(
                        currentX, currentY, companion.x(), companion.y());
                if (sawBefore && !seesAfter) {
                    sendEncrypted(Protocol.removeObject(companion.objectId()),
                            "S_REMOVE_OBJECT classic-world-companion="
                                    + companion.objectId() + " reason=screen-exit");
                } else if (!sawBefore && seesAfter) {
                    sendClassicWorldCompanionObject(owner, companion, "screen-enter");
                }
            }
        }
    }

    private void openBattleDoor(byte[] payload) throws IOException {
        Protocol.OpenRequest request = Protocol.openRequest(payload);
        if (phase != Phase.BATTLE || observer || currentRoomId == 0
                || playerHp <= 0 || pendingPortal != null || movementLockPending) {
            System.out.println("[LiTo] C_OPEN ignored outside eligible battle player="
                    + playerName() + " phase=" + phase);
            return;
        }
        if (rejectWhileParalyzed("C_OPEN")) return;
        BattleDoor.Snapshot door = hub.battleDoor(currentRoomId);
        if (door == null
                || request.worldObjectId() != door.objectId()
                || request.x() != door.x()
                || request.y() != door.y()
                || Math.abs(positionX - door.x()) > 2
                || Math.abs(positionY - door.y()) > 1) {
            System.out.println("[LiTo] C_OPEN rejected stale/unknown door player="
                    + playerName() + " object="
                    + Long.toUnsignedString(request.worldObjectId())
                    + " x=" + request.x() + " y=" + request.y());
            return;
        }
        BattleDoor.Snapshot updated = hub.toggleBattleDoor(currentRoomId);
        if (updated == null || updated.objectId() != door.objectId()) return;
        byte[] action = Protocol.objectAction(updated.objectId(), updated.action());
        byte[] attribute = Protocol.doorAttribute(
                updated.x(), updated.y(), updated.direction(), updated.passable());
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(action,
                    "S_ACTION door=" + updated.objectId() + " action=" + updated.action()
                            + " open=" + updated.open());
            member.sendEncrypted(attribute,
                    "S_CHANGE_ATTR door=" + updated.objectId() + " x=" + updated.x()
                            + " y=" + updated.y() + " direction=" + updated.direction()
                            + " passable=" + updated.passable());
        }
        System.out.println("[LiTo] C_OPEN door=" + updated.objectId()
                + " player=" + playerName() + " open=" + updated.open()
                + " action=" + updated.action());
    }

    private void issueMovementLock(String reason) throws IOException {
        if (movementLockPending) {
            System.out.println("[LiTo] S_BLINK coalesced pending player=" + playerName()
                    + " reason=" + reason);
            return;
        }
        movementLockPending = true;
        sendEncrypted(Protocol.movementLock(),
                "S_BLINK movement-lock player=" + playerName() + " reason=" + reason);
    }

    private void movementUnlock(byte[] byArray) throws IOException {
        Protocol.movementUnlock(byArray);
        if (!this.movementLockPending) {
            System.out.println("[LiTo] C_BLINK ignored unsolicited player=" + this.playerName() + " phase=" + String.valueOf((Object)this.phase));
            return;
        }
        this.sendEncrypted(Protocol.movementLockRelease(), "S_PARALYSE movement-lock-release mode=17");
        this.movementLockPending = false;
        System.out.println("[LiTo] C_BLINK movement-unlock accepted player=" + this.playerName() + " phase=" + String.valueOf((Object)this.phase));
    }

