    private ArenaMapCatalog.Point resolveBattleTeleportSpellDestination(
            Protocol.TeleportSpellRequest request, ArenaMapCatalog.Arena arena) {
        if (request.mapId() != arena.mapId()) return null;
        if (request.x() == 0 && request.y() == 0) {
            return BattleMassTeleport.randomDestination(
                    arena, positionX, positionY,
                    bound -> ThreadLocalRandom.current().nextInt(bound));
        }
        if (request.x() == 0 || request.y() == 0
                || !arena.nativeStandingFloor(request.x(), request.y())) return null;
        boolean exactServerBookmark = state.bookmarks(stateCharacter()).stream()
                .anyMatch(bookmark -> bookmark.mapId() == request.mapId()
                        && bookmark.x() == request.x()
                        && bookmark.y() == request.y());
        return exactServerBookmark
                ? new ArenaMapCatalog.Point(request.x(), request.y()) : null;
    }

    private ArenaMapCatalog.Point resolveClassicWorldTeleportSpellDestination(
            Protocol.TeleportSpellRequest request,
            ClassicWorldMapCatalog.ClassicMap sourceMap) {
        if (request.x() == 0 && request.y() == 0) {
            if (request.mapId() != sourceMap.mapId()
                    || !sourceMap.allowsRandomTeleport()) return null;
            return BattleMassTeleport.randomDestination(
                    sourceMap, positionX, positionY,
                    bound -> ThreadLocalRandom.current().nextInt(bound));
        }
        if (request.x() == 0 || request.y() == 0
                || !sourceMap.allowsEscape()
                || !ClassicWorldMapCatalog.supports(request.mapId())) return null;
        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(request.mapId());
        if (!destinationMap.standingPassable(request.x(), request.y())) return null;
        boolean exactServerBookmark = state.bookmarks(stateCharacter()).stream()
                .anyMatch(bookmark -> bookmark.mapId() == request.mapId()
                        && bookmark.x() == request.x()
                        && bookmark.y() == request.y());
        return exactServerBookmark
                ? new ArenaMapCatalog.Point(request.x(), request.y()) : null;
    }

    private void rejectTeleportSpell(String reason, int messageId) throws IOException {
        sendTeleportCursorUnlock("C_USE_SPELL-Teleport-5-" + reason);
        if (messageId > 0) {
            sendEncrypted(Protocol.messageCode(messageId),
                    "S_MESSAGE_CODE teleport-5-rejected=" + messageId
                            + " reason=" + reason);
        }
        System.out.println("[LiTo] C_USE_SPELL Teleport-5 rejected player="
                + playerName() + " reason=" + reason);
    }

    private void requestTeleport(byte[] payload) throws IOException {
        Protocol.TeleportRequest request = Protocol.teleportRequest(payload);
        if (phase == Phase.WORLD) {
            requestClassicWorldTeleport(request);
            return;
        }
        if (phase != Phase.BATTLE || observer || currentRoomId == 0) {
            sendTeleportCursorUnlock("outside-active-world");
            System.out.println("[LiTo] C_TELEPORT ignored outside active combat player="
                    + playerName() + " phase=" + phase);
            return;
        }
        if (rejectWhileParalyzed("C_TELEPORT")) {
            sendTeleportCursorUnlock("battle-paralyzed");
            return;
        }
        if (pendingPortal != null) {
            sendTeleportCursorUnlock("battle-portal-pending");
            System.out.println("[LiTo] C_TELEPORT coalesced pending player=" + playerName());
            return;
        }

        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(
                hub.battleMapId(currentRoomId, this));
        int requestedMap = request.includesMap() ? request.mapId() : arena.mapId();
        boolean accepted = isAdministrator() && requestedMap == arena.mapId()
                && arena.contains(request.x(), request.y());
        int destinationX = accepted ? request.x() : positionX;
        int destinationY = accepted ? request.y() : positionY;
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
        sendTeleportCursorUnlock(accepted
                ? "battle-teleport-accepted" : "battle-teleport-rejected");
        if (!accepted) {
            System.out.println("[LiTo] C_TELEPORT player=" + playerName()
                    + " requested=" + requestedMap + ":" + request.x() + ","
                    + request.y() + " accepted=false result=cursor-unlocked");
            return;
        }
        pendingPortal = new Protocol.PortalDestination(
                arena.mapId(), destinationX, destinationY, true);
        pendingPortalReady = true;
        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT battle instant-teleport target=" + playerObjectId());
            }
        }
        sendEncrypted(Protocol.portal(
                        arena.mapId(), destinationX, destinationY),
                "S_PORTAL battle instant-teleport map=" + arena.mapId()
                        + " x=" + destinationX + " y=" + destinationY);
        System.out.println("[LiTo] C_TELEPORT player=" + playerName()
                + " requested=" + requestedMap + ":" + request.x() + "," + request.y()
                + " accepted=true result=awaiting-C_GOTO_PORTAL");
    }

    /**
     * Completes the selected client's ordinary-world C_TELEPORT cursor flow.
     * Same-family L1Teleport releases mode 7 on every terminal branch; omitting
     * it leaves both the mouse and actor in the native teleport action lock.
     */
    private void requestClassicWorldTeleport(Protocol.TeleportRequest request)
            throws IOException {
        if (observer || playerHp <= 0) {
            sendTeleportCursorUnlock("classic-world-ineligible");
            return;
        }
        if (rejectWhileParalyzed("C_TELEPORT")) {
            sendTeleportCursorUnlock("classic-world-paralyzed");
            return;
        }
        if (pendingPortal != null) {
            sendTeleportCursorUnlock("classic-world-portal-pending");
            return;
        }

        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        int requestedMap = request.includesMap()
                ? request.mapId() : classicWorldMapId;
        boolean accepted = requestedMap == classicWorldMapId
                && map.allowsRandomTeleport()
                && map.standingPassable(request.x(), request.y());
        sendTeleportCursorUnlock(accepted
                ? "classic-world-teleport-accepted"
                : "classic-world-teleport-rejected");
        if (!accepted) {
            sendEncrypted(Protocol.messageCode(276),
                    "S_MESSAGE_CODE classic-world-teleport-rejected=276 map="
                            + requestedMap + " x=" + request.x()
                            + " y=" + request.y());
            return;
        }

        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                classicWorldMapId, request.x(), request.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, Math.floorMod(playerHeading, 8), 0,
                "C_TELEPORT-instant", classicWorldInstanceId);
        pendingPortal = destination;
        pendingPortalReady = true;

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (member.classicWorldInstanceId != classicWorldInstanceId
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)) continue;
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world instant-teleport target="
                            + playerObjectId());
        }
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL classic-world instant-teleport map="
                        + destination.mapId() + " x=" + destination.x()
                        + " y=" + destination.y());
        System.out.println("[LiTo] C_TELEPORT classic-world accepted player="
                + playerName() + " destination=" + destination.mapId() + ":"
                + destination.x() + "," + destination.y()
                + " result=awaiting-C_GOTO_PORTAL");
    }

