    private void completeRentalTownPortal(
            Protocol.PortalDestination destination) throws IOException {
        PendingRentalTownMapTransition mapTransition =
                pendingRentalTownMapTransition;
        if (mapTransition != null) {
            RentalHotelLease lease = rentalHotelLease;
            boolean valid = phase == Phase.BATTLE && currentRoomId != 0
                    && destination.accepted()
                    && destination.equals(mapTransition.destination())
                    && rentalTownMapId == mapTransition.sourceMapId()
                    && lease != null && lease.token() == mapTransition.leaseToken()
                    && rentalMapStandingPassable(
                            destination.mapId(), destination.x(), destination.y());
            if (!valid) {
                pendingPortal = null;
                pendingPortalReady = false;
                pendingRentalTownMapTransition = null;
                System.out.println("[LiTo] C_GOTO_PORTAL rental-town map-transition"
                        + " discarded player=" + playerName() + " destination="
                        + destination.mapId() + ":" + destination.x() + ","
                        + destination.y());
                return;
            }
            pendingPortal = null;
            pendingPortalReady = false;
            pendingCallClanPortal = null;
            pendingRunClanPortal = null;
            pendingClassicWorldPortal = null;
            pendingRentalTownMapTransition = null;
            rentalTownMapId = destination.mapId();
            positionX = destination.x();
            positionY = destination.y();
            playerHeading = mapTransition.heading();
            if (mapTransition.clearLeaseOnCompletion()) {
                synchronized (rentalHotelLifecycleLock) {
                    if (rentalHotelLease != null
                            && rentalHotelLease.token() == mapTransition.leaseToken()) {
                        rentalHotelLease = null;
                    }
                }
            }
            cancelMeditation(mapTransition.reason());
            resetAndSendRentalTownStatus();
            sendRentalTownActor(mapTransition.reason() + "-rebuild");
            sendRentalTownNpcs(mapTransition.reason() + "-rebuild");
            sendRentalHotelGroundKeys(mapTransition.reason() + "-rebuild");
            sendEncrypted(Protocol.minimapPlayer(
                            playerObjectId(), positionX, positionY, true),
                    "S_LITO_MINIMAP " + mapTransition.reason()
                            + " player=" + playerName() + " x=" + positionX
                            + " y=" + positionY);
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(playerHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT " + mapTransition.reason() + " player="
                            + playerHp + "/" + playerMaxHp);
            synchronizeRentalTownActors(mapTransition.reason() + "-rebuild");
            System.out.println("[LiTo] C_GOTO_PORTAL " + mapTransition.reason()
                    + " completed player=" + playerName() + " map="
                    + rentalTownMapId + " x=" + positionX + " y=" + positionY
                    + " heading=" + playerHeading);
            return;
        }
        if (phase != Phase.BATTLE || currentRoomId == 0
                || !destination.accepted()
                || destination.mapId() != rentalTownMapId
                || NativeLitoTownCatalog.forMap(destination.mapId()) == null
                || !NativeLitoTownPassabilityCatalog.get().isStandingPassable(
                        destination.mapId(), destination.x(), destination.y())) {
            pendingPortal = null;
            pendingPortalReady = false;
            System.out.println("[LiTo] C_GOTO_PORTAL rental-town discarded player="
                    + playerName() + " phase=" + phase + " destination="
                    + destination.mapId() + ":" + destination.x() + "," + destination.y());
            return;
        }
        pendingPortal = null;
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
        int previousX = positionX;
        int previousY = positionY;
        positionX = destination.x();
        positionY = destination.y();
        playerHeading = 0;
        cancelMeditation("rental-town-portal");
        resetAndSendRentalTownStatus();
        sendRentalTownActor("portal-rebuild");
        sendRentalHotelGroundKeys("portal-rebuild");
        sendEncrypted(Protocol.minimapPlayer(
                        playerObjectId(), positionX, positionY, true),
                "S_LITO_MINIMAP rental-town portal player=" + playerName()
                        + " x=" + positionX + " y=" + positionY);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT rental-town portal player="
                        + playerHp + "/" + playerMaxHp);
        publishRentalTownPortalRebuild(previousX, previousY, "portal-rebuild");
        System.out.println("[LiTo] C_GOTO_PORTAL rental-town completed player="
                + playerName() + " map=" + rentalTownMapId
                + " x=" + positionX + " y=" + positionY);
    }

    private void completeClassicWorldPortal(Protocol.PortalDestination portalDestination, PendingClassicWorldPortal pendingClassicWorldPortal) throws IOException {
        NativeCompanionPlacement.portal(this, portalDestination, pendingClassicWorldPortal, () -> this.nativePlacementPortalBody(portalDestination, pendingClassicWorldPortal));
    }

    /** Retained L1Teleport-based PK punishment, represented by LiTo's S_PORTAL handshake. */
    private void beginClassicWorldHell(boolean firstEntry) throws IOException {
        if (hellRemainingTicks <= 0 && !firstEntry) return;
        if (firstEntry) {
            GameStateStore.HellState started = state.startHell(
                    stateCharacter(), generalPkCount);
            hellRemainingTicks = started.remainingTicks();
        }
        if (phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(classicWorldMapId)) {
            hellClock.clear();
            return;
        }
        if (classicWorldMapId != ClassicWorldHell.MAP_ID) {
            queueClassicWorldHellPortal(ClassicWorldHell.entry(),
                    firstEntry ? "Hell-first" : "Hell-resume");
        } else {
            hellClock.reset(System.nanoTime());
        }
        if (firstEntry) {
            sendEncrypted(Protocol.messageCode(552,
                            Integer.toString(generalPkCount),
                            Integer.toString(hellRemainingTicks / 60)),
                    "S_MESSAGE_CODE Hell-entry=552 pk=" + generalPkCount
                            + " minutes=" + (hellRemainingTicks / 60));
        } else {
            sendEncrypted(Protocol.messageCode(637,
                            Integer.toString(hellRemainingTicks)),
                    "S_MESSAGE_CODE Hell-resume=637 ticks=" + hellRemainingTicks);
        }
    }

    private void queueClassicWorldHellPortal(
            ClassicWorldHell.Destination target, String reason) throws IOException {
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                target.mapId(), target.x(), target.y(), true);
        if (!ClassicWorldMapCatalog.forMap(destination.mapId())
                .standingPassable(destination.x(), destination.y())) {
            throw new IOException("Hell destination is not passable: "
                    + destination.mapId() + ":" + destination.x() + ","
                    + destination.y());
        }
        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, target.heading(), 0, reason);
        pendingPortal = destination;
        pendingPortalReady = true;
        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT " + reason + " target=" + playerObjectId());
            }
        }
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL " + reason + " destination=" + destination.mapId()
                        + ":" + destination.x() + "," + destination.y());
    }

    private void serverClassicWorldHellTick(long nowNanos) throws IOException {
        if (hellRemainingTicks <= 0) {
            hellClock.clear();
            return;
        }
        // Retained PcHellTimer decrements every online character with
        // HellTime, regardless of current map or death state.  The LiTo
        // character becomes source-equivalent once it has entered WORLD.
        if (phase != Phase.WORLD
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        int elapsed = Math.min(hellRemainingTicks, hellClock.pollDue(nowNanos));
        if (elapsed <= 0) return;
        hellRemainingTicks = state.elapseHell(
                stateCharacter(), elapsed).remainingTicks();
        if (hellRemainingTicks > 0) return;
        hellClock.clear();
        int index = java.util.concurrent.ThreadLocalRandom.current().nextInt(
                ClassicWorldHell.returnDestinations().size());
        queueClassicWorldHellPortal(
                ClassicWorldHell.returnDestination(index), "Hell-complete");
        System.out.println("[LiTo] native HellTime completed player=" + playerName()
                + " return-index=" + index + " map=4");
    }

    /**
     * The retained quest117 source calls Npc_DragonB2 from a "transparent
     * teleport object", but neither retained database contains an NPC template
     * or quest-spawn row that can instantiate that executor.  Route 464 is the
     * only retained producer into its exact destination and is therefore the
     * evidence-backed repair point for the otherwise unreachable boss chain.
     */
    private void startClassicWorldWaterDragonBossFromRetainedEntrance(
            String transitionReason) {
        if (!"ground-dungeon-route-464".equals(transitionReason)
                || classicWorldMapId != ClassicWorldWaterDragonCatalog.MAP_ID
                || classicWorldInstanceId <= 0) {
            return;
        }
        ClassicWorldWaterDragonInstances.GateTalk talk =
                hub.talkClassicWorldWaterDragonBossGate(
                        this, System.nanoTime());
        System.out.println("[LiTo] Water-Dragon retained-transparent-gate"
                + " player=" + playerName()
                + " show=" + classicWorldInstanceId
                + " accepted=" + talk.accepted()
                + " scheduled=" + talk.scheduled()
                + " source=ground-dungeon-route-464");
    }

    private void sendClassicWorldRebuild(
            List<ClientSession> occupants, String reason) throws IOException {
        pendingRepairNpc = null;
        pendingSpellShop = null;
        pendingSpellMaterialShop = null;
        pendingCastleAdmin = null;
        pendingMercenaryAdmin = null;
        clearPendingClassicList();
        sendBattleStatus();
        sendBattleObject(playerObjectId(), litoDisplayName(), sourceCharacterIdentity(),
                positionX, positionY, battleGfx(), battleWalkAction(), battleLightRange(),
                battleMoveSpeed(), 4 | (invisible ? 2 : 0), battleLevel(),
                nativeLawful(characterLawful()), classicTitle, 0xFF);
        long rebuildNow = System.nanoTime();
        BattleTimedStatus.Brave localBrave = timedStatus.brave(rebuildNow);
        if (localBrave.mode() != BattleTimedStatus.BRAVE_NORMAL) {
            sendEncrypted(Protocol.braveSpeed(playerObjectId(),
                            Protocol.BraveMode.fromWire(localBrave.mode()),
                            localBrave.remainingSeconds()),
                    "S_EMOTION(brave) object=" + playerObjectId()
                            + " mode=" + localBrave.mode()
                            + " duration=" + localBrave.remainingSeconds()
                            + " reason=" + reason + "-classic-world-rebuild");
        }
        for (ClientSession occupant : occupants) {
            if (!sameClassicWorldMap(occupant)
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY, occupant.positionX, occupant.positionY)) {
                continue;
            }
            if (!occupant.invisible) {
                sendBattleObject(occupant.playerObjectId(), occupant.litoDisplayName(),
                        occupant.sourceCharacterIdentity(), occupant.positionX, occupant.positionY,
                        occupant.battleGfx(), occupant.battleWalkAction(),
                        occupant.battleLightRange(), occupant.battleMoveSpeed(), 4,
                        occupant.battleLevel(), nativeLawful(occupant.characterLawful()),
                        occupant.classicTitle, occupant.battleHpRatio());
            }
            if (!invisible) {
                occupant.sendBattleObject(playerObjectId(), litoDisplayName(),
                        sourceCharacterIdentity(), positionX, positionY, battleGfx(),
                        battleWalkAction(), battleLightRange(), battleMoveSpeed(), 4,
                        battleLevel(), nativeLawful(characterLawful()), classicTitle,
                        battleHpRatio());
            }
            BattleTimedStatus.Brave occupantBrave =
                    occupant.timedStatus.brave(rebuildNow);
            if (!occupant.invisible
                    && occupantBrave.mode() != BattleTimedStatus.BRAVE_NORMAL) {
                sendEncrypted(Protocol.braveSpeed(
                                occupant.playerObjectId(), Protocol.BraveMode.fromWire(
                                        occupantBrave.mode()), 0),
                        "S_EMOTION(brave) object=" + occupant.playerObjectId()
                                + " mode=" + occupantBrave.mode()
                                + " duration=0 reason=" + reason
                                + "-classic-world-peer-rebuild");
            }
            if (!invisible
                    && localBrave.mode() != BattleTimedStatus.BRAVE_NORMAL) {
                occupant.sendEncrypted(Protocol.braveSpeed(
                                playerObjectId(), Protocol.BraveMode.fromWire(
                                        localBrave.mode()), 0),
                        "S_EMOTION(brave) object=" + playerObjectId()
                                + " mode=" + localBrave.mode()
                                + " duration=0 reason=" + reason
                                + "-classic-world-peer-enter");
            }
        }
        List<ClientSession> companionOwners = new ArrayList<>(occupants);
        companionOwners.add(this);
        for (ClientSession owner : companionOwners) {
            for (BattleCompanion.Snapshot companion
                    : owner.classicWorldCompanionSnapshots()) {
                if (!companion.active()) continue;
                if (BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, companion.x(), companion.y())) {
                    sendClassicWorldCompanionObject(
                            owner, companion, reason + "-rebuild");
                }
                if (owner == this) {
                    for (ClientSession occupant : occupants) {
                        if (BattleSpellCatalog.isInNativeScreen(
                                occupant.positionX, occupant.positionY,
                                companion.x(), companion.y())) {
                            occupant.sendClassicWorldCompanionObject(
                                    this, companion, reason + "-peer-enter");
                        }
                    }
                }
            }
        }
        sendClassicWorldStaticNpcs("classic-world-rebuild");
        sendClassicCastleWarObjects("classic-world-rebuild");
        sendClassicWorldRescueFollowers("classic-world-rebuild");
        sendClassicWorldDspyFollowers("classic-world-rebuild");
        sendClassicWorldRoiFollowers("classic-world-rebuild");
        sendMainlandCastleDoors("classic-world-rebuild");
        sendDwarfCastleDoors("classic-world-rebuild");
        sendAdenCastleDoors("classic-world-rebuild");
        sendHeineCastleDoors("classic-world-rebuild");
        sendWaterDragonDoors("classic-world-rebuild");
        sendClassicWorldMonsters("classic-world-rebuild");
        sendClassicWorldGroundItems("classic-world-rebuild");
        sendClassicWorldCubeIgnitions("classic-world-rebuild");
        sendClassicWorldCubeQuakes("classic-world-rebuild");
        sendClassicWorldCubeShocks("classic-world-rebuild");
        sendClassicWorldCubeHarmonies("classic-world-rebuild");
        sendClassicWorldBoneBreakEffects("classic-world-rebuild");
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT classic-world=" + playerHp + "/" + playerMaxHp);
        sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                "S_PARALYSE mode=7 reason=" + reason + "-classic-world-ready");
    }

    void serverClassicWorldCkewEnded(
            ClassicWorldCkewInstances.Ended ended) throws IOException {
        if (ended == null) return;
        synchronized (classicWorldPortalLifecycleLock) {
            boolean entered = phase == Phase.WORLD
                    && classicWorldMapId == ClassicWorldCkewCatalog.MAP_ID
                    && classicWorldInstanceId == ended.showId();
            boolean pendingEntry = !entered
                    && pendingClassicWorldCkewEntryShowId() == ended.showId();
            if (!entered && !pendingEntry) return;

            if (pendingEntry) {
                invalidatePendingClassicWorldCkewEntry(ended.showId());
            }
            if ("timeout".equals(ended.reason())) {
                sendEncrypted(Protocol.messageCode(3112),
                        "S_MESSAGE_CODE CKEW timeout=3112 show="
                                + ended.showId());
            }
            if (pendingEntry) {
                System.out.println("[LiTo] CKEW pending entry invalidated player="
                        + playerName() + " show=" + ended.showId()
                        + " reason=" + ended.reason());
                return;
            }

            ClassicWorldCkewCatalog.Location exit =
                    ClassicWorldCkewCatalog.FAILURE_EXIT;
            Protocol.PortalDestination destination =
                    new Protocol.PortalDestination(
                            exit.mapId(), exit.x(), exit.y(), true);
            pendingCallClanPortal = null;
            pendingRunClanPortal = null;
            pendingClassicWorldPortal = new PendingClassicWorldPortal(
                    destination, exit.heading(), 0,
                    "CKEW-" + ended.reason() + "-show-" + ended.showId());
            pendingPortal = destination;
            pendingPortalReady = true;

            byte[] effect = Protocol.effectObject(
                    playerObjectId(), ClassicWorldTeleportCatalog
                            .TELEPORT_EFFECT_GFX);
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        positionX, positionY)) {
                    member.sendEncrypted(effect,
                            "S_EFFECT CKEW-end target=" + playerObjectId()
                                    + " show=" + ended.showId()
                                    + " reason=" + ended.reason());
                }
            }
            sendEncrypted(Protocol.portal(destination.mapId(),
                            destination.x(), destination.y()),
                    "S_PORTAL CKEW-end show=" + ended.showId()
                            + " reason=" + ended.reason() + " destination="
                            + destination.mapId() + ":" + destination.x()
                            + "," + destination.y());
        }
    }

    private void invalidatePendingClassicWorldCkewEntry(int showId) {
        PendingClassicWorldPortal pending = pendingClassicWorldPortal;
        if (pending == null || pending.instanceId() != showId
                || pending.destination().mapId()
                    != ClassicWorldCkewCatalog.MAP_ID) return;
        pendingPortal = null;
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
    }

    void serverClassicWorldCkewCountdown(
            int showId, int remainingSeconds) throws IOException {
        boolean entered = phase == Phase.WORLD
                && classicWorldMapId == ClassicWorldCkewCatalog.MAP_ID
                && classicWorldInstanceId == showId;
        if (!entered && pendingClassicWorldCkewEntryShowId() != showId) return;
        String unit = remainingSeconds >= 60 ? "分" : "秒";
        int value = remainingSeconds >= 60
                ? remainingSeconds / 60 : remainingSeconds;
        String message = "\\fV副本任務-剩餘時間：" + value + unit;
        sendEncrypted(Protocol.questHelpMessage(message, positionX, positionY),
                "S_SAY_CODE CKEW countdown show=" + showId
                        + " remaining=" + remainingSeconds);
    }

    void serverClassicWorldWaterDragonMessage(
            int showId, int messageId) throws IOException {
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldWaterDragonCatalog.MAP_ID
                || classicWorldInstanceId != showId || messageId <= 0) return;
        sendEncrypted(Protocol.messageCode(messageId),
                "S_MESSAGE_CODE Water-Dragon show=" + showId
                        + " message=" + messageId);
    }

    void serverClassicWorldWaterDragonEnded(
            int showId, String reason,
            ClassicWorldWaterDragonCatalog.Location exit,
            boolean bloodRecipient) throws IOException {
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldWaterDragonCatalog.MAP_ID
                || classicWorldInstanceId != showId || exit == null) return;
        if (bloodRecipient) {
            long durationNanos = ClassicWorldWaterDragonCatalog
                    .COMPLETION_BLOOD_SECONDS * 1_000_000_000L;
            long now = System.nanoTime();
            state.saveWaterDragonBlood(
                    stateCharacter(), ClassicWorldWaterDragonCatalog
                            .COMPLETION_BLOOD_SECONDS);
            storySkillEffectDeadlines.put(
                    ClassicWorldWaterDragonCatalog.WATER_DRAGON_BLOOD_SKILL_ID,
                    now > Long.MAX_VALUE - durationNanos
                            ? Long.MAX_VALUE : now + durationNanos);
            sendEncrypted(Protocol.effectObject(
                            playerObjectId(),
                            ClassicWorldWaterDragonCatalog.COMPLETION_GFX),
                    "S_EFFECT Water-Dragon-blood show=" + showId
                            + " skill=" + ClassicWorldWaterDragonCatalog
                                    .WATER_DRAGON_BLOOD_SKILL_ID
                            + " duration=" + ClassicWorldWaterDragonCatalog
                                    .COMPLETION_BLOOD_SECONDS);
        }
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                exit.mapId(), exit.x(), exit.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, exit.heading(), 0,
                "Water-Dragon-" + reason + "-show-" + showId);
        pendingPortal = destination;
        pendingPortalReady = true;

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT Water-Dragon-exit target=" + playerObjectId()
                                + " show=" + showId + " reason=" + reason);
            }
        }
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL Water-Dragon show=" + showId + " reason=" + reason
                        + " blood=" + bloodRecipient + " destination="
                        + destination.mapId() + ":" + destination.x()
                        + "," + destination.y());
    }

    private void sendClassicWorldStaticNpcs(String string) throws IOException {
        for (ClassicWorldNpcCatalog.StaticNpc staticNpc : NativeStaticNpcMotion.inScreen(this.classicWorldMapId, this.positionX, this.positionY, this)) {
            if (ClassicWorldCastleWarField.isStaticTower(staticNpc) || ClassicWorldBowCatalog.isBow(staticNpc) || ClassicWorldGuardianCatalog.isGuardian(staticNpc) || ClassicWorldGuardCatalog.isGuard(staticNpc)) continue;
            this.sendClassicWorldStaticNpc(staticNpc, string);
        }
    }

    private void sendClassicWorldStaticNpc(ClassicWorldNpcCatalog.StaticNpc staticNpc, String string) throws IOException {
        if (ClassicWorldBowCatalog.isBow(staticNpc)) {
            return;
        }
        if (ClassicWorldGuardianCatalog.isGuardian(staticNpc)) {
            return;
        }
        if (ClassicWorldGuardCatalog.isGuard(staticNpc)) {
            return;
        }
        int n = NativeStaticNpcScene.heading(this.hub, staticNpc, this);
        int n2 = NativeStaticNpcScene.gfx(this.hub, staticNpc, this);
        this.sendEncrypted(NativeCancellationNpcStatic.putObject(staticNpc, n, n2, this), "S_PUT_OBJECT classic-world-static-npc=" + staticNpc.objectId() + " spawn=" + staticNpc.spawnId() + " npc=" + staticNpc.npcId() + " impl=" + staticNpc.implementation() + " gfx=" + n2 + " x=" + NativeStaticNpcMotion.x(staticNpc, this) + " y=" + NativeStaticNpcMotion.y(staticNpc, this) + " heading=" + n + " reason=" + string);
    }

