    private List<ClassicWorldCastleDoorCombat.View> mainlandCastleDoorsInScreen(
            int x, int y) {
        return hub.mainlandCastleDoors().stream()
                .filter(door -> door.definition().mapId() == classicWorldMapId
                        && BattleSpellCatalog.isInNativeScreen(
                            x, y, door.definition().x(), door.definition().y()))
                .toList();
    }

    private void sendMainlandCastleDoors(String reason) throws IOException {
        for (ClassicWorldCastleDoorCombat.View door
                : mainlandCastleDoorsInScreen(positionX, positionY)) {
            sendMainlandCastleDoor(door, reason);
        }
    }

    private void sendMainlandCastleDoor(
            ClassicWorldCastleDoorCombat.View door, String reason)
            throws IOException {
        ClassicWorldCastleDoorCombat.Definition definition = door.definition();
        int action = door.open() ? BattleDoor.ACTION_OPEN : BattleDoor.ACTION_CLOSED;
        int passable = door.open() ? BattleDoor.PASSABLE : BattleDoor.NOT_PASSABLE;
        sendEncrypted(Protocol.classicCastleDoor(
                        definition.objectId(), definition.x(), definition.y(),
                        definition.gfxId(), action),
                "S_PUT_OBJECT " + definition.family().name().toLowerCase(Locale.ROOT)
                        + "-castle-door=" + definition.doorId()
                        + " gfx=" + definition.gfxId() + " action=" + action
                        + " hp=" + door.currentHp() + "/" + definition.maximumHp()
                        + " reason=" + reason);
        sendMainlandCastleDoorAttributes(definition, passable, reason);
    }

    private void sendMainlandCastleDoorAttributes(
            ClassicWorldCastleDoorCombat.Definition door,
            int passable, String reason) throws IOException {
        for (int edge = door.edgeLow(); edge <= door.edgeHigh(); edge++) {
            int x = door.direction() == 0 ? edge : door.entranceX();
            int y = door.direction() == 0 ? door.entranceY() : edge;
            sendEncrypted(Protocol.doorAttribute(x, y, door.direction(), passable),
                    "S_CHANGE_ATTR " + door.family().name().toLowerCase(Locale.ROOT)
                            + "-castle-door=" + door.doorId()
                            + " x=" + x + " y=" + y
                            + " direction=" + door.direction()
                            + " passable=" + passable + " reason=" + reason);
        }
    }

