    private List<ClassicWorldHeineCastleDoorState.Snapshot> heineCastleDoorsInScreen(
            int x, int y) {
        if (classicWorldMapId != ClassicWorldHeineCatalog.CASTLE_EXTERIOR_MAP_ID) {
            return List.of();
        }
        return hub.heineCastleDoors().stream()
                .filter(door -> BattleSpellCatalog.isInNativeScreen(
                        x, y, door.definition().x(), door.definition().y()))
                .toList();
    }

    private void sendHeineCastleDoors(String reason) throws IOException {
        for (ClassicWorldHeineCastleDoorState.Snapshot door
                : heineCastleDoorsInScreen(positionX, positionY)) {
            sendHeineCastleDoor(door, reason);
        }
    }

    private void sendHeineCastleDoor(
            ClassicWorldHeineCastleDoorState.Snapshot door, String reason)
            throws IOException {
        int action = door.open() ? BattleDoor.ACTION_OPEN : BattleDoor.ACTION_CLOSED;
        int passable = door.open() ? BattleDoor.PASSABLE : BattleDoor.NOT_PASSABLE;
        sendEncrypted(Protocol.classicCastleDoor(door.definition().objectId(),
                        door.definition().x(), door.definition().y(),
                        door.definition().gfxId(), action),
                "S_PUT_OBJECT Heine-castle-door=" + door.definition().doorId()
                        + " gfx=" + door.definition().gfxId() + " action=" + action
                        + " hp=" + door.currentHp() + "/"
                        + door.definition().maximumHp() + " reason=" + reason);
        sendHeineCastleDoorAttributes(door.definition(), passable, reason);
    }

    private List<ClassicWorldWaterDragonCatalog.Door>
            waterDragonDoorsInScreen(int x, int y) {
        if (classicWorldMapId != ClassicWorldWaterDragonCatalog.MAP_ID
                || classicWorldInstanceId <= 0) return List.of();
        return ClassicWorldWaterDragonCatalog.doors().stream()
                .filter(door -> BattleSpellCatalog.isInNativeScreen(
                        x, y, door.x(), door.y())).toList();
    }

    private void sendWaterDragonDoors(String reason) throws IOException {
        ClassicWorldWaterDragonInstances.Snapshot snapshot =
                hub.classicWorldWaterDragonInstances().snapshot(
                        classicWorldInstanceId);
        if (snapshot == null || !snapshot.active()) return;
        for (ClassicWorldWaterDragonCatalog.Door door
                : waterDragonDoorsInScreen(positionX, positionY)) {
            sendWaterDragonDoor(door,
                    Boolean.TRUE.equals(snapshot.openDoors().get(door.doorId())),
                    reason);
        }
    }

    private void sendWaterDragonDoor(
            ClassicWorldWaterDragonCatalog.Door door,
            boolean open, String reason) throws IOException {
        int action = open ? BattleDoor.ACTION_OPEN : BattleDoor.ACTION_CLOSED;
        int passable = open ? BattleDoor.PASSABLE : BattleDoor.NOT_PASSABLE;
        sendEncrypted(Protocol.classicCastleDoor(
                        door.objectId(classicWorldInstanceId), door.x(), door.y(),
                        door.gfxId(), action),
                "S_PUT_OBJECT Water-Dragon-door=" + door.doorId()
                        + " show=" + classicWorldInstanceId
                        + " gfx=" + door.gfxId() + " action=" + action
                        + " hp=0/0 reason=" + reason);
        sendWaterDragonDoorAttributes(door, passable, reason);
    }

    private void sendWaterDragonDoorAttributes(
            ClassicWorldWaterDragonCatalog.Door door,
            int passable, String reason) throws IOException {
        for (int edge = door.edgeLow(); edge <= door.edgeHigh(); edge++) {
            int x = door.heading() == 0 ? edge : door.entranceX();
            int y = door.heading() == 0 ? door.entranceY() : edge;
            sendEncrypted(Protocol.doorAttribute(
                            x, y, door.heading(), passable),
                    "S_CHANGE_ATTR Water-Dragon-door=" + door.doorId()
                            + " show=" + classicWorldInstanceId
                            + " x=" + x + " y=" + y
                            + " direction=" + door.heading()
                            + " passable=" + passable + " reason=" + reason);
        }
    }

    private void broadcastWaterDragonDoorOpen(
            ClassicWorldWaterDragonCatalog.Door door,
            int showId, String reason) throws IOException {
        byte[] action = Protocol.objectAction(
                door.objectId(showId), BattleDoor.ACTION_OPEN);
        for (ClientSession member : hub.classicWorldMembers(
                ClassicWorldWaterDragonCatalog.MAP_ID, showId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, door.x(), door.y())) {
                continue;
            }
            member.sendEncrypted(action,
                    "S_ACTION Water-Dragon-door=" + door.doorId()
                            + " show=" + showId + " action="
                            + BattleDoor.ACTION_OPEN + " reason=" + reason);
            member.sendWaterDragonDoorAttributes(
                    door, BattleDoor.PASSABLE, reason);
        }
    }

    private void sendClassicWorldMonsters(String reason) throws IOException {
        for (ClassicWorldMonsterPopulation.Snapshot monster
                : hub.classicWorldMonstersInScreen(
                        classicWorldMapId, classicWorldInstanceId,
                        positionX, positionY)) {
            sendClassicWorldMonster(monster, reason);
        }
    }

    private void sendClassicWorldCompanionObject(ClientSession clientSession, BattleCompanion.Snapshot snapshot, String string) throws IOException {
        if (clientSession == null || snapshot == null || !snapshot.active() || !snapshot.kind().classicWorldEligible()) {
            return;
        }
        if (snapshot.kind() == BattleCompanion.Kind.PET) {
            this.sendEncrypted(Protocol.classicPet(snapshot, clientSession.playerName(), this == clientSession), "S_PUT_OBJECT persistent-pet=" + snapshot.objectId() + " owner=" + clientSession.playerName() + " exp=" + snapshot.experience() + " lawful=" + snapshot.lawful() + " hp-tail=" + (this == clientSession ? NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()) : 255) + " reason=" + string);
        } else {
            this.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(), snapshot.x(), snapshot.y(), snapshot.gfx(), 0, 0, snapshot.moveSpeed(), 0, snapshot.level(), 0, clientSession.playerName(), this == clientSession ? NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()) : 255);
            this.sendEncrypted(Protocol.master(snapshot.objectId(), clientSession.playerName()), "S_MASTER classic-world-companion=" + snapshot.objectId() + " owner=" + clientSession.playerName() + " reason=" + string);
            this.sendEncrypted(Protocol.speed(snapshot.objectId(), Protocol.SpeedMode.fromWire(snapshot.moveSpeed()), 0), "S_SPEED classic-world-companion=" + snapshot.objectId() + " mode=" + snapshot.moveSpeed() + " reason=" + string);
        }
        if (snapshot.hp() == 0) {
            this.sendEncrypted(Protocol.objectAction(snapshot.objectId(), 8), "S_ACTION classic-world-pet-corpse=" + snapshot.objectId() + " reason=" + string);
        }
    }

    private void sendClassicWorldMonster(
            ClassicWorldMonsterPopulation.Snapshot monster, String reason)
            throws IOException {
        if (monster.hiddenStatus()
                == ClassicWorldMonsterPopulation.HIDDEN_STATUS_SINK) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.HIDE),
                    "S_ACTION classic-world-monster hidden-sink="
                            + monster.objectId() + " action="
                            + BattleActionCodes.HIDE + " reason=" + reason);
        } else if (monster.hiddenStatus()
                == ClassicWorldMonsterPopulation.HIDDEN_STATUS_ICE) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.HIDE),
                    "S_ACTION classic-world-monster hidden-ice="
                            + monster.objectId() + " action="
                            + BattleActionCodes.HIDE + " reason=" + reason);
        } else if (monster.hiddenStatus()
                == ClassicWorldMonsterPopulation.HIDDEN_STATUS_FLY) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.MOVE_UP),
                    "S_ACTION classic-world-monster hidden-fly="
                            + monster.objectId() + " action="
                            + BattleActionCodes.MOVE_UP + " reason=" + reason);
        }
        int moveSpeed = phase == Phase.WORLD
                && classicWorldMapId == monster.mapId()
                ? hub.classicWorldMonsterMoveSpeed(
                        monster.mapId(), classicWorldInstanceId,
                        monster.objectId(), System.nanoTime())
                : BattleTimedStatus.NORMAL;
        sendEncrypted(Protocol.classicWorldMonster(monster, moveSpeed),
                "S_PUT_OBJECT classic-world-monster=" + monster.objectId()
                        + " spawn=" + monster.spawnId()
                        + " slot=" + monster.spawnNumber()
                        + " npc=" + monster.npcId()
                        + " gfx=" + monster.gfxId()
                        + " name=" + monster.nameId()
                        + " title=" + monster.title()
                        + " lawful=" + monster.lawful()
                        + " move-speed=" + moveSpeed
                        + " hp=" + monster.currentHp() + "/" + monster.maximumHp()
                        + " x=" + monster.x() + " y=" + monster.y()
                        + " heading=" + monster.heading()
                        + " hidden=" + monster.hiddenStatus()
                        + " actor-status=" + monster.actorStatus()
                        + " reason=" + reason);
        if (!monster.alive()) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.DIE),
                    "S_ACTION classic-world-monster corpse=" + monster.objectId());
        } else if (phase == Phase.WORLD
                && classicWorldMapId == monster.mapId()) {
            int palette = hub.classicWorldMonsterPoisonPalette(
                    monster.mapId(), classicWorldInstanceId,
                    monster.objectId(), System.nanoTime());
            if (palette != 0) {
                sendEncrypted(Protocol.poison(monster.objectId(), palette),
                        "S_POISON classic-world-monster=" + monster.objectId()
                                + " type=" + palette + " reason=" + reason
                                + "-bootstrap");
            }
        }
    }

