    private BattleCompanion.Damage applyClassicWorldMonsterCompanionPoisonDamage(
            BattleCompanion controlled, BattleCompanion.Snapshot companion,
            int damage, long attackerObjectId) throws IOException {
        return applyClassicWorldMonsterCompanionDamageInternal(
                controlled, companion, damage, attackerObjectId,
                "monster-poison-death", true);
    }

    private BattleCompanion.Damage applyClassicWorldMonsterCompanionDamageInternal(BattleCompanion battleCompanion, BattleCompanion.Snapshot snapshot, int n, long l, String string, boolean bl) throws IOException {
        if (battleCompanion == null || snapshot == null || n <= 0 || battleCompanion.snapshot().objectId() != snapshot.objectId() || !snapshot.active() || !snapshot.kind().classicWorldEligible() || !bl && NativeCombatAttacker.companionEarth(battleCompanion, System.nanoTime()) || l <= 0L || string == null || string.isBlank()) {
            return NativeCompanionTargets.finished(null, this, battleCompanion);
        }
        BattleCompanion.Damage damage = NativeCompanionTargets.damage(this, battleCompanion, n);
        if (NativeSummonTerminalLifecycle.legacyApplied(damage) <= 0) {
            return NativeCompanionTargets.finished(damage, this, battleCompanion);
        }
        if (!damage.diedNow()) {
            this.sendEncrypted(NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), damage.after().hp(), damage.after().maxHp()), "S_HIT_RATIO classic-world-companion=" + snapshot.objectId() + " hp=" + damage.after().hp() + "/" + damage.after().maxHp() + " owner-only=true");
            return NativeCompanionTargets.finished(damage, this, battleCompanion);
        }
        if (snapshot.kind() == BattleCompanion.Kind.PET) {
            this.hub.transferClassicWorldMonsterTargets(snapshot.objectId(), this.playerObjectId());
            this.sendEncrypted(NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), 0, snapshot.maxHp()), "S_HIT_RATIO classic-world-pet-death=" + snapshot.objectId() + " hp=0/" + snapshot.maxHp() + " owner-only=true");
            byte[] byArray = Protocol.objectAction(snapshot.objectId(), 8);
            for (ClientSession clientSession : NativeCompanionTargets.damageMembers(this, this.classicWorldMapId, battleCompanion)) {
                if (!BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y())) continue;
                clientSession.sendEncrypted(byArray, "S_ACTION classic-world-pet-death=" + snapshot.objectId() + " owner=" + this.playerName());
            }
            System.out.println("[LiTo] persistent pet died owner=" + this.playerName() + " object=" + snapshot.objectId() + " attacker=" + l + " corpse-retained=true hate-transferred=true");
        } else {
            this.removeClassicWorldCompanion(battleCompanion, damage.before(), string, true);
        }
        return NativeCompanionTargets.finished(damage, this, battleCompanion);
    }

    /** Advances retained non-player poison timers; NPC targets never receive messages 212/310/311 or S_PARALYSE. */
    private boolean pollClassicWorldCompanionPoison(
            BattleCompanion controlled, BattleCompanion.Snapshot snapshot,
            long nowNanos) throws IOException {
        BattleCompanion.NpcPoisonPoll poll = controlled.pollNpcPoison(nowNanos);
        if (poll.kind() == ClassicWorldMonsterPoisonAttack.Kind.NONE) {
            return false;
        }
        if (poll.activated()) {
            broadcastClassicWorldCompanionPoisonPalette(
                    snapshot, 2, "monster-paralysis-poison-active");
        }
        if (poll.expired()) {
            broadcastClassicWorldCompanionPoisonPalette(
                    snapshot, 0, "monster-poison-expired");
        }
        BattleCompanion.Damage transition = null;
        if (poll.damageTicks() > 0) {
            int damage = Math.multiplyExact(
                    poll.damageTicks(),
                    ClassicWorldMonsterPoisonAttack.DAMAGE_PER_TICK);
            transition = applyClassicWorldMonsterCompanionPoisonDamage(
                    controlled, snapshot, damage, poll.attackerObjectId());
            System.out.println("[LiTo] classic-world companion damage poison tick"
                    + " target=" + snapshot.objectId() + " target-kind="
                    + snapshot.kind() + " attacker=" + poll.attackerObjectId()
                    + " ticks=" + poll.damageTicks() + " requested-damage="
                    + damage + " applied-damage=" + (transition == null
                        ? 0 : transition.appliedDamage()) + " ignores-physical-zero=true");
            if (transition != null && transition.diedNow()) {
                broadcastClassicWorldCompanionPoisonPalette(
                        snapshot, 0, "monster-poison-target-died");
            }
        }
        return transition != null && transition.diedNow();
    }

    /** Advances the independent skill33 L1Paralysis lease for TAMED targets. */
    private void pollClassicWorldCompanionCurseParalysis(
            BattleCompanion controlled, BattleCompanion.Snapshot snapshot,
            long nowNanos) throws IOException {
        BattleCompanion.NpcCurseParalysisPoll poll =
                controlled.pollNpcCurseParalysis(nowNanos);
        if (poll.activated()) {
            // Zero-delay NPC installation emits type 2 synchronously. This
            // branch is retained as a defensive clock assertion.
            broadcastClassicWorldCompanionPoisonPalette(
                    snapshot, 2, "monster-curse-paralysis-active-poll");
        }
        if (poll.expired()) {
            broadcastClassicWorldCompanionPoisonPalette(
                    snapshot, 0, "monster-curse-paralysis-expired");
        }
    }

    private void broadcastClassicWorldCompanionPoisonPalette(
            BattleCompanion.Snapshot companion, int palette, String reason)
            throws IOException {
        byte[] packet = Protocol.poison(companion.objectId(), palette);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            companion.x(), companion.y())) continue;
            member.sendEncrypted(packet,
                    "S_POISON classic-world-companion=" + companion.objectId()
                            + " type=" + palette + " reason=" + reason);
        }
    }

    private boolean sameClassicWorldMap(ClientSession other) {
        return other != null && other.phase == Phase.WORLD
                && ClassicWorldMapCatalog.supports(classicWorldMapId)
                && other.classicWorldMapId == classicWorldMapId
                && other.classicWorldInstanceId == classicWorldInstanceId;
    }

    private List<ClientSession> classicWorldMembers(int mapId) {
        int instanceId = mapId == classicWorldMapId
                ? classicWorldInstanceId : -1;
        return hub.classicWorldMembers(mapId, instanceId);
    }

    private void notifyClassicWorldPeersOfRemoval(String string) throws IOException {
        if (this.phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(this.classicWorldMapId)) {
            return;
        }
        byte[] byArray = Protocol.removeObject(this.playerObjectId());
        List<byte[]> list = NativeCompanionPlacement.departing(this).stream().filter(BattleCompanion.Snapshot::active).map(snapshot -> Protocol.removeObject(snapshot.objectId())).toList();
        IOException iOException = null;
        for (ClientSession clientSession : this.classicWorldMembers(this.classicWorldMapId)) {
            if (clientSession == this || !this.sameClassicWorldMap(clientSession)) continue;
            try {
                clientSession.sendEncrypted(byArray, "S_REMOVE_OBJECT classic-world player=" + this.playerName() + " reason=" + string);
                for (byte[] byArray2 : list) {
                    clientSession.sendEncrypted(byArray2, "S_REMOVE_OBJECT classic-world companion-owner=" + this.playerName() + " reason=" + string);
                }
            }
            catch (IOException iOException2) {
                if (iOException != null) continue;
                iOException = iOException2;
            }
        }
        if (iOException != null) {
            throw iOException;
        }
    }

    private void sendPortalWorldRebuild() throws IOException {
        // sub_48BC80 emits C_GOTO_PORTAL and then destroys the previous local
        // actor and every known world object.  Re-establish status before the
        // local S_PUT_OBJECT, just as at battle bootstrap, then repopulate all
        // authoritative combatants and their minimap rows.
        pendingRepairNpc = null;
        pendingSpellShop = null;
        pendingSpellMaterialShop = null;
        pendingCastleAdmin = null;
        pendingMercenaryAdmin = null;
        clearPendingClassicList();
        sendBattleStatus();
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        List<ClientSession> combatants = NativeBattleVisibility.localFirst(hub.visibleBattleCombatants(
                currentRoomId, this), this);
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(
                hub.battleMapId(currentRoomId, this));
        for (ClientSession member : combatants) {
            if (!member.invisible || member == this) {
                sendBattleObject(member.playerObjectId(), member.litoDisplayName(),
                        member.sourceCharacterIdentity(),
                        member.positionX, member.positionY, member.battleGfx(),
                        member.battleWalkAction(), member.battleLightRange(),
                        member.battleMoveSpeed(),
                        4 | (member.invisible ? 2 : 0), member.battleLevel(),
                        nativeLawful(member.characterLawful()), member.classicTitle,
                        member == this ? 0xFF : member.battleHpRatio());
            }
            sendBattleCompanion(member, arena,
                    new ArenaMapCatalog.Point(member.positionX, member.positionY),
                    "portal-rebuild");
        }
        ArenaMapCatalog.Point bot = hub.botPosition(currentRoomId);
        if (bot == null) bot = arena.botSpawn();
        if (NativeRoomRules.bot(rules.mode(), this)
                && hub.roomCombatantCount(currentRoomId) < 2) {
            sendBattleObject(2, "ArenaBot", "ArenaBot", bot.x(), bot.y(), 61,
                    BattleActionCodes.WALK, 0, BattleTimedStatus.NORMAL, 0, 1, 0, "", Protocol.healthRatio(
                            hub.botHp(currentRoomId), GameHub.ARENA_BOT_MAX_HP));
        }
        sendGuardianTowers("portal-rebuild");
        sendQuestMonsters("portal-rebuild");
        sendQuestBoundary("portal-rebuild");
        sendTimeAttackActors("portal-rebuild");
        sendBattleDoor("portal-rebuild");
        sendSiegeGate("portal-rebuild");
        sendRepairNpc("portal-rebuild");
        sendSpellShopNpc("portal-rebuild");
        sendSpellMaterialNpc("portal-rebuild");
        sendClassicMerchantNpc("portal-rebuild");
        sendWarehouseNpc("portal-rebuild");
        sendCastleStewardNpc("portal-rebuild");
        sendHouseAuctionBoard("portal-rebuild");
        sendMercenaryCommanderNpc("portal-rebuild");
        sendGroundItems("portal-rebuild");
        sendCookingFires("portal-rebuild");
        sendCubeIgnitions("portal-rebuild");
        sendCubeQuakes("portal-rebuild");
        sendCubeShocks("portal-rebuild");
        sendCubeHarmonies("portal-rebuild");
        sendShockStunEffects("portal-rebuild");
        sendBoneBreakEffects("portal-rebuild");
        sendFreezeEffects("portal-rebuild");
        sendBattleCompanionMasters(combatants, "portal-rebuild");
        sendBattleSpeedStates(combatants, "portal-rebuild");
        sendBattleBraveStates(combatants, "portal-rebuild");
        sendBattleBlindState("portal-rebuild");
        sendBattleBreathState("portal-rebuild");
        sendBattleDrunkenState("portal-rebuild");
        sendBattlePoisonStates(combatants, "portal-rebuild");
        sendBattleParalysisState("portal-rebuild");
        sendBattleSleepState("portal-rebuild");
        sendBattleFreezeState("portal-rebuild");
        sendBattleShockStunState("portal-rebuild");
        sendBattleThunderGrabState("portal-rebuild");
        if (invisible && !observer) {
            sendEncrypted(Protocol.invisible(playerObjectId(), 1),
                    "S_INVISIBLE mode=1 reason=portal-local-rebuild");
        }
        for (ClientSession member : combatants) {
            if (member.invisible && member != this) continue;
            GameHub.ClanData clan = hub.clanData(member.sourceCharacterIdentity());
            if (!clan.name().isBlank()) {
                sendEncrypted(Protocol.battleClanMetadata(
                                member.playerObjectId(), 0, clan.name(), true),
                        "S_LITO_CLAN portal object=" + member.playerObjectId()
                                + " clan=" + clan.name());
            }
            sendEncrypted(Protocol.minimapPlayer(member.playerObjectId(),
                            member.positionX, member.positionY, minimapAlliedWith(member)),
                    "S_LITO_MINIMAP portal player=" + member.playerName()
                            + " x=" + member.positionX + " y=" + member.positionY);
        }
        if (NativeRoomRules.bot(rules.mode(), this) && hub.roomCombatantCount(currentRoomId) < 2) {
            sendEncrypted(Protocol.minimapPlayer(2, bot.x(), bot.y(),
                            minimapAlliedWithForce(1)),
                    "S_LITO_MINIMAP portal player=ArenaBot x=" + bot.x()
                            + " y=" + bot.y());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT portal player=" + playerHp + "/" + playerMaxHp);
        // S_PORTAL makes the native client enter its teleport/action cursor
        // lock again after the early C_TELEPORT acknowledgement.  Release it
        // only after C_GOTO_PORTAL has rebuilt the local actor and world rows;
        // otherwise the picture is visible but both mouse actions and walking
        // remain disabled.
        sendTeleportCursorUnlock("battle-portal-rebuild-ready");
    }

    private void changeDirection(byte[] payload) throws IOException {
        if ((phase != Phase.BATTLE && phase != Phase.WORLD) || observer) return;
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        int heading = in.remaining() > 0 ? in.c() & 7 : 0;
        if (rejectWhileParalyzed("C_CHANGE_DIRECTION")) return;
        playerHeading = heading;
        byte[] changed = new Protocol.Writer().c(Protocol.S_CHANGE_DIRECTION)
                .d(playerObjectId()).c(heading).bytes();
        if (rentalTownRoomState) {
            for (ClientSession member : rentalTownMembers()) {
                if (member != this && !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, positionX, positionY)) {
                    continue;
                }
                member.sendEncrypted(changed,
                        "S_CHANGE_DIRECTION rental-town object="
                                + playerObjectId() + " heading=" + heading);
            }
            return;
        }
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY, member.positionX, member.positionY)) continue;
            if (invisible && member != this) continue;
            member.sendEncrypted(changed,
                    "S_CHANGE_DIRECTION object=" + playerObjectId() + " heading=" + heading);
        }
    }

    private void action(byte[] payload) throws IOException {
        if ((phase != Phase.BATTLE && phase != Phase.WORLD) || observer) return;
        closePersonalShopIfOpen("action");
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        int action = in.remaining() > 0 ? in.c() : 0;
        if (rejectWhileParalyzed("C_ACTION")) return;
        int gfx = battleGfx();
        BattleAnimationCatalog animations = BattleAnimationCatalog.get();
        if (!animations.supportsTimedAction(gfx, action)
                && !BattleActionCodes.isUntimedCoreAction(action)) {
            System.out.println("[LiTo] rejected unavailable action player=" + playerName()
                    + " gfx=" + gfx + " action=" + action);
            return;
        }
        byte[] performed = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(action).bytes();
        if (rentalTownRoomState) {
            for (ClientSession member : rentalTownMembers()) {
                if (member != this && !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, positionX, positionY)) {
                    continue;
                }
                member.sendEncrypted(performed,
                        "S_ACTION rental-town object=" + playerObjectId()
                                + " action=" + action);
            }
            return;
        }
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY, member.positionX, member.positionY)) continue;
            if (invisible && member != this) continue;
            member.sendEncrypted(performed,
                    "S_ACTION object=" + playerObjectId() + " action=" + action);
        }
    }

    private void useSpell(byte[] byArray) throws IOException {
        NativeLightAction.dispatch(this, byArray);
    }

