    private void useAdvanceSpiritSpell(byte[] byArray, BattleSpellCatalog.AdvanceSpiritSpell advanceSpiritSpell) throws IOException {
        byte[] object2Packet;
        byte[] objectPacket;
        int n;
        int n2;
        int n3;
        int n4;
        boolean bl;
        int n5;
        boolean bl2;
        Object object;
        boolean bl3;
        Protocol.ObjectSpellRequest objectSpellRequest = NativeSourceObjectTargetRequest.request(Protocol.objectSpellRequest(byArray), this, advanceSpiritSpell.skillId());
        if (!NativeSelectedPlayerIntent.object(this, objectSpellRequest)) {
            return;
        }
        boolean bl4 = this.phase == Phase.WORLD;
        List<ClientSession> list = bl4 ? this.classicWorldMembers(this.classicWorldMapId) : this.hub.roomCombatants(this.currentRoomId);
        ClientSession clientSession2 = list.stream().filter(clientSession -> clientSession.playerObjectId() == objectSpellRequest.targetObjectId()).findFirst().orElse(null);
        boolean bl5 = clientSession2 != null && (bl4 ? this.sameClassicWorldMap(clientSession2) : this.hub.battleMapId(this.currentRoomId, this) == this.hub.battleMapId(this.currentRoomId, clientSession2));
        boolean bl6 = clientSession2 != null && clientSession2.phase == this.phase && !clientSession2.observer && clientSession2.playerHp > 0 && (!clientSession2.invisible || clientSession2 == this);
        boolean bl7 = bl3 = clientSession2 != null && BattleSpellCatalog.isInNativeScreen(this.positionX, this.positionY, clientSession2.positionX, clientSession2.positionY);
        if (!(objectSpellRequest.skillId() == advanceSpiritSpell.skillId() && bl5 && bl6 && bl3 && BattleAnimationCatalog.get().supportsTimedAction(this.battleGfx(), advanceSpiritSpell.actionId()))) {
            System.out.println("[LiTo] C_USE_SPELL Advance Spirit rejected selector/target/range player=" + this.playerName() + " skill=" + objectSpellRequest.skillId() + " target=" + objectSpellRequest.targetObjectId() + " same-map=" + bl5 + " living=" + bl6 + " native-screen=" + bl3);
            return;
        }
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        SourceEquipmentMagicStats sourceEquipmentMagicStats = this.requiredEquipmentMagicStats();
        int n6 = sourceEquipmentMagicStats.effectiveIntelligence(this.baseIntelligence());
        int n7 = BattleSpellCatalog.originalMagicConsumeReduction(characterSummary == null ? 0 : characterSummary.type(), characterSummary == null ? 0 : Math.max(0, characterSummary.originalIntelligence()));
        int n8 = NativeSkillConsumptionBridges.AdvanceSpiritSpell_effectiveMpCost_III(advanceSpiritSpell, n6, n7);
        ClientSession clientSession3 = this.playerObjectId() <= clientSession2.playerObjectId() ? this : clientSession2;
        ClientSession clientSession4 = clientSession3 == this ? clientSession2 : this;
        long l = System.nanoTime();
        Object object2 = clientSession3;
        synchronized (object2) {
            object = clientSession4;
            synchronized (object) {
                long l2 = this.spellReadyNanos.getOrDefault(advanceSpiritSpell.skillId(), 0L);
                boolean bl8 = this.phase == Phase.BATTLE && this.currentRoomId != 0L && clientSession2.phase == Phase.BATTLE && clientSession2.currentRoomId == this.currentRoomId;
                boolean bl9 = bl2 = this.phase == Phase.WORLD && clientSession2.phase == Phase.WORLD && this.sameClassicWorldMap(clientSession2);
                if (l < l2 || this.playerMp < n8 || this.phase != Phase.BATTLE && this.phase != Phase.WORLD || !bl8 && !bl2 || clientSession2.phase != this.phase || this.observer || this.playerHp <= 0 || clientSession2.observer || clientSession2.playerHp <= 0 || clientSession2.invisible && clientSession2 != this) {
                    System.out.println("[LiTo] C_USE_SPELL Advance Spirit rejected state skill=" + advanceSpiritSpell.skillId() + " mp=" + this.playerMp + " cost=" + n8 + " cooldownNanos=" + Math.max(0L, l2 - l));
                    return;
                }
                this.cancelMeditation("spell-" + advanceSpiritSpell.skillId());
                ClientSession clientSession5 = this;
                clientSession5.playerMp = NativeSkillConsumption.boundMp(clientSession5, clientSession5.playerMp - n8);
                n5 = this.playerMp;
                bl = clientSession2.timedStatus.activateAdvanceSpirit(l, advanceSpiritSpell.durationSeconds());
                clientSession2.rebuildMaximumVitals(l);
                n4 = clientSession2.playerHp;
                n3 = clientSession2.playerMp;
                n2 = clientSession2.playerMaxHp;
                n = clientSession2.playerMaxMp;
                this.commitSpellReady(advanceSpiritSpell.skillId(), l + (long)advanceSpiritSpell.reuseDelayMillis() * 1000000L);
            }
        }
        object2Packet = Protocol.objectAction(this.playerObjectId(), advanceSpiritSpell.actionId());
        objectPacket = Protocol.effectObject(clientSession2.playerObjectId(), advanceSpiritSpell.effectGfx());
        List<ClientSession> list2 = bl4 ? this.classicWorldMembers(this.classicWorldMapId) : this.hub.roomMembers(this.currentRoomId);
        for (ClientSession clientSession6 : list2) {
            boolean bl10;
            bl2 = !bl4 || this.sameClassicWorldMap(clientSession6) && BattleSpellCatalog.isInNativeScreen(clientSession6.positionX, clientSession6.positionY, this.positionX, this.positionY);
            boolean bl11 = bl10 = !bl4 || this.sameClassicWorldMap(clientSession6) && BattleSpellCatalog.isInNativeScreen(clientSession6.positionX, clientSession6.positionY, clientSession2.positionX, clientSession2.positionY);
            if (bl2 && (!this.invisible || clientSession6 == this)) {
                clientSession6.sendEncrypted(object2Packet, "S_ACTION advance-spirit-cast object=" + this.playerObjectId() + " action=" + advanceSpiritSpell.actionId());
            }
            if (!bl10) continue;
            clientSession6.sendEncrypted(objectPacket, "S_EFFECT advance-spirit target=" + clientSession2.playerObjectId() + " gfx=" + advanceSpiritSpell.effectGfx());
        }
        clientSession2.sendEncrypted(new Protocol.Writer().c(13).h(n4).h(n2).bytes(), "S_HIT_POINT advance-spirit=" + n4 + "/" + n2);
        clientSession2.broadcastOwnHitRatio("advance-spirit-max-hp");
        clientSession2.sendEncrypted(Protocol.manaPoint(n3, n), "S_MANA_POINT advance-spirit=" + n3 + "/" + n);
        clientSession2.sendNativeBattleStatus(l, "advance-spirit-active");
        if (clientSession2 != this) {
            this.sendEncrypted(Protocol.manaPoint(n5, this.playerMaxMp), "S_MANA_POINT advance-spirit-caster=" + n5 + "/" + this.playerMaxMp);
        }
        System.out.println("[LiTo] C_USE_SPELL Advance Spirit caster=" + this.playerName() + " target=" + clientSession2.playerName() + " selector=" + objectSpellRequest.row() + "/" + objectSpellRequest.column() + " action=" + advanceSpiritSpell.actionId() + " gfx=" + advanceSpiritSpell.effectGfx() + " duration=" + advanceSpiritSpell.durationSeconds() + " newly-active=" + bl + " max-hp=" + n2 + " max-mp=" + n + " effective-int=" + n6 + " mp-cost=" + n8 + " mp=" + n5 + "/" + this.playerMaxMp + " phase=" + String.valueOf((Object)this.phase) + " cancellation-immune=true selected-client-icon=unavailable");
    }

