    /** Build skill211's current PC/NPC candidates from authoritative state. */
    private Map<Long, PatienceTarget> patienceTargets(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int originX, int originY, int maximumRange,
            long nowNanos) {
        LinkedHashMap<Long, PatienceTarget> targets = new LinkedHashMap<>();
        ArenaMapCatalog.Arena arena = originPhase == Phase.BATTLE
                ? ArenaMapCatalog.forMap(originMapId) : null;
        ClassicWorldMapCatalog.ClassicMap worldMap = originPhase == Phase.WORLD
                ? ClassicWorldMapCatalog.forMap(originMapId) : null;
        List<ClientSession> visiblePlayers = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.visibleBattleCombatants(originRoomId, this);
        for (ClientSession candidate : visiblePlayers) {
            if (candidate == null || candidate == this || candidate.observer
                    || candidate.playerHp <= 0 || candidate.invisible
                    || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        candidate.timedStatus.absoluteBarrierActive(nowNanos),
                        BattleSpellCatalog.PATIENCE)) continue;
            boolean sameContext = originPhase == Phase.WORLD
                    ? candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                    : candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == originMapId;
            if (!sameContext || !patiencePositionEligible(
                    originPhase, arena, worldMap, originX, originY,
                    candidate.positionX, candidate.positionY, maximumRange)) continue;
            if (!putUniquePatienceTarget(targets, new PatienceTarget(
                    candidate.playerObjectId(), candidate.positionX,
                    candidate.positionY, BattleTrueTarget.Kind.PLAYER,
                    candidate))) return null;
        }

        for (ClientSession owner : visiblePlayers) {
            boolean sameOwnerContext = originPhase == Phase.WORLD
                    ? owner.phase == Phase.WORLD
                        && owner.classicWorldMapId == originMapId
                        && owner.classicWorldInstanceId == originInstanceId
                    : owner.phase == Phase.BATTLE
                        && owner.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, owner) == originMapId;
            if (!sameOwnerContext) continue;
            List<BattleCompanion.Snapshot> companions = originPhase == Phase.WORLD
                    ? owner.classicWorldCompanionSnapshots()
                    : owner.controlledCompanionSnapshots();
            for (BattleCompanion.Snapshot companion : companions) {
                if (!companion.active() || companion.hp() <= 0
                        || !patiencePositionEligible(
                            originPhase, arena, worldMap, originX, originY,
                            companion.x(), companion.y(), maximumRange)) continue;
                if (!putUniquePatienceTarget(targets, new PatienceTarget(
                        companion.objectId(), companion.x(), companion.y(),
                        BattleTrueTarget.Kind.COMPANION, null))) return null;
            }
        }

        if (originPhase == Phase.WORLD) {
            for (ClassicWorldMonsterPopulation.Snapshot monster
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, originX, originY)) {
                if (!monster.present() || !monster.alive()
                        || monster.mapId() != originMapId
                        || !patiencePositionEligible(
                            originPhase, arena, worldMap, originX, originY,
                            monster.x(), monster.y(), maximumRange)) continue;
                if (!putUniquePatienceTarget(targets, new PatienceTarget(
                        monster.objectId(), monster.x(), monster.y(),
                        BattleTrueTarget.Kind.WORLD_MONSTER, null))) return null;
            }
            return targets;
        }

        for (BattleGuardianTower.Snapshot tower
                : hub.visibleGuardianTowers(originRoomId, this)) {
            if (tower.destroyed() || tower.hp() <= 0
                    || !patiencePositionEligible(originPhase, arena, worldMap,
                        originX, originY, tower.x(), tower.y(), maximumRange)) continue;
            if (!putUniquePatienceTarget(targets, new PatienceTarget(
                    tower.objectId(), tower.x(), tower.y(),
                    BattleTrueTarget.Kind.GUARDIAN_TOWER, null))) return null;
        }
        for (BattleQuestEncounter.Snapshot monster
                : hub.visibleQuestMonsters(originRoomId, this)) {
            if (!monster.alive() || monster.hp() <= 0
                    || !patiencePositionEligible(originPhase, arena, worldMap,
                        originX, originY, monster.x(), monster.y(), maximumRange)) continue;
            if (!putUniquePatienceTarget(targets, new PatienceTarget(
                    monster.objectId(), monster.x(), monster.y(),
                    BattleTrueTarget.Kind.QUEST_MONSTER, null))) return null;
        }
        for (BattleTimeAttackEncounter.Snapshot actor
                : hub.visibleTimeAttackActors(originRoomId, this)) {
            if (!actor.alive() || actor.hp() <= 0
                    || !patiencePositionEligible(originPhase, arena, worldMap,
                        originX, originY, actor.x(), actor.y(), maximumRange)) continue;
            if (!putUniquePatienceTarget(targets, new PatienceTarget(
                    actor.objectId(), actor.x(), actor.y(),
                    BattleTrueTarget.Kind.TIME_ATTACK_ACTOR, null))) return null;
        }
        BattleRules.Mode mode = hub.roomRules(originRoomId).mode();
        if (mode != BattleRules.Mode.QUEST_BATTLE
                && mode != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(originRoomId) < 2
                && hub.botHp(originRoomId) > 0) {
            ArenaMapCatalog.Point bot = hub.botPosition(originRoomId);
            if (bot != null && patiencePositionEligible(
                    originPhase, arena, worldMap, originX, originY,
                    bot.x(), bot.y(), maximumRange)
                    && !putUniquePatienceTarget(targets, new PatienceTarget(
                        2L, bot.x(), bot.y(), BattleTrueTarget.Kind.ARENA_BOT,
                        null))) return null;
        }
        return targets;
    }

    private static boolean putUniquePatienceTarget(
            Map<Long, PatienceTarget> targets, PatienceTarget candidate) {
        return targets.putIfAbsent(candidate.objectId(), candidate) == null;
    }

    private static boolean patiencePositionEligible(
            Phase originPhase, ArenaMapCatalog.Arena arena,
            ClassicWorldMapCatalog.ClassicMap worldMap,
            int originX, int originY, int targetX, int targetY,
            int maximumRange) {
        if (targetRange(originX, originY, targetX, targetY) > maximumRange) {
            return false;
        }
        return originPhase == Phase.WORLD
                ? worldMap.hasLineOfSight(originX, originY, targetX, targetY)
                : BattleSpellCatalog.hasNativeLineOfSight(
                        arena, originX, originY, targetX, targetY);
    }

    private PatienceTarget resolveSelectorOnlyPatienceTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int originX, int originY, int maximumRange,
            long nowNanos) {
        Map<Long, PatienceTarget> external = patienceTargets(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, maximumRange, nowNanos);
        if (external == null) {
            System.out.println("[LiTo] C_USE_SPELL Patience rejected duplicate"
                    + " object identity player=" + playerName());
            return null;
        }
        if (IllusionSkillRequests.current() != null) return (PatienceTarget)IllusionSkillRequests.selectActor(this, external);
        PatienceTarget lastExplicit = external.get(lastCombatTargetObjectId);
        if (lastExplicit != null) return lastExplicit;
        if (external.size() == 1) return external.values().iterator().next();
        if (external.isEmpty()) {
            return new PatienceTarget(playerObjectId(), originX, originY,
                    BattleTrueTarget.Kind.PLAYER, this);
        }
        System.out.println("[LiTo] C_USE_SPELL Patience rejected ambiguous"
                + " selector-only PC/NPC target player=" + playerName()
                + " last-explicit=" + lastCombatTargetObjectId
                + " eligible-external=" + external.size()
                + " phase=" + originPhase);
        return null;
    }

    /**
     * Skill212 uses the same selected-client target recovery as skill211, but
     * retains an Absolute Barrier target as a failed attempt.  The source
     * target gate rejects its effect; dropping the actor here would wrongly
     * retarget the selector-only request to the caster.
     */
    private Map<Long, PatienceTarget> phantasmTargets(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int originX, int originY, int maximumRange,
            long nowNanos) {
        Map<Long, PatienceTarget> base = patienceTargets(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, maximumRange, nowNanos);
        if (base == null) return null;
        LinkedHashMap<Long, PatienceTarget> targets =
                new LinkedHashMap<>(base);
        ArenaMapCatalog.Arena arena = originPhase == Phase.BATTLE
                ? ArenaMapCatalog.forMap(originMapId) : null;
        ClassicWorldMapCatalog.ClassicMap worldMap = originPhase == Phase.WORLD
                ? ClassicWorldMapCatalog.forMap(originMapId) : null;
        List<ClientSession> visiblePlayers = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.visibleBattleCombatants(originRoomId, this);
        for (ClientSession candidate : visiblePlayers) {
            if (candidate == null || candidate == this || candidate.observer
                    || candidate.playerHp <= 0 || candidate.invisible
                    || !candidate.timedStatus.absoluteBarrierActive(nowNanos)) {
                continue;
            }
            boolean sameContext = originPhase == Phase.WORLD
                    ? candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                    : candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == originMapId;
            if (!sameContext || !patiencePositionEligible(
                    originPhase, arena, worldMap, originX, originY,
                    candidate.positionX, candidate.positionY,
                    maximumRange)) continue;
            if (!putUniquePatienceTarget(targets, new PatienceTarget(
                    candidate.playerObjectId(), candidate.positionX,
                    candidate.positionY, BattleTrueTarget.Kind.PLAYER,
                    candidate))) return null;
        }
        return targets;
    }

    private PatienceTarget resolveSelectorOnlyPhantasmTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int originX, int originY, int maximumRange,
            long nowNanos) {
        Map<Long, PatienceTarget> external = phantasmTargets(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, maximumRange, nowNanos);
        if (external == null) return null;
        if (config.phantasmSpellFixtureEnabled()) {
            System.out.println("[LiTo] Phantasm fixture target recovery caster="
                    + playerObjectId() + " last=" + lastCombatTargetObjectId
                    + " candidates=" + external.keySet() + " position="
                    + originX + "," + originY + " map=" + originMapId);
        }
        if (IllusionSkillRequests.current() != null) return (PatienceTarget)IllusionSkillRequests.selectActor(this, external);
        PatienceTarget lastExplicit = external.get(lastCombatTargetObjectId);
        if (lastExplicit != null) return lastExplicit;
        if (external.size() == 1) return external.values().iterator().next();
        if (external.isEmpty()) {
            return new PatienceTarget(playerObjectId(), originX, originY,
                    BattleTrueTarget.Kind.PLAYER, this);
        }
        System.out.println("[LiTo] C_USE_SPELL Phantasm rejected ambiguous"
                + " selector-only PC/NPC target player=" + playerName()
                + " last-explicit=" + lastCombatTargetObjectId
                + " eligible-external=" + external.size()
                + " phase=" + originPhase);
        return null;
    }

