    private ArenaMapCatalog.Point resolveMassTeleportDestination(
            Protocol.MassTeleportSpellRequest request,
            ArenaMapCatalog.Arena arena) {
        if (request.mapId() != arena.mapId()) return null;
        if (request.x() == 0 && request.y() == 0) {
            return BattleMassTeleport.randomDestination(arena, positionX, positionY,
                    bound -> ThreadLocalRandom.current().nextInt(bound));
        }
        if (request.x() == 0 || request.y() == 0
                || !arena.nativeStandingFloor(request.x(), request.y())) {
            return null;
        }
        boolean exactServerBookmark = state.bookmarks(stateCharacter()).stream()
                .anyMatch(bookmark -> bookmark.mapId() == request.mapId()
                        && bookmark.x() == request.x() && bookmark.y() == request.y());
        return exactServerBookmark
                ? new ArenaMapCatalog.Point(request.x(), request.y()) : null;
    }

    private ArenaMapCatalog.Point resolveClassicWorldMassTeleportDestination(
            Protocol.MassTeleportSpellRequest request,
            ClassicWorldMapCatalog.ClassicMap sourceMap) {
        if (request.x() == 0 && request.y() == 0) {
            if (request.mapId() != sourceMap.mapId()
                    || !sourceMap.allowsRandomTeleport()) return null;
            return BattleMassTeleport.randomDestination(
                    sourceMap, positionX, positionY,
                    bound -> ThreadLocalRandom.current().nextInt(bound));
        }
        if (request.x() == 0 || request.y() == 0
                || !sourceMap.allowsEscape()
                || !ClassicWorldMapCatalog.supports(request.mapId())) {
            return null;
        }
        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(request.mapId());
        if (!destinationMap.standingPassable(request.x(), request.y())) return null;
        boolean exactServerBookmark = state.bookmarks(stateCharacter()).stream()
                .anyMatch(bookmark -> bookmark.mapId() == request.mapId()
                        && bookmark.x() == request.x()
                        && bookmark.y() == request.y());
        return exactServerBookmark
                ? new ArenaMapCatalog.Point(request.x(), request.y()) : null;
    }

    private boolean massTeleportSceneStillValid(
            Phase originPhase, long roomId, int mapId, int instanceId) {
        if (originPhase == Phase.BATTLE) {
            return phase == Phase.BATTLE && currentRoomId == roomId
                    && roomId != 0 && hub.battleStarted(roomId)
                    && hub.battleMapId(roomId, this) == mapId;
        }
        GameHub.ClassicWorldLocation location = hub.classicWorldLocation(this);
        return originPhase == Phase.WORLD && phase == Phase.WORLD
                && classicWorldMapId == mapId
                && classicWorldInstanceId == instanceId
                && location != null && location.mapId() == mapId
                && location.instanceId() == instanceId;
    }

    private void rejectMassTeleport(BattleSpellCatalog.MassTeleportSpell spell,
                                    String reason, int messageId) throws IOException {
        sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                "S_PARALYSE mode=7 mass-teleport-unlock reason=" + reason);
        if (messageId > 0) {
            sendEncrypted(Protocol.messageCode(messageId),
                    "S_MESSAGE_CODE mass-teleport-rejected=" + messageId
                            + " reason=" + reason);
        }
        System.out.println("[LiTo] C_USE_SPELL " + spell.key()
                + " rejected player=" + playerName() + " reason=" + reason);
    }

