    private boolean tripleArrowTargetPresent(long targetObjectId) {
        if (targetObjectId <= 0 || targetObjectId == playerObjectId()) return false;
        if (phase == Phase.WORLD) {
            ClientSession playerTarget = classicWorldMembers(classicWorldMapId).stream()
                    .filter(candidate -> candidate != this
                            && sameClassicWorldMap(candidate)
                            && candidate.playerObjectId() == targetObjectId
                            && !candidate.observer && candidate.playerHp > 0
                            && !candidate.invisible)
                    .findFirst().orElse(null);
            if (playerTarget != null) return true;
            ClassicWorldMonsterPopulation.Snapshot monster =
                    hub.classicWorldMonster(classicWorldMapId,
                            classicWorldInstanceId, targetObjectId);
            return monster != null && monster.present() && monster.alive();
        }
        if (phase != Phase.BATTLE || currentRoomId == 0
                || !hub.battleStarted(currentRoomId)) return false;
        ClientSession playerTarget = hub.roomCombatants(currentRoomId).stream()
                .filter(candidate -> candidate != this
                        && candidate.playerObjectId() == targetObjectId
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible)
                .findFirst().orElse(null);
        if (playerTarget != null && hub.canAttack(
                currentRoomId, this, playerTarget)) return true;
        BattleGuardianTower.Snapshot tower =
                hub.guardianTower(currentRoomId, targetObjectId);
        if (tower != null && hub.canAttackGuardianTower(
                currentRoomId, this, targetObjectId)) return true;
        BattleQuestEncounter.Snapshot monster =
                hub.questMonster(currentRoomId, targetObjectId);
        if (monster != null && hub.canAttackQuestMonster(
                currentRoomId, this, targetObjectId)) return true;
        BattleTimeAttackEncounter.Snapshot timeActor =
                hub.timeAttackActor(currentRoomId, targetObjectId);
        if (timeActor != null && hub.canAttackTimeAttackActor(
                currentRoomId, this, targetObjectId)) return true;
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        return targetObjectId == 2
                && rules.mode() != BattleRules.Mode.QUEST_BATTLE
                && rules.mode() != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2;
    }

