    private void rejectRunClan(BattleSpellCatalog.RunClanSpell spell,
                               String reason, int messageId, String argument)
            throws IOException {
        if (messageId > 0) {
            byte[] message = argument == null
                    ? Protocol.messageCode(messageId)
                    : Protocol.messageCode(messageId, argument);
            sendEncrypted(message,
                    "S_MESSAGE_CODE Run Clan rejected=" + messageId
                            + " reason=" + reason
                            + (argument == null ? "" : " argument=" + argument));
        }
        System.out.println("[LiTo] C_USE_SPELL " + spell.key()
                + " rejected player=" + playerName() + " reason=" + reason);
    }

    private void beginRunClanPortal(PendingRunClanPortal portal)
            throws IOException {
        if (pendingPortal != null || portal == null) {
            throw new IllegalStateException("Run Clan portal already pending");
        }
        clearPendingAskCallbacks();
        pendingPortal = new Protocol.PortalDestination(
                portal.destination().mapId(), portal.destination().x(),
                portal.destination().y(), true);
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = portal;
        pendingClassicWorldPortal = portal.originPhase() == Phase.WORLD
                ? new PendingClassicWorldPortal(
                        pendingPortal, portal.destination().heading(), 0,
                        "Run-Clan-118", portal.targetInstanceId())
                : null;
        sendEncrypted(Protocol.requestSummon(playerObjectId()),
                "S_REQUEST_SUMMON Run Clan player=" + playerName()
                        + " object=" + playerObjectId());
    }

    private boolean runClanPortalStillValid(PendingRunClanPortal portal,
                                             long nowNanos) {
        return portal != null && portal == pendingRunClanPortal
                && runClanPortalContextValid(portal, nowNanos);
    }

    private boolean runClanPortalContextValid(PendingRunClanPortal portal,
                                               long nowNanos) {
        ClientSession target = portal == null ? null : portal.target();
        if (portal == null || target == null
                || nowNanos - portal.expiresAtNanos() >= 0
                || observer || target.observer || playerHp <= 0 || target.playerHp <= 0
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(target)
                || target.positionX != portal.targetX()
                || target.positionY != portal.targetY()
                || !sameNonemptyClan(target)
                || (target != this && target.pendingPortal != null)) {
            return false;
        }
        if (portal.originPhase() == Phase.WORLD) {
            if (portal.roomId() != 0 || phase != Phase.WORLD
                    || target.phase != Phase.WORLD
                    || classicWorldMapId != portal.sourceMapId()
                    || classicWorldInstanceId != portal.sourceInstanceId()
                    || target.classicWorldMapId != portal.targetMapId()
                    || target.classicWorldInstanceId != portal.targetInstanceId()
                    || !ClassicWorldMapCatalog.supports(portal.sourceMapId())
                    || !ClassicWorldMapCatalog.forMap(portal.sourceMapId()).allowsEscape()
                    || !runClanClassicWorldDestinationAllowed(target)) {
                return false;
            }
        } else if (portal.originPhase() == Phase.BATTLE) {
            if (portal.roomId() != currentRoomId
                    || target.currentRoomId != currentRoomId
                    || phase != Phase.BATTLE || target.phase != Phase.BATTLE
                    || currentRoomId == 0 || !hub.battleStarted(currentRoomId)
                    || !hub.roomCombatants(currentRoomId).contains(this)
                    || !hub.roomCombatants(currentRoomId).contains(target)
                    || hub.battleMapId(currentRoomId, this) != portal.sourceMapId()
                    || hub.battleMapId(currentRoomId, target) != portal.targetMapId()
                    || portal.sourceMapId() != portal.targetMapId()) {
                return false;
            }
        } else {
            return false;
        }
        BattleRunClan.Destination current = BattleRunClan.exactDestination(
                portal.targetMapId(), target.positionX, target.positionY);
        return portal.destination().equals(current);
    }

    private static boolean runClanClassicWorldDestinationAllowed(
            ClientSession target) {
        if (target == null || target.phase != Phase.WORLD
                || target.classicWorldInstanceId != -1
                || (target.classicWorldMapId != 0
                    && target.classicWorldMapId != 4
                    && target.classicWorldMapId != 304)) return false;
        if (target.classicWorldMapId != 4) return true;
        int castleId = callClanClassicWorldCastleId(
                target.positionX, target.positionY);
        return castleId == 0 || target.hub.classicCastleWarActive(
                target.selectedClassicServerName, castleId);
    }

