    /** Server-side Water Dragon encounter producer; the client receives S_EFFECT only. */
    boolean applyWaterDragonAffliction(
            BattleWaterDragonAffliction.Kind kind, long nowNanos)
            throws IOException {
        boolean applied;
        synchronized (this) {
            if (kind == null || nowNanos < 0 || observer || playerHp <= 0
                    || phase != Phase.BATTLE && phase != Phase.WORLD) {
                return false;
            }
            applied = timedStatus.activateWaterDragonAffliction(
                    kind, nowNanos,
                    BattleWaterDragonAffliction.DURATION_SECONDS);
        }
        if (!applied) return false;

        byte[] effect = Protocol.effectObject(playerObjectId(), kind.effectGfx());
        if (phase == Phase.WORLD) {
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, positionX, positionY)) {
                    continue;
                }
                member.sendEncrypted(effect,
                        "S_EFFECT Water-Dragon-affliction target=" + playerObjectId()
                                + " skill=" + kind.skillId()
                                + " gfx=" + kind.effectGfx());
            }
        } else {
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendEncrypted(effect,
                        "S_EFFECT Water-Dragon-affliction target=" + playerObjectId()
                                + " skill=" + kind.skillId()
                                + " gfx=" + kind.effectGfx());
            }
        }
        System.out.println("[LiTo] Water Dragon affliction player=" + playerName()
                + " skill=" + kind.skillId() + " alias=" + kind.aliasSkillId()
                + " gfx=" + kind.effectGfx() + " duration="
                + BattleWaterDragonAffliction.DURATION_SECONDS + "s");
        return true;
    }

