    /**
     * Selected LiTo cases above 175 omit the target tail even for retained
     * target-centred magic.  Recover only a previously admitted explicit
     * combat target, or one unambiguous in-range hostile actor, and then feed
     * the authoritative coordinates into the ordinary area pipeline.
     */
    private void useSelectorOnlyTargetedAreaAttackSpell(
            byte[] payload, BattleSpellCatalog.AreaAttackSpell spell)
            throws IOException {
        Protocol.SpellSelector selector =
                Protocol.selectorOnlySpellRequest(payload);
        if (selector.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY
                || spell.maximumRange() <= 0) return;
        Protocol.AttackSpellRequest request =
                resolveSelectorOnlyAreaPrimary(spell);
        if (request == null) return;
        if (phase == Phase.WORLD) {
            useClassicWorldAreaAttackSpell(request, spell);
        } else if (phase == Phase.BATTLE) {
            useAreaAttackSpell(request, spell);
        }
    }

    private Protocol.AttackSpellRequest resolveSelectorOnlyAreaPrimary(
            BattleSpellCatalog.AreaAttackSpell spell) {
        return resolveSelectorOnlyPrimary(
                spell.skillId(), spell.row(), spell.column(),
                spell.maximumRange(), "area");
    }

