    /** Exact selected LiTo skill192/202/203/207/208 requests are selector-only ccc. */
    private void useSelectorOnlyTargetedAttackSpell(
            byte[] payload, BattleSpellCatalog.AttackSpell spell)
            throws IOException {
        Protocol.SpellSelector selector =
                Protocol.selectorOnlySpellRequest(payload);
        BattleSpellCatalog.ThunderGrabSpell thunderGrab =
                BattleSpellCatalog.thunderGrabSpell(spell.skillId());
        BattleSpellCatalog.ConfusionSpell confusion =
                BattleSpellCatalog.confusionSpell(spell.skillId());
        BattleSpellCatalog.MindBreakSpell mindBreak =
                BattleSpellCatalog.mindBreakSpell(spell.skillId());
        BattleSpellCatalog.BoneBreakSpell boneBreak =
                BattleSpellCatalog.boneBreakSpell(spell.skillId());
        BattleSpellCatalog.ArmBreakerSpell armBreaker =
                BattleSpellCatalog.armBreakerSpell(spell.skillId());
        BattleSpellCatalog.SmashSpell smash =
                BattleSpellCatalog.smashSpell(spell.skillId());
        if (thunderGrab == null && confusion == null && smash == null
                && mindBreak == null && boneBreak == null && armBreaker == null
                || selector.skillId() != spell.skillId()) return;
        Protocol.AttackSpellRequest request = resolveSelectorOnlyPrimary(
                spell.skillId(), spell.row(), spell.column(),
                spell.maximumRange(), "attack");
        if (request == null) return;
        if (phase == Phase.WORLD) {
            useClassicWorldAttackSpell(request, spell);
        } else if (phase == Phase.BATTLE) {
            int configuredRoll = config.thunderGrabFixtureD100();
            useAttackSpell(request, spell, -1,
                    configuredRoll > 0 ? configuredRoll : -1,
                    config.thunderGrabFixtureDurationOffset(),
                    config.boneBreakFixtureD1000());
        }
    }

    private Protocol.AttackSpellRequest resolveSelectorOnlyPrimary(
            int skillId, int row, int column, int maximumRange,
            String spellKind) {
        Protocol.AttackSpellRequest explicit = DragonSkillRequests.current();
        if (explicit != null) return explicit;
        if (skillId != (row << 3) + column + 1 || maximumRange <= 0
                || spellKind == null || spellKind.isBlank()) {
            throw new IllegalArgumentException(
                    "invalid selector-only target metadata");
        }
        Map<Long, SelectorOnlyAreaCandidate> eligible = new LinkedHashMap<>();
        int sourceX = positionX;
        int sourceY = positionY;
        if (phase == Phase.WORLD) {
            int mapId = classicWorldMapId;
            int instanceId = classicWorldInstanceId;
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(mapId);
            List<ClientSession> members = classicWorldMembers(mapId);
            for (ClientSession candidate : members) {
                if (candidate == this || candidate.phase != Phase.WORLD
                        || candidate.observer || candidate.playerHp <= 0
                        || candidate.invisible
                        || candidate.classicWorldMapId != mapId
                        || candidate.classicWorldInstanceId != instanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                sourceX, sourceY,
                                candidate.positionX, candidate.positionY)
                        || !map.attackPosition(
                                sourceX, sourceY,
                                candidate.positionX, candidate.positionY,
                                maximumRange)) continue;
                eligible.put(candidate.playerObjectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.playerObjectId(), candidate.positionX,
                                candidate.positionY, "player"));
            }
            for (ClientSession owner : members) {
                if (owner == this || owner.phase != Phase.WORLD
                        || owner.classicWorldMapId != mapId
                        || owner.classicWorldInstanceId != instanceId) continue;
                for (BattleCompanion.Snapshot candidate
                        : owner.classicWorldCompanionSnapshots()) {
                    if (!candidate.kind().classicWorldEligible()
                            || !candidate.active() || candidate.hp() <= 0
                            || !BattleSpellCatalog.isInNativeScreen(
                                    sourceX, sourceY,
                                    candidate.x(), candidate.y())
                            || !map.attackPosition(
                                    sourceX, sourceY,
                                    candidate.x(), candidate.y(),
                                    maximumRange)) continue;
                    eligible.put(candidate.objectId(),
                            new SelectorOnlyAreaCandidate(
                                    candidate.objectId(), candidate.x(),
                                    candidate.y(), "companion"));
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : hub.classicWorldMonstersInScreen(
                            mapId, instanceId, sourceX, sourceY)) {
                if (!candidate.present() || !candidate.alive()
                        || candidate.mapId() != mapId
                        || !map.attackPosition(
                                sourceX, sourceY, candidate.x(), candidate.y(),
                                maximumRange)) continue;
                eligible.put(candidate.objectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.objectId(), candidate.x(),
                                candidate.y(), "monster"));
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : classicCastleTrebuchetsInScreen(
                            selectedClassicServerName, mapId,
                            sourceX, sourceY)) {
                if (!candidate.present() || !candidate.alive()
                        || candidate.mapId() != mapId
                        || !map.attackPosition(
                                sourceX, sourceY, candidate.x(), candidate.y(),
                                maximumRange)) continue;
                eligible.put(candidate.objectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.objectId(), candidate.x(),
                                candidate.y(), "castle-trebuchet"));
            }
        } else if (phase == Phase.BATTLE) {
            for (ClientSession candidate : hub.roomCombatants(currentRoomId)) {
                if (candidate == this || candidate.phase != Phase.BATTLE
                        || candidate.observer || candidate.playerHp <= 0
                        || candidate.invisible
                        || !hub.canAttack(currentRoomId, this, candidate)
                        || targetRange(sourceX, sourceY,
                                candidate.positionX, candidate.positionY)
                            > maximumRange) continue;
                eligible.put(candidate.playerObjectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.playerObjectId(), candidate.positionX,
                                candidate.positionY, "player"));
            }
            for (BattleGuardianTower.Snapshot candidate
                    : hub.visibleGuardianTowers(currentRoomId, this)) {
                if (!hub.canAttackGuardianTower(
                            currentRoomId, this, candidate.objectId())
                        || targetRange(sourceX, sourceY,
                                candidate.x(), candidate.y())
                            > maximumRange) continue;
                eligible.put(candidate.objectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.objectId(), candidate.x(),
                                candidate.y(), "tower"));
            }
            for (BattleQuestEncounter.Snapshot candidate
                    : hub.visibleQuestMonsters(currentRoomId, this)) {
                if (!candidate.alive()
                        || !hub.canAttackQuestMonster(
                                currentRoomId, this, candidate.objectId())
                        || targetRange(sourceX, sourceY,
                                candidate.x(), candidate.y())
                            > maximumRange) continue;
                eligible.put(candidate.objectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.objectId(), candidate.x(),
                                candidate.y(), "quest-monster"));
            }
            for (BattleTimeAttackEncounter.Snapshot candidate
                    : hub.visibleTimeAttackActors(currentRoomId, this)) {
                if (!candidate.alive()
                        || !hub.canAttackTimeAttackActor(
                                currentRoomId, this, candidate.objectId())
                        || targetRange(sourceX, sourceY,
                                candidate.x(), candidate.y())
                            > maximumRange) continue;
                eligible.put(candidate.objectId(),
                        new SelectorOnlyAreaCandidate(
                                candidate.objectId(), candidate.x(),
                                candidate.y(), "time-attack"));
            }
            BattleRules.Mode mode = hub.roomRules(currentRoomId).mode();
            ArenaMapCatalog.Point bot = hub.botPosition(currentRoomId);
            if (mode != BattleRules.Mode.QUEST_BATTLE
                    && mode != BattleRules.Mode.TIME_ATTACK
                    && bot != null && hub.botHp(currentRoomId) > 0
                    && targetRange(sourceX, sourceY, bot.x(), bot.y())
                        <= maximumRange) {
                eligible.put(2L, new SelectorOnlyAreaCandidate(
                        2L, bot.x(), bot.y(), "arena-bot"));
            }
        }

        SelectorOnlyAreaCandidate resolved =
                eligible.get(lastCombatTargetObjectId);
        String resolution = "last-explicit-target";
        if (resolved == null && eligible.size() == 1) {
            resolved = eligible.values().iterator().next();
            resolution = "unique-range-target";
        }
        if (resolved == null) {
            System.out.println("[LiTo] C_USE_SPELL selector-only " + spellKind
                    + " rejected unresolved skill=" + skillId + " player="
                    + playerName() + " last-explicit="
                    + lastCombatTargetObjectId + " range-candidates="
                    + eligible.size() + " maximum-range="
                    + maximumRange + " phase=" + phase);
            return null;
        }
        System.out.println("[LiTo] C_USE_SPELL selector-only " + spellKind
                + " restored skill=" + skillId + " target="
                + resolved.objectId() + " kind=" + resolved.kind()
                + " resolution=" + resolution + " server="
                + resolved.x() + "," + resolved.y());
        return new Protocol.AttackSpellRequest(
                row, column, resolved.objectId(),
                resolved.x(), resolved.y());
    }

    private static int targetRange(
            int sourceX, int sourceY, int targetX, int targetY) {
        return Math.max(Math.abs(sourceX - targetX),
                Math.abs(sourceY - targetY));
    }

