    private MindBreakTargetMpDebit debitMindBreakPlayerTargetMp(
            ClientSession target, int requested, String source)
            throws IOException {
        int before;
        int after;
        boolean debited;
        synchronized (target) {
            before = target.playerMp;
            debited = target.playerHp > 0 && before > requested;
            if (debited) target.playerMp -= requested;
            after = target.playerMp;
        }
        MindBreakTargetMpDebit result = new MindBreakTargetMpDebit(
                requested, before, after, debited, "player");
        if (debited) {
            target.sendEncrypted(Protocol.manaPoint(after, target.playerMaxMp),
                    "S_MANA_POINT Mind-Break-target=" + after + "/"
                            + target.playerMaxMp + " source=" + source
                            + " requested=" + requested);
        }
        return result;
    }

    private MindBreakTargetMpDebit debitBattleMindBreakTargetMp(int n, ClientSession clientSession, BattleQuestEncounter.Snapshot snapshot, BattleTimeAttackEncounter.Snapshot snapshot2, SourceNpcPhysicalStats sourceNpcPhysicalStats, String string) throws IOException {
        Object object = NativeSourceSpecialNpc.mind(this, n, clientSession, snapshot, snapshot2, sourceNpcPhysicalStats, string);
        if (object != null) {
            return (MindBreakTargetMpDebit)object;
        }
        return this.nativeSourceSpecialOriginalMind(n, clientSession, snapshot, snapshot2, sourceNpcPhysicalStats, string);
    }

    private MindBreakTargetMpDebit debitClassicWorldMindBreakTargetMp(
            int requested, ClientSession playerTarget,
            BattleCompanion controlledCompanion,
            ClassicWorldMonsterPopulation.Snapshot monsterTarget,
            boolean castleTrebuchetTarget, String source) throws IOException {
        if (playerTarget != null) {
            return debitMindBreakPlayerTargetMp(
                    playerTarget, requested, source);
        }
        if (controlledCompanion != null) {
            BattleCompanion.ManaDebit debit =
                    controlledCompanion.debitManaIfStrictlyAbove(requested);
            return new MindBreakTargetMpDebit(
                    requested, debit.before().mp(), debit.after().mp(),
                    debit.debited(), "companion");
        }
        if (monsterTarget != null) {
            ClassicWorldMonsterPopulation.ManaDrain drain =
                    castleTrebuchetTarget
                        ? hub.drainClassicCastleTrebuchetManaIfStrictlyAbove(
                                selectedClassicServerName, classicWorldMapId,
                                monsterTarget.objectId(), requested)
                        : hub.drainClassicWorldMonsterManaIfStrictlyAbove(
                                classicWorldMapId, classicWorldInstanceId,
                                monsterTarget.objectId(), requested);
            String kind = castleTrebuchetTarget
                    ? "classic-castle-trebuchet" : "classic-world-monster";
            return drain == null
                    ? MindBreakTargetMpDebit.unavailable(
                            requested, kind)
                    : new MindBreakTargetMpDebit(
                            requested, drain.before().currentMp(),
                            drain.after().currentMp(),
                            drain.actualDrain() == requested,
                            kind);
        }
        return MindBreakTargetMpDebit.unavailable(requested, "unknown");
    }

