    private void publishClassicWorldFreezePalette(
            long objectId, int x, int y, int palette,
            String actorKind, String reason) throws IOException {
        byte[] packet = Protocol.poison(objectId, palette);
        for (ClientSession recipient : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(recipient)
                    || !BattleSpellCatalog.isInNativeScreen(
                            recipient.positionX, recipient.positionY, x, y)) {
                continue;
            }
            recipient.sendEncrypted(packet,
                    "S_POISON classic-world-" + actorKind + "=" + objectId
                            + " type=" + palette + " reason=" + reason);
        }
    }

    private void placeBattleFreezeEffect(
            long targetObjectId, int x, int y, long nowNanos,
            int durationSeconds, List<ClientSession> recipients,
            String reason) throws IOException {
        BattleFreezeEffects.Placement placement = hub.placeFreezeEffect(
                currentRoomId, targetObjectId, x, y,
                nowNanos, durationSeconds);
        if (placement == null) return;
        if (placement.previous() != null) {
            byte[] remove = Protocol.removeObject(placement.previous().objectId());
            for (ClientSession recipient : recipients) {
                recipient.sendEncrypted(remove,
                        "S_REMOVE_OBJECT refreshed freeze effect="
                                + placement.previous().objectId());
            }
        }
        byte[] packet = Protocol.freezeEffect(placement.placed());
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(packet,
                    "S_PUT_OBJECT freeze effect="
                            + placement.placed().objectId() + " target="
                            + targetObjectId + " npc="
                            + BattleFreezeEffects.NPC_ID + " gfx="
                            + BattleFreezeEffects.GFX + " duration="
                            + durationSeconds + " reason=" + reason);
        }
    }

