    private void publishClassicWorldAttackSpellResources(
            BattleSpellCatalog.AttackSpell spell,
            int remainingHp, int remainingMp, String reason) throws IOException {
        BattleSpellCatalog.ThunderGrabSpell thunderGrab =
                BattleSpellCatalog.thunderGrabSpell(spell.skillId());
        BattleSpellCatalog.ConfusionSpell confusion =
                BattleSpellCatalog.confusionSpell(spell.skillId());
        BattleSpellCatalog.MindBreakSpell mindBreak =
                BattleSpellCatalog.mindBreakSpell(spell.skillId());
        if (spell.finalBurn()
                || thunderGrab != null && thunderGrab.hpCost() > 0
                || confusion != null && confusion.hpCost() > 0
                || mindBreak != null && mindBreak.hpCost() > 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT classic-world attack-spell-" + reason + "="
                            + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("classic-world-attack-spell-hp-cost-" + reason);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world attack-spell-" + reason + "="
                        + remainingMp + "/" + playerMaxMp);
    }

    /**
     * Retained CHILL_TOUCH/VAMPIRIC_TOUCH semantics: the caster receives the
     * final positive magic damage after the target commit is accepted.  The
     * requested damage is intentionally used rather than the target's
     * remaining HP; L1SkillUse passes its calculated _dmg to
     * adjustCurrentHpIfAlive after an accepted terminal hit as well.
     */
    private int applyAcceptedLifeDrain(
            BattleSpellCatalog.AttackSpell spell, int damage, String reason)
            throws IOException {
        if (!spell.drainsLife() || damage <= 0) return 0;
        int before;
        int after;
        synchronized (this) {
            if (playerHp <= 0) return 0;
            before = playerHp;
            playerHp = (int) Math.min((long) playerMaxHp,
                    Math.addExact((long) playerHp, (long) damage));
            after = playerHp;
        }
        if (after == before) return 0;
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(after).h(playerMaxHp).bytes(),
                "S_HIT_POINT life-drain skill=" + spell.skillId()
                        + " reason=" + reason + " restored=" + (after - before)
                        + " hp=" + after + "/" + playerMaxHp);
        broadcastOwnHitRatio("life-drain-" + spell.skillId() + "-" + reason);
        return after - before;
    }

    private void publishClassicWorldSpellMonsterDamage(int n, ClassicWorldMonsterPopulation.Hit hit) throws IOException {
        ClassicWorldMonsterPopulation.Snapshot snapshot = hit.after();
        byte[] byArray = NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), snapshot.currentHp(), snapshot.maximumHp());
        for (ClientSession clientSession : this.classicWorldMembers(this.classicWorldMapId)) {
            if (!this.sameClassicWorldMap(clientSession) || !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y())) continue;
            clientSession.sendEncrypted(byArray, "S_HIT_RATIO classic-world-monster=" + snapshot.objectId() + " hp=" + snapshot.currentHp() + "/" + snapshot.maximumHp() + " source=spell-" + n);
            if (!hit.diedNow()) continue;
            clientSession.sendEncrypted(Protocol.objectAction(snapshot.objectId(), 8), "S_ACTION classic-world-monster=" + snapshot.objectId() + " action=8 source=spell-" + n);
        }
        System.out.println("[LiTo] classic-world spell damaged monster player=" + this.playerName() + " skill=" + n + " object=" + snapshot.objectId() + " npc=" + snapshot.npcId() + " damage=" + hit.appliedDamage() + " hp=" + snapshot.currentHp() + "/" + snapshot.maximumHp() + " died=" + hit.diedNow());
        if (hit.diedNow()) {
            this.handleClassicWorldWaterDragonDeath(snapshot, hit.contributions());
            this.distributeClassicWorldMonsterRewards(snapshot, hit.contributions());
            this.hub.scheduleClassicWorldMonsterLifecycle(this.classicWorldInstanceId, snapshot);
        }
    }

    void serverClassicWorldBowMonsterDamage(ClassicWorldNpcCatalog.StaticNpc staticNpc, ClassicWorldMonsterPopulation.Hit hit) throws IOException {
        if (!ClassicWorldBowCatalog.isBow(staticNpc) || hit == null || this.phase != Phase.WORLD || this.classicWorldMapId != staticNpc.mapId()) {
            return;
        }
        ClassicWorldMonsterPopulation.Snapshot snapshot = hit.after();
        byte[] byArray = NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), snapshot.currentHp(), snapshot.maximumHp());
        for (ClientSession clientSession : this.classicWorldMembers(this.classicWorldMapId)) {
            if (!this.sameClassicWorldMap(clientSession) || !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y())) continue;
            try {
                clientSession.sendEncrypted(byArray, "S_HIT_RATIO classic-world-monster=" + snapshot.objectId() + " hp=" + snapshot.currentHp() + "/" + snapshot.maximumHp() + " source=bow-aperture-" + staticNpc.spawnId());
                if (!hit.diedNow()) continue;
                clientSession.sendEncrypted(Protocol.objectAction(snapshot.objectId(), 8), "S_ACTION classic-world-monster=" + snapshot.objectId() + " action=8 source=bow-aperture-" + staticNpc.spawnId());
            }
            catch (IOException iOException) {}
        }
        System.out.println("[LiTo] classic-world bow damaged monster bow=" + staticNpc.objectId() + " spawn=" + staticNpc.spawnId() + " object=" + snapshot.objectId() + " npc=" + snapshot.npcId() + " damage=" + hit.appliedDamage() + " hp=" + snapshot.currentHp() + "/" + snapshot.maximumHp() + " died=" + hit.diedNow() + " contributor=none");
        if (hit.diedNow()) {
            this.hub.scheduleClassicWorldMonsterLifecycle(this.classicWorldInstanceId, snapshot);
        }
    }

