    private void publishSummonedCompanion(BattleCompanion battleCompanion, List<ClientSession> list, int n, String string) throws IOException {
        BattleCompanion.Snapshot snapshot = battleCompanion.snapshot();
        boolean bl = this.phase == Phase.WORLD;
        for (ClientSession clientSession : list) {
            if (bl && !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y())) continue;
            clientSession.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(), snapshot.x(), snapshot.y(), snapshot.gfx(), 0, 0, snapshot.moveSpeed(), 0, snapshot.level(), 0, this.playerName(), bl && clientSession != this ? 255 : NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()));
            clientSession.sendEncrypted(Protocol.master(snapshot.objectId(), this.playerName()), "S_MASTER " + string + "-companion=" + snapshot.objectId() + " owner=" + this.playerName());
            clientSession.sendEncrypted(Protocol.speed(snapshot.objectId(), Protocol.SpeedMode.fromWire(snapshot.moveSpeed()), 0), "S_SPEED " + string + "-companion=" + snapshot.objectId() + " mode=" + snapshot.moveSpeed());
            clientSession.sendEncrypted(Protocol.effectObject(snapshot.objectId(), n), "S_EFFECT " + string + "-companion=" + snapshot.objectId() + " gfx=" + n);
        }
    }

    private void applySpellLawfulDelta(int delta, String source) throws IOException {
        if (delta == 0) return;
        CharacterSummary character = selectedCharacterSummary();
        int sourceLawful = character == null ? 0 : nativeLawful(character.lawful());
        GameStateStore.LawfulMutation mutation = state.addLawful(
                stateCharacter(), sourceLawful, delta);
        playerLawful = mutation.after();
        if (!mutation.changed()) return;
        byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
        boolean classicWorld = phase == Phase.WORLD;
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (classicWorld && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(packet,
                    "S_CHANGE_ALIGNMENT player=" + playerName()
                            + " object=" + playerObjectId()
                            + " requested-delta=" + mutation.requestedDelta()
                            + " applied-delta=" + mutation.appliedDelta()
                            + " lawful=" + mutation.before() + "->" + mutation.after()
                            + " source=" + source);
        }
    }

