    private void publishClassicWorldTaming(
            ClassicWorldMonsterPopulation.Capture capture,
            BattleCompanion companion, BattleSpellCatalog.TamingSpell spell,
            List<ClientSession> recipients) throws IOException {
        BattleCompanion.Snapshot snapshot = companion.snapshot();
        byte[] removed = Protocol.removeObject(capture.captured().objectId());
        byte[] effect = Protocol.effectObject(snapshot.objectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            member.sendEncrypted(removed,
                    "S_REMOVE_OBJECT classic-world-monster="
                            + capture.captured().objectId() + " reason=tamed");
            member.sendClassicWorldCompanionObject(this, snapshot, "taming");
            member.sendEncrypted(effect,
                    "S_EFFECT taming-success target=" + snapshot.objectId()
                            + " gfx=" + spell.effectGfx() + " phase=WORLD");
        }
    }

    private void publishQuestTaming(BattleQuestEncounter.Capture capture,
                                    BattleCompanion companion,
                                    BattleSpellCatalog.TamingSpell spell)
            throws IOException {
        BattleQuestEncounter.Snapshot captured = capture.captured();
        List<ClientSession> recipients = hub.battleRecipients(
                currentRoomId, captured.force());
        for (ClientSession member : recipients) {
            member.sendEncrypted(Protocol.removeObject(captured.objectId()),
                    "S_REMOVE_OBJECT quest-monster=" + captured.objectId()
                            + " reason=tamed");
        }
        publishTamedCompanion(companion, recipients, spell);
        if (capture.waveCleared()) {
            publishQuestWaveAdvance(captured.force(), capture.clearedRoom(),
                    capture.spawned(), capture.objectiveUnlocked(), "taming");
        }
    }

    private void publishTimeAttackTaming(BattleTimeAttackEncounter.Capture capture,
                                         BattleCompanion companion,
                                         BattleSpellCatalog.TamingSpell spell)
            throws IOException {
        List<ClientSession> recipients = hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            member.sendEncrypted(Protocol.removeObject(capture.captured().objectId()),
                    "S_REMOVE_OBJECT timeattack-actor="
                            + capture.captured().objectId() + " reason=tamed");
        }
        publishTamedCompanion(companion, recipients, spell);
        for (ClientSession member : recipients) {
            for (BattleTimeAttackEncounter.Snapshot spawned : capture.spawned()) {
                member.sendEncrypted(Protocol.timeAttackActor(spawned),
                        "S_PUT_OBJECT timeattack-actor=" + spawned.objectId()
                                + " npc=" + spawned.npcId() + " final-boss="
                                + spawned.finalBoss() + " source=taming");
            }
        }
        if (capture.spawned().stream()
                .anyMatch(BattleTimeAttackEncounter.Snapshot::activeAi)) {
            hub.armPveAi(currentRoomId);
        }
    }

    private static int heading(int sourceX, int sourceY, int targetX, int targetY) {
        int dx = Integer.compare(targetX, sourceX);
        int dy = Integer.compare(targetY, sourceY);
        if (dx > 0 && dy > 0) return 3;
        if (dx < 0 && dy < 0) return 7;
        if (dx > 0 && dy == 0) return 2;
        if (dx < 0 && dy == 0) return 6;
        if (dx == 0 && dy > 0) return 4;
        if (dx < 0) return 5;
        if (dx > 0) return 1;
        return 0;
    }

