    /**
     * Retained L1GuardianInstance harvest happens before attack.action().
     * False means storeItem failed and the source returns without publishing
     * the attack; a no-reward roll remains a successful no-op.
     */
    private boolean harvestClassicWorldGuardian(
            ClassicWorldMonsterPopulation.Snapshot guardian,
            int oneBasedRoll) throws IOException {
        if (!ClassicWorldGuardianCatalog.isGuardian(guardian)) {
            throw new IllegalArgumentException("harvest target is not L1Guardian");
        }
        ClassicWorldGuardianCatalog.Harvest harvest =
                ClassicWorldGuardianCatalog.harvest(
                        guardian.npcId(), oneBasedRoll);
        if (harvest == null) {
            System.out.println("[LiTo] L1Guardian harvest no-drop player="
                    + playerName() + " npc=" + guardian.npcId()
                    + " roll=" + oneBasedRoll);
            return true;
        }
        InventoryCatalog.Definition reward =
                InventoryCatalog.require(harvest.itemId());
        RuntimeInventory next = inventory.copy();
        boolean weightAllowed = permitsInventoryAddition(
                next, reward, harvest.quantity());
        boolean added = weightAllowed && next.add(reward, harvest.quantity());
        if (!added) {
            if (!weightAllowed) sendInventoryWeightOver("L1Guardian-harvest");
            else sendInventoryCapacityOver("L1Guardian-harvest");
            System.out.println("[LiTo] L1Guardian harvest storeItem failed player="
                    + playerName() + " npc=" + guardian.npcId()
                    + " item=" + harvest.itemId() + " count="
                    + harvest.quantity() + " roll=" + oneBasedRoll);
            return false;
        }
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        RuntimeInventory previous = inventory;
        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(
                        ClassicWorldGuardianCatalog.HARVEST_MESSAGE,
                        harvest.giverNameId(), harvest.itemMessageArgument()),
                "S_MESSAGE_CODE L1Guardian-harvest=143 npc="
                        + guardian.npcId() + " item=" + harvest.itemId()
                        + " count=" + harvest.quantity());
        System.out.println("[LiTo] L1Guardian harvest player=" + playerName()
                + " npc=" + guardian.npcId() + " roll=" + oneBasedRoll
                + " item=" + harvest.itemId() + " count="
                + harvest.quantity());
        return true;
    }

    private void resolveClassicWorldScarecrowHit(ClassicWorldNpcCatalog.StaticNpc staticNpc, ClassicWorldMonsterCatalog.MonsterTemplate monsterTemplate, int n) throws IOException {
        int n2;
        int n3;
        if (staticNpc == null || monsterTemplate == null || !ClassicWorldScarecrowCatalog.isScarecrow(staticNpc)) {
            throw new IllegalArgumentException("invalid classic scarecrow hit");
        }
        if (n < this.config.classicWorldScarecrowMaxLevel()) {
            this.applyClassicWorldNpcReward(monsterTemplate, staticNpc.experience(), 0, 1L, 1L);
        }
        n2 = NativeStaticNpcScene.heading(this.hub, staticNpc, this);
        n3 = n2 + 1 & 7;
        if (!NativeStaticNpcScene.turn(this.hub, staticNpc, n3, this)) {
            throw new IOException("canonical scarecrow heading update failed object=" + staticNpc.objectId());
        }
        byte[] byArray = new Protocol.Writer().c(28).d(staticNpc.objectId()).c(n3).bytes();
        for (ClientSession clientSession : this.classicWorldMembers(staticNpc.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this))) continue;
            clientSession.sendEncrypted(byArray, "S_CHANGE_DIRECTION L1Scarecrow=" + staticNpc.objectId() + " npc=" + staticNpc.npcId() + " heading=" + n2 + "->" + n3);
        }
        System.out.println("[LiTo] classic-world L1Scarecrow hit player=" + this.playerName() + " object=" + staticNpc.objectId() + " npc=" + staticNpc.npcId() + " heading=" + n2 + "->" + n3 + " training-level=" + n + "/" + this.config.classicWorldScarecrowMaxLevel() + " exp=" + (n < this.config.classicWorldScarecrowMaxLevel() ? staticNpc.experience() : 0L));
    }

    private void publishClassicCastleTrebuchetHit(
            ClassicWorldCastleWarField.TrebuchetHit hit) throws IOException {
        ClassicWorldCastleWarField.WarObject after = hit.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(after.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO castle-trebuchet=" + after.objectId()
                            + " hp=" + after.currentHp() + "/" + after.maximumHp());
            if (hit.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION castle-trebuchet=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE);
            }
        }
        System.out.println("[LiTo] classic castle trebuchet damaged player="
                + playerName() + " object=" + after.objectId()
                + " npc=" + after.npcId() + " applied=" + hit.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + hit.diedNow());
    }

    private void publishMainlandCastleDoorHit(
            ClassicWorldCastleDoorCombat.Hit hit) throws IOException {
        ClassicWorldCastleDoorCombat.View after = hit.after();
        ClassicWorldCastleDoorCombat.Definition door = after.definition();
        byte[] action = hit.action() == 0 ? null
                : Protocol.objectAction(door.objectId(), hit.action());
        for (ClientSession member : classicWorldMembers(door.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, door.x(), door.y())) continue;
            if (action != null) {
                member.sendEncrypted(action,
                        "S_ACTION " + door.family().name().toLowerCase(Locale.ROOT)
                                + "-castle-door=" + door.doorId()
                                + " action=" + hit.action()
                                + " hp=" + after.currentHp() + "/"
                                + door.maximumHp());
            }
            if (hit.diedNow()) {
                member.sendMainlandCastleDoorAttributes(
                        door, BattleDoor.PASSABLE, "door-death");
            }
        }
        System.out.println("[LiTo] mainland castle door damaged player="
                + playerName() + " family=" + door.family()
                + " door=" + door.doorId() + " object=" + door.objectId()
                + " applied=" + hit.appliedDamage()
                + " hp=" + after.currentHp() + "/" + door.maximumHp()
                + " crack-stage=" + after.crackStage()
                + " action=" + hit.action() + " died=" + hit.diedNow());
    }

