    /** Retained C15 monster executor: last attacker, active crown trial, 40%. */
    private void awardClassicWorldRoyalTrialQuestDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return;
        int fixtureRoll = config.classicWorldQuestDropFixtureRoll();
        int roll = fixtureRoll == 0
                ? ThreadLocalRandom.current().nextInt(100) : fixtureRoll - 1;
        ClassicWorldRoyalTrialCatalog.QuestDropDecision decision =
                ClassicWorldRoyalTrialCatalog.decideQuestDrop(
                        defeated.npcId(), character.type(),
                        state.storyQuests(stateCharacter()).effective(),
                        inventory.catalogCounts(), roll);
        if (decision == null) return;
        if (!decision.awarded()) {
            System.out.println("[LiTo] royal-trial quest drop skipped player="
                    + playerName() + " npc=" + defeated.npcId()
                    + " item=" + decision.itemId() + " crown=" + decision.crown()
                    + " active=" + decision.trialActive() + " owned="
                    + decision.alreadyOwned() + " roll=" + decision.roll());
            return;
        }

        InventoryCatalog.Definition definition = InventoryCatalog.find(decision.itemId());
        if (definition == null) {
            throw new IOException("royal trial quest item definition vanished "
                    + decision.itemId());
        }
        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        RuntimeInventory next = inventory.copy();
        // A synthetic transfer object always has id 1; direct catalog storage
        // must allocate/merge a real unique inventory object instead.
        boolean stored = next.add(definition, 1)
                && permitsInventoryAddition(inventory, definition, 1);
        if (stored) {
            RuntimeInventory previous = inventory;
            state.saveEconomyState(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY,
                    defeated.npcId());
            if (ground == null) {
                throw new IOException("royal trial quest item ground handoff failed");
            }
            broadcastClassicWorldGroundItem(
                    ground, "royal-trial-quest-drop-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, defeated.nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE royal-trial-quest-drop=143 npc="
                        + defeated.npcId() + " item=" + decision.itemId()
                        + " stored=" + stored + " roll=" + decision.roll());
        System.out.println("[LiTo] royal-trial quest item awarded player="
                + playerName() + " npc=" + defeated.npcId()
                + " item=" + decision.itemId() + " stored=" + stored
                + " roll=" + decision.roll());
    }

    /** Retained CKEW50_* death executors: last attacker, show-local and item guarded. */
    private void awardClassicWorldCkewQuestDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        if (defeated.mapId() != ClassicWorldCkewCatalog.MAP_ID
                || classicWorldInstanceId < 0) return;
        int fixtureRoll = config.classicWorldQuestDropFixtureRoll();
        int roll = fixtureRoll == 0
                ? ThreadLocalRandom.current().nextInt(100) : fixtureRoll - 1;
        Map<Long, Integer> counts = inventory.catalogCounts();
        long itemId = ClassicWorldCkewMonsterDeathExecutor.questItem(
                defeated.npcId(), activeStorySkillEffect(
                        ClassicWorldCkewCatalog.DESTRUCTION_MEDICINE_EFFECT,
                        System.nanoTime()),
                counts.containsKey(49165L), counts.containsKey(49166L),
                counts.containsKey(49168L), roll);
        if (itemId == 0) return;

        InventoryCatalog.Definition definition = InventoryCatalog.find(itemId);
        if (definition == null) {
            throw new IOException("CKEW quest item definition vanished " + itemId);
        }
        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        RuntimeInventory next = inventory.copy();
        boolean stored = next.add(definition, 1)
                && permitsInventoryAddition(inventory, definition, 1);
        if (stored) {
            RuntimeInventory previous = inventory;
            state.saveEconomyState(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY,
                    defeated.npcId());
            if (ground == null) {
                throw new IOException("CKEW quest item ground handoff failed");
            }
            broadcastClassicWorldGroundItem(ground, "CKEW-quest-drop-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, defeated.nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE CKEW-quest-drop=143 show="
                        + classicWorldInstanceId + " npc=" + defeated.npcId()
                        + " item=" + itemId + " stored=" + stored
                        + " roll=" + roll);
        System.out.println("[LiTo] CKEW quest item awarded player="
                + playerName() + " show=" + classicWorldInstanceId
                + " npc=" + defeated.npcId() + " item=" + itemId
                + " stored=" + stored + " roll=" + roll);
    }

    /** Retained CKEW50_Altar: complete quest122 and award 49241 to the whole show. */
    private void completeClassicWorldCkewAltar(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        if (defeated.mapId() != ClassicWorldCkewCatalog.MAP_ID
                || defeated.npcId() != 87000 || classicWorldInstanceId < 0) return;
        int showId = classicWorldInstanceId;
        for (ClientSession member : hub.classicWorldMembers(
                ClassicWorldCkewCatalog.MAP_ID, showId)) {
            member.serverClassicWorldCkewAltarCompleted(showId, defeated);
        }
    }

    private void serverClassicWorldCkewAltarCompleted(
            int showId, ClassicWorldMonsterPopulation.Snapshot altar)
            throws IOException {
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID
                || classicWorldInstanceId != showId || altar == null) return;
        InventoryCatalog.Definition definition = InventoryCatalog.find(
                ClassicWorldCkewCatalog.ALTAR_PROOF);
        if (definition == null) {
            throw new IOException("CKEW altar proof definition vanished");
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        boolean alreadyOwned = next.catalogCounts().containsKey(
                (long) ClassicWorldCkewCatalog.ALTAR_PROOF);
        boolean stored = alreadyOwned || (permitsInventoryAddition(
                inventory, definition, 1) && next.add(definition, 1));
        Map<Integer, Integer> quests = new LinkedHashMap<>(
                state.storyQuests(stateCharacter()).effective());
        quests.put(ClassicWorldCkewCatalog.QUEST_ID,
                ClassicWorldCkewCatalog.QUEST_COMPLETED);
        state.saveEconomyStateAndStoryQuests(
                stateCharacter(), shopPoints, next.catalogCounts(),
                next.catalogItemStates(), quests);
        NativeDeItemApplication.replace(this, next, 0);
        if (alreadyOwned) return;

        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        if (stored) {
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    altar.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY, altar.npcId());
            if (ground == null) {
                throw new IOException("CKEW altar proof ground handoff failed");
            }
            broadcastClassicWorldGroundItem(ground, "CKEW-altar-proof-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, altar.template().nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE CKEW-altar-proof=143 show=" + showId
                        + " item=" + ClassicWorldCkewCatalog.ALTAR_PROOF
                        + " stored=" + stored);
        System.out.println("[LiTo] CKEW altar completed player=" + playerName()
                + " show=" + showId + " quest-step="
                + ClassicWorldCkewCatalog.QUEST_COMPLETED
                + " proof-stored=" + stored);
    }

    /** A liberated pet keeps its former bag until the replacement monster dies. */
    private void distributeReleasedPetItems(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible,
            List<RuntimeInventory.Item> releasedItems) throws IOException {
        int autoLoot = config.classicWorldDropAutoLoot();
        for (RuntimeInventory.Item item : releasedItems) {
            ClientSession recipient = autoLoot == 0 ? null
                    : selectClassicWorldDropRecipient(
                            defeated, contributions, eligible, autoLoot);
            boolean granted = recipient != null
                    && recipient.receiveReleasedPetItem(defeated, item);
            if (granted) continue;
            int x;
            int y;
            if (recipient == null) {
                int[] location = classicWorldAdjacentDropLocation(defeated);
                x = location[0];
                y = location[1];
            } else {
                x = recipient.positionX;
                y = recipient.positionY;
            }
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    item, item.quantity(), x, y, defeated.npcId());
            if (ground == null) {
                throw new IllegalStateException(
                        "released pet item ground handoff was rejected");
            }
            broadcastClassicWorldGroundItem(ground,
                    recipient == null ? "released-pet-drop" : "released-pet-overflow");
            System.out.println("[LiTo] released pet item dropped wild="
                    + defeated.objectId() + " catalog="
                    + item.definition().catalogId() + " object=" + ground.objectId()
                    + " quantity=" + ground.quantity() + " x=" + x + " y=" + y);
        }
    }

    private boolean receiveReleasedPetItem(ClassicWorldMonsterPopulation.Snapshot snapshot, RuntimeInventory.Item item) throws IOException {
        RuntimeInventory runtimeInventory = this.inventory.copy();
        if (!runtimeInventory.add(item, (long)item.quantity()) || !this.permitsInventoryAddition(this.inventory, item.definition(), item.quantity())) {
            return false;
        }
        RuntimeInventory runtimeInventory2 = this.inventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 0);
        this.sendInventoryDelta(runtimeInventory2, this.inventory);
        this.sendEncrypted(Protocol.messageCode(143, snapshot.nameId(), item.nativeViewName()), "S_MESSAGE_CODE released-pet-autoloot=143 wild=" + snapshot.objectId() + " catalog=" + item.definition().catalogId() + " quantity=" + item.quantity());
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, this.inventory.catalogCounts(), this.inventory.catalogItemStates());
        return true;
    }

    private ClientSession selectClassicWorldDropRecipient(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible, int autoLoot) {
        List<ClassicWorldMonsterPopulation.Contribution> candidates = new ArrayList<>();
        long totalHate = 0;
        for (ClassicWorldMonsterPopulation.Contribution contribution : contributions) {
            ClientSession recipient = eligible.get(contribution.playerObjectId());
            if (recipient == null || contribution.hate() <= 0) continue;
            if (autoLoot == 1 && Math.max(
                    Math.abs(recipient.positionX - defeated.x()),
                    Math.abs(recipient.positionY - defeated.y()))
                    > config.classicWorldDropLootingRange()) continue;
            candidates.add(contribution);
            totalHate = Math.addExact(totalHate, contribution.hate());
        }
        if (totalHate <= 0) return null;
        long selected = ThreadLocalRandom.current().nextLong(totalHate);
        for (ClassicWorldMonsterPopulation.Contribution contribution : candidates) {
            if (selected < contribution.hate()) {
                return eligible.get(contribution.playerObjectId());
            }
            selected -= contribution.hate();
        }
        return eligible.get(candidates.get(candidates.size() - 1).playerObjectId());
    }

    private boolean receiveClassicWorldMonsterDrop(ClassicWorldMonsterPopulation.Snapshot snapshot, ClassicWorldDropCatalog.RolledItem rolledItem) throws IOException {
        ClassicWorldDropCatalog.ItemWire itemWire = rolledItem.item();
        InventoryCatalog.Definition definition = itemWire.inventoryDefinition();
        RuntimeInventory.Item item = new RuntimeInventory.Item(1L, definition, rolledItem.quantity(), false, 0, 0, false, itemWire.blessing());
        RuntimeInventory runtimeInventory = this.inventory.copy();
        if (!runtimeInventory.add(item, (long)rolledItem.quantity()) || !this.permitsInventoryAddition(this.inventory, definition, rolledItem.quantity())) {
            System.out.println("[LiTo] classic-world autoloot overflow player=" + this.playerName() + " npc=" + snapshot.npcId() + " catalog=" + itemWire.itemId() + " quantity=" + rolledItem.quantity());
            return false;
        }
        RuntimeInventory runtimeInventory2 = this.inventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 0);
        this.sendInventoryDelta(runtimeInventory2, this.inventory);
        this.sendEncrypted(Protocol.messageCode(143, snapshot.nameId(), ClientSession.classicWorldDropLogName(definition, rolledItem.quantity())), "S_MESSAGE_CODE classic-world-autoloot=143 npc=" + snapshot.npcId() + " catalog=" + itemWire.itemId() + " quantity=" + rolledItem.quantity());
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, this.inventory.catalogCounts(), this.inventory.catalogItemStates());
        System.out.println("[LiTo] classic-world autoloot player=" + this.playerName() + " npc=" + snapshot.npcId() + " catalog=" + itemWire.itemId() + " quantity=" + rolledItem.quantity() + " chance-roll=" + rolledItem.chanceRoll());
        return true;
    }

    private static String classicWorldDropLogName(
            InventoryCatalog.Definition definition, int quantity) {
        if (definition.stackable()) return definition.name() + " (" + quantity + ")";
        return definition.name();
    }

    private void putClassicWorldMonsterDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            ClassicWorldDropCatalog.RolledItem drop,
            int x, int y, String reason) throws IOException {
        int objects = drop.item().stackable() ? 1 : drop.quantity();
        int quantity = drop.item().stackable() ? drop.quantity() : 1;
        for (int index = 0; index < objects; index++) {
            ClassicWorldGroundItems.Item item = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    drop.item(), quantity, x, y, defeated.npcId());
            if (item == null) {
                throw new IllegalStateException("validated classic WORLD drop was rejected");
            }
            broadcastClassicWorldGroundItem(item, reason);
            System.out.println("[LiTo] classic-world ground drop npc=" + defeated.npcId()
                    + " catalog=" + drop.item().itemId() + " object=" + item.objectId()
                    + " quantity=" + item.quantity() + " x=" + x + " y=" + y
                    + " chance-roll=" + drop.chanceRoll() + " reason=" + reason);
        }
    }

    private int[] classicWorldAdjacentDropLocation(
            ClassicWorldMonsterPopulation.Snapshot defeated) {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(defeated.mapId());
        int start = ThreadLocalRandom.current().nextInt(CLASSIC_GROUND_DX.length);
        for (int offset = 0; offset < CLASSIC_GROUND_DX.length; offset++) {
            int direction = (start + offset) & 7;
            int x = defeated.x() + CLASSIC_GROUND_DX[direction];
            int y = defeated.y() + CLASSIC_GROUND_DY[direction];
            if (map.canStep(defeated.x(), defeated.y(), x, y)) {
                return new int[]{x, y};
            }
        }
        return new int[]{defeated.x(), defeated.y()};
    }

    private void applyClassicWorldNpcReward(
            ClassicWorldMonsterCatalog.MonsterTemplate npc,
            long baseExperience, int sourceLawfulShare,
            long hate, long totalHate) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || phase != Phase.WORLD || playerHp <= 0) return;

        int requestedLawfulDelta = -((int) (
                sourceLawfulShare * config.classicWorldLawfulRate()));
        GameStateStore.LawfulMutation lawful = state.addLawful(
                stateCharacter(), nativeLawful(character.lawful()), requestedLawfulDelta);
        playerLawful = lawful.after();
        if (lawful.changed()) {
            byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
            for (ClientSession viewer : classicWorldMembers(classicWorldMapId)) {
                if (viewer != this && !BattleSpellCatalog.isInNativeScreen(
                        viewer.positionX, viewer.positionY, positionX, positionY)) continue;
                viewer.sendEncrypted(packet,
                        "S_CHANGE_ALIGNMENT classic-world player=" + playerName()
                                + " object=" + playerObjectId() + " npc=" + npc.npcId()
                                + " source-share=" + sourceLawfulShare
                                + " requested-delta=" + lawful.requestedDelta()
                                + " applied-delta=" + lawful.appliedDelta()
                                + " lawful=" + lawful.before() + "->" + lawful.after());
            }
        }

        int sourceLevel = Math.max(1,
                Math.min(ClassicExperienceCatalog.MAXIMUM_LEVEL, character.level()));
        int fixedExperienceBonus = experienceGemStatus.snapshot(
                System.nanoTime()).bonusExperience();
        NativeMagicDollPowers dollPowers = activeMagicDollPowers();
        double dollExperienceMultiplier =
                dollPowers.percentMultiplier("PASSIVE_EXP_RATE");
        double effectiveExperienceRate = config.classicWorldExperienceRate()
                * dollExperienceMultiplier;
        GameStateStore.ClassicExperienceMutation experience =
                 state.addClassicExperience(
                        stateCharacter(), character.experience(), sourceLevel, baseExperience,
                        effectiveExperienceRate,
                        fixedExperienceBonus);
        playerClassicExperience = experience.afterExperience();
        playerClassicLevel = experience.afterLevel();
        if (experience.changed()) {
            if (experience.levelChanged()) {
                sendNativeBattleStatus(System.nanoTime(), "classic-world-level-up");
            } else {
                sendEncrypted(Protocol.experience(
                                playerClassicLevel, playerClassicExperience),
                        "S_EXP classic-world player=" + playerName()
                                + " npc=" + npc.npcId()
                                + " level=" + playerClassicLevel
                                + " experience=" + experience.beforeExperience()
                                + "->" + experience.afterExperience()
                                + " base=" + baseExperience
                                + " adjusted=" + experience.adjustedExperience());
            }
        }
        System.out.println("[LiTo] classic-world NPC reward player=" + playerName()
                + " npc=" + npc.npcId() + " hate=" + hate + "/" + totalHate
                + " exp-base=" + baseExperience
                + " exp-server-rate=" + config.classicWorldExperienceRate()
                + " exp-doll-percent=" + dollPowers.value("PASSIVE_EXP_RATE")
                + " exp-rate=" + effectiveExperienceRate
                + " dragon-gem-fixed=" + fixedExperienceBonus
                + " exp-adjusted=" + experience.adjustedExperience()
                + " exp=" + experience.beforeExperience() + "->"
                + experience.afterExperience() + " level="
                + experience.beforeLevel() + "->" + experience.afterLevel()
                + " lawful-source-share=" + sourceLawfulShare
                + " lawful-rate=" + config.classicWorldLawfulRate()
                + " lawful=" + lawful.before() + "->" + lawful.after());
    }

    private synchronized BattleCounterBarrier.Decision counterBarrierDecision(
            int attackerLevel, int attackerMagicResistance,
            boolean attackerBoss, int oneBasedRoll, long nowNanos) {
        BattleSpellCatalog.CounterBarrierSpell spell =
                BattleSpellCatalog.counterBarrierSpell(
                        BattleSpellCatalog.COUNTER_BARRIER);
        boolean active = abilityStatus.counterBarrier(nowNanos)
                .remainingSeconds() != 0;
        SourceWeaponPhysicalStats weapon = activePhysicalWeapon();
        if (active && !spell.supportsWeapon(weapon)) {
            abilityStatus.removeCounterBarrier();
            active = false;
            System.out.println("[LiTo] Counter Barrier removed player=" + playerName()
                    + " reason=trigger-without-two-hand-sword");
        }
        int holderMagicHit = Math.addExact(
                requiredEquipmentMagicStats().totalMagicHit(),
                dragonEyeStatus.snapshot(nowNanos).magicHit());
        return BattleCounterBarrier.decide(
                spell, active, weapon, battleLevel(), attackerLevel,
                holderMagicHit, attackerMagicResistance, attackerBoss,
                oneBasedRoll);
    }

    private int counterBarrierRoll() {
        int fixture = config.counterBarrierFixtureD100();
        return fixture > 0 ? fixture
                : ThreadLocalRandom.current().nextInt(1, 101);
    }

    private int mortalBodyRoll() {
        int fixture = config.mortalBodyFixtureD100();
        return fixture > 0 ? fixture
                : ThreadLocalRandom.current().nextInt(1, 101);
    }

