    private void applyBounceAttackWeaponDamage(
            ClientSession attacker, SourceWeaponPhysicalStats activeWeapon,
            SourceWeaponPhysicalStats sourceWeaponSnapshot,
            boolean sourceWeaponActive, long runtimeWeaponObjectId) throws IOException {
        if (attacker.timedStatus.soulOfFlameActive(System.nanoTime())) {
            System.out.println("[LiTo] Bounce Attack weapon-damage suppressed"
                    + " attacker=" + attacker.playerName()
                    + " reason=Soul-of-Flame");
            return;
        }
        BattleAbilityStatus.BounceAttack status =
                abilityStatus.bounceAttack(System.nanoTime());
        if (status.remainingSeconds() == 0 || activeWeapon == null
                || !activeWeapon.present() || activeWeapon.ranged()) {
            return;
        }
        int roll = ThreadLocalRandom.current().nextInt(1, 101);
        BattleBounceAttack.Decision decision = BattleBounceAttack.decide(
                status, activeWeapon, roll);
        System.out.println("[LiTo] Bounce Attack weapon-damage roll target="
                + playerName() + " attacker=" + attacker.playerName()
                + " weapon-item=" + activeWeapon.itemId()
                + " chance=" + decision.chance() + " roll=" + decision.roll()
                + " triggered=" + decision.damagesWeapon());
        if (decision.damagesWeapon()) {
            attacker.damageAttackingWeapon(
                    activeWeapon, sourceWeaponSnapshot,
                    sourceWeaponActive, runtimeWeaponObjectId);
        }
    }

    private void damageAttackingWeapon(
            SourceWeaponPhysicalStats activeWeapon,
            SourceWeaponPhysicalStats sourceWeaponSnapshot,
            boolean sourceWeaponActive, long runtimeWeaponObjectId) throws IOException {
        if (sourceWeaponActive) {
            GameStateStore.SourceWeaponDurabilityBalance result;
            synchronized (this) {
                SourceWeaponPhysicalStats current =
                        requiredEquipmentMagicStats().physical().weapon();
                if (playerHp <= 0 || sourceWeaponSuppressed
                        || inventory.hasEquippedWeapon() || !current.present()
                        || current.itemId() != sourceWeaponSnapshot.itemId()
                        || current.durability() != sourceWeaponSnapshot.durability()) {
                    return;
                }
                result = state.damageSourceWeapon(
                        stateCharacter(), sourceWeaponSnapshot);
            }
            sendEncrypted(Protocol.messageCode(
                            268, activeWeaponLogName(activeWeapon)),
                    "S_MESSAGE_CODE bounce-attack-weapon-damaged=268 source-item="
                            + result.itemId() + " durability="
                            + result.effectiveDurability());
            System.out.println("[LiTo] Bounce Attack damaged source weapon player="
                    + playerName() + " item=" + result.itemId()
                    + " observed=" + result.observedDurability()
                    + " effective=" + result.effectiveDurability());
            return;
        }

        RuntimeInventory previous;
        RuntimeInventory.Item damaged;
        synchronized (this) {
            RuntimeInventory.Item equipped = inventory.equippedWeaponItem();
            if (playerHp <= 0 || equipped == null
                    || equipped.objectId() != runtimeWeaponObjectId
                    || equipped.definition().catalogId() != activeWeapon.itemId()
                    || equipped.durability() >= 0x7F) {
                return;
            }
            RuntimeInventory next = inventory.copy();
            if (!next.damageWeapon(
                    equipped.objectId(), equipped.durability() + 1)) return;
            previous = inventory;
            NativeDeItemApplication.replace(this, next, 0);
            try {
                state.saveEconomyState(stateCharacter(), shopPoints,
                        inventory.catalogCounts(), inventory.catalogItemStates());
            } catch (IOException failure) {
                NativeDeItemApplication.replace(this, previous, 0);
                throw failure;
            }
            damaged = inventory.item(equipped.objectId());
        }
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(268, damaged.definition().name()),
                "S_MESSAGE_CODE bounce-attack-weapon-damaged=268 object="
                        + damaged.objectId() + " durability=" + damaged.durability());
        sendEncrypted(Protocol.changeInventoryDescriptionExtended(
                        damaged.objectId(), damaged.nativeViewName(), damaged.quantity(),
                        damaged.nativeStatusDetail()),
                "S_CHANGE_ITEM_DESC_EX bounce-attack-weapon-damaged object="
                        + damaged.objectId() + " durability=" + damaged.durability());
        System.out.println("[LiTo] Bounce Attack damaged runtime weapon player="
                + playerName() + " object=" + damaged.objectId()
                + " catalog=" + damaged.definition().catalogId()
                + " durability=" + damaged.durability());
    }

    private void applyWeaponBreakWeaponDamage(int points) throws IOException {
        if (points <= 0 || points > 0x7F) {
            throw new IllegalArgumentException("invalid Weapon Break damage points");
        }

        RuntimeInventory.Item runtimeWeapon = inventory.equippedWeaponItem();
        if (runtimeWeapon != null) {
            RuntimeInventory previous;
            RuntimeInventory.Item damaged;
            synchronized (this) {
                RuntimeInventory.Item current = inventory.equippedWeaponItem();
                if (playerHp <= 0 || current == null
                        || current.objectId() != runtimeWeapon.objectId()) return;
                int nextDurability = BattleWeaponBreak.durabilityAfterDamage(
                        current.durability(), current.enchantLevel(), points);
                previous = inventory;
                if (nextDurability != current.durability()) {
                    RuntimeInventory next = inventory.copy();
                    if (!next.damageWeapon(
                            current.objectId(), nextDurability)) return;
                    NativeDeItemApplication.replace(this, next, 0);
                    try {
                        state.saveEconomyState(stateCharacter(), shopPoints,
                                inventory.catalogCounts(),
                                inventory.catalogItemStates());
                    } catch (IOException failure) {
                        NativeDeItemApplication.replace(this, previous, 0);
                        throw failure;
                    }
                }
                damaged = inventory.item(current.objectId());
            }
            sendInventoryDelta(previous, inventory);
            sendEncrypted(Protocol.messageCode(268, damaged.definition().name()),
                    "S_MESSAGE_CODE weapon-break-weapon-damaged=268 object="
                            + damaged.objectId() + " durability="
                            + damaged.durability());
            sendEncrypted(Protocol.changeInventoryDescriptionExtended(
                            damaged.objectId(), damaged.nativeViewName(),
                            damaged.quantity(), damaged.nativeStatusDetail()),
                    "S_CHANGE_ITEM_DESC_EX weapon-break-weapon-damaged object="
                            + damaged.objectId() + " durability="
                            + damaged.durability());
            return;
        }

        SourceWeaponPhysicalStats sourceWeapon =
                requiredEquipmentMagicStats().physical().weapon();
        if (sourceWeaponSuppressed || sourceWeapon == null
                || !sourceWeapon.present()) return;
        GameStateStore.SourceWeaponDurabilityBalance result;
        synchronized (this) {
            if (playerHp <= 0 || sourceWeaponSuppressed
                    || inventory.hasEquippedWeapon()) return;
            SourceWeaponPhysicalStats current =
                    requiredEquipmentMagicStats().physical().weapon();
            if (current == null || !current.present()
                    || current.itemId() != sourceWeapon.itemId()) return;
            result = state.damageSourceWeapon(
                    stateCharacter(), current, points);
        }
        sendEncrypted(Protocol.messageCode(268, activeWeaponLogName(sourceWeapon)),
                "S_MESSAGE_CODE weapon-break-source-weapon-damaged=268 item="
                        + result.itemId() + " durability="
                        + result.effectiveDurability());
        System.out.println("[LiTo] Weapon Break damaged source weapon player="
                + playerName() + " item=" + result.itemId() + " durability="
                + result.effectiveDurability() + " points=" + points);
    }

    private int applyGuardianTowerDamage(long objectId, int damage, String source)
            throws IOException {
        markBattleCombat();
        BattleGuardianTowers.Hit hit = hub.damageGuardianTower(
                currentRoomId, this, objectId, damage);
        if (hit == null) {
            System.out.println("[LiTo] guardian-tower damage rejected room=" + currentRoomId
                    + " attacker=" + playerName() + " object=" + objectId
                    + " damage=" + damage + " source=" + source);
            return 0;
        }
        BattleGuardianTower.Damage transition = hit.damage();
        BattleGuardianTower.Snapshot tower = transition.after();
        String objectiveLabel = tower.objectiveKind().wireLabel();
        byte[] ratio = Protocol.hitRatio(tower.objectId(), tower.hp(), tower.maxHp());
        List<ClientSession> recipients = hub.roomRules(currentRoomId).mode()
                == BattleRules.Mode.QUEST_BATTLE
                ? hub.battleRecipients(currentRoomId, tower.force())
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO " + objectiveLabel + "=" + tower.objectId()
                            + " force=" + tower.force() + " hp=" + tower.hp()
                            + "/" + tower.maxHp() + " source=" + source);
            if (transition.actionChanged()) {
                member.sendEncrypted(Protocol.objectAction(
                                tower.objectId(), tower.action()),
                        "S_ACTION " + objectiveLabel + "=" + tower.objectId()
                                + " action=" + tower.action()
                                + " source=" + source);
            }
            if (!hit.spawnedTimeAttackActors().isEmpty()) {
                int seconds = hub.roomRules(currentRoomId).timeLimitSeconds();
                member.sendEncrypted(Protocol.litoTimeLimit(seconds),
                        "S_LITO_TIMELIMIT timeattack-start-tower="
                                + tower.objectId() + " battle-seconds=" + seconds
                                + " destroyer-role=" + hit.timeAttackStartRole()
                                + " dragon-policy="
                                + (hit.timeAttackStartRole().equals("leader")
                                    ? BattleTimeAttackEncounter.DRAGON_SELECTION_SOURCE
                                    : BattleTimeAttackEncounter
                                            .NON_LEADER_DRAGON_BOUNDARY_SOURCE));
            }
            if (hit.openedSiegeGate() != null) {
                BattleDoor.Snapshot gate = hit.openedSiegeGate();
                member.sendEncrypted(Protocol.objectAction(
                                gate.objectId(), gate.action()),
                        "S_ACTION siege-inner-gate=" + gate.objectId()
                                + " action=" + gate.action()
                                + " source=two-outer-towers-destroyed");
                member.sendEncrypted(Protocol.doorAttribute(
                                gate.x(), gate.y(), gate.direction(), gate.passable()),
                        "S_CHANGE_ATTR siege-inner-gate=" + gate.objectId()
                                + " x=" + gate.x() + " y=" + gate.y()
                                + " direction=" + gate.direction()
                                + " passable=" + gate.passable()
                                + " source=two-outer-towers-destroyed");
            }
            for (BattleTimeAttackEncounter.Snapshot boss
                    : hit.spawnedTimeAttackActors()) {
                member.sendEncrypted(Protocol.timeAttackActor(boss),
                        "S_PUT_OBJECT timeattack-actor=" + boss.objectId()
                                + " npc=" + boss.npcId()
                                + " gfx=" + boss.gfx()
                                + " final-boss=" + boss.finalBoss()
                                + " hp=" + boss.hp() + "/" + boss.maxHp()
                                + " start-tower=" + tower.objectId()
                                + " destroyer-role=" + hit.timeAttackStartRole()
                                + " wave-source=" + boss.ordinaryWaveSource());
            }
        }
        if (hit.spawnedTimeAttackActors().stream()
                .anyMatch(BattleTimeAttackEncounter.Snapshot::activeAi)) {
            hub.armPveAi(currentRoomId);
        }
        if (!hit.spawnedQuestActors().isEmpty()) {
            publishQuestWaveAdvance(tower.force(), hit.completedQuestRoom(),
                    hit.spawnedQuestActors(), false,
                    tower.objectiveKind().wireLabel() + "-destroyed");
        }
        System.out.println("[LiTo] " + objectiveLabel + " damaged room=" + currentRoomId
                + " attacker=" + playerName() + " object=" + tower.objectId()
                + " force=" + tower.force() + " damage=" + damage
                + " hp=" + tower.hp() + "/" + tower.maxHp()
                + " action=" + tower.action() + " source=" + source);
        int appliedDamage = Math.max(0,
                transition.before().hp() - transition.after().hp());
        if (!hit.resolution().ended()) return appliedDamage;
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.serverEndBattle(hit.resolution());
        }
        hub.endBattle(currentRoomId);
        return appliedDamage;
    }

