    private void publishQuestWaveAdvance(
            int force, int clearedRoom,
            List<BattleQuestEncounter.Snapshot> spawned,
            boolean objectiveUnlocked, String source) throws IOException {
        List<ClientSession> recipients = hub.battleRecipients(currentRoomId, force);
        if (!spawned.isEmpty()) {
            int nextRoom = clearedRoom + 1;
            String announcement = BattleQuestEncounter.armyAnnouncement(force, nextRoom);
            byte[] announcementPacket = Protocol.systemMessage(9, announcement);
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendEncrypted(announcementPacket,
                        "S_MESSAGE quest-army force=" + force
                                + " room=" + nextRoom
                                + " source=room-monsters-eliminated+"
                                + BattleQuestEncounter.ARMY_ANNOUNCEMENT_SOURCE);
            }
            for (ClientSession member : recipients) {
                for (BattleQuestBoundary.Attribute edge
                        : hub.openedQuestBoundary(currentRoomId, force, clearedRoom)) {
                    member.sendEncrypted(Protocol.doorAttribute(
                                    edge.x(), edge.y(), edge.direction(), edge.passable()),
                            "S_CHANGE_ATTR quest-boundary-open force=" + force
                                    + " after-room=" + clearedRoom
                                    + " x=" + edge.x() + " y=" + edge.y()
                                    + " direction=" + edge.direction()
                                    + " source=room-monsters-eliminated+"
                                    + BattleQuestBoundary.WIRE_SOURCE);
                }
                for (BattleQuestEncounter.Snapshot actor : spawned) {
                    member.sendEncrypted(Protocol.questMonster(actor),
                            "S_PUT_OBJECT quest-monster=" + actor.objectId()
                                    + " force=" + actor.force()
                                    + " room=" + actor.roomNumber()
                                    + " npc=" + actor.npcId()
                                    + " after-cleared-room=" + clearedRoom);
                }
            }
            hub.armPveAi(currentRoomId);
            return;
        }
        if (!objectiveUnlocked) return;
        for (ClientSession member : recipients) {
            BattleGuardianTower.Snapshot tower =
                    hub.visibleGuardianTowers(currentRoomId, member).stream()
                            .filter(candidate -> candidate.force() == force
                                    && candidate.objectiveKind()
                                    != BattleGuardianTower.ObjectiveKind
                                            .COMMON_GUARDIAN_TOWER)
                            .findFirst().orElse(null);
            if (tower == null) {
                throw new IllegalStateException("missing visible Quest objective: "
                        + "force=" + force + " room=" + clearedRoom);
            }
            member.sendEncrypted(Protocol.guardianTower(tower),
                    "S_PUT_OBJECT " + tower.objectiveKind().wireLabel()
                            + "=" + tower.objectId()
                            + " force=" + force
                            + " room=" + clearedRoom
                            + " flow-source="
                            + BattleQuestEncounter.MAP_SPECIFIC_FLOW_SOURCE
                            + " presentation-source=" + tower.placementSource()
                            + " trigger=" + source);
        }
    }

