    private void publishQuestMonsterPoisonUpdate(GameHub.QuestMonsterPoisonUpdate questMonsterPoisonUpdate, long l) throws IOException {
        NativeSourceArenaPoison.hpbar(questMonsterPoisonUpdate.update());
        BattleQuestEncounter.PoisonUpdate poisonUpdate = questMonsterPoisonUpdate.update();
        for (BattleQuestEncounter.Hit object : poisonUpdate.hits()) {
            BattleQuestEncounter.Damage damage = object.damage();
            BattleQuestEncounter.Snapshot snapshot = damage.after();
            List<ClientSession> list = this.hub.battleRecipients(this.currentRoomId, snapshot.force());
            byte[] byArray = NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), snapshot.hp(), snapshot.maxHp());
            for (ClientSession clientSession : list) {
                NativeSourceArenaPoison.send(clientSession, byArray, "S_HIT_RATIO quest-monster=" + snapshot.objectId() + " force=" + snapshot.force() + " room=" + snapshot.roomNumber() + " hp=" + snapshot.hp() + "/" + snapshot.maxHp() + " source=enchant-venom-poison-tick", questMonsterPoisonUpdate.update());
                if (!damage.diedNow()) continue;
                NativeSourceArenaPoison.send(clientSession, Protocol.poison(snapshot.objectId(), 0), "S_POISON quest-monster=" + snapshot.objectId() + " type=0 reason=damage-poison-death", questMonsterPoisonUpdate.update());
                NativeSourceArenaPoison.send(clientSession, Protocol.objectAction(snapshot.objectId(), 8), "S_ACTION quest-monster=" + snapshot.objectId() + " action=8 source=enchant-venom-poison-tick", questMonsterPoisonUpdate.update());
            }
            if (damage.diedNow() && questMonsterPoisonUpdate.attacker() != null) {
                NativeSourceArenaPoison.reward(questMonsterPoisonUpdate.attacker(), snapshot.npcId(), "quest-enchant-venom-poison", questMonsterPoisonUpdate.update());
            }
            if (object.waveCleared()) {
                this.publishQuestWaveAdvance(snapshot.force(), object.clearedRoom(), object.spawned(), object.objectiveUnlocked(), "enchant-venom-poison-tick");
            }
            System.out.println("[LiTo] Quest monster poison tick room=" + this.currentRoomId + " attacker=" + poisonUpdate.attackerObjectId() + " object=" + snapshot.objectId() + " damage=" + (damage.before().hp() - damage.after().hp()) + " hp=" + snapshot.hp() + "/" + snapshot.maxHp() + " died=" + damage.diedNow() + " wave-cleared=" + object.waveCleared());
        }
        if (poisonUpdate.expired() && poisonUpdate.target().alive()) {
            int n = this.hub.questMonsterPoisonPalette(this.currentRoomId, poisonUpdate.target().objectId(), l);
            byte[] byArray = Protocol.poison(poisonUpdate.target().objectId(), n);
            for (ClientSession clientSession : this.hub.battleRecipients(this.currentRoomId, poisonUpdate.target().force())) {
                NativeSourceArenaPoison.send(clientSession, byArray, "S_POISON quest-monster=" + poisonUpdate.target().objectId() + " type=" + n + " reason=damage-poison-expired", questMonsterPoisonUpdate.update());
            }
        }
    }

