    /**
     * Exact retained CalcExp/L1PcInstance lawful path: negate the defeated
     * NPC's source lawful value, clamp the character to a signed word, then
     * publish S_CHANGE_ALIGNMENT to every room member that owns the actor.
     */
    private void applyNpcLawfulReward(int npcId, String source) throws IOException {
        SourceNpcPhysicalStats npc;
        try {
            npc = selectedSourceAccounts().npcPhysicalStats(npcId);
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] lawful reward skipped; source NPC lookup failed"
                    + " player=" + playerName() + " npc=" + npcId
                    + " reason=" + sourceFailure.getClass().getSimpleName()
                    + ": " + sourceFailure.getMessage());
            return;
        }
        if (npc.lawful() == 0) return;

        CharacterSummary character = selectedCharacterSummary();
        int sourceLawful = character == null ? 0 : nativeLawful(character.lawful());
        GameStateStore.LawfulMutation mutation = state.addLawful(
                stateCharacter(), sourceLawful, -npc.lawful());
        playerLawful = mutation.after();
        if (!mutation.changed()) return;

        byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(packet,
                    "S_CHANGE_ALIGNMENT player=" + playerName()
                            + " object=" + playerObjectId()
                            + " npc=" + npcId
                            + " source-npc-lawful=" + npc.lawful()
                            + " requested-delta=" + mutation.requestedDelta()
                            + " applied-delta=" + mutation.appliedDelta()
                            + " lawful=" + mutation.before() + "->" + mutation.after()
                            + " source=" + source);
        }
        System.out.println("[LiTo] lawful changed player=" + playerName()
                + " npc=" + npcId + " source-npc-lawful=" + npc.lawful()
                + " lawful=" + mutation.before() + "->" + mutation.after()
                + " source=" + source);
    }

