    private void takeClassicWorldPlayerDamage(int n, ClientSession clientSession, boolean bl, boolean bl2) throws IOException {
        if (CombatRules.loaded()) {
            NativePlayerCommit.worldPlayer(this, n, clientSession, bl, bl2);
            return;
        }
        if (this.phase != Phase.WORLD || this.playerHp <= 0 || n <= 0 || clientSession == null || !this.sameClassicWorldMap(clientSession)) {
            return;
        }
        if (bl && (n = this.earthBindProtectedCombatDamage(n, "classic-world-player-" + clientSession.playerName())) <= 0) {
            return;
        }
        BattleJoyOfPainStatus.Lease lease = !bl2 && clientSession != this ? clientSession.joyOfPainStatus.capture(System.nanoTime()) : null;
        int n2 = lease == null ? 0 : BattleJoyOfPain.feedbackDamage(this.playerMaxHp, this.playerHp, this.joyOfPainEquipmentAddedHp());
        int n3 = this.playerHp;
        CombatPoisonLifecycle.lastDamage(this, clientSession);
        ClassicWorldFatalContext classicWorldFatalContext = this.takeClassicWorldMonsterDamage(n, clientSession.playerObjectId());
        if (this.playerHp >= n3) {
            return;
        }
        this.applyClassicWorldPlayerLiability(clientSession, classicWorldFatalContext);
        if (!bl2 && clientSession.playerHp > 0) {
            this.tryMortalBodyPlayerReflection(clientSession, "classic-world-accepted-player-damage");
        }
        this.applyJoyOfPainPlayerFeedback(clientSession, lease, n2, "classic-world-accepted-player-damage");
    }

    private void takeClassicWorldCompanionDamage(int n, ClientSession clientSession, BattleCompanion battleCompanion) throws IOException {
        if (CombatRules.loaded()) {
            NativePlayerCommit.worldCompanion(this, n, clientSession, battleCompanion);
            return;
        }
        if (this.phase != Phase.WORLD || this.playerHp <= 0 || n <= 0 || clientSession == null || clientSession == this || battleCompanion == null || !this.sameClassicWorldMap(clientSession)) {
            return;
        }
        BattleCompanion.Snapshot snapshot = battleCompanion.snapshot();
        if (!snapshot.active() || !snapshot.kind().classicWorldEligible()) {
            return;
        }
        int n2 = this.playerHp;
        CombatPoisonLifecycle.lastDamage(this, clientSession);
        ClassicWorldFatalContext classicWorldFatalContext = this.takeClassicWorldMonsterDamage(n, snapshot.objectId());
        if (this.playerHp >= n2) {
            return;
        }
        this.applyClassicWorldPlayerLiability(clientSession, classicWorldFatalContext);
    }

    /** Shared retained player liability after direct, pet, or summon damage. */
    private void applyClassicWorldPlayerLiability(
            ClientSession attacker, ClassicWorldFatalContext fatalContext)
            throws IOException {
        boolean fatalPkExempt = playerHp == 0
                && (fatalContext.clanWarPkExempt()
                    || classicWorldPlayerKillPkExempt(attacker));
        boolean nativePk = playerHp == 0
                && !fatalPkExempt
                && attacker.classicWorldPinkNameEligible(
                        this, ClassicWorldMapCatalog.forMap(classicWorldMapId));
        if (nativePk) {
            boolean incrementPkCount = attacker.playerLawful < 30_000;
            GameStateStore.GeneralPkState recorded =
                    attacker.state.recordGeneralPkKill(
                            attacker.stateCharacter(),
                            incrementPkCount);
            attacker.generalPkCount = recorded.count();
            attacker.lastPkEpochSeconds = recorded.lastPkEpochSeconds();
            attacker.applyGeneralPkLawfulPenalty();
            System.out.println("[LiTo] native general-PK recorded attacker="
                    + attacker.playerName() + " victim=" + playerName()
                    + " count=" + attacker.generalPkCount
                    + " wanted-seconds=" + ClassicWorldGuardCatalog.WANTED_SECONDS);

            if (attacker.isElfCharacter() && isElfCharacter()) {
                GameStateStore.ElfPkState elfRecorded =
                        attacker.state.recordElfPkKill(
                                attacker.stateCharacter(),
                                incrementPkCount);
                attacker.elfPkCount = elfRecorded.count();
                attacker.lastPkForElfEpochSeconds =
                        elfRecorded.lastPkEpochSeconds();
                System.out.println("[LiTo] native elf-PK recorded attacker="
                        + attacker.playerName() + " victim=" + playerName()
                        + " count=" + attacker.elfPkCount
                        + " wanted-seconds="
                        + ClassicWorldGuardianCatalog.WANTED_SECONDS);
            }
            if (incrementPkCount && attacker.generalPkCount >= 5
                    && attacker.generalPkCount < ClassicWorldHell.PK_THRESHOLD) {
                attacker.sendEncrypted(Protocol.messageCode(551,
                                Integer.toString(attacker.generalPkCount),
                                Integer.toString(ClassicWorldHell.PK_THRESHOLD)),
                        "S_MESSAGE_CODE Hell-warning=551 pk="
                                + attacker.generalPkCount + " threshold="
                                + ClassicWorldHell.PK_THRESHOLD);
            } else if (incrementPkCount
                    && attacker.generalPkCount >= ClassicWorldHell.PK_THRESHOLD) {
                attacker.beginClassicWorldHell(true);
            }
        }
        attacker.publishClassicWorldPinkName(this);
    }

    private ClientSession classicWorldPlayerAttacker(long attackerObjectId) {
        if (attackerObjectId == playerObjectId()) return null;
        List<ClientSession> members = classicWorldMembers(classicWorldMapId);
        ClientSession direct = members.stream()
                .filter(member -> member != this
                        && member.playerObjectId() == attackerObjectId
                        && sameClassicWorldMap(member))
                .findFirst().orElse(null);
        if (direct != null) return direct;
        return members.stream()
                .filter(member -> member != this && sameClassicWorldMap(member))
                .filter(member -> member.classicWorldCompanionSnapshots().stream()
                        .anyMatch(companion -> companion.active()
                                && companion.objectId() == attackerObjectId))
                .findFirst().orElse(null);
    }

    /** Retained Death post-penalty exemptions; pink-name action is independent. */
    private boolean classicWorldPlayerKillPkExempt(ClientSession attacker) {
        if (attacker == null) return false;
        if (ClassicWorldDeathContext.encounterProtects(
                battleLevel(), attacker.battleLevel())) {
            return true;
        }
        if (ClassicWorldDeathContext.castleAreaSuppressesPk(
                classicWorldMapId, positionX, positionY)) {
            return true;
        }
        return hub.classicClanWarActiveBetween(
                sourceCharacterIdentity(), attacker.sourceCharacterIdentity());
    }

    private void takeClassicWorldPlayerPoisonDamage(int n, ClientSession clientSession) throws IOException {
        if (CombatRules.loaded()) {
            NativePlayerCommit.worldPoison(this, n, clientSession);
            return;
        }
        if (this.phase != Phase.WORLD || this.playerHp <= 0 || n <= 0 || clientSession == null) {
            return;
        }
        int n2 = this.playerHp;
        CombatPoisonLifecycle.lastDamage(this, clientSession);
        this.takeClassicWorldMonsterDamage(n, clientSession.playerObjectId());
        if (this.playerHp < n2 && this.sameClassicWorldMap(clientSession)) {
            clientSession.publishClassicWorldPinkName(this);
        }
    }

    private boolean classicWorldPinkNameEligible(
            ClientSession target, ClassicWorldMapCatalog.ClassicMap map) {
        if (target == null || target == this || !sameClassicWorldMap(target)) {
            return false;
        }
        int castleId = ClassicWorldCastleWarField.castleIdAt(
                target.classicWorldMapId, target.positionX, target.positionY);
        return (castleId == 0 || !hub.classicCastleWarActive(
                        target.selectedClassicServerName, castleId))
                && map.isNormalZone(positionX, positionY)
                && map.isNormalZone(target.positionX, target.positionY)
                && target.playerLawful >= 0
                && !target.classicWorldPinkName.active();
    }

    /** Exact retained player-kill lawful formula from L1PcInstance.Death. */
    private void applyGeneralPkLawfulPenalty() throws IOException {
        int level = Math.max(1, battleLevel());
        int calculated = level < 50
                ? -Math.multiplyExact(Math.multiplyExact(level, level), 4)
                : -(int) (Math.pow(level, 3) * 0.08D);
        int target = Math.max(Short.MIN_VALUE,
                Math.min(calculated, playerLawful - 1_000));
        GameStateStore.LawfulMutation mutation = state.addLawful(
                stateCharacter(), selectedCharacterSummary() == null ? 0
                        : nativeLawful(selectedCharacterSummary().lawful()),
                target - playerLawful);
        playerLawful = mutation.after();
        if (!mutation.changed()) return;
        byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)) continue;
            member.sendEncrypted(packet,
                    "S_CHANGE_ALIGNMENT native-general-PK player=" + playerName()
                            + " level=" + level + " calculated=" + calculated
                            + " lawful=" + mutation.before() + "->"
                            + mutation.after());
        }
    }

    private void publishClassicWorldPinkName(ClientSession target)
            throws IOException {
        if (phase != Phase.WORLD || target == null
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        if (!classicWorldPinkNameEligible(target, map)) return;

        // Retained publishPinkNameActive sends the 180 packet on every eligible
        // accepted hit, even while the attacker's original timer is still active.
        byte[] activePacket = Protocol.criminalStatus(
                playerObjectId(), ClassicWorldPinkNameStatus.WIRE_SECONDS);
        publishClassicWorldCriminalPacket(activePacket,
                "active target=" + target.playerName());
        ClassicWorldPinkNameStatus.Publication publication =
                classicWorldPinkName.publishActive(
                        classicWorldMapId, classicWorldInstanceId,
                        positionX, positionY, System.nanoTime());
        System.out.println("[LiTo] classic-world pink-name active attacker="
                + playerName() + " target=" + target.playerName()
                + " started=" + publication.started() + " generation="
                + publication.snapshot().generation() + " origin="
                + publication.snapshot().originX() + ","
                + publication.snapshot().originY() + " wire-seconds="
                + ClassicWorldPinkNameStatus.WIRE_SECONDS);
    }

    private void publishClassicWorldCriminalPacket(byte[] packet, String reason)
            throws IOException {
        List<ClientSession> recipients = phase == Phase.WORLD
                && ClassicWorldMapCatalog.supports(classicWorldMapId)
                ? classicWorldMembers(classicWorldMapId) : List.of(this);
        IOException first = null;
        for (ClientSession member : recipients) {
            if (member != this && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            try {
                member.sendEncrypted(packet,
                        "S_CRIMINAL classic-world player=" + playerObjectId()
                                + " " + reason);
            } catch (IOException failure) {
                if (first == null) first = failure;
            }
        }
        if (first != null) throw first;
    }

    private void expireClassicWorldPinkName(long nowNanos) throws IOException {
        boolean inClassicWorld = phase == Phase.WORLD
                && ClassicWorldMapCatalog.supports(classicWorldMapId);
        ClassicWorldPinkNameStatus.Expiration expiration =
                classicWorldPinkName.expire(
                        inClassicWorld, playerHp > 0,
                        classicWorldMapId, classicWorldInstanceId,
                        positionX, positionY, nowNanos);
        if (!expiration.cleared()) return;
        publishClassicWorldCriminalPacket(
                Protocol.criminalStatus(playerObjectId(), 0),
                "clear reason=" + expiration.reason());
        System.out.println("[LiTo] classic-world pink-name cleared player="
                + playerName() + " generation="
                + expiration.previous().generation() + " reason="
                + expiration.reason());
    }

