    private void abandonClassicWorldDspyFollower(String reason) throws IOException {
        ClassicWorldDspyEscorts.Transition transition =
                hub.classicWorldDspyEscorts().ownerLost(
                        sourceCharacterIdentity());
        if (transition.kind() == ClassicWorldDspyEscorts.TransitionKind.NONE) return;
        broadcastClassicWorldDspyReplacement(
                transition.before(), transition.after(), reason);
        hub.clearClassicWorldMonsterTargets(transition.before().objectId());
    }

