    private void broadcastClassicWorldRoiMovement(
            ClassicWorldRoiFollowers.Snapshot before,
            ClassicWorldRoiFollowers.Snapshot after) throws IOException {
        byte[] movement = new Protocol.Writer().c(Protocol.S_MOVE_OBJECT)
                .d(before.objectId()).h(before.x()).h(before.y())
                .c(after.heading()).bytes();
        for (ClientSession member : classicWorldMembers(before.mapId())) {
            boolean sawBefore = BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, before.x(), before.y());
            boolean seesAfter = BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y());
            if (sawBefore && !seesAfter) {
                member.sendEncrypted(Protocol.removeObject(before.objectId()),
                        "S_REMOVE_OBJECT Roi-follower=" + before.objectId()
                                + " reason=follow-screen-exit");
            } else if (!sawBefore && seesAfter) {
                member.sendClassicWorldRoiFollower(after, "follow-screen-enter");
            } else if (seesAfter) {
                member.sendEncrypted(movement,
                        "S_MOVE_OBJECT Roi-follower=" + before.objectId()
                                + " source=" + before.x() + "," + before.y()
                                + " destination=" + after.x() + "," + after.y()
                                + " heading=" + after.heading());
            }
        }
    }

