    private ClassicWorldNpcPathfinder.Result chooseClassicWorldCompanionStep(
            BattleCompanion.Snapshot companion,
            int targetX, int targetY, long targetObjectId, int attackRange) {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        return ClassicWorldNpcPathfinder.nextStep(
                map, companion.x(), companion.y(), targetX, targetY, attackRange,
                (x, y) -> classicWorldCompanionTileOccupied(
                        x, y, companion.objectId(), targetObjectId));
    }

    private boolean noFreeClassicWorldCompanionApproachSlot(
            BattleCompanion.Snapshot companion,
            int targetX, int targetY, long targetObjectId, int attackRange) {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        for (int x = targetX - attackRange; x <= targetX + attackRange; x++) {
            for (int y = targetY - attackRange; y <= targetY + attackRange; y++) {
                if (x == targetX && y == targetY) continue;
                if (map.standingPassable(x, y)
                        && map.attackPosition(x, y, targetX, targetY, attackRange)
                        && !classicWorldCompanionTileOccupied(
                                x, y, companion.objectId(), targetObjectId)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean sameMasterCompanionCrowdingTarget(
            BattleCompanion.Snapshot companion,
            int targetX, int targetY, long targetObjectId, int attackRange) {
        return classicWorldCompanionSnapshots().stream().anyMatch(peer ->
                peer.active()
                        && peer.objectId() != companion.objectId()
                        && peer.targetObjectId() == targetObjectId
                        && Math.max(Math.abs(peer.x() - targetX),
                                Math.abs(peer.y() - targetY)) <= attackRange);
    }

    private void removeClassicWorldCompanion(
            BattleCompanion controlled, BattleCompanion.Snapshot snapshot,
            String reason, boolean dismissEffect) throws IOException {
        if (snapshot.kind() == BattleCompanion.Kind.PET) {
            transferCompanionItems(controlled);
            GameStateStore.PetState durable = controlled.durablePetState();
            if (durable != null) state.savePet(durable);
            dismissEffect = false;
        } else if (snapshot.kind() == BattleCompanion.Kind.TAMED) {
            abandonClassicWorldTamedOrigin(controlled, reason);
        }
        controlled.deactivate();
        hub.transferClassicWorldMonsterTargets(snapshot.objectId(), playerObjectId());
        synchronized (tamedCompanions) {
            tamedCompanions.removeIf(candidate ->
                    candidate.snapshot().objectId() == snapshot.objectId());
        }
        byte[] effect = Protocol.effectObject(snapshot.objectId(), 169);
        byte[] remove = Protocol.removeObject(snapshot.objectId());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, snapshot.x(), snapshot.y())) continue;
            if (dismissEffect) {
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world-companion=" + snapshot.objectId()
                                + " gfx=169 reason=" + reason);
            }
            member.sendEncrypted(remove,
                    "S_REMOVE_OBJECT classic-world-companion=" + snapshot.objectId()
                            + " owner=" + playerName() + " reason=" + reason);
        }
        System.out.println("[LiTo] classic-world companion removed owner="
                + playerName() + " object=" + snapshot.objectId()
                + " npc=" + snapshot.npcId() + " reason=" + reason);
    }

    private void abandonClassicWorldTamedOrigin(
            BattleCompanion controlled, String reason) {
        ClassicWorldMonsterPopulation.Snapshot origin = controlled == null
                ? null : controlled.classicWorldTamedOrigin();
        if (origin == null) return;
        ClassicWorldMonsterPopulation.Snapshot abandoned =
                hub.abandonClassicWorldTamedMonster(
                        origin.mapId(), controlled.classicWorldTamedInstanceId(),
                        origin.objectId());
        System.out.println("[LiTo] classic-world tamed origin abandoned owner="
                + playerName() + " origin=" + origin.objectId()
                + " map=" + origin.mapId() + " reason=" + reason
                + " respawn-scheduled=" + (abandoned != null));
    }

    /*
     * WARNING - Removed try catching itself - possible behaviour change.
     */
    private void cleanupClassicWorldTransientCompanionsOnDisconnect() throws IOException {
        List<BattleCompanion> list;
        List<BattleCompanion> list2 = this.tamedCompanions;
        synchronized (list2) {
            list = this.tamedCompanions.stream().filter(battleCompanion -> {
                if (battleCompanion.snapshot().kind() == BattleCompanion.Kind.SUMMON) {
                    return false;
                }
                return battleCompanion.snapshot().kind() != BattleCompanion.Kind.PET;
            }).toList();
        }
        for (BattleCompanion battleCompanion2 : list) {
            BattleCompanion.Snapshot snapshot = battleCompanion2.snapshot();
            if (snapshot.kind() == BattleCompanion.Kind.TAMED) {
                this.abandonClassicWorldTamedOrigin(battleCompanion2, "owner-disconnect");
            }
            battleCompanion2.deactivate();
            byte[] byArray = Protocol.removeObject(snapshot.objectId());
            for (ClientSession clientSession : this.classicWorldMembers(this.classicWorldMapId)) {
                if (clientSession == this || !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y())) continue;
                clientSession.sendEncrypted(byArray, "S_REMOVE_OBJECT classic-world-transient=" + snapshot.objectId() + " owner=" + this.playerName() + " reason=owner-disconnect");
            }
        }
        list2 = this.tamedCompanions;
        synchronized (list2) {
            this.tamedCompanions.removeAll(list);
        }
    }

