    private int[] chooseCompanionStep(long roomId, ArenaMapCatalog.Arena arena,
                                      BattleCompanion.Snapshot companion,
                                      int targetX, int targetY, long targetObjectId) {
        int preferred = heading(companion.x(), companion.y(), targetX, targetY);
        int[] headingOrder = {
                preferred, (preferred + 1) & 7, (preferred + 7) & 7,
                (preferred + 2) & 7, (preferred + 6) & 7,
                (preferred + 3) & 7, (preferred + 5) & 7, (preferred + 4) & 7
        };
        int[] headingX = {0, 1, 1, 1, 0, -1, -1, -1};
        int[] headingY = {-1, -1, 0, 1, 1, 1, 0, -1};
        int currentRange = Math.max(Math.abs(companion.x() - targetX),
                Math.abs(companion.y() - targetY));
        for (int candidate : headingOrder) {
            int x = companion.x() + headingX[candidate];
            int y = companion.y() + headingY[candidate];
            if (!arena.contains(x, y) || (x == targetX && y == targetY)
                    || !arena.nativeCanStep(companion.x(), companion.y(), x, y)
                    || hub.questBoundaryBlocks(roomId, this,
                            companion.x(), companion.y(), x, y)
                    || companionTileOccupied(roomId, x, y,
                    companion.objectId(), targetObjectId)) continue;
            int nextRange = Math.max(Math.abs(x - targetX), Math.abs(y - targetY));
            if (nextRange <= currentRange) return new int[] {x, y, candidate};
        }
        return null;
    }

    private boolean companionTileOccupied(long roomId, int x, int y,
                                          long companionObjectId, long targetObjectId) {
        if (hub.battleDoorBlocks(roomId, x, y)
                || hub.siegeGateBlocks(roomId, x, y)
                || hub.guardianTowerBlocks(roomId, x, y)
                || hub.questMonsterBlocks(roomId, this, x, y)
                || hub.timeAttackActorBlocks(roomId, x, y)) return true;
        for (ClientSession combatant : hub.roomCombatants(roomId)) {
            if (combatant.playerObjectId() != targetObjectId && combatant.playerHp > 0
                    && combatant.positionX == x && combatant.positionY == y) return true;
            for (BattleCompanion.Snapshot peer
                    : combatant.controlledCompanionSnapshots()) {
                if (peer.active() && peer.objectId() != companionObjectId
                        && peer.objectId() != targetObjectId
                        && peer.x() == x && peer.y() == y) return true;
            }
        }
        ArenaMapCatalog.Point bot = hub.botPosition(roomId);
        return bot != null && targetObjectId != 2 && bot.x() == x && bot.y() == y;
    }

    static int companionHitChance(int targetArmorClass, int d20, int negativeAcRoll) {
        return companionHitChance(
                BattleCompanion.LEVEL, targetArmorClass, d20, negativeAcRoll);
    }

    private static int companionHitChance(int level, int targetArmorClass,
                                          int d20, int negativeAcRoll) {
        if (level <= 0) throw new IllegalArgumentException("invalid companion level");
        if (d20 < 1 || d20 > 20) throw new IllegalArgumentException("invalid companion d20");
        int hitRate = level + 5;
        int attackerDice = d20 + hitRate - 3;
        int defenderDice;
        if (targetArmorClass >= 0) {
            defenderDice = 10 - targetArmorClass;
        } else {
            if (negativeAcRoll < 1 || negativeAcRoll > -targetArmorClass) {
                throw new IllegalArgumentException("invalid negative-AC defense roll");
            }
            defenderDice = 10 + negativeAcRoll;
        }
        if (attackerDice <= hitRate) return 15;
        if (attackerDice >= hitRate + 19) return 100;
        return attackerDice > defenderDice ? 100 : 15;
    }

    static int companionPhysicalDamage(int n, int n2, int n3, int n4, int n5) {
        return ClientSession.companionPhysicalDamage(5, 15, n, n2, n3, n4, n5);
    }

    private static int companionPhysicalDamage(int n, int n2, int n3, int n4, int n5, int n6, int n7) {
        if (n <= 0 || n2 <= 0 || n5 < 0 || n5 >= n || n6 < 0 || n6 >= 100) {
            throw new IllegalArgumentException("invalid companion damage roll");
        }
        int n8 = ClientSession.companionDefenseMaximum(n3, n4);
        if (n7 < 0 || (n8 == 0 ? n7 != 0 : n7 >= n8)) {
            throw new IllegalArgumentException("invalid companion AC defense roll");
        }
        int n9 = n2 == 15 ? 2 : Math.floorDiv(n2 - 11, 2);
        double d = (double)n5 + (double)n2 * 0.8 + (double)n9;
        if (n6 < 15) {
            d *= 1.8;
        }
        if (n8 > 0) {
            d -= (double)(n7 + Math.max(1, n8 >> 3));
        }
        return Math.max(0, (int)(d *= CombatRules.replace(0.3, "PET_TO_PC_DAMAGE_MULTIPLIER")));
    }

    private static int companionNpcPhysicalDamage(int level, int strength,
                                                  int levelRoll, int criticalRoll,
                                                  int strengthDamage) {
        if (level <= 0 || strength <= 0 || levelRoll < 0 || levelRoll >= level
                || criticalRoll < 0 || criticalRoll >= 100) {
            throw new IllegalArgumentException("invalid companion NPC damage roll");
        }
        double damage = levelRoll + strength * 0.8 + strengthDamage;
        if (criticalRoll < 15) damage *= 1.8;
        return Math.max(0, (int) damage);
    }

    private static int companionDefenseMaximum(int targetType, int targetArmorClass) {
        return BattlePhysicalDefense.playerAcMaximum(targetType, targetArmorClass);
    }

    int battleArmorClass() {
        return this.battleArmorClass(System.nanoTime());
    }

    private int battleArmorClass(long l) {
        BattleSpellCatalog.WeaknessSpell weaknessSpell = BattleSpellCatalog.weaknessSpell(56);
        int n = this.timedStatus.diseaseActive(l) ? CombatWeaponBuffs.diseaseArmor(weaknessSpell.armorClassModifier()) : 0;
        long l2 = (long)this.baseArmorClass() + (long)this.activeMagicDollPowers().value("PASSIVE_AC") + (long)this.abilityStatus.shield(l).amount() + (long)this.earthBlessStatus.armorClass(l) + (long)this.ironSkinStatus.armorClass(l) + (long)this.guardBrakeStatus.armorClass(l) + (long)this.abilityStatus.berserk(l).armorClass() + (long)this.abilityStatus.bounceAttack(l).armorClass() + (long)this.abilityStatus.royalAura(l).armorClass() + (long)this.abilityStatus.diamondGolem(l).armorClass() + (long)CombatAwaken.ability(this.awakenStatus.snapshot(), "AC") + (long)this.cookingStatus.active(l).armorClass() + (long)this.activeItemArmorEnchantModifier(l) + (long)n + (long)this.waterDragonBlessingArmorClass(l);
        return NumericBreakthrough.clampArmorClass(l2);
    }

    private int activeItemArmorEnchantModifier(long l) {
        int n = 0;
        for (RuntimeInventory.Item item : this.inventory.items()) {
            InventoryCatalog.NativeArmorStatus nativeArmorStatus = item.definition().sourceArmorStatus();
            if (!item.equipped() || nativeArmorStatus == null || nativeArmorStatus.armorType() != 2) continue;
            n += CombatWeaponBuffs.itemArmorModifier(this.itemArmorEnchantStatus, l, item.objectId(), this).armorClass();
        }
        return CombatWeaponBuffs.armor(n, this, l);
    }

    int battleStrength() {
        return battleStrength(System.nanoTime());
    }

    private int battleStrength(long nowNanos) {
        return NumericBreakthrough.clampAbility(
                (long) battleStrengthWithoutAbility()
                        + abilityStatus.strength(nowNanos).amount()
                        + abilityStatus.insight(nowNanos).abilityScoreModifier()
                        + abilityStatus.panic(nowNanos).abilityScoreModifier()
                        + (timedStatus.horrorOfDeathActive(nowNanos) ? -5 : 0));
    }

