    private int effectiveRangedEvasionRate(long l) {
        if (this.timedStatus.strikerGaleActive(l)) {
            return 0;
        }
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        if (characterSummary == null) {
            throw new IllegalStateException("selected character has no ER source");
        }
        SourceEquipmentPhysicalStats sourceEquipmentPhysicalStats = this.requiredEquipmentMagicStats().physical();
        return CombatSpecialBuffs.evasion(BattleRangedEvasion.total(characterSummary.type(), Math.max(0, characterSummary.level()), this.battleDexterity(l), characterSummary.originalDexterity(), Math.addExact(sourceEquipmentPhysicalStats.totalEvasionRate(), this.activeMagicDollPowers().value("PASSIVE_ER")), Math.addExact(this.dragonEyeStatus.snapshot(l).evasionRate(), Math.addExact(this.aquaProtectStatus.evasionRate(l), Math.addExact(this.abilityStatus.solidCarriage(l).evasionRate(), this.abilityStatus.dressEvasion(l).evasionRate())))), this, l);
    }

    private int effectivePhysicalDodge(long nowNanos) {
        return Math.addExact(activeMagicDollPowers().value("PASSIVE_DODGE"),
                Math.addExact(
                abilityStatus.uncannyDodge(nowNanos).dodgeModifier(),
                abilityStatus.mirrorImage(nowNanos).dodgeModifier()));
    }

