    private BattleInventoryWeight.Profile rentalTownWeightProfile(
            RuntimeInventory candidate, long nowNanos) {
        if (candidate == null) {
            throw new IllegalArgumentException("candidate inventory is required");
        }
        CharacterSummary character = selectedCharacterSummary();
        RentalEquipmentBonuses bonuses =
                RentalEquipmentBonuses.from(candidate.items());
        int baseStrength = character == null ? 13
                : Math.max(1, character.strength());
        int baseConstitution = character == null ? 10
                : Math.max(1, character.constitution());
        int strength = NumericBreakthrough.clampAbility(
                Math.addExact(baseStrength, bonuses.strength()));
        int constitution = NumericBreakthrough.clampAbility(
                Math.addExact(baseConstitution, bonuses.constitution()));
        BattleWeightStatus.Snapshot weight = weightStatus.snapshot(nowNanos);
        return new BattleInventoryWeight.Profile(
                candidate.totalWeight(), 1.0,
                character == null ? 0 : character.type(),
                strength, constitution,
                character == null ? baseStrength
                        : Math.max(0, character.originalStrength()),
                character == null ? baseConstitution
                        : Math.max(0, character.originalConstitution()),
                bonuses.weightReduction(), 0,
                weight.decreaseWeightActive());
    }

    private BattleInventoryWeight.Profile weightProfile(RuntimeInventory runtimeInventory, long l, int n) {
        if (runtimeInventory == null) {
            throw new IllegalArgumentException("candidate inventory is required");
        }
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        SourceEquipmentMagicStats sourceEquipmentMagicStats = this.requiredEquipmentMagicStats();
        SourceInventoryWeightStats sourceInventoryWeightStats = this.requiredInventoryWeightStats();
        int n2 = this.retainedSourceInventoryWeight < 0 ? sourceInventoryWeightStats.rawWeight() : this.retainedSourceInventoryWeight;
        int n3 = BattleInventoryWeight.addWeight(n2, runtimeInventory.totalWeight());
        BattleWeightStatus.Snapshot snapshot = this.weightStatus.snapshot(l);
        int n4 = this.effectiveConstitution();
        return new BattleInventoryWeight.Profile(n3, sourceInventoryWeightStats.serverWeightRate(), characterSummary == null ? 0 : characterSummary.type(), n, n4, characterSummary == null ? n : Math.max(0, characterSummary.originalStrength()), characterSummary == null ? n4 : Math.max(0, characterSummary.originalConstitution()), Math.addExact(CombatSpecialBuffs.weight(sourceEquipmentMagicStats.totalWeightReduction(), this, l), this.activeMagicDollPowers().value("PASSIVE_WEIGHT_REDUCTION")), 0, snapshot.decreaseWeightActive());
    }

