    List<BattleCompanion.Snapshot> controlledCompanionSnapshots() {
        List<BattleCompanion.Snapshot> result = new ArrayList<>();
        result.add(battleCompanion.snapshot());
        synchronized (tamedCompanions) {
            for (BattleCompanion companion : tamedCompanions) {
                result.add(companion.snapshot());
            }
        }
        return List.copyOf(result);
    }

    /*
     * WARNING - Removed try catching itself - possible behaviour change.
     */
    List<BattleCompanion.Snapshot> classicWorldCompanionSnapshots() {
        if (this.phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(this.classicWorldMapId)) {
            return NativeCompanionPlacement.snapshots(this, List.of());
        }
        List<BattleCompanion> list = this.tamedCompanions;
        List<BattleCompanion.Snapshot> eligible;
        synchronized (list) {
            eligible = this.tamedCompanions.stream().map(BattleCompanion::snapshot).filter(snapshot -> snapshot.kind().classicWorldEligible()).toList();
        }
        return NativeCompanionPlacement.snapshots(this, eligible);
    }

