    /** Retained C_SelectTarget visibility/world/safety authorization for a PC. */
    private ClientSession classicWorldCompanionPlayerTarget(
            BattleCompanion.Snapshot companion, long targetObjectId) {
        if (companion == null || targetObjectId == playerObjectId()) return null;
        ClientSession target = classicWorldMembers(classicWorldMapId).stream()
                .filter(candidate -> candidate != this
                        && candidate.playerObjectId() == targetObjectId
                        && candidate.phase == Phase.WORLD
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && sameClassicWorldMap(candidate)
                        && BattleSpellCatalog.isInNativeScreen(
                                companion.x(), companion.y(),
                                candidate.positionX, candidate.positionY))
                .findFirst().orElse(null);
        if (target == null) return null;
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        return map.isSafetyZone(companion.x(), companion.y())
                || map.isSafetyZone(target.positionX, target.positionY)
                ? null : target;
    }

    private boolean classicWorldCompanionTileOccupied(int n, int n2, long l, long l2) {
        if (NativeStaticNpcMotion.occupies(this.classicWorldMapId, n, n2, this)) {
            return true;
        }
        ClassicWorldMonsterPopulation.Snapshot snapshot = this.hub.classicWorldMonster(this.classicWorldMapId, this.classicWorldInstanceId, l2);
        if (this.hub.classicWorldMonsterOccupies(this.classicWorldMapId, this.classicWorldInstanceId, n, n2) && (snapshot == null || snapshot.x() != n || snapshot.y() != n2)) {
            return true;
        }
        for (ClientSession clientSession : this.classicWorldMembers(this.classicWorldMapId)) {
            if (clientSession.playerObjectId() != l2 && clientSession.playerHp > 0 && clientSession.positionX == n && clientSession.positionY == n2) {
                return true;
            }
            for (BattleCompanion.Snapshot snapshot2 : clientSession.classicWorldCompanionSnapshots()) {
                if (!snapshot2.active() || snapshot2.objectId() == l || snapshot2.objectId() == l2 || snapshot2.x() != n || snapshot2.y() != n2) continue;
                return true;
            }
        }
        return false;
    }

    private BattleCompanion ownedCompanion(long objectId) {
        if (battleCompanion.snapshot().objectId() == objectId) return battleCompanion;
        synchronized (tamedCompanions) {
            return tamedCompanions.stream()
                    .filter(companion -> companion.snapshot().objectId() == objectId)
                    .findFirst().orElse(null);
        }
    }

    private boolean peerOwnsCompanion(long objectId) {
        return hub.roomCombatants(currentRoomId).stream()
                .filter(member -> member != this)
                .flatMap(member -> member.controlledCompanionSnapshots().stream())
                .anyMatch(companion -> companion.objectId() == objectId);
    }

    private void clearControlledCompanionTargets() {
        for (BattleCompanion.Snapshot snapshot : controlledCompanionSnapshots()) {
            BattleCompanion companion = ownedCompanion(snapshot.objectId());
            if (companion != null) companion.clearTarget();
        }
    }

