    private void applyJoyOfPainArenaBotFeedback(
            long roomId, BattleJoyOfPainStatus.Lease lease,
            int feedbackDamage, List<ClientSession> recipients,
            String source) throws IOException {
        if (lease == null || !hub.consumeBotJoyOfPain(roomId, lease)) return;
        if (feedbackDamage <= 0 || hub.botHp(roomId) <= 0) return;
        byte[] reaction = Protocol.objectAction(2, BattleActionCodes.DAMAGE);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(reaction,
                    "S_ACTION Joy-of-Pain-feedback bot=2 defender="
                            + playerObjectId() + " action="
                            + BattleActionCodes.DAMAGE + " source=" + source);
        }
        int remaining = hub.damageBot(roomId, feedbackDamage);
        broadcastHitRatio(2, remaining, GameHub.ARENA_BOT_MAX_HP,
                remaining == 0 ? "joy-of-pain-bot-death"
                        : "joy-of-pain-bot-damage");
        if (remaining == 0) {
            byte[] death = Protocol.objectAction(2, BattleActionCodes.DIE);
            for (ClientSession recipient : recipients) {
                recipient.sendEncrypted(death,
                        "S_ACTION Joy of Pain bot death");
            }
            BattleRules.Resolution resolution = new BattleRules.Resolution(
                    true, false, Set.of(playerObjectId()), Set.of(),
                    "arena-bot-defeated-by-joy-of-pain");
            for (ClientSession recipient : recipients) {
                recipient.serverEndBattle(resolution);
            }
            hub.endBattle(roomId);
        }
        System.out.println("[LiTo] Joy of Pain triggered bot=2 defender="
                + playerName() + " feedback-damage=" + feedbackDamage
                + " remaining=" + remaining + " source=" + source
                + " lease-consumed=true");
    }

