    private BattleJoyOfPainStatus.Lease captureEncounterJoyOfPain(
            GameHub.MonsterAiTick tick, long nowNanos) {
        if (tick == null || phase != Phase.BATTLE
                || currentRoomId != tick.roomId()) return null;
        return tick.mode() == BattleRules.Mode.QUEST_BATTLE
                ? hub.captureQuestMonsterJoyOfPain(
                    tick.roomId(), tick.objectId(), nowNanos)
                : tick.mode() == BattleRules.Mode.TIME_ATTACK
                    ? hub.captureTimeAttackActorJoyOfPain(
                        tick.roomId(), tick.objectId(), nowNanos)
                    : null;
    }

