    private void publishNpcCounterMirrorTrigger(long l, int n, int n2, BattleCounterMirrorStatus.Decision decision, List<ClientSession> list, String string) throws IOException {
        if (!decision.triggered()) {
            return;
        }
        BattleSpellCatalog.CounterMirrorSpell counterMirrorSpell = BattleSpellCatalog.counterMirrorSpell(134);
        byte[] byArray = Protocol.effectObject(this.playerObjectId(), counterMirrorSpell.effectGfx());
        byte[] byArray2 = Protocol.objectAction(l, 2);
        for (ClientSession clientSession : list) {
            if (this.phase == Phase.WORLD && !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, n, n2) && !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, this.positionX, this.positionY)) continue;
            clientSession.sendEncrypted(byArray, "S_EFFECT Counter-Mirror-trigger defender=" + this.playerObjectId() + " npc-attacker=" + l + " gfx=" + counterMirrorSpell.effectGfx() + " source=" + string);
            String reflectedActionNote = "S_ACTION Counter-Mirror-reflected npc-attacker=" + l + " defender=" + this.playerObjectId() + " action=2 source=" + string;
            if (!NativeSourceNpcReaction.allow(this, l)) continue;
            clientSession.sendEncrypted(byArray2, reflectedActionNote);
        }
        System.out.println("[LiTo] Counter Mirror triggered defender=" + this.playerName() + " npc-attacker=" + l + " wisdom=" + decision.wisdom() + " roll=" + decision.roll() + " reflected-damage=" + decision.reflectedDamage() + " original-target-damage=0 source=" + string + " lease-consumed=true recursive-reflection-suppressed=true");
    }

