    private void serverQuestMonsterAreaPhysicalAttack(
            GameHub.MonsterAiTick tick,
            BattleQuestEncounter.Snapshot actor,
            List<ClientSession> recipients,
            BattleTimeAttackMagicSkillCatalog.PhysicalDefinition physical)
            throws IOException {
        if (tick == null || actor == null || recipients == null || physical == null
                || actor.objectId() != tick.objectId()
                || actor.npcId() != physical.npcId()
                || !physical.areaAttack()) return;

        List<ClientSession> targets = recipients.stream()
                .filter(target -> target.battleAiTargetEligible(tick.roomId()))
                .filter(target -> physical.areaContains(
                        actor.x(), actor.y(), tick.heading(),
                        target.positionX, target.positionY))
                .sorted(Comparator.comparingInt(target -> target == this ? 0 : 1))
                .toList();
        if (!targets.contains(this)) return;

        SourceNpcPhysicalStats actorStats = null;
        try {
            actorStats = selectedSourceAccounts().npcPhysicalStats(actor.npcId());
        } catch (Exception sourceFailure) {
            System.err.println("[LiTo] Quest area physical NPC source lookup"
                    + " failed npc=" + actor.npcId() + " object=" + actor.objectId()
                    + " reason=" + sourceFailure.getMessage());
        }
        for (ClientSession target : targets) {
            target.serverQuestMonsterAreaPhysicalHit(
                    tick, actor, recipients, physical, actorStats,
                    target == this, targets.size());
        }
    }

