    private void serverTimeAttackMonsterSummon(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.SummonDefinition summon =
                tick.summonSkill();
        if (summon == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || summon.npcId() != actor.npcId()) return;

        // Retained L1MobSkillUse.summon materializes the actors first, then
        // broadcasts S_SkillSound(gfx761) and ACTION_SkillBuff(action19).
        for (ClientSession recipient : recipients) {
            for (BattleTimeAttackEncounter.Snapshot spawned : tick.spawned()) {
                recipient.sendEncrypted(Protocol.timeAttackActor(spawned),
                        "S_PUT_OBJECT Time-Attack-mobskill-summon actor="
                                + spawned.objectId() + " npc=" + spawned.npcId()
                                + " gfx=" + spawned.gfx() + " caster="
                                + actor.objectId() + " authority=" + tick.source());
            }
            recipient.sendEncrypted(
                    Protocol.effectObject(actor.objectId(), summon.effectGfx()),
                    "S_EFFECT Time-Attack-mobskill-summon caster="
                            + actor.objectId() + " gfx=" + summon.effectGfx()
                            + " trigger-roll=" + tick.magicTriggerRoll());
            recipient.sendEncrypted(
                    Protocol.objectAction(actor.objectId(), summon.actionId()),
                    "S_ACTION Time-Attack-mobskill-summon caster="
                            + actor.objectId() + " action=" + summon.actionId()
                            + " spawned=" + tick.spawned().size()
                            + " authority=" + tick.source());
        }
    }

