    private int nativeMagicDollTriggeredSkillDamage(SourceMagicDollPower sourceMagicDollPower, ClientSession clientSession, SourceNpcPhysicalStats sourceNpcPhysicalStats) {
        int n;
        int n2;
        CombatMagicDamage.Attempt attempt = null;
        BattleSpellCatalog.AreaAttackSpell areaAttackSpell = BattleSpellCatalog.areaAttackSpell(sourceMagicDollPower.triggerSkillId());
        if (areaAttackSpell == null) {
            System.out.println("[LiTo] magic-doll ACTIVE_SKILL rejected unsupported skill=" + sourceMagicDollPower.triggerSkillId() + " power=" + sourceMagicDollPower.id());
            return 0;
        }
        int n3 = this.rollAreaSpellSourceDamage(areaAttackSpell);
        int n4 = n2 = clientSession == null ? 0 : clientSession.effectiveSpellElementalResistance(areaAttackSpell.attribute());
        int n5 = n = clientSession != null ? clientSession.effectiveBaseMagicResistance() : (sourceNpcPhysicalStats == null ? 0 : sourceNpcPhysicalStats.magicResistance());
        int n6 = clientSession != null ? clientSession.effectiveArmorMagicReductionBase() : (sourceNpcPhysicalStats == null ? 0 : sourceNpcPhysicalStats.damageReduction());
        attempt = CombatMagicDamage.ordinary(this, areaAttackSpell.skillId(), areaAttackSpell.attribute(), n3, n2, n, n6, "magic-doll-proc", clientSession);
        return CombatMagicDamage.direct(attempt.damage(), attempt, this, clientSession, true);
    }

    private void commitNativeMagicDollProcDamage(
            int damage, long targetObjectId, ClientSession playerTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget, String source)
            throws IOException {
        if (damage <= 0) return;
        if (playerTarget != null) {
            if (playerTarget.phase == Phase.WORLD) {
                playerTarget.takeClassicWorldPlayerDamage(
                        damage, this, false, true);
            } else {
                playerTarget.takePlayerDamage(damage, this, false, true);
            }
        } else if (questTarget != null) {
            applyQuestMonsterDamage(targetObjectId, damage,
                    "magic-doll-" + source);
        } else if (timeTarget != null) {
            applyTimeAttackActorDamage(targetObjectId, damage,
                    "magic-doll-" + source);
        }
    }

    private void publishNativeMagicDollProcVisual(
            SourceMagicDollPower power, long targetObjectId,
            boolean defense, String reason) throws IOException {
        NativeMagicDoll doll;
        synchronized (activeMagicDollObjectIds) {
            doll = activeMagicDoll;
        }
        if (doll == null) return;
        byte[] packet;
        String wire;
        if (power.gfxId() > 0) {
            packet = Protocol.effectObject(targetObjectId, power.gfxId());
            wire = "S_EFFECT magic-doll-proc=" + power.id()
                    + " target=" + targetObjectId + " gfx=" + power.gfxId();
        } else {
            packet = Protocol.objectAction(doll.objectId(), 67);
            wire = "S_ACTION magic-doll-proc=" + power.id()
                    + " doll=" + doll.objectId() + " action=67";
        }
        for (ClientSession viewer : nativeMagicDollRecipients(doll)) {
            viewer.sendEncrypted(packet, wire + " defense=" + defense
                    + " reason=" + reason);
        }
    }

