    private String activeWeaponLogName(SourceWeaponPhysicalStats weapon) {
        if (weapon == null || !weapon.present()) return "";
        String name = weapon.nameId();
        if (name == null || name.isBlank()) {
            InventoryCatalog.Definition definition = InventoryCatalog.find(weapon.itemId());
            name = definition == null ? "item#" + weapon.itemId() : definition.name();
        }
        String enchant = weapon.enchantLevel() >= 0
                ? "+" + weapon.enchantLevel() : Integer.toString(weapon.enchantLevel());
        return enchant + " " + name;
    }

