    private synchronized void recordBattleResult(boolean won, boolean disconnected) {
        if (DurableBattleSettlement.unranked(this)) return;
        won = DurableBattleSettlement.won(this, won);
        disconnected = DurableBattleSettlement.disconnected(this, disconnected);
        if (observer || resultRecorded || selectedCharacter.isBlank()) return;
        try {
            int reward = won ? config.battleWinReward() : config.battleLossReward();
            int experienceBonusPercent = cookingExperiencePercent(System.nanoTime());
            GameStateStore.Progress progress = DisconnectedBattleResult.record(
                    state, stateCharacter(), won, disconnected, reward,
                    experienceBonusPercent, sqlTournamentAuthoritative
                            ? this::persistSqlTournamentResult : null, this);
            if (!config.nativeTournamentEconomyEnabled()) {
                shopPoints = progress.shopPoints();
            }
            // Arm idempotency only after both the source-qualified SQL CAS and
            // the sidecar save have completed.  The previous ordering marked
            // a refused READ_ONLY/CONFLICT attempt as recorded forever, so a
            // later authoritative end callback could not retry the result.
            resultRecorded = true;
            System.out.println("[LiTo] battle result player=" + playerName() + " won=" + won
                    + " shop-points=" + shopPoints
                    + " ranking-points=" + progress.rankingPoints()
                    + " wins=" + progress.wins()
                    + " losses=" + progress.losses()
                    + " disconnects=" + progress.disconnects()
                    + " disconnected=" + disconnected
                    + " cooking-exp-percent=" + experienceBonusPercent
                    + " exp=" + progress.experience()
                    + " level=" + progress.level());
        } catch (IOException error) {
            System.out.println("[LiTo] state save failed player=" + playerName() + ": " + error.getMessage());
        }
    }

