    int battleGfx() {
        BattlePolymorphCatalog.Form form;
        long l = System.nanoTime();
        if (this.petRaceBaseGfx != 0) {
            if (this.petRaceTemporaryGfx != 0 && l < this.petRaceTemporaryDeadlineNanos) {
                return this.petRaceTemporaryGfx;
            }
            return this.petRaceBaseGfx;
        }
        if (this.desireQuestPolymorphGfx != 0) {
            if (l < this.desireQuestPolymorphDeadlineNanos) {
                return this.desireQuestPolymorphGfx;
            }
            this.desireQuestPolymorphGfx = 0;
            this.desireQuestPolymorphDeadlineNanos = 0L;
        }
        if ((form = this.polymorphStatus.active(l)) != null) {
            return form.gfx();
        }
        BattleAwakenStatus.Snapshot snapshot = this.awakenStatus.snapshot();
        if (CombatAwaken.classicActive(snapshot)) {
            return snapshot.dragonGfx();
        }
        return this.baseBattleGfx();
    }

    private int baseBattleGfx() {
        CharacterSummary character = characters.stream()
                .filter(candidate -> candidate.name().equalsIgnoreCase(playerName()))
                .findFirst()
                .orElse(characters.isEmpty() ? null : characters.get(0));
        if (character == null) return 61;
        // The persisted Type/Sex pair selects the original base sprite.  In
        // particular, claw and edoryu actions do not exist on knight gfx 61;
        // dark elves must retain native gfx 2786/2796.
        return BattleClassGfx.forCharacter(character.type(), character.sex());
    }

