    private void receiveHouseAuctionRefund(Map<Long, Integer> map, long l) throws IOException {
        if (map == null || l <= 0L || l > 2000000000L) {
            throw new IllegalArgumentException("invalid house-auction refund");
        }
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        InventoryCatalog.Definition definition = InventoryCatalog.find(40308L);
        if (map.isEmpty()) {
            if (definition == null || !runtimeInventory2.add(definition, l)) {
                throw new IOException("cannot install SQL house-auction refund");
            }
        } else if (definition == null || !runtimeInventory2.add(definition, l) || !runtimeInventory2.catalogCounts().equals(map)) {
            runtimeInventory2 = RuntimeInventory.fromDurableState(map, this.inventory.catalogItemStates());
        }
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        if (this.inventoryBootstrapSent) {
            this.sendInventoryDelta(runtimeInventory, this.inventory);
        }
        this.sendEncrypted(Protocol.messageCode(525, Long.toString(l)), "S_MESSAGE_CODE house-auction-refund=525 amount=" + l);
    }

    synchronized void serverHouseAuctionSettlement(String string, GameStateStore.HouseAuction houseAuction, RepositoryHouseSettlement repositoryHouseSettlement) throws IOException {
        if (houseAuction == null || repositoryHouseSettlement == null || this.selectedCharacter.isBlank() || !this.usesClassicSource(string)) {
            return;
        }
        long l = this.playerObjectId();
        if (l == repositoryHouseSettlement.oldOwnerObjectId()) {
            if (repositoryHouseSettlement.status() == RepositoryHouseSettlementStatus.TRANSFERRED && repositoryHouseSettlement.payout() > 0L) {
                RuntimeInventory runtimeInventory = this.inventory;
                RuntimeInventory runtimeInventory2 = this.inventory.copy();
                InventoryCatalog.Definition definition = InventoryCatalog.find(40308L);
                if (definition == null || !runtimeInventory2.add(definition, repositoryHouseSettlement.payout())) {
                    throw new IOException("cannot install SQL house-auction payout");
                }
                NativeDeItemApplication.replace(this, runtimeInventory2, 0);
                if (this.inventoryBootstrapSent) {
                    this.sendInventoryDelta(runtimeInventory, this.inventory);
                }
                this.sendEncrypted(Protocol.messageCode(527, Long.toString(repositoryHouseSettlement.payout())), "S_MESSAGE_CODE house-auction-sale=527 amount=" + repositoryHouseSettlement.payout());
            } else if (repositoryHouseSettlement.status() == RepositoryHouseSettlementStatus.CANCELLED) {
                this.sendEncrypted(Protocol.messageCode(528, new String[0]), "S_MESSAGE_CODE house-auction-cancelled=528 house=" + houseAuction.houseId());
            }
        }
        if (l == repositoryHouseSettlement.bidderObjectId() && repositoryHouseSettlement.status() == RepositoryHouseSettlementStatus.TRANSFERRED) {
            this.sendEncrypted(Protocol.messageCode(524, Long.toString(houseAuction.price()), repositoryHouseSettlement.bidder()), "S_MESSAGE_CODE house-auction-won=524 house=" + houseAuction.houseId() + " price=" + houseAuction.price());
        }
    }

