    void nativeMaterialPhysicalProcBuffBody(
            byte[] payload, BattleSpellCatalog.PhysicalProcBuffSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL physical proc buff rejected selector/action"
                    + " player=" + playerName() + " skill=" + request.skillId());
            return;
        }

        long requestNow = System.nanoTime();
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (spell.attribute() != BattleSpellCatalog.ATTRIBUTE_UNSPECIFIED
                && (elfAttribute & spell.attribute()) == 0
                && !isAdministrator()) {
            System.out.println("[LiTo] C_USE_SPELL physical proc buff rejected"
                    + " attribute player=" + playerName() + " skill="
                    + spell.skillId() + " required=" + spell.attribute()
                    + " elf-attr=" + elfAttribute + " phase=" + phase);
            return;
        }
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=physical-proc-buff-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE physical-proc-buff-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=physical-proc-buff-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE physical-proc-buff-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE physical-proc-buff-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned physical proc buff"
                    + " player=" + playerName() + " skill=" + spell.skillId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = NativeSkillConsumptionBridges.PhysicalProcBuffSpell_effectiveMpCost_III(spell, effectiveIntelligence, originalReduction);
        RuntimeInventory previousInventory = null;
        int remainingMp;
        boolean refreshed;
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long now = System.nanoTime();
        {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (now < readyAt || playerMp < mpCost
                    || phase != originPhase || observer || playerHp <= 0
                    || (originPhase == Phase.BATTLE
                        ? currentRoomId != originRoomId
                        : classicWorldMapId != originMapId
                            || classicWorldInstanceId != originInstanceId)) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE physical-proc-buff-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL physical proc buff rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (!NativeSelfCastAction.admit(this, spell)) return;
            if (spell.itemConsumeId() != 0) {
                previousInventory = NativeCastMaterial.previous(this);
            }
            cancelMeditation("spell-" + spell.skillId());
            if (spell.skillId() == BattleSpellCatalog.BURNING_SPIRIT) {
                refreshed = timedStatus.burningSpiritActive(now);
                timedStatus.activateBurningSpirit(now, spell.durationSeconds());
            } else if (spell.skillId() == BattleSpellCatalog.DOUBLE_BRAKE) {
                refreshed = timedStatus.doubleBrakeActive(now);
                timedStatus.activateDoubleBrake(now, spell.durationSeconds());
            } else if (spell.skillId() == BattleSpellCatalog.ELEMENTAL_FIRE) {
                refreshed = timedStatus.activateElementalFire(
                        now, spell.durationSeconds());
            } else if (spell.skillId() == BattleSpellCatalog.SOUL_OF_FLAME) {
                refreshed = timedStatus.activateSoulOfFlame(
                        now, spell.durationSeconds());
            } else {
                throw new IllegalStateException("unsupported physical proc buff");
            }
            playerMp = NativeSkillConsumption.boundMp(this, playerMp - mpCost);
            remainingMp = playerMp;
            int sourceReuseDelayMillis = sourceSkillReuseDelays.getOrDefault(
                    spell.skillId(), spell.reuseDelayMillis());
            commitSpellReady(spell.skillId(), now
                    + sourceReuseDelayMillis * 1_000_000L);
        }

        if (previousInventory != null) {
            sendInventoryDelta(previousInventory, NativeCastMaterial.next(this));
        }

        nativeSpellRevealControlled("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION physical-proc-buff caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT physical-proc-buff target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        if (spell.happenMessage() > 0) {
            sendEncrypted(Protocol.messageCode(spell.happenMessage()),
                    "S_MESSAGE_CODE physical-proc-buff-happen="
                            + spell.happenMessage());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT physical-proc-buff=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL physical proc buff=" + spell.key()
                + " caster=" + playerName() + " selector=" + request.row()
                + "/" + request.column() + " action=" + spell.actionId()
                + " gfx=" + spell.effectGfx() + " duration=" + spell.durationSeconds()
                + " refreshed=" + refreshed
                + " chance=" + spell.procChance()
                + " multiplier=" + spell.damageMultiplier()
                + " reagent=" + spell.itemConsumeId() + "x" + spell.itemConsumeCount()
                + " source-reuse-ms=" + sourceSkillReuseDelays.getOrDefault(
                        spell.skillId(), spell.reuseDelayMillis())
                + " effective-int=" + effectiveIntelligence + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase + " persisted=false"
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

