    void nativeMaterialInvisibilityBody(byte[] payload,
                                      BattleSpellCatalog.InvisibilitySpell spell)
            throws IOException {
        Long clientTick = null;
        int requestSkillId;
        if (spell.requestShape() == BattleSpellCatalog.RequestShape.SELF_TICK) {
            Protocol.SelfSpellRequest request = Protocol.selfSpellRequest(payload);
            requestSkillId = request.skillId();
            clientTick = request.clientTick();
        } else {
            Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
            requestSkillId = request.skillId();
        }
        if (requestSkillId != spell.skillId()) {
            throw new IllegalArgumentException("invisibility selector/catalog mismatch");
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL invisibility rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = NativeSkillConsumptionBridges.InvisibilitySpell_effectiveMpCost_III(spell, effectiveIntelligence, originalReduction);
        RuntimeInventory previousInventory = null;
        int remainingMp;
        boolean inventoryChanged = false;
        boolean previouslyInvisible;
        boolean toggleOff;
        long now = System.nanoTime();
        {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (now < readyAt || playerMp < mpCost
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)
                    || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL invisibility rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " invisible=" + invisible
                        + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (!NativeSelfCastAction.admit(this, spell)) return;
            if (spell.itemConsumeCount() > 0) {
                previousInventory = NativeCastMaterial.previous(this);
                inventoryChanged = true;
            }
            playerMp = NativeSkillConsumption.boundMp(this, playerMp - mpCost);
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);





            cancelMeditation("spell-" + spell.skillId());
            previouslyInvisible = invisible;
            toggleOff = previouslyInvisible
                    && invisibilityStatus.skillId() == spell.skillId();
            toggleOff = CombatInvisibilityRules.toggle(invisibilityStatus.hasSkill(spell.skillId()), this);
            if (previouslyInvisible) nativeClearInvisibilityOnCast();
            if (!toggleOff) {
                activateInvisibilityState(spell.skillId(), now, spell.durationSeconds());
            }
        }




        if (!toggleOff && phase == Phase.WORLD) {
            hub.clearClassicWorldMonsterTargets(playerObjectId());
        }

        if (inventoryChanged) {
            sendInventoryDelta(previousInventory, NativeCastMaterial.next(this));
        }



        if (previouslyInvisible) {
            nativePublishInvisibilityOnCast("invisibility-recast-" + spell.skillId());
        }
        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] removed = Protocol.removeObject(playerObjectId());
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY,
                            member.positionX, member.positionY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION invisibility-cast object=" + playerObjectId()
                            + " action=" + spell.actionId());
            if (!toggleOff && member == this) {
                member.sendEncrypted(Protocol.invisible(playerObjectId(), 1),
                        "S_INVISIBLE object=" + playerObjectId()
                                + " mode=1 skill=" + spell.skillId());
            } else if (!toggleOff) {
                member.sendEncrypted(removed,
                        "S_REMOVE_OBJECT invisible=" + playerObjectId());
            }
        }
        if (spell.effectGfx() > 0) {
            byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (phase == Phase.WORLD && member != this
                        && !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                member.positionX, member.positionY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT invisibility skill=" + spell.skillId()
                                + " object=" + playerObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT invisibility=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL invisibility skill=" + spell.skillId()
                + " caster=" + playerName()
                + (clientTick == null ? " selector-only=true" : " client-tick="
                    + Long.toUnsignedString(clientTick))
                + " duration=" + spell.durationSeconds()
                + " toggle-off=" + toggleOff
                + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

