    private void sourcePlayerLegacyBattleDamage(int n, ClientSession clientSession, boolean bl, boolean bl2, long l) throws IOException {
        if (this.phase != Phase.BATTLE || this.playerHp <= 0 || n <= 0) {
            return;
        }
        if (bl && (n = this.earthBindProtectedCombatDamage(n, clientSession == null ? "server-actor" : clientSession.playerName())) <= 0) {
            return;
        }
        if ((n = this.nativeMagicDollDamageAfterActiveReduction(n, !bl2, "battle")) <= 0) {
            return;
        }
        n = CombatIncomingSource.battle(this.abilityStatus.illusionAvatar(System.nanoTime()), n, this);
        BattleJoyOfPainStatus.Lease lease = !bl2 && clientSession != null && clientSession != this ? clientSession.joyOfPainStatus.capture(System.nanoTime()) : null;
        int n2 = lease == null ? 0 : BattleJoyOfPain.feedbackDamage(this.playerMaxHp, this.playerHp, this.joyOfPainEquipmentAddedHp());
        this.markBattleCombatWith(clientSession);
        CombatPoisonLifecycle.lastDamage(this, clientSession);
        this.playerHp = Math.max(0, this.playerHp - n);
        if (this.playerHp == 0 && l > 0L) {
            this.terminalEffectResultNotBeforeNanos = Math.max(this.terminalEffectResultNotBeforeNanos, System.nanoTime() + l * 1000000L);
        }
        this.cancelSleep(this.playerHp == 0 ? "accepted-fatal-damage" : "accepted-damage");
        this.sendEncrypted(new Protocol.Writer().c(13).h(this.playerHp).h(this.playerMaxHp).bytes(), "S_HIT_POINT player=" + this.playerHp + "/" + this.playerMaxHp);
        this.broadcastOwnHitRatio(this.playerHp == 0 ? "player-death" : "player-damage");
        if (this.playerHp == 0) {
            this.hub.cancelArmorBreak(this.currentRoomId, this.playerObjectId());
            this.hub.cancelPatience(this.currentRoomId, this.playerObjectId());
            CombatDeathCancellation.death(this);
            this.timedStatus.clearWaterDragonAffliction();
            this.dragonSkinStatus.clear();
            if (CombatBuffLeases.onDeath(this.awakenStatus.clear(), this).active()) {
                this.polymorphStatus.clear();
                this.rebuildMaximumVitals(System.nanoTime());
            }
            this.burningSlashStatus.clear();
            this.guardBrakeStatus.clear();
            this.armBreakerStatus.clear();
            this.joyOfPainStatus.clear();
            this.resistFearStatus.clear();
            this.state.saveTimedResistFearBuff(this.stateCharacter(), GameStateStore.TimedResistFearBuff.none());
            this.cancelParalysis("player-death");
            this.cancelFreeze("player-death");
            this.cancelEarthBind("player-death");
            this.cancelShockStun("player-death");
            this.cancelThunderGrab("player-death");
        }
        this.revealInvisibility(this.playerHp == 0 ? "accepted-fatal-damage" : "accepted-damage");
        if (this.playerHp == 0) {
            this.deathConfirmationPending = true;
            byte[] byArray = new Protocol.Writer().c(32).d(this.playerObjectId()).c(8).bytes();
            for (ClientSession clientSession2 : this.hub.roomMembers(this.currentRoomId)) {
                clientSession2.sendEncrypted(byArray, "S_ACTION player death object=" + this.playerObjectId());
            }
            this.sendEncrypted(new Protocol.Writer().c(227).bytes(), "S_LITO_CONFIRM_DEATH required");
        }
        if (!bl2 && clientSession != null && clientSession != this && clientSession.playerHp > 0) {
            this.tryMortalBodyPlayerReflection(clientSession, "battle-accepted-player-damage");
        }
        this.applyJoyOfPainPlayerFeedback(clientSession, lease, n2, "battle-accepted-player-damage");
    }

    private ClassicWorldFatalContext sourcePlayerLegacyWorldDirectDamage(double d, long l, CombatPoisonLifecycle.Scope scope) throws IOException {
        GameStateStore.GeneralPkState generalPk;
        GameStateStore.ElfPkState elfPk;
        if (this.phase != Phase.WORLD || this.playerHp <= 0 || d <= 0.0) {
            return ClassicWorldFatalContext.NON_FATAL;
        }
        ClassicWorldMonsterPopulation.Snapshot snapshot = this.hub.classicWorldMonster(this.classicWorldMapId, this.classicWorldInstanceId, l);
        BattleAbilityStatus.IllusionAvatar illusionAvatar = this.abilityStatus.illusionAvatar(System.nanoTime());
        int n = CombatIncomingSource.worldBefore(d, illusionAvatar);
        if ((n = CombatIncomingSource.world(this, n, true, "classic-world", d, illusionAvatar)) <= 0) {
            return ClassicWorldFatalContext.NON_FATAL;
        }
        this.playerHp = Math.max(0, this.playerHp - n);
        this.cancelSleep(this.playerHp == 0 ? "classic-world-fatal-damage" : "classic-world-damage");
        this.sendEncrypted(new Protocol.Writer().c(13).h(this.playerHp).h(this.playerMaxHp).bytes(), "S_HIT_POINT classic-world player=" + this.playerHp + "/" + this.playerMaxHp + " attacker=" + l);
        byte[] byArray = Protocol.hitRatio(this.playerObjectId(), this.playerHp, this.playerMaxHp);
        for (ClientSession clientSession : this.classicWorldMembers(this.classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, this.positionX, this.positionY)) continue;
            clientSession.sendEncrypted(byArray, "S_HIT_RATIO classic-world-player=" + this.playerObjectId() + " hp=" + this.playerHp + "/" + this.playerMaxHp);
        }
        this.revealInvisibility(this.playerHp == 0 ? "classic-world-fatal-damage" : "classic-world-damage");
        if (this.playerHp != 0) {
            return ClassicWorldFatalContext.NON_FATAL;
        }
        if (ClassicWorldGuardCatalog.isGuard(snapshot)) {
            generalPk = this.state.clearGeneralPkAfterGuardDeath(this.stateCharacter());
            this.generalPkCount = (generalPk).count();
            this.lastPkEpochSeconds = (generalPk).lastPkEpochSeconds();
            System.out.println("[LiTo] L1Guard death absolution player=" + this.playerName() + " guard=" + snapshot.objectId() + " pk-count=" + this.generalPkCount + " last-pk-cleared=true");
        }
        if (ClassicWorldGuardianCatalog.isGuardian(snapshot)) {
            elfPk = this.state.clearElfPkAfterGuardianDeath(this.stateCharacter());
            this.elfPkCount = (elfPk).count();
            this.lastPkForElfEpochSeconds = (elfPk).lastPkEpochSeconds();
            System.out.println("[LiTo] L1Guardian death absolution player=" + this.playerName() + " guardian=" + snapshot.objectId() + " elf-pk-count=" + this.elfPkCount + " last-pk-for-elf-cleared=true");
        }
        this.deathConfirmationPending = false;
        CombatDeathCancellation.death(this);
        this.timedStatus.clearWaterDragonAffliction();
        this.dragonSkinStatus.clear();
        if (CombatBuffLeases.onDeath(this.awakenStatus.clear(), this).active()) {
            this.polymorphStatus.clear();
            this.rebuildMaximumVitals(System.nanoTime());
        }
        this.burningSlashStatus.clear();
        this.guardBrakeStatus.clear();
        this.armBreakerStatus.clear();
        this.joyOfPainStatus.clear();
        this.resistFearStatus.clear();
        this.state.saveTimedResistFearBuff(this.stateCharacter(), GameStateStore.TimedResistFearBuff.none());
        this.cancelClassicWorldArmorBreak();
        this.hub.cancelClassicWorldPatience(this.classicWorldMapId, this.classicWorldInstanceId, this.playerObjectId());
        this.hub.clearClassicWorldMonsterTargets(this.playerObjectId());
        ClientSession clientSession = this;
        boolean bl = CombatPoisonLifecycle.cure(clientSession.timedStatus, clientSession, scope);
        ClientSession clientSession2 = this;
        boolean bl2 = CombatPoisonLifecycle.silence(clientSession2.timedStatus, clientSession2, scope);
        CombatPoisonAtomic.attacker(this, null);
        if (bl2) {
            CombatPoisonLifecycle.silenceDeathSend(this, Protocol.messageCode(311, new String[0]), "S_MESSAGE_CODE classic-world-silence-poison-death-cured=311", scope);
        }
        this.cancelParalysis("classic-world-player-death");
        CombatPoisonAtomic.object(this, 0L);
        CombatPoisonAtomic.kind(this, ClassicWorldMonsterPoisonAttack.Kind.NONE);
        if (bl || bl2) {
            CombatPoisonLifecycle.palette(this, this.currentPoisonPalette(System.nanoTime()), "classic-world-player-death", scope);
        }
        this.cancelFreeze("classic-world-player-death");
        this.cancelEarthBind("classic-world-player-death");
        this.cancelShockStun("classic-world-player-death");
        this.cancelThunderGrab("classic-world-player-death");
        byte[] byArray2 = Protocol.objectAction(this.playerObjectId(), 8);
        for (ClientSession clientSession3 : this.classicWorldMembers(this.classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(clientSession3.positionX, clientSession3.positionY, this.positionX, this.positionY)) continue;
            clientSession3.sendEncrypted(byArray2, "S_ACTION classic-world player-death=" + this.playerObjectId() + " attacker=" + l + " tournament-confirm-death=false");
        }
        ClassicWorldFatalContext classicWorldFatalContext = this.handleClassicWorldWarLeaderDeath(l);
        this.publishClassicWorldPlayerKill(l, classicWorldFatalContext.warDeath());
        System.out.println("[LiTo] classic-world player defeated player=" + this.playerName() + " attacker=" + l + " C_RESTART-awaiting=true S_LITO_CONFIRM_DEATH=false");
        return classicWorldFatalContext;
    }

